BEGIN;
UPDATE glossary g SET definition = CASE WHEN d.p ? 'definition' THEN d.p->>'definition' ELSE g.definition END, plain_english = CASE WHEN d.p ? 'plain_english' THEN d.p->>'plain_english' ELSE g.plain_english END, purpose_function = CASE WHEN d.p ? 'purpose_function' THEN d.p->>'purpose_function' ELSE g.purpose_function END, practical_application = CASE WHEN d.p ? 'practical_application' THEN d.p->>'practical_application' ELSE g.practical_application END, category = CASE WHEN d.p ? 'category' THEN d.p->>'category' ELSE g.category END, related_terms = CASE WHEN d.p ? 'related_terms' THEN ARRAY(SELECT jsonb_array_elements_text(d.p->'related_terms')) ELSE g.related_terms END, common_mistakes = CASE WHEN d.p ? 'common_mistakes' THEN ARRAY(SELECT jsonb_array_elements_text(d.p->'common_mistakes')) ELSE g.common_mistakes END, scenario_contexts = CASE WHEN d.p ? 'scenario_contexts' THEN ARRAY(SELECT jsonb_array_elements_text(d.p->'scenario_contexts')) ELSE g.scenario_contexts END FROM (SELECT key::uuid AS id, value AS p FROM jsonb_each($ape${"22b054c7-78b9-4c19-9c36-ef5d93bd3300": {"definition": "An overflow-zone feed is the dedicated output or zone feed that carries program audio to an overflow zone, a defined secondary coverage area such as an extra room, lobby, or seating block activated when the main space is at capacity. It is functionally the same as an overflow feed, described from the system-zoning viewpoint as one addressable zone in a distributed or matrixed system.", "plain_english": "An overflow-zone feed is a set output that sends sound to one extra area. That area is used when the main room fills up. It is treated as its own zone, so its level and on/off can be set on their own.", "purpose_function": "It exists to make an overflow area an addressable zone with its own level, delay, and mute, so operators can enable it or turn it off and tune it on its own. This keeps the main room and the overflow area under separate control.", "practical_application": "A tech assigns a matrix or DSP output as the overflow-zone feed, then sets its level, delay, and EQ and enables it only when the extra space is in use.", "category": "Signal Distribution", "related_terms": ["Overflow feed", "Zone (audio)", "Matrix output", "Output Mute", "Distributed system", "Delay (fill)"], "common_mistakes": ["UNSAFE: Relying on an entertainment overflow-zone feed for emergency announcements, which need a separate system meeting NFPA 72 and local code.", "Treating the overflow-zone feed as a copy of the master, losing independent level and mute control.", "Leaving the zone enabled when the area is empty, wasting power and adding spill."], "scenario_contexts": ["Switching on a lobby zone only when the main room reaches capacity.", "Tuning delay and level for one overflow block in a multi-zone DSP.", "Muting the overflow zone from the console once the crowd thins."]}, "df02568e-a018-47bf-b3bf-63124bcb1677": {"definition": "An overhead audio zone is a coverage region served by loudspeakers positioned above the audience, either ceiling-mounted or flown height/overhead loudspeakers, used to deliver localized program, effects, or the height layer of an immersive (object-based) system. It is defined spatially by the overhead loudspeakers' coverage rather than by a seating tier.", "plain_english": "An overhead audio zone is the area covered by speakers placed above the audience. These can be ceiling speakers or flown boxes pointing down. They add sound from overhead, such as effects or the 'height' layer in surround systems.", "purpose_function": "It exists to bring sound from above—which speakers at ear level cannot provide—for even ceiling coverage, localized effects, or the height channels of immersive audio. It expands the sound field vertically.", "practical_application": "A tech deploys and delays ceiling or flown overhead loudspeakers to cover a zone from above, for paging coverage or the height layer of an immersive mix.", "category": "Loudspeaker Deployment", "related_terms": ["Immersive audio", "Height layer", "Ceiling loudspeaker", "Distributed system", "Zone (audio)", "Flown loudspeaker"], "common_mistakes": ["UNSAFE: Suspending overhead loudspeakers without a rated secondary safety and without staying within rigging-point and hardware working load limits.", "Ignoring the extra path-length delay from high overhead boxes, so their sound arrives late and smears the image.", "Spacing ceiling speakers too far apart, leaving level and coverage gaps between them."], "scenario_contexts": ["Deploying the height layer of an immersive, object-based system.", "Covering a large flat floor with distributed ceiling loudspeakers.", "Adding overhead effects speakers in a theatre or themed attraction."]}, "84a1cf57-208e-4945-9faf-dc0fb103e19b": {"definition": "Overhead scare audio is sound content, typically sudden startling effects or ambience, delivered from loudspeakers mounted above guests in a themed or haunted attraction to produce a fright or 'jump-scare' effect. It uses overhead placement so the sound appears to come from directly above, heightening surprise and immersion at a scare point.", "plain_english": "Overhead scare audio is scary sound played from speakers above people's heads. It is used in haunted houses and theme-park rides. Coming from overhead makes a sudden noise more startling.", "purpose_function": "It exists to trigger a startle or fright reaction at a set point by placing sudden sound directly overhead, where listeners do not expect it. Overhead placement adds surprise and a sense of something looming above.", "practical_application": "A themed-entertainment tech mounts and aims small overhead loudspeakers at a scare zone, then triggers the effects from a show-control or playback system on cue.", "category": "Loudspeaker Deployment", "related_terms": ["Overhead Audio Zone", "Effects loudspeaker", "Show control", "Ceiling loudspeaker", "Localization", "Flown loudspeaker"], "common_mistakes": ["UNSAFE: Rigging overhead scare speakers over an occupied path without a rated secondary safety and without meeting overhead-suspension and working-load-limit requirements.", "UNSAFE: Running scare effects at SPLs above safe exposure limits for guests and repeatedly-exposed staff, instead of managing level and duration to OSHA hearing-conservation limits.", "Placing the speaker where its sound does not localize overhead, so the scare loses its effect."], "scenario_contexts": ["Triggering a jump-scare effect from above in a haunted-house room.", "Adding overhead creature or ambience sounds on a dark ride.", "Placing startle effects over a queue line or hallway in a seasonal attraction."]}, "590b9273-b51f-4953-9be5-da7c55b943bc": {"definition": "PA (public address) is the complete sound reinforcement system, the assembled loudspeakers, power amplifiers, mixer, and signal processing, used to amplify and distribute speech or music to an audience larger than the source could reach unaided.", "plain_english": "A PA, short for public address, is the set of speakers and gear for live sound. It makes voices and music loud enough for a whole crowd to hear.", "purpose_function": "It raises sound to an even, intelligible level across a listening area so everyone can hear speech or music clearly, no matter how large the audience.", "practical_application": "A technician sets up, patches, and tunes the PA before a show, matching loudspeaker coverage and level to the room and audience size.", "category": "Sound Reinforcement", "related_terms": ["Sound Reinforcement", "Point-Source Loudspeaker", "Line Array", "Power Amplifier", "Loudspeaker Management System"], "common_mistakes": ["Assuming a bigger PA automatically sounds better; coverage design and tuning matter more than raw wattage.", "Confusing 'PA' meaning the whole public address system with 'PA' used loosely for a single power amplifier.", "UNSAFE: Running a PA at sustained high sound pressure levels that exceed safe audience and crew exposure limits, which can cause permanent hearing damage."], "scenario_contexts": ["Setting up a PA for a conference so a speaker's voice reaches the back row clearly.", "Deploying a festival main PA with subwoofers and delay loudspeakers for a large field audience.", "Tuning a house-of-worship PA for even speech intelligibility across all seating."]}, "713a1234-e721-41a2-8655-ed6f8a851af8": {"definition": "Pattern overlap is the region where the coverage patterns of two or more loudspeakers intersect, so both sources deliver significant energy to the same listeners; in that zone the signals sum, producing level addition and, where arrivals differ in phase, comb filtering and coverage variance.", "plain_english": "Pattern overlap is where two speakers aimed nearby both hit one listener. The two sounds mix there, which can add loudness but also cause an uneven, hollow-sounding tone (called comb filtering).", "purpose_function": "Understanding overlap lets designers control how adjacent loudspeakers combine, trading added level and wider coverage against comb filtering and tonal unevenness.", "practical_application": "When splaying or stacking cabinets, a technician manages overlap by angling boxes so their patterns meet near the edges, limiting ripple while keeping coverage even.", "category": "Coverage Design", "related_terms": ["Comb Filtering", "Coverage Angle", "Splay Angle", "Point-Source Loudspeaker", "Line Array"], "common_mistakes": ["Thinking overlap only adds level; in the overlap zone, differing arrival times also cause comb filtering and tonal coloration.", "Over-splaying or under-splaying cabinets, which creates either coverage gaps or excessive overlap and uneven response.", "Assuming more overlap always means smoother coverage, when it often increases level variance across the audience."], "scenario_contexts": ["Aiming a pair of point-source tops so their patterns overlap only at the edges to cover a wide room evenly.", "Diagnosing a hollow, filtered sound in seats where two loudspeakers' patterns heavily overlap.", "Setting splay angles in a line array so element overlap is controlled across the frequency range."]}, "010b26de-af85-46de-a1fe-3f0f16fc78b8": {"definition": "A peak limiter is a dynamics processor with a very high ratio (effectively infinite) and fast attack that prevents a signal's instantaneous level from exceeding a set threshold, capping transient peaks to guard against clipping, overload, or driver and amplifier damage.", "plain_english": "A peak limiter is a safety valve for audio. It watches the loudest split-second peaks and quickly holds them down so they never rise above a set ceiling.", "purpose_function": "It stops brief transient peaks from clipping converters or pushing amplifiers and loudspeakers past their safe limits, protecting equipment and keeping the output clean.", "practical_application": "A technician sets peak limiters in loudspeaker processors and amplifiers to the manufacturer's driver limits, and on console outputs to prevent digital clipping.", "category": "Dynamics Processing", "related_terms": ["Limiter", "Compressor", "Threshold", "Clipping", "Loudspeaker Management System"], "common_mistakes": ["Confusing a peak limiter with an RMS/average limiter; peak limiting controls instantaneous peaks, not long-term energy.", "Relying on a peak limiter to rescue a badly gain-staged system instead of setting proper levels first.", "UNSAFE: Disabling or setting driver-protection peak limiters above the manufacturer's specified limits, which can overheat and destroy loudspeaker components."], "scenario_contexts": ["Configuring peak limiter thresholds in an amplifier to match a subwoofer's voice-coil limits.", "Placing a brickwall peak limiter on a mix bus to prevent digital overs during a live broadcast.", "Protecting compression drivers with a fast peak limiter in the high-frequency band of a processor."]}, "36395a11-30bc-4955-abd3-e28c74505cb5": {"definition": "A personal monitor system is a stage-monitoring arrangement that gives each performer an individually controllable monitor mix, typically delivered through in-ear monitors (wired or wireless) and often via a small personal mixer that lets the musician set the balance of source channels for their own mix.", "plain_english": "A personal monitor system lets each musician build and control their own mix of the band. It is usually heard through in-ear earpieces. Everyone gets what they need to hear.", "purpose_function": "It lets performers hear themselves and bandmates with a mix tailored to them, reducing onstage volume and easing the load on the monitor engineer.", "practical_application": "A technician patches the personal mixers or in-ear transmitters, sets up the source channels, and helps each performer dial in and save their own monitor mix.", "category": "Monitoring", "related_terms": ["In-Ear Monitor", "Monitor Mix", "Stage Monitor", "Aux Send", "Monitor Engineer"], "common_mistakes": ["Assuming personal monitors remove all stage-volume problems, when open earpieces or wedges still spill into microphones.", "UNSAFE: Setting in-ear monitor levels too high, or ignoring feedback and signal spikes, which risks sudden loud bursts and permanent hearing damage.", "Forgetting that a lost or muted personal mix leaves a performer with no monitoring, so players must be briefed on level safeguards."], "scenario_contexts": ["Deploying a personal-mixer rig so each band member mixes their own in-ears.", "Setting up wireless in-ear transmitters for a touring act's personal monitor mixes.", "Using personal monitors in a house of worship to keep the stage quiet during services."]}, "6852edc6-b10a-4968-98b3-472cc87f0a27": {"definition": "A phase filter (per band) is an all-pass filter applied within an individual frequency band of a loudspeaker processor or crossover; it passes all frequencies at unity gain while shifting phase around a chosen frequency, letting the engineer align the relative phase and timing of that band with adjacent bands or drivers without altering its magnitude response.", "plain_english": "A per-band phase filter changes the timing of one frequency range without changing its loudness. It helps line up a speaker's bands so they blend smoothly instead of fighting.", "purpose_function": "It corrects phase misalignment between drivers or bands near their crossover, improving how they sum together and smoothing both the frequency response and the pattern through the crossover.", "practical_application": "While tuning a processor, a technician uses a per-band phase filter to time-align, for example, a compression driver to a woofer so the crossover region sums flat.", "category": "Signal Processing", "related_terms": ["All-Pass Filter", "Crossover", "Phase Alignment", "Group Delay", "Loudspeaker Management System"], "common_mistakes": ["Confusing a phase filter (all-pass) with an EQ filter; the all-pass changes phase only, not magnitude.", "Adjusting phase filters by ear without a dual-channel measurement, so the crossover alignment is guessed rather than verified.", "Applying broadband delay when a per-band phase filter is the correct tool for aligning a single band's phase."], "scenario_contexts": ["Aligning the phase of a horn and woofer at the crossover using a per-band all-pass filter.", "Fine-tuning a subwoofer-to-mains crossover so the two sum instead of cancel.", "Setting phase filters in a system processor while watching a transfer-function measurement."]}, "b0659360-f474-4fad-8e07-64747c73b7f9": {"definition": "Pilot tone monitoring is a squelch technique in wireless microphone and in-ear systems where the transmitter adds an inaudible pilot tone to its RF signal; the receiver keeps its audio output muted unless it detects that pilot tone, so the channel stays silent when the transmitter is off, out of range, or when a non-matching signal appears on the frequency.", "plain_english": "Pilot tone monitoring is like a secret password sent with a wireless mic's signal. The receiver stays muted unless it hears that hidden tone. So it will not blast noise when the mic is off.", "purpose_function": "It stops bursts of noise or interference from being heard when the transmitter is switched off or drops out, and helps the receiver ignore signals that lack the correct pilot.", "practical_application": "A technician enables matching pilot tone settings on transmitter and receiver so channels mute cleanly at power-down, disabling it only when pairing incompatible older gear.", "category": "Wireless Systems", "related_terms": ["Squelch", "Wireless Microphone", "In-Ear Monitor", "RF Interference", "Diversity Reception"], "common_mistakes": ["Mismatching pilot tone settings between transmitter and receiver, so the receiver stays muted even with a good signal.", "Assuming pilot tone removes interference; it only mutes non-matching signals and does not prevent RF interference itself.", "Leaving pilot tone off to pair old and new gear, then wondering why the channel passes noise when the transmitter is off."], "scenario_contexts": ["Enabling pilot tone so a handheld mutes silently when a presenter powers it down mid-event.", "Troubleshooting a wireless channel that stays muted because transmitter and receiver pilot settings do not match.", "Using pilot tone squelch on a busy RF spectrum to reduce noise from stray signals."]}, "82c05c88-17db-43dc-af0f-127be6844fef": {"definition": "A point-source loudspeaker is a system that radiates sound as if from a single, compact origin, with its drivers positioned and combined so their output appears to come from one point; its level falls with distance following the inverse-square law (about 6 dB per doubling of distance), unlike line-source (line-array) behavior.", "plain_english": "A point-source speaker acts like sound coming from one small spot. As you walk away it gets quieter fast, dropping about 6 dB each time you double your distance.", "purpose_function": "It gives predictable, wide coverage from a single well-behaved source, used where a coherent origin and simple pattern control are preferred over long-throw line arrays.", "practical_application": "A technician deploys point-source cabinets for small-to-medium venues, front-fills, or delays, aiming each box at its zone and using the distance falloff to plan levels.", "category": "Loudspeaker System", "related_terms": ["Line Array", "Coverage Angle", "Inverse-Square Law", "Pattern Overlap", "PA"], "common_mistakes": ["Confusing a point-source loudspeaker with a line array; they follow different distance-loss and coverage rules.", "Expecting line-array-style long throw from a point source, whose level drops about 6 dB per doubling of distance.", "Stacking several point-source boxes vertically and expecting them to couple like a true line array."], "scenario_contexts": ["Choosing point-source tops for a club where a full line array would be oversized.", "Using point-source cabinets as front-fills to cover the first rows below a main array.", "Deploying delay point-source loudspeakers to extend coverage to the back of a room."]}, "d5aeb70e-74f7-4fac-9141-96e844f34d76": {"definition": "A loudspeaker system in which sound radiates from a single acoustic source, or from a compact cluster of drivers/cabinets close enough to behave as one, producing a coherent, spherically spreading wavefront. Its level falls by roughly 6 dB per doubling of distance (inverse-square behaviour), distinguishing it from a line-source (line array) system.", "plain_english": "A point-source system sends sound out from one spot, like a single light bulb glowing in all directions. As you walk away, the sound gets quiet fast. This is different from a line array, which is a tall stack that throws sound much farther.", "purpose_function": "It provides broad, natural coverage from one location and is simple to deploy, making it well suited to smaller rooms and shorter throws where a full line array is unnecessary.", "practical_application": "A technician flies or stands one point-source box, or a horn-loaded cluster, per side and aims it across the seating, allowing for the roughly 6 dB loss per distance doubling when setting levels.", "category": "System Type", "related_terms": ["Line array", "Coverage angle", "Inverse-square law", "Loudspeaker cluster", "Horn loading", "Directivity"], "common_mistakes": ["Assuming a point-source box throws as far as a line array; its level drops about 6 dB per doubling of distance, so far seats fall short.", "Splaying several point-source cabinets side by side and expecting seamless coverage, which instead causes lobing and comb filtering in the overlap zones.", "Confusing the 'point source' design goal with a literal single driver; a well-designed multi-way box behaves as one point source only within its usable range."], "scenario_contexts": ["Deploying a single trapezoidal cabinet per side for speech in a small conference room.", "Flying a horn-loaded point-source cluster in a house of worship with modest throw distances.", "Choosing a point-source box over a line array for a low-ceiling club where a tall array will not fit."]}, "1c9902a2-657e-46da-be4a-d4b3156cb5bf": {"definition": "A small additional delay time deliberately added to a delayed or fill loudspeaker, beyond the time-of-flight alignment to the main system, so that under the precedence (Haas) effect listeners localise the combined sound toward the main/stage source rather than the nearer fill. Typical added offsets are on the order of 5-15 ms, kept within the roughly 10-30 ms window before a discrete echo becomes audible.", "plain_english": "Our ears point to whichever sound reaches them first. A precedence offset adds a tiny extra delay to a nearby fill speaker. This makes the sound seem to come from the stage, not from the close speaker. The delay stays small so you never hear a separate echo.", "purpose_function": "It preserves natural source localisation, so sound still appears to come from the performer, even when closer fill or delay speakers are louder at the listener, improving realism and image.", "practical_application": "After time-aligning a delay or front-fill to the mains, the engineer adds a few extra milliseconds so the audience still localises to the stage instead of the nearby box.", "category": "Localization", "related_terms": ["Precedence effect", "Haas effect", "Delay speaker", "Time alignment", "Front-fill", "Localization"], "common_mistakes": ["Aligning a fill to zero offset and then wondering why the audience localises to the fill instead of the stage.", "Adding too much offset, so the extra delay crosses into audible-echo territory and smears clarity.", "Believing the precedence effect works at any level difference; if the fill is far louder than the mains, level rather than timing wins and the image collapses to the fill."], "scenario_contexts": ["Setting front-fills so a front-row listener still localises to the singer on stage.", "Tuning under-balcony delays so distant rows hear the image at the stage, not overhead.", "Adjusting a distributed delay ring in a large room to keep speech anchored to the talker."]}, "35f5c2f4-6be2-4525-999e-727074ac381f": {"definition": "The stored-settings feature of a mixing console or signal processor that saves a complete snapshot of parameters, such as fader levels, routing, EQ, dynamics and effects, as a named scene or preset and reloads it instantly on command. Recall can be global or scoped/isolated so that selected channels or parameters are excluded from the change.", "plain_english": "A scene is a saved snapshot of every setting on the mixer. Recalling it puts all those settings back at once, like loading a saved game. An operator can jump to the right sound for each part of a show with one press.", "purpose_function": "It lets an operator reconfigure an entire console or processor reliably and repeatably, which is essential for theatre cue sequences, multi-band festival changeovers and installed presets.", "practical_application": "A mix engineer builds and stores scenes during rehearsal, then recalls them live for each song or scene, often using 'scope' or 'recall safe' to protect channels they still want to control by hand.", "category": "Console Feature", "related_terms": ["Snapshot", "Scene", "Mixing console", "Recall safe", "Automation", "DSP preset"], "common_mistakes": ["Recalling a full scene live without setting recall scope, so an unexpected fader or mute jumps and disrupts the mix.", "Forgetting to save an edited scene, so the change is lost at the next recall.", "Assuming presets transfer between different firmware or console models unchanged, when parameter maps and versions often differ."], "scenario_contexts": ["Storing a scene per musical number so a theatre operator recalls cues on time.", "Recalling channel presets at a festival to reset the console between bands quickly.", "Loading a saved processor preset when powering up an installed sound system."]}, "b3880f4a-f286-48be-bd89-e41bcbfd6e8a": {"definition": "A dedicated, isolated distribution of an event's program audio (and sometimes video) supplied to press and broadcast media, typically delivered from a press box or mult box that provides multiple mic- or line-level outputs, each transformer- or electronically isolated so that one outlet's connection cannot load down or interfere with the others or the main mix.", "plain_english": "At a press event, many reporters need clean audio of what is said. A press feed splits the sound into many separate outputs, one per crew. Each output is isolated. So if one reporter has a fault, everyone else still gets clean sound.", "purpose_function": "It gives every media outlet a clean, consistent copy of the program sound without letting their equipment load down or interfere with the house system or with each other.", "practical_application": "A technician patches the program mix into a press/mult box and hands out isolated line- or mic-level outputs to news crews, so each feed is ground-isolated to avoid hum and interference.", "category": "Signal Distribution", "related_terms": ["Mult box", "Press box", "Transformer splitter", "Ground loop", "Line level", "Program feed"], "common_mistakes": ["UNSAFE: Lifting the AC safety (earth) ground on media gear to cure hum in a press feed; never defeat mains earth. Break the loop on the signal side using the splitter's transformer ground-lift instead.", "Handing out a raw line output with no isolation, so a fault or ground loop in one crew's rig injects hum into every feed.", "Providing the wrong level (line where crews expect mic, or the reverse) and overloading or under-driving the reporters' recorders."], "scenario_contexts": ["Feeding dozens of TV and radio crews from a mult box at a political press conference.", "Providing an isolated program feed to a broadcast truck at a concert or sports event.", "Supplying clean audio to media at a corporate keynote from the main console's matrix output."]}, "459e32e7-b17c-4c34-9667-db65266abce0": {"definition": "A line-array configuration in which the inter-cabinet splay angles increase progressively from top to bottom: tight angles between the upper boxes to throw energy to distant seats, opening to wider angles between the lower boxes to cover nearer seating. The graduated taper shapes the array's vertical coverage to match seat distances and equalise level from front to back.", "plain_english": "A line array is a curved column of speakers. In a progressive splay, the top boxes are angled almost straight to reach the far seats. Lower down, the angles open wider to cover the close seats. This gentle fan shape spreads the sound evenly from front to back.", "purpose_function": "It matches the array's output to the room geometry so front and rear listeners hear similar levels, using tighter angles for the throw needed at distance and wider angles for the spread needed up close.", "practical_application": "Using prediction software, a system engineer sets each inter-box angle from tight at the top to wide at the bottom, then confirms the mechanical angles are within the frame's rated limits before flying.", "category": "Array Configuration", "related_terms": ["Line array", "Splay angle", "Rigging frame", "Coverage angle", "J-array", "Prediction software"], "common_mistakes": ["UNSAFE: Setting a lower splay angle beyond the manufacturer's rated maximum; over-splayed boxes place excess load on the frame and pins and can compromise the flown array's structural integrity.", "Using equal splay angles throughout, which over-covers the front rows and leaves the back rows weak.", "Setting the taper by eye instead of by prediction and measurement, giving uneven front-to-back level."], "scenario_contexts": ["Designing a J-array where the top boxes are near-straight for the back rows and the bottom boxes splay to cover the pit.", "Tapering a flown array in a deep theatre to keep balcony and orchestra levels within a few dB.", "Adjusting splay in prediction software to fill a raked seating bowl evenly."]}, "1df57dda-2071-49ee-b6c4-7ed903d8b63b": {"definition": "A loudspeaker cluster flown at or just above the proscenium arch of a proscenium-stage theatre, usually a central cluster (or left/centre/right cluster) positioned above the stage opening to cover the main auditorium. It creates a natural sound image originating from the stage area while keeping the loudspeakers clear of sightlines and scenery.", "plain_english": "A proscenium is the big frame around a theatre stage. A proscenium cluster is a group of speakers flown just above that frame. Placed there, the sound seems to come from the stage, where the actors are. It also stays out of the way of the view.", "purpose_function": "It centralises coverage from a natural stage location so the audience localises sound to the performers, while the flown position keeps the boxes above sightlines and clear of set pieces.", "practical_application": "A designer flies a central cluster above the proscenium on rated rigging, aims and delays it to the stage, and often adds front-fills so the sound image stays low for the first rows.", "category": "Speaker Placement", "related_terms": ["Loudspeaker cluster", "Central cluster", "Point-source system", "Front-fill", "Proscenium", "Overhead rigging"], "common_mistakes": ["UNSAFE: Flying a proscenium cluster from scenery battens, unrated points, or single-point rigging over the audience; overhead clusters must hang from independently rated, load-verified structure with secondary retention.", "Placing the cluster too high, so the sound image floats above the stage instead of at the performers.", "Omitting front-fills, so the front rows localise up to the cluster instead of to the stage."], "scenario_contexts": ["Flying a central cluster above the proscenium for a Broadway-style musical.", "Covering a road-house theatre's main floor from a permanent proscenium cluster.", "Designing a house-of-worship platform where a central cluster above the proscenium anchors the image to the stage."]}, "f907a42c-ac1a-4929-9e8e-44627e5992c8": {"definition": "Supplementary loudspeakers positioned toward the rear of a venue and electronically delayed so their arrival is time-aligned with the sound from the main system, restoring level and intelligibility for far audience areas the mains cannot adequately reach. The delay is set so the main system's sound still arrives first, preserving localization toward the stage.", "plain_english": "Rear delays are extra speakers placed near the back of a crowd. They turn on a split second late so their sound lines up with the main speakers. This keeps far-back listeners clear, without pulling the sound toward the back.", "purpose_function": "They extend clear, even coverage to distant seats where the main array has lost level and clarity, while the added delay keeps the stage as the apparent sound source.", "practical_application": "A system tech places the rear speakers, measures the distance back from the mains, and dials in a matching delay plus a small offset so the two arrivals fuse.", "category": "Loudspeaker Deployment", "related_terms": ["Delay loudspeaker", "Main array", "Time alignment", "Haas effect", "Fill loudspeaker", "Delay tower"], "common_mistakes": ["Setting no delay or the wrong delay time, so the rear speakers arrive out of sync and blur the sound.", "Turning the rear delays up too loud, which pulls the apparent sound image toward the back of the room.", "Omitting the small extra offset beyond the pure distance delay, so localization still drifts rearward."], "scenario_contexts": ["Covering the rear of a deep theatre where the main hangs have rolled off in level.", "Adding delayed rear speakers under a balcony overhang that shadows the main system."]}, "134e3c72-eee2-402e-a79c-6862b29eca5d": {"definition": "Load-rated detachable components used to connect, support, and adjust suspended loads in an entertainment rigging system, including shackles, master links, rings, swivels, turnbuckles, eye bolts, hoist rings, wire rope clips, and load pins. Each item carries a marked Working Load Limit and is governed by standards such as ASME B30.26.", "plain_english": "Rigging hardware is the set of rated metal parts that hold up flown gear. It includes shackles, rings, and bolts that link speakers or truss to the structure above. Each part has a stamped safe load limit you must never go past.", "purpose_function": "It provides certified, load-rated connections that transfer the weight of flown equipment safely into the building structure or supporting truss.", "practical_application": "A rigger picks hardware whose Working Load Limit exceeds the calculated load with the required design factor, inspects each piece, and records it before flying.", "category": "Rigging Hardware", "related_terms": ["Shackle", "Working load limit", "Design factor", "Chain hoist", "Truss", "Wire rope sling", "Load rating"], "common_mistakes": ["UNSAFE: Using unrated hardware-store shackles or bolts in place of load-rated rigging hardware.", "UNSAFE: Exceeding a component's marked Working Load Limit or ignoring the required design (safety) factor.", "UNSAFE: Side-loading a shackle or bending an eye bolt off-axis, which sharply lowers its rated capacity.", "Confusing Working Load Limit with breaking strength; the Working Load Limit already includes the safety factor."], "scenario_contexts": ["Selecting and inspecting shackles and steels to fly a line array from a chain hoist.", "Building a truss grid and connecting motors with rated hardware before a show load-in."]}, "a72c90cf-c1a8-4d6e-9586-b46563515d01": {"definition": "The loudspeaker cluster deployed on the right side of a sound reinforcement system (audience right), one half of a left/right main pair and typically a flown point-source grouping or array that covers the right portion of the audience.", "plain_english": "The right cluster is the group of main speakers on the right side. Paired with a left cluster, the two together cover the whole crowd. 'Right' normally means the audience's right as they face the stage.", "purpose_function": "It supplies the right-hand share of main coverage and, with the left cluster, creates the wide horizontal or stereo image across the audience.", "practical_application": "A tech flies the right cluster, matches its level and delay to the left cluster, and aims it to cover the right seating block.", "category": "Loudspeaker Deployment", "related_terms": ["Left cluster", "Right hang", "Right main", "Main array", "Point source", "Line array"], "common_mistakes": ["Confusing audience right with stage right; from the performer's view they are opposite sides.", "Failing to level- and time-match the right cluster to the left, causing an uneven or pulled image.", "Assuming a cluster must be a line array; a cluster can also be a point-source grouping."], "scenario_contexts": ["Flying left and right clusters for a corporate presentation in a ballroom.", "Troubleshooting why the right side of the room is quieter than the left."]}, "07692bbb-bfcd-4e0e-94a4-ed97cb552635": {"definition": "The flown (suspended) loudspeaker array on the right side (audience right) of a left/right main system, commonly a vertical line array 'hang' rigged from a single set of overhead points.", "plain_english": "The right hang is the line of speaker boxes flown on the right side. 'Hang' means the boxes are rigged from points above, not stacked on the ground. It works with the left hang to cover the room.", "purpose_function": "It delivers the right-side portion of main coverage from height, improving throw and giving more even level from front to back.", "practical_application": "A rigger flies the right hang on a motor, then the system tech sets its inter-box splay angles and level to cover the right side.", "category": "Loudspeaker Deployment", "related_terms": ["Left hang", "Right cluster", "Right main", "Line array", "Flown array", "Rigging hardware"], "common_mistakes": ["Mixing up audience right and stage right when labeling or aiming the hangs.", "UNSAFE: Flying a hang without verifying rigging points, load ratings, and a secondary safety where required.", "Setting different splay or level on the right hang than the left, causing a tonal or coverage mismatch."], "scenario_contexts": ["Flying line-array hangs left and right for an outdoor festival main stage.", "Adjusting the right hang's lower-box angles to reach the front seats."]}, "ba894efa-5973-4731-9f75-7f3b09dbf102": {"definition": "The main loudspeaker system on the right side (audience right) of a left/right sound reinforcement setup; the right half of the primary PA that, together with the left main, provides principal coverage of the main audience area.", "plain_english": "The right main is the primary speaker system on the right side. With the left main, it forms the two-sided PA the audience mostly hears. It can be a flown array or a stacked cluster.", "purpose_function": "It provides the right-side half of the main program coverage and completes the left/right pair that anchors the whole system.", "practical_application": "An engineer routes the main mix to left and right, then balances the right main's level, delay, and EQ against the left.", "category": "Loudspeaker Deployment", "related_terms": ["Left main", "Main array", "Right hang", "Right cluster", "Main system", "Main feed"], "common_mistakes": ["Confusing the right main (the speakers) with the right output channel of the console (the signal).", "Swapping audience right and stage right when patching or aiming the system.", "Not matching level and delay between the left and right mains, which skews the stereo image."], "scenario_contexts": ["Balancing the left and right mains during system tuning before doors open.", "Diagnosing a dead right main by tracing the signal from the console output onward."]}, "0efdf64f-9ad8-4c25-8312-233ceb3a657c": {"definition": "A limiter that acts on the RMS (root-mean-square, long-term average) level of a signal rather than its instantaneous peaks, using a relatively long time constant to constrain the sustained energy delivered to a loudspeaker and protect its voice coil from thermal overload. It is typically paired with a faster peak limiter that guards against cone excursion and clipping.", "plain_english": "An RMS limiter watches the average, sustained loudness of a signal, not quick spikes. It reacts slowly to stop long, loud passages from overheating a speaker's voice coil. A separate fast limiter handles the sudden peaks.", "purpose_function": "It protects loudspeaker drivers from long-term thermal damage by capping average power over time, complementing the peak limiter that handles short transients.", "practical_application": "A tech sets the RMS limiter threshold from the speaker's rated continuous power and a chosen time constant, so sustained content cannot overheat the coil.", "category": "Signal Processing", "related_terms": ["Peak limiter", "Threshold", "Voice coil", "Loudspeaker protection", "Dynamics processing", "System processor"], "common_mistakes": ["Confusing the RMS limiter with a peak limiter; RMS guards against heat, peak guards against excursion and clipping.", "Setting the RMS threshold too high, which lets sustained power overheat and destroy the driver.", "Using too short a time constant, so the RMS limiter acts like a peak limiter and squashes dynamics."], "scenario_contexts": ["Configuring driver-protection presets in a loudspeaker management processor.", "Protecting subwoofers from sustained low-frequency energy during a long DJ set."]}, "3aa7d85d-e874-43b1-aaee-8f7a572f7b6c": {"definition": "A password- or PIN-protected lock feature on audio equipment or its control software that prevents unauthorized users from changing settings, presets, or system configuration until the correct credential is entered, usually leaving controls in a read-only state while locked.", "plain_english": "A security lock is a password that stops other people changing a device's settings. Once locked, the controls become read-only until someone types the correct code. It keeps a tuned system from being altered by mistake.", "purpose_function": "It safeguards a configured system from accidental or unauthorized changes, keeping presets and tuning intact in shared or public installations.", "practical_application": "An installer locks a processor or amplifier with a password after tuning, so venue staff cannot alter limiter or crossover settings.", "category": "System Configuration", "related_terms": ["Preset", "System processor", "Setup Wizard", "Firmware", "User access level", "Recall"], "common_mistakes": ["Forgetting or failing to document the password, so the device must be factory-reset to regain access.", "Assuming the lock encrypts audio or the network; it only restricts access to the controls.", "Leaving the factory default password in place, which defeats the protection."], "scenario_contexts": ["Locking a DSP in a house of worship so volunteers cannot change the tuning.", "Password-protecting amplifier settings in a permanent installation."]}, "33ee0b2e-c20b-45f9-87ee-c75ccb4e7743": {"definition": "A guided, step-by-step software routine that walks a user through the initial configuration of a device or system, prompting for key parameters such as loudspeaker model, application, or channel assignments and applying appropriate default settings and presets automatically.", "plain_english": "A setup wizard is a step-by-step helper for first-time setup. It asks simple questions and fills in the right starting settings for you. It saves you from configuring everything by hand.", "purpose_function": "It speeds correct initial configuration and reduces errors by choosing suitable defaults and presets based on the user's answers.", "practical_application": "A tech runs the setup wizard on a new processor, selects the loudspeaker models and roles, and lets it load matching crossover and limiter presets.", "category": "System Configuration", "related_terms": ["Preset", "Security Lock (Password)", "System processor", "Crossover", "Limiter", "Firmware"], "common_mistakes": ["Assuming the wizard's defaults are final; they are a starting point that still needs tuning.", "Selecting the wrong loudspeaker model in the wizard, which loads unsuitable crossover or limiter presets.", "Skipping the wizard on a new device and missing important default protection settings."], "scenario_contexts": ["Commissioning a new loudspeaker management system for the first time.", "Quickly configuring a rental processor for a known loudspeaker package."]}, "1ff32604-2f61-4be6-9d89-d5c7e69e8fd1": {"definition": "A stage monitor loudspeaker or stack placed at the side of the stage and aimed across it, providing broad monitoring coverage for performers who move around, supplementing or replacing individual floor wedges. Side fills are typically larger, full-range systems delivering higher level over a wide area.", "plain_english": "A side fill is a monitor speaker set at the side of the stage, pointed across it. It lets performers hear the mix while moving, not just from one wedge. It is usually a bigger, louder speaker than a single floor monitor.", "purpose_function": "It gives performers consistent, wide monitor coverage across the stage, so they hear their mix even when they are away from a personal wedge.", "practical_application": "A monitor engineer places side fills at stage left and right, feeds them a dedicated mix, and sets level to cover the whole stage.", "category": "Stage Monitoring", "related_terms": ["Floor monitor", "Wedge", "Monitor mix", "In-ear monitor", "Drum fill", "Stage monitor system", "Side fills"], "common_mistakes": ["Running side fills too loud, which spills into vocal mics and worsens feedback and overall stage volume.", "UNSAFE: Driving side fills to very high levels for long shows, risking performer and crew hearing damage.", "Confusing side fills with front fills; side fills face the performers, front fills face the audience."], "scenario_contexts": ["Providing stage-wide monitoring for a lead singer who roams the stage.", "Supplementing wedges with side fills at a festival with fast changeovers."]}, "6a36d2ec-9034-40ce-9370-b874ef9961f3": {"definition": "Loudspeakers placed at the left and/or right sides of a stage, usually in the wings, aimed inward across the performance area to deliver a broad on-stage monitor mix. They supplement floor wedges and in-ear monitors, covering performers who move around the stage rather than a single fixed spot.", "plain_english": "Side fills are monitor speakers set at the sides of the stage. They point across the stage so the band can hear the mix. They cover performers who move around, unlike a wedge aimed at one place.", "purpose_function": "They give performers a wide, shared on-stage monitor mix across the whole stage, so people can still hear vocals and instruments when they move away from their own floor wedge.", "practical_application": "A monitor engineer places side fills on stands or stacks them in the wings, then feeds them a dedicated monitor mix kept separate from the front-of-house mix.", "category": "Stage Monitoring", "related_terms": ["Stage Wedge", "Floor monitor", "In-ear monitor", "Monitor mix", "Front-of-house", "Stage-lip fill"], "common_mistakes": ["Turning side fills up so loud that they spill into vocal microphones and cause feedback.", "Confusing side fills (side-stage monitors for performers) with front fills (small speakers for the front audience rows).", "UNSAFE: Stacking heavy side-fill cabinets too high or on an unstable base, so they can topple onto performers."], "scenario_contexts": ["Providing a band-wide monitor wash on a festival stage where musicians roam.", "Covering backing vocalists who step away from their own floor wedges."]}, "d3a29566-1692-4cd3-9af0-1fa1817a7244": {"definition": "A perforated or mesh panel, usually powder-coated steel and sometimes backed with acoustically transparent foam or cloth, fitted over the front of a loudspeaker enclosure. It protects the drivers and diaphragms from impact and debris while allowing sound to pass through with minimal acoustic effect.", "plain_english": "A speaker grille is the metal mesh cover on the front of a speaker. It shields the fragile cones and horns from knocks and dirt. Sound passes through the holes almost freely.", "purpose_function": "It protects the loudspeaker's drivers from impact, debris, and handling damage, and can hide the drivers for a cleaner look, without significantly blocking the sound.", "practical_application": "A technician checks the grille for dents that could rattle or press on the cone, and removes it to inspect or replace a blown driver.", "category": "Loudspeaker Hardware", "related_terms": ["Loudspeaker enclosure", "Driver", "Compression driver", "Horn", "Diaphragm"], "common_mistakes": ["Assuming a dented grille is only cosmetic, when a bent grille can buzz or press against the cone.", "Thinking the grille shapes the sound, when a proper grille is designed to be acoustically transparent.", "Reinstalling a grille with its foam missing or torn, letting dust reach the drivers."], "scenario_contexts": ["Inspecting stage-monitor grilles for dents after a load-out.", "Removing a grille to replace a blown compression driver in a repair shop."]}, "9fc9ffec-2b52-4157-8c2e-a77ac9a06ea4": {"definition": "A raised, load-rated deck or riser on which loudspeakers are set to elevate them above ground level, improving audience coverage and sightlines; it is commonly used to lift subwoofers or ground-stacked mains off the floor. The platform's rated load capacity and stability must suit the mass and footprint of the loudspeakers it carries.", "plain_english": "A speaker platform is a sturdy raised deck that holds speakers up higher. Lifting the boxes helps the sound reach more of the crowd. The deck must be rated to hold the weight safely.", "purpose_function": "It raises loudspeakers to a height that clears the audience and spreads coverage more evenly, while transferring the cabinets' weight safely into a stable, rated structure.", "practical_application": "A crew sets ground-stacked mains or subs on a rated riser, checks it is level and within its load limit, then secures the cabinets against tipping.", "category": "Loudspeaker Deployment", "related_terms": ["Ground stack", "Speaker tower", "Subwoofer array", "Riser", "Stage deck"], "common_mistakes": ["UNSAFE: Placing loudspeakers on a platform without checking its rated load capacity, risking structural collapse.", "UNSAFE: Stacking cabinets high on a platform without strapping or securing them, so they can topple.", "Using an unlevel or soft-ground platform, which lets the stack lean and shifts speaker aim."], "scenario_contexts": ["Raising subwoofers onto a rated deck at a corporate event for better coverage.", "Ground-stacking mains on a riser when no overhead rigging points are available."]}, "970d42ad-9027-490c-925c-78e071dcb997": {"definition": "The chosen location, height, and orientation of a loudspeaker mounted on a tripod or pole stand, selected to optimise audience coverage and gain-before-feedback while keeping the stand within its rated load and stable footprint. Position covers where the stand sits, how high the box is raised, and how it is aimed.", "plain_english": "This is where you put a speaker on its stand, how high you raise it, and where you aim it. Good placement covers the crowd and avoids feedback. The stand must stay stable and within its weight limit.", "purpose_function": "Correct stand position lifts the loudspeaker above the audience's heads for even coverage and keeps it clear of microphones to reduce feedback, while a stable base and rated load stop it tipping.", "practical_application": "A technician sets speakers on stands just behind and outside the mic line, raises them so the box clears the audience, and spreads the tripod legs on firm, level ground.", "category": "Loudspeaker Placement", "related_terms": ["Speaker stand", "Tripod stand", "Feedback", "Coverage angle", "Front-of-house", "Speaker platform"], "common_mistakes": ["Placing speakers behind or level with the microphones, which invites feedback.", "UNSAFE: Exceeding the stand's rated weight limit or raising the box too high, making the stand unstable and prone to tipping.", "UNSAFE: Spreading tripod legs on soft or uneven ground, or not extending them fully, so the stand can topple."], "scenario_contexts": ["Setting up a small PA on pole-mount stands for a conference or wedding.", "Repositioning stands to move the speakers ahead of the mics after feedback."]}, "d60d37a9-7c18-4572-b07b-92a1dd7dcf76": {"definition": "A ground-supported vertical structure, often a rated ground-support tower system, used to elevate and support loudspeakers at height, commonly at side-stage or delay positions in large-format and outdoor sound systems. As an engineered load-bearing and, outdoors, wind-loaded structure, it must be designed, assembled, and used to recognised entertainment-rigging standards.", "plain_english": "A speaker tower is a tall, engineered frame that holds speakers high off the ground. It is used at big shows and festivals to reach far-away crowds. It carries heavy loads and catches wind, so only trained riggers should build it.", "purpose_function": "It raises loudspeakers to the height needed for long-throw or delay coverage where flying from a roof or building is not possible, carrying the load safely into a ground-based rated structure.", "practical_application": "Riggers assemble a ground-support tower to the manufacturer's load and ballast specifications, then hoist a speaker array up it and secure it before the show.", "category": "Loudspeaker Deployment", "related_terms": ["Ground support", "Speaker platform", "Delay loudspeaker", "Line array", "Ground stack", "Ballast"], "common_mistakes": ["UNSAFE: Building or loading a speaker tower beyond its rated capacity, or without the required ballast or guying, risking collapse.", "UNSAFE: Erecting an outdoor speaker tower without a wind-management plan, so gusts can overturn it.", "Assuming any scaffold or truss can serve as a speaker tower, instead of an engineered system rated for the load."], "scenario_contexts": ["Setting delay towers midway back at an outdoor festival to reinforce distant seating.", "Ground-supporting side-stage arrays where no overhead rigging structure exists."]}, "bf56ffa1-596c-465f-bd2c-329099f3bd35": {"definition": "A loudspeaker system tuning preset, loaded into the amplifier or system processor, whose filters, crossover, limiter, and voicing are optimised for spoken-word reproduction rather than music. It emphasises clarity and intelligibility in the vocal frequency range while keeping the drivers protected, and is supplied by manufacturers in their preset libraries for a given loudspeaker model.", "plain_english": "A speech system preset is a ready-made settings file for a speaker. It tunes the speaker to make talking clear and easy to understand. You load it when the event is mostly speech, not music.", "purpose_function": "It configures a loudspeaker for maximum speech intelligibility by shaping tone toward the voice range, so announcements and presentations are clear, while keeping the drivers safely within limits.", "practical_application": "A technician loads the manufacturer's speech preset into the amplifier for a conference or house-of-worship talk, instead of a full-range music preset.", "category": "System Tuning", "related_terms": ["System preset", "Loudspeaker preset", "System processor", "Crossover", "Limiter", "Intelligibility"], "common_mistakes": ["Leaving a full-range music preset loaded for a speech event, which can sound boomy and less intelligible.", "Assuming a speech preset raises level, when it shapes tone and protection for voice, not loudness.", "Editing the preset's limiter settings without understanding them, removing the driver protection it provides."], "scenario_contexts": ["Loading a speech preset for a keynote presentation in a conference hall.", "Switching a house-of-worship system to a speech preset for the sermon."]}, "f1192196-73a8-4390-9dc3-fd84acc7af2f": {"definition": "A floor monitor loudspeaker with a wedge-shaped (angled) enclosure, placed on the stage floor and tilted upward toward a performer so they can hear a dedicated monitor mix of vocals and instruments. The wedge angle aims the sound at head height while keeping the cabinet low and out of sightlines.", "plain_english": "A stage wedge is a slanted speaker that sits on the stage floor. It tilts up toward a singer or player so they hear their own mix. Its low, angled shape keeps it out of the way and out of sight.", "purpose_function": "It gives a performer a personal on-stage monitor mix aimed up at their ears, so they can hear themselves and the band over the loud sound on stage.", "practical_application": "A monitor engineer sets a wedge at the front edge in front of each performer, dials a separate monitor mix for it, and rings out feedback before the show.", "category": "Stage Monitoring", "related_terms": ["Floor monitor", "Side fills", "Monitor mix", "In-ear monitor", "Feedback", "Ring out"], "common_mistakes": ["UNSAFE: Placing a wedge where it blocks a walkway or stage edge, creating a trip or fall hazard for performers.", "Aiming the wedge into a vocal microphone's rear pickup, which causes feedback.", "Pushing wedge level too high, which adds to stage volume and spill into open mics."], "scenario_contexts": ["Placing a vocal wedge at the front of the stage for the lead singer.", "Setting drum-fill and side wedges for a full band's monitor world."]}, "f0a1beff-7019-426b-9270-84c68adf2f33": {"definition": "A front-fill loudspeaker, or row of them, placed along the front edge (the lip) of the stage and firing down and out to cover the first few audience rows that the main arrays overshoot. Stage-lip fills provide near-field coverage and localisation for listeners closest to the stage.", "plain_english": "Stage-lip fills are small speakers along the front edge of the stage. They cover the first few rows that the big main speakers fly over. This keeps the closest audience from being left out.", "purpose_function": "They fill the coverage gap directly in front of the stage that the main arrays cannot reach, giving front-row listeners even level and sound that seems to come from the stage.", "practical_application": "A system tech spaces small fills along the stage lip, delays and levels them to blend with the mains, and aims them to cover the front rows without spilling onstage.", "category": "Fill Loudspeakers", "related_terms": ["Front fill", "Main array", "Delay loudspeaker", "Side fills", "Coverage", "Localisation"], "common_mistakes": ["Setting stage-lip fills too loud, so the front rows are louder than the rest of the house.", "Skipping delay alignment, so the fills and mains arrive out of time and smear the sound.", "Confusing stage-lip (front) fills for the audience with stage wedges or side fills for performers."], "scenario_contexts": ["Covering the front rows at a theatre where the flown mains start several rows back.", "Adding front fills along a runway or thrust-stage lip for the close audience."]}, "7e4c682e-c9dc-47e6-bd91-e67a9b314db8": {"definition": "A sound-reinforcement system deployed as two discrete channels, left and right, so that panned material reproduces a horizontal stereo image. In large-scale live sound only listeners near the centre line hear correct imaging, so many systems run dual-mono or use stereo mainly for effect rather than accurate localization across the whole audience.", "plain_english": "A stereo PA uses two sides, a left and a right. It can spread sound across the stage, like your headphones do. But only people sitting in the middle hear the effect properly. People far to one side mostly hear the near speaker.", "purpose_function": "It reproduces left/right panning and width for the audience, giving a sense of a wide sound stage instead of a single point of sound.", "practical_application": "A technician feeds left and right matrix outputs to the two main hangs, then decides how much true stereo panning to use given that side seats hear mostly the near side.", "category": "Main system format", "related_terms": ["Line array", "Subwoofer feed", "System crossover", "Coverage", "Dual-mono"], "common_mistakes": ["Assuming everyone in the room hears the stereo image, when only centre seats do", "Hard-panning key vocals or lead instruments, so one side of the room loses them", "Confusing a stereo PA with a system that simply has speakers on both sides fed the same mono signal"], "scenario_contexts": ["Deploying left and right main hangs for a concert that uses stereo effects", "Choosing between true stereo and dual-mono for even coverage in a wide room", "Mixing stereo keyboard or playback tracks into two main system channels"]}, "594cfda2-fd80-4541-840c-6bb941832380": {"definition": "Common shorthand for subwoofers: loudspeakers designed to reproduce only the lowest audio frequencies, typically below roughly 80-120 Hz. They are fed a low-passed signal and deployed to extend the low-frequency range and impact of a sound-reinforcement system.", "plain_english": "Subs is a nickname for subwoofers. These are the big speakers that make the deep, low notes you feel in your chest. They handle only the bass. The other speakers handle the higher sounds.", "purpose_function": "They extend a system's low-frequency output and headroom so bass instruments and effects are heard and felt, freeing the main speakers to handle mid and high frequencies.", "practical_application": "A technician places subs on the ground or flies them, feeds them a low-passed or aux-fed signal, and sets their level and crossover to blend with the main speakers.", "category": "Loudspeaker Systems", "related_terms": ["Subwoofer array", "Subwoofer feed", "System crossover", "Subwoofer arc", "Line array"], "common_mistakes": ["Setting sub level by feel and burying or losing the rest of the mix", "Ignoring the crossover point, so subs and mains overlap and cause a lumpy low end", "Placing scattered subs without a plan, creating uneven bass across the audience"], "scenario_contexts": ["Setting up ground-stacked subs across the front of a stage", "Blending sub level and crossover with the main hangs during system tuning", "Choosing how many subs a show needs for the room size and music style"]}, "380efe56-7b63-42e6-b4b1-07ceaf38a288": {"definition": "A subwoofer array configuration in which the enclosures are splayed physically along a curved arc so their combined low-frequency output broadens horizontal coverage. A curved array behaves like a virtual source set back behind it, widening the covered angle at the cost of some on-axis low-frequency addition compared with a straight (broadside) row.", "plain_english": "A subwoofer arc is a row of subs set in a gentle curve, like a fan. The curve spreads the bass wider across the audience. A straight row aims the bass more forward. The arc trades a little forward power for wider reach.", "purpose_function": "It widens the horizontal spread of low frequencies so bass reaches seats off to the sides, which a straight ground row would leave weaker.", "practical_application": "A technician angles a ground row of subs along a shallow arc when the venue is wide, checking coverage in prediction software before committing to the splay angles.", "category": "Subwoofer Array", "related_terms": ["Subwoofer array", "Subs", "Broadside array", "Coverage", "Splay angle"], "common_mistakes": ["Confusing a physical arc, which widens coverage, with electronic steering that redirects it", "Using too much curve, which weakens the forward output more than needed", "Assuming an arc removes the need to check coverage in prediction software"], "scenario_contexts": ["Curving a ground-stacked sub row to cover a wide festival audience", "Comparing an arc against a straight row for horizontal low-frequency spread", "Setting sub splay angles for a room wider than it is deep"]}, "f6606a1d-791e-48ac-8ea9-2b2ab63bb704": {"definition": "Two or more subwoofers deployed together in a defined geometry to control the directivity and coverage of low frequencies, which a single enclosure cannot do. Common forms include broadside (in-line) rows, arcs, end-fire, and cardioid/gradient arrays, each shaping where low-frequency energy goes and where it is cancelled.", "plain_english": "A subwoofer array is several subs arranged in a set pattern, not scattered. The pattern controls where the bass goes and where it is cancelled. This can push bass off the stage, or keep it off the sides, depending on the layout.", "purpose_function": "It gives the system control over low-frequency direction and evenness, letting the tech aim bass at the audience and reduce it on stage or in unwanted areas.", "practical_application": "A technician chooses a layout such as end-fire or cardioid, sets the spacing, polarity, and delay between subs, then verifies the pattern with measurement or prediction software.", "category": "Subwoofer Array", "related_terms": ["Subwoofer arc", "Cardioid subwoofer", "End-fire array", "Subs", "System crossover"], "common_mistakes": ["Spacing subs randomly, so they cancel unevenly and leave dead spots in the bass", "Skipping the delay or polarity settings that a cardioid or end-fire array depends on", "Believing more subs always means better bass, ignoring how the array geometry interacts"], "scenario_contexts": ["Building a cardioid sub array to keep bass off the stage and out of the backline", "Laying out an end-fire array to direct low frequencies toward the audience", "Spacing a broadside sub row for even coverage across the front of the crowd"]}, "31b121ec-0617-44cd-8c0c-ed7262d07c98": {"definition": "The signal routed specifically to the subwoofers, derived either from the low-frequency band of a system crossover or from a dedicated send such as an aux/matrix (an aux-fed sub arrangement). An aux-fed subwoofer feed lets the engineer choose exactly which sources reach the subs, independent of the main mix.", "plain_english": "The subwoofer feed is the signal sent just to the subs. It can be the low end split off from the main mix. Or it can be its own send. That way the engineer picks which instruments, like kick and bass, go to the subs.", "purpose_function": "It controls what low-frequency content reaches the subs and at what level, so bass energy comes only from sources that need it and the low end stays clean.", "practical_application": "A technician either low-passes the main output to the subs, or sets up an aux/matrix send and routes only kick, bass, and low synths to the subwoofer feed.", "category": "Signal routing", "related_terms": ["Subs", "Subwoofer array", "System crossover", "Aux-fed subs", "Matrix"], "common_mistakes": ["Sending the full mix to an aux-fed sub, which muddies the low end with sources that do not need it", "Forgetting the subwoofer feed level, so the subs are too loud or nearly silent", "Confusing an aux-fed feed with a crossover split and setting both by accident"], "scenario_contexts": ["Configuring an aux-fed sub send for a dance or hip-hop show", "Low-passing the main output to feed ground-stacked subs", "Choosing which instruments route to the subwoofer feed during soundcheck"]}, "9b0e1704-8c9b-4a02-a4cb-4f632500bd0b": {"definition": "The active (usually DSP-based) crossover that splits the full-range program signal into frequency bands and routes each band to the correct loudspeaker section, such as subs, low-mid, and high. It sets the crossover frequencies, slopes, and often the level, delay, and equalization for each output, and typically uses Linkwitz-Riley filters for a flat summed response through the crossover region.", "plain_english": "A system crossover splits the sound into frequency bands. It sends the low notes to the subs and the higher notes to the other speakers. This way each speaker only plays the range it handles best. It works like a sorting station for frequencies.", "purpose_function": "It directs each frequency band to the loudspeaker built for it, protecting drivers and letting each section work in its best range for cleaner, louder output.", "practical_application": "A technician sets the crossover points, slopes, and per-output level and delay in the system processor so the subs and mains blend smoothly and drivers are not overdriven.", "category": "Crossover design", "related_terms": ["Subwoofer feed", "Loudspeaker processor", "Linkwitz-Riley filter", "Subs", "Line array"], "common_mistakes": ["Setting a crossover point outside a driver's safe range, risking distortion or damage", "Using mismatched slopes or polarity, causing a dip or bump where the bands overlap", "UNSAFE: bypassing the processor's high-pass or limiter settings, which can drive drivers past their limits and cause failure"], "scenario_contexts": ["Setting sub-to-main crossover points in a loudspeaker processor", "Loading a manufacturer preset that includes the correct crossover and limiter settings", "Adjusting crossover slopes to smooth the blend between subs and mains"]}, "b0d8f3e3-acee-4df0-a340-b0802f253d16": {"definition": "A malfunction or error condition in a sound system that stops it working correctly, such as loss of signal, an open or shorted loudspeaker circuit, an amplifier in protection or reporting an error, or a network dropout. In networked systems the amplifier or processor reports the fault as a status, which the technician then localizes and clears.", "plain_english": "A system fault is something going wrong in the sound rig. It could be a dead speaker line, a lost signal, or an amp shutting itself off. The gear often flags the problem. The tech then finds the cause and fixes it.", "purpose_function": "Recognizing and reporting faults lets a technician quickly find and fix a failing part before or during a show, keeping the system working and reliable.", "practical_application": "A technician reads fault indicators on amplifiers or in the monitoring software, then works logically from source to output to isolate the failed cable, connector, or device.", "category": "Troubleshooting", "related_terms": ["Amplifier protection", "Signal chain", "System crossover", "Loudspeaker processor", "Network audio"], "common_mistakes": ["Swapping parts at random instead of tracing the signal chain step by step", "Ignoring an amplifier's protection or fault indicator instead of finding why it tripped", "UNSAFE: probing or working inside powered mains equipment while troubleshooting instead of following lockout/de-energizing practice"], "scenario_contexts": ["Tracing why one loudspeaker hang has gone silent during a show", "Reading amplifier fault status in the system monitoring software", "Isolating a network dropout that muted part of a distributed system"]}}$ape$::jsonb)) d WHERE g.id=d.id;
UPDATE glossary g SET definition = CASE WHEN d.p ? 'definition' THEN d.p->>'definition' ELSE g.definition END, plain_english = CASE WHEN d.p ? 'plain_english' THEN d.p->>'plain_english' ELSE g.plain_english END, purpose_function = CASE WHEN d.p ? 'purpose_function' THEN d.p->>'purpose_function' ELSE g.purpose_function END, practical_application = CASE WHEN d.p ? 'practical_application' THEN d.p->>'practical_application' ELSE g.practical_application END, category = CASE WHEN d.p ? 'category' THEN d.p->>'category' ELSE g.category END, related_terms = CASE WHEN d.p ? 'related_terms' THEN ARRAY(SELECT jsonb_array_elements_text(d.p->'related_terms')) ELSE g.related_terms END, common_mistakes = CASE WHEN d.p ? 'common_mistakes' THEN ARRAY(SELECT jsonb_array_elements_text(d.p->'common_mistakes')) ELSE g.common_mistakes END, scenario_contexts = CASE WHEN d.p ? 'scenario_contexts' THEN ARRAY(SELECT jsonb_array_elements_text(d.p->'scenario_contexts')) ELSE g.scenario_contexts END FROM (SELECT key::uuid AS id, value AS p FROM jsonb_each($ape${"11f50eab-211e-4d2f-8e41-4f68e343530e": {"definition": "The program signal supplied to the sound system, typically the main mix output routed from the mixing console through system processing to the amplifiers and loudspeakers. The term also describes a feed derived for another destination, such as a broadcast, recording, or press feed taken from the same system.", "plain_english": "The system feed is the main signal sent into the PA. It is the mix leaving the console that the speakers play. The same term can mean a copy sent elsewhere, like to a broadcast truck or a recorder.", "purpose_function": "It carries the finished mix from the console into the system's processing and amplification, and can also provide a matching signal to other users like broadcast or recording.", "practical_application": "A technician patches the console's main outputs into the loudspeaker processor as the system feed, and may split a separate feed to a broadcast or recording rig.", "category": "Signal routing", "related_terms": ["System crossover", "Subwoofer feed", "Splitter", "Matrix", "System handoff"], "common_mistakes": ["Confusing the system feed with the console's monitor or aux outputs and patching the wrong signal", "Providing a broadcast or press feed at the wrong level or without a limiter", "Losing the whole show by relying on a single unbacked system feed with no redundancy"], "scenario_contexts": ["Patching console main outputs into the loudspeaker processor", "Splitting a clean system feed to a broadcast or recording truck", "Setting up a redundant system feed path for a high-profile event"]}, "ebca6795-a561-4131-88ba-bb5bc4c9e9a3": {"definition": "The point in deployment at which a commissioned, tuned sound system is turned over from the system engineer or deploying crew to the mix engineer or client for use. It normally includes verifying coverage and tuning, confirming signal flow and redundancy, and communicating any limits or notes about the system's state.", "plain_english": "A system handoff is when the crew who built and tuned the PA give it over. The person who will mix on it then takes control. They check it works, then explain how it is set up. It is like handing over the keys after a car has been serviced and tested.", "purpose_function": "It ensures the mix engineer receives a verified, documented system and knows its layout, limits, and any issues, so the show starts on a known-good rig.", "practical_application": "The system tech walks the mix engineer through the tuning, signal flow, and any caveats, confirms the system passes checks, and then the mix engineer takes control for the show.", "category": "Deployment workflow", "related_terms": ["System feed", "System tuning", "Coverage", "Signal chain", "System crossover"], "common_mistakes": ["Handing over an untuned or unverified system and leaving problems for the mix engineer to find live", "Skipping documentation, so the operator does not know the signal flow or system limits", "Not confirming redundancy and backup paths before the handoff"], "scenario_contexts": ["Turning a tuned festival system over to a visiting act's engineer", "Handing a commissioned install to the client after verification", "Briefing the mix engineer on signal flow and limits before doors open"]}, "676d664f-dbaa-48cb-a86f-b1ad06476feb": {"definition": "A signal-routing and mixing structure in a console or system processor that combines multiple input buses or sources and routes them to multiple outputs, so each output (such as a loudspeaker zone) receives its own independently balanced blend of those sources. In deployment it lets main, fill, delay, and zone outputs each carry a tailored mix and level.", "plain_english": "A matrix is like a grid that mixes several sound sources. It sends a custom blend to each set of speakers. So the balcony speakers and the floor speakers can each get their own mix from the same show. It gives every area the balance it needs.", "purpose_function": "It lets one system feed many loudspeaker zones with independently adjusted mixes and levels, so each part of the venue gets the content and loudness it needs.", "practical_application": "A system tech assigns matrix outputs to delays, fills, and zones, then sets each output's source balance, level, and delay for that area.", "category": "Signal Routing", "related_terms": ["Matrix-fed system", "System zone", "Delay loudspeaker", "Fill loudspeaker", "Main output bus", "System processor"], "common_mistakes": ["Confusing a matrix, which mixes buses to outputs, with a simple output router or patchbay.", "Feeding all zones from a single output instead of separate matrix outputs, losing independent control.", "Forgetting that a matrix output is fed post its source bus, so muting that bus silences every matrix output fed from it."], "scenario_contexts": ["Setting up separate matrix outputs for main, delay, and under-balcony zones in a theatre.", "Providing a matrixed feed with reduced vocal level to an on-stage or press zone."]}, "cfcb3919-b55b-44f5-8fdd-2141c043069b": {"definition": "The process of adjusting the overall tonal balance of a sound system to a preferred, consistent target or house curve, using output EQ (and sometimes level) after measurement-based alignment. It shapes the subjective tonal character on top of the objective tuning rather than correcting measured errors.", "plain_english": "Voicing means shaping the overall tone of the whole PA to a chosen target sound. It is like setting the tone controls on a stereo so everything sounds the way you want. You do it after the measured tuning is finished.", "purpose_function": "It gives the system a consistent, pleasing tonal signature matched to the venue, program, or engineer's taste, beyond a flat measured response.", "practical_application": "After aligning and equalising the system to a flat target, a system engineer applies a voicing curve on the drive processor before soundcheck.", "category": "System Optimization", "related_terms": ["System tuning", "Tuning/Component Preset", "House curve", "Target curve", "System EQ", "System alignment"], "common_mistakes": ["Voicing by ear before completing measurement-based alignment, which bakes in room and array errors.", "Over-boosting lows and highs to a 'smiley' curve that falls apart once the room is full.", "Confusing voicing (subjective tonal shaping) with tuning (correcting measured response)."], "scenario_contexts": ["Applying a warmer house curve for a spoken-word event versus a brighter curve for dance music.", "Matching voicing across venues on a tour so front-of-house sounds consistent night to night."]}, "057692c1-81b6-427d-969c-d9bc130bb8de": {"definition": "A defined coverage area of a venue served by a specific loudspeaker subsystem such as the main, front-fill, under-balcony, or delay system, often given its own processing, level, and delay so coverage and timing can be managed per area. Zones sum acoustically in the room but remain individually controllable.", "plain_english": "A zone is one section of the audience covered by its own set of speakers. Each zone can have its own volume and timing. That way every part of the room hears the show clearly.", "purpose_function": "Dividing coverage into zones lets each area receive correct level, tonal balance, and time alignment, giving even sound across a large or complex venue.", "practical_application": "A tech assigns each subsystem to a zone output, then sets level and delay per zone so near and distant seats are aligned and even.", "category": "Loudspeaker Deployment", "related_terms": ["System matrix", "Delay loudspeaker", "Under-balcony fill", "Front-fill", "Coverage", "Time alignment"], "common_mistakes": ["Treating the whole venue as one zone, leaving balcony and rear seats under-covered.", "Forgetting to time-align a zone's delay to the main system, which causes audible echoes.", "Confusing a physical coverage zone with a mixing matrix output that feeds it."], "scenario_contexts": ["Splitting a theatre into orchestra, mezzanine, and balcony zones, each with its own delay and level.", "Setting up a separate zone for a lobby or overflow area fed from the main mix."]}, "2f0a3b5d-c407-44ba-8a57-39cb887367c5": {"definition": "A protection function in an amplifier or loudspeaker processor that limits long-term signal level in response to the estimated or measured temperature of the loudspeaker voice coil (or amplifier output stage), preventing thermal overload and voice-coil burnout. It models heat build-up over time rather than acting only on instantaneous peaks.", "plain_english": "A thermal limiter turns the sound down when a speaker's voice coil gets too hot. It protects the speaker from burning out during long, loud shows. Think of it as a heat guard that eases off before damage happens.", "purpose_function": "It protects loudspeaker drivers and amplifier output stages from heat damage by limiting sustained power once the modelled temperature nears a safe limit.", "practical_application": "A tech relies on the manufacturer's thermal limiter in the amp or processor preset; if it engages often, they add boxes or reduce drive rather than defeating it.", "category": "System Protection", "related_terms": ["Peak limiter", "Multiband limiter", "Tuning/Component Preset", "Voice coil", "Power compression", "Amplifier"], "common_mistakes": ["Defeating or raising the thermal limiter to gain level, which risks voice-coil burnout and speaker failure.", "Confusing a thermal limiter (slow, temperature-based) with a fast peak limiter that guards against excursion.", "Assuming the thermal limiter also protects against mechanical over-excursion, which needs a separate limiter."], "scenario_contexts": ["A sustained loud set causing the thermal limiter to pull down level as the voice coils heat up.", "Loading the manufacturer's approved preset so the thermal limiter matches that specific driver."]}, "b39a919a-c995-4576-85f3-e5dc65af356c": {"definition": "The distance over which a loudspeaker or array can effectively project sound while maintaining adequate level and intelligibility at the target area; 'long-throw' and 'short-throw' describe designs optimised for far and near coverage respectively. Throw depends on directivity, output capability, and the level loss with distance described by the inverse-square law.", "plain_english": "Throw is how far a speaker can send clear, loud enough sound. Long-throw boxes reach the back of a big room. Short-throw boxes cover the people close to the stage.", "purpose_function": "Describing throw lets designers choose and aim boxes so every part of the audience, near or far, gets enough level and clarity.", "practical_application": "A designer picks long-throw array elements for distant seats and adds short-throw fills for the front, checking predicted level against distance.", "category": "Loudspeaker Deployment", "related_terms": ["Directivity", "Line array", "Coverage angle", "Front-fill", "Delay loudspeaker", "Inverse-square law"], "common_mistakes": ["Expecting one box to both throw far and cover the front row, when near and far need different boxes.", "Ignoring inverse-square level loss, so distant seats end up too quiet.", "Confusing throw (how far the sound reaches) with coverage angle (how wide it spreads)."], "scenario_contexts": ["Selecting long-throw line-array elements to reach the rear of an arena.", "Adding short-throw down-fill boxes at the bottom of a hang for the closest seats."]}, "a81e8ab7-3ea0-4d37-b4b9-593b4e5b2330": {"definition": "A full-range or mid-high loudspeaker enclosure deployed above the subwoofers in a stacked or flown system, reproducing the mid and high frequencies (and often low-mids) while the subs handle the lows; also called a 'top'. In a ground stack it sits on the sub, and in a line array the 'tops' form the main hang separate from sub duty.", "plain_english": "A top box is the speaker that sits on top of the subwoofer and plays the mid and high sounds. The sub handles the deep bass below it. Together they cover the full range.", "purpose_function": "It reproduces the mid and high frequencies subwoofers cannot, completing the system's frequency range in a stacked or flown deployment.", "practical_application": "A tech stacks or flies the top box above the sub, aims it at the audience, and crosses it over to the sub at the recommended frequency.", "category": "Loudspeaker Deployment", "related_terms": ["Subwoofer", "Ground stack", "Crossover", "Full-range loudspeaker", "Line array", "Main array"], "common_mistakes": ["Placing the top box too low, so its output fires into the crowd's heads instead of over them.", "Setting the wrong crossover point between top and sub, leaving a gap or an overlap.", "UNSAFE: Ground-stacking a top box on a sub without securing it (straps or a proper stacking frame), risking it toppling onto people; follow the manufacturer's stacking and stability instructions."], "scenario_contexts": ["Ground-stacking tops on subs at a club show with no flying points.", "Flying the tops as the main hang while the subs are arrayed separately on the ground."]}, "4cd44dab-058d-4570-8f67-f87db556707d": {"definition": "A manufacturer-supplied DSP configuration (crossover, EQ, delay, and limiter settings) matched to a specific loudspeaker model or component, loaded into the amplifier or processor as the verified starting point for system tuning. Using the correct component preset keeps the driver within its designed response and protection limits.", "plain_english": "This is a ready-made settings file from the speaker maker for a specific speaker model. It sets the crossover, EQ, and limiters correctly for that box. You load it before you start tuning the system.", "purpose_function": "It provides the correct, protected baseline processing for a given loudspeaker, so tuning starts from a safe, flat, manufacturer-verified response.", "practical_application": "A system tech loads the matching component preset for each box into the amp or processor, then tunes the room on top of that baseline.", "category": "System Optimization", "related_terms": ["System Voicing", "System tuning", "Crossover", "Thermal Limiter", "System processor", "Loudspeaker preset"], "common_mistakes": ["Loading the wrong component preset (for a different model), so the driver's protection limiters no longer match and the driver can be damaged.", "Building custom tuning EQ but disabling or bypassing the preset's protection limiters.", "Assuming one generic preset works for every box, instead of using the correct per-model preset."], "scenario_contexts": ["Loading the correct amplifier preset for each loudspeaker model before a show.", "Updating component presets when the manufacturer releases a firmware or preset revision."]}, "64892fda-dfb1-4149-bb45-a7c355de364a": {"definition": "A supplementary loudspeaker or group mounted beneath or at the front edge of a balcony overhang to cover seats the main array cannot reach because the balcony blocks the direct sound path, usually time-delayed to the main system. It restores level and high-frequency clarity to the shadowed area under the balcony.", "plain_english": "These are small speakers under a balcony that cover the seats it blocks. The main speakers cannot reach under the overhang. A delay keeps their sound in time with the mains.", "purpose_function": "It provides adequate level and speech intelligibility to seats shadowed by a balcony, where the main system's direct sound is obstructed.", "practical_application": "A tech mounts under-balcony fills along the soffit, sets their level, and delays them to the mains so speech stays clear and in time.", "category": "Loudspeaker Deployment", "related_terms": ["Under-balcony loudspeaker", "Delay loudspeaker", "Fill loudspeaker", "Front-fill", "System zone", "Time alignment"], "common_mistakes": ["Not delaying under-balcony fills to the mains, which causes echo or smeared speech.", "Setting them too loud, so sound localises to the fills instead of the stage.", "Leaving the shadowed area uncovered, assuming the mains reach under the overhang."], "scenario_contexts": ["Covering rear orchestra seats tucked under a deep balcony in a theatre.", "Adding delayed under-balcony fills for speech intelligibility in a house of worship."]}, "930f53fd-100c-4a7f-ba74-c5867b06d5f0": {"definition": "A loudspeaker installed beneath a balcony or overhang to serve the seats in that shadowed area; it is the device that provides under-balcony fill, typically a compact full-range cabinet or soffit-mounted speaker time-aligned to the main system. Several are usually distributed along the soffit for even coverage.", "plain_english": "This is the actual speaker placed under a balcony to cover the seats it hides. It fills in sound where the main speakers cannot reach. It is timed to match the main system.", "purpose_function": "It delivers direct sound to listeners seated under an overhang, restoring the level and clarity lost where the main array is blocked.", "practical_application": "An installer mounts under-balcony loudspeakers into the soffit, aims them at the seats, and delays them to the mains.", "category": "Loudspeaker Deployment", "related_terms": ["Under-balcony fill", "Delay loudspeaker", "Fill loudspeaker", "System zone", "Distributed loudspeaker", "Time alignment"], "common_mistakes": ["Confusing the under-balcony loudspeaker (the device) with under-balcony fill (its coverage role).", "Installing too few units, so coverage under the overhang is patchy.", "Forgetting to time-align them to the mains, which smears speech."], "scenario_contexts": ["Installing recessed soffit loudspeakers under a mezzanine in a performing-arts centre.", "Retrofitting under-balcony loudspeakers to fix poor intelligibility beneath a deep balcony."]}, "02f018c9-e3cc-43f6-b69d-388098fe0196": {"definition": "A loudspeaker installed beneath a balcony overhang to cover the seats acoustically shadowed from the main system by the balcony soffit. It is typically a small, wide-dispersion cabinet mounted on the soffit and fed a delayed, level-matched signal so it time-aligns with the mains.", "plain_english": "A balcony overhang blocks the main speakers from reaching the seats below it. A small speaker under the balcony covers those shaded seats. It gets a delayed signal so its sound lines up with the main system.", "purpose_function": "It restores even coverage and intelligibility for under-balcony seats the main array cannot reach, so those listeners hear the same clear sound as the rest of the audience.", "practical_application": "A technician mounts under-balcony speakers along the soffit, then sets their delay and level so they blend with the mains instead of drawing attention to themselves.", "category": "Loudspeaker Deployment", "related_terms": ["Under-balcony fill", "Delay loudspeaker", "Fill loudspeaker", "Main array", "Time alignment", "Distributed system", "Under-balcony loudspeaker"], "common_mistakes": ["Not delaying the under-balcony speakers, so their sound arrives before the mains and smears clarity.", "Setting the level too high, which makes the fill obvious instead of blending it with the main system.", "Confusing an under-balcony speaker under the overhang with a front-fill at the stage lip."], "scenario_contexts": ["Covering rear stalls seats tucked beneath a deep balcony in a proscenium theatre.", "Adding delayed fills under a mezzanine overhang in a house of worship."]}, "42a78f9d-be0f-4f4f-9071-735a2d05ee41": {"definition": "A fill subsystem of one or more small loudspeakers dedicated to covering the seating shadowed beneath a balcony overhang. It is fed a delayed, level-matched signal so it seamlessly extends the main system's coverage into that zone.", "plain_english": "This is the job of covering seats hidden under a balcony. Small extra speakers do that work. They get a delayed signal so they blend in with the main speakers.", "purpose_function": "It fills the acoustic shadow created by the balcony soffit, delivering even level and intelligibility to seats the mains cannot cover directly.", "practical_application": "A tech designs the underbalcony fill as its own zone with its own delay and EQ, then tunes it to match the mains at the seats along the coverage boundary.", "category": "Loudspeaker Deployment", "related_terms": ["Under-balcony speaker", "Delay loudspeaker", "Fill loudspeaker", "Front-fill", "Main array", "Zoned system"], "common_mistakes": ["Treating underbalcony fill as an afterthought and skipping its delay alignment.", "Using cabinets with too narrow a pattern, which leaves gaps between the fill speakers.", "Running the fill too loud, so listeners localize to the nearest box instead of the stage."], "scenario_contexts": ["Designing a delayed underbalcony fill zone for a theatre's rear stalls.", "Tuning underbalcony fill in a concert hall so the overhang seats match the main hangs."]}, "28862412-40b3-4369-9b77-0ea013270dc0": {"definition": "In themed and haunted-attraction sound design, audio reproduced from loudspeakers or tactile (bass-shaker) transducers mounted beneath a floor or platform to create startle effects and felt vibration underfoot. It is typically low-frequency content triggered by show control in sync with a scare cue.", "plain_english": "This is sound played from under the floor in a haunted attraction. It is usually deep, rumbling bass you feel through your feet. It fires at the right moment to startle guests.", "purpose_function": "It adds a hidden, physical layer of fright by putting sound and vibration under guests' feet, where they do not expect it, heightening the startle of a scare.", "practical_application": "A technician mounts subwoofers or tactile transducers under a floor section and triggers the underfloor audio from the show-control system on each scare cue.", "category": "Themed Audio", "related_terms": ["Zoned Haunt Audio", "Tactile transducer", "Subwoofer array", "Show control", "Zoned system", "Localization"], "common_mistakes": ["Placing full-range speakers under the floor when low-frequency effects and tactile transducers deliver the felt-vibration effect.", "UNSAFE: Running speaker or trigger cabling across a walking surface without securing it, creating trip and fall hazards for guests and staff.", "UNSAFE: Driving underfloor audio at high levels for long periods near staff without hearing protection, risking noise-exposure injury."], "scenario_contexts": ["Rigging bass transducers under a floor panel so guests feel a rumble as a creature emerges.", "Triggering underfloor low-frequency hits from a show-control cue to punctuate a jump scare."]}, "7be1e3ef-aa17-43d5-b587-4814e7465705": {"definition": "A three-dimensional geometric (and often acoustic) representation of a venue's dimensions, surfaces, and audience areas, built in loudspeaker-prediction or acoustic-modeling software. Designers use it to predict coverage, SPL, and array aiming before physical deployment.", "plain_english": "This is a computer 3D model of a room and its seats. Designers load it into speaker-design software. They can then test speaker coverage on screen before hanging anything.", "purpose_function": "It lets designers predict how a loudspeaker system will cover the audience and set hang positions, splay, and aim on screen, which reduces guesswork and rework on site.", "practical_application": "A system designer imports or draws the venue model in prediction software, places the arrays, and reads the predicted SPL and coverage maps to finalize the rig plan.", "category": "System Design", "related_terms": ["Coverage", "SPL mapping", "Line array", "Splay angle", "Acoustic prediction", "Main array"], "common_mistakes": ["Trusting the venue model's predictions without verifying them with measurement in the real room.", "Building the model with inaccurate dimensions or missing surfaces, so predicted coverage does not match reality.", "Modeling only geometry and ignoring absorption, which gives unrealistic reverberation and SPL results."], "scenario_contexts": ["Designing a festival main hang in prediction software from a venue model before load-in.", "Predicting coverage in a modeled arena to decide how many delay towers are needed."]}, "a7c2e1b9-80e2-4fdb-a7e3-ef9f403f3dba": {"definition": "The degree to which a loudspeaker or array confines its radiated energy to a defined vertical coverage angle, directing sound toward the audience and away from ceilings and floors. In line arrays, vertical pattern control improves as array length increases relative to wavelength, so longer arrays maintain control to lower frequencies.", "plain_english": "This is how well a speaker aims its sound up and down. Good vertical control sends sound at the crowd, not the ceiling or floor. Taller line arrays keep this control down to lower notes.", "purpose_function": "It keeps sound energy on the audience and off reflective ceilings and floors, which improves clarity and gain-before-feedback by cutting wasted, reverberant energy.", "practical_application": "A designer chooses array length and splay angles to hold vertical pattern control across the needed frequency range, then aims the array so its controlled coverage lands on the seats.", "category": "Loudspeaker Coverage", "related_terms": ["Directivity", "Line array", "Coverage angle", "Splay angle", "Beamwidth", "Horizontal coverage"], "common_mistakes": ["Expecting a short line array to control low frequencies, when only longer arrays hold vertical pattern that low.", "Confusing vertical pattern control with simply aiming the box; control is about how tightly energy is confined.", "Adding too much down-tilt or splay and losing coverage to the back rows."], "scenario_contexts": ["Sizing a line array long enough to control the vertical pattern in a reverberant arena.", "Adjusting inter-box splay to keep the vertical pattern on the raked seating."]}, "14d9ff80-7090-4e69-8371-5c94fe8cd454": {"definition": "A protective cover or cap fitted over a loudspeaker, usually the front baffle, grille, or input panel, to shield the drivers, electronics, and connectors from rain, sun, and debris during outdoor use. It is designed to preserve acoustic performance while reducing weather exposure.", "plain_english": "This is a cover that protects an outdoor speaker from rain and sun. It shields the cones and the connectors. It is built so it barely changes the sound.", "purpose_function": "It lets a loudspeaker survive outdoor weather without water ingress or sun damage, which extends equipment life and helps prevent electrical faults in wet conditions.", "practical_application": "A crew fits weather hoods to flown or ground-stacked cabinets at an outdoor show, then routes and drip-loops cables so water cannot track into connectors.", "category": "Weather Protection", "related_terms": ["Weatherized loudspeaker", "IP rating", "Outdoor deployment", "Ground stack", "Flown array", "Cable management"], "common_mistakes": ["Assuming a weather hood makes a speaker fully waterproof, when it only reduces exposure and connectors still need protection.", "Leaving hoods off flown cabinets, which lets water pool and damages drivers or amplifiers.", "UNSAFE: Powering outdoor loudspeakers in wet conditions without weather protection, drip loops, and GFCI/RCD protection, risking water ingress and electric shock."], "scenario_contexts": ["Fitting rain hoods to a flown line array for an outdoor festival with rain forecast.", "Weather-hooding delay-tower speakers left rigged overnight outdoors."]}, "17f78dbc-11a0-481d-b1f1-8a52729b4f88": {"definition": "In haunted-attraction sound design, an audio system divided into independent playback zones, typically one per room, scene, or scare. Each zone has its own loudspeakers, content, and level, triggered by show control so effects and ambience localize to the space a guest is currently in.", "plain_english": "A haunted house is split into separate sound zones, one per room. Each zone has its own speakers and its own creepy sounds. The system plays the right sounds as guests move from room to room.", "purpose_function": "It keeps each scene's sound contained to its own space so effects feel local and believable, and lets operators trigger or change audio per zone without bleeding into neighboring rooms.", "practical_application": "A technician wires each room as an audio zone, loads scene-specific content, and links playback to sensors or show control so audio fires as guests enter each zone.", "category": "Themed Audio", "related_terms": ["Underfloor Scare Audio", "Zoned system", "Show control", "Localization", "Distributed system", "Delay loudspeaker"], "common_mistakes": ["Letting zones bleed into each other, so a guest hears the next room's scare before reaching it.", "Running all rooms from one shared feed, which loses the independent, localized effect that defines zoned haunt audio.", "UNSAFE: Running speaker and trigger cabling across walkways or sets without securing it, creating trip hazards in dark, crowded spaces."], "scenario_contexts": ["Programming per-room audio zones in a walk-through haunted house so each scene has its own soundscape.", "Using motion sensors to trigger a zone's scare audio only when guests enter that room."]}, "99764bd9-aa93-479b-93eb-16df87ba9090": {"definition": "A sound system whose output is divided into multiple independently controllable areas, or zones, each able to receive its own source, level, and on/off control. It is common in distributed commercial systems (paging and background music) and in large reinforcement rigs with separately tuned subsystems.", "plain_english": "This is a sound system split into separate areas called zones. Each zone can play its own audio at its own volume. For example, one room can be loud while another stays quiet.", "purpose_function": "It lets one system serve areas with different needs, such as separate music, paging, or level, so audio can be targeted and controlled area by area instead of everywhere at once.", "practical_application": "An installer assigns loudspeaker circuits to zones at the amplifier or DSP, then sets each zone's source and level so paging or music reaches only the intended areas.", "category": "Signal Distribution", "related_terms": ["Distributed system", "Constant-voltage system", "Paging system", "Matrix-fed system", "Zoned Haunt Audio", "Signal routing"], "common_mistakes": ["Confusing zones (separately controlled areas) with channels or with individual speakers.", "Overloading a zone amplifier by adding more 70-volt speaker taps than the amplifier's rated power.", "Wiring speakers into the wrong zone, so paging or music plays in areas it should not."], "scenario_contexts": ["Setting up separate background-music and paging zones for a retail store or airport terminal.", "Muting a bar zone for a paging announcement while music continues in the dining zone."]}, "015e9b45-d4ba-412a-b00b-da6b236cb978": {"definition": "Equalization that boosts high frequencies to offset the progressive absorption of high-frequency energy by air as sound travels over distance, with the amount of correction scaled to propagation distance and atmospheric conditions such as temperature and humidity. It is applied chiefly to long-throw or distant zones so their tonal balance matches nearer coverage.", "plain_english": "Air soaks up high sounds more than low sounds as they travel. So far-away speakers can sound dull. Air-compensation EQ turns the highs back up to fix this. It keeps distant seats sounding as bright as the front rows.", "purpose_function": "It restores the high-frequency balance lost to air absorption, so distant listeners hear the same tonal quality as those close to the loudspeakers.", "practical_application": "A system tech applies extra high-frequency boost, often through a processor's atmospheric-correction function, to long-throw or delay speakers covering far seating.", "category": "Equalization", "related_terms": ["Air absorption", "High-frequency attenuation", "Atmospheric correction", "System equalization", "Delay loudspeaker", "Time alignment"], "common_mistakes": ["Applying the high-frequency boost to the whole system instead of only the distant zones that need it, making near seats too bright.", "Ignoring temperature and humidity, which change how much high frequency the air absorbs over the course of a show.", "UNSAFE: Pushing large high-frequency boosts that drive tweeters or compression drivers past their limits, risking driver damage."], "scenario_contexts": ["Tuning an outdoor festival's long-throw hangs so the back field hears crisp highs on a hot, dry day.", "Setting atmospheric correction on a stadium delay tower covering seats far from the stage."]}, "3b463c22-d7f3-417c-ba60-99f55192bf36": {"definition": "A supplementary loudspeaker placed farther from the stage than the main system and fed a signal that is electronically delayed so its output arrives in time with (or slightly after) the main system's wavefront at the listener, preserving intelligibility and stage localization. It reinforces level and clarity in areas the mains cannot adequately cover.", "plain_english": "In a big venue, one set of speakers cannot cover everyone clearly. Extra speakers are placed deeper in the crowd. Their sound is delayed a little so it lines up with the main speakers. This keeps the sound clear while it still seems to come from the stage.", "purpose_function": "It extends clear, even coverage to distant audience areas, while a matched time delay keeps its sound aligned with the mains so listeners still localize the source to the stage.", "practical_application": "A tech positions delay loudspeakers down a long room, measures the distance to them, and sets a delay time plus a small offset so their output aligns with the arriving main signal.", "category": "Loudspeaker Deployment", "related_terms": ["Delay speaker", "Delay ring", "Fill loudspeaker", "Main array", "Haas effect", "Time alignment"], "common_mistakes": ["Setting no delay or too little, so the extra speaker arrives before the mains and the sound seems to come from it, not the stage.", "Measuring the distance wrong, which offsets the timing and smears clarity.", "Turning delay speakers up too loud, which pulls localization off the stage and can cause echo-like doubling."], "scenario_contexts": ["Covering the rear of a deep theatre where the main array's level has dropped off.", "Adding under-balcony delay speakers so seats beneath the balcony regain clarity."]}, "b7937aa1-ff81-4807-83f9-a862ead6758b": {"definition": "A group of delay loudspeakers arranged in an arc or ring at roughly equal distance from the stage, all fed the same delay time so they act together to cover an audience band that the mains or an inner ring can no longer reach. Very large or long venues use successive delay rings at increasing distances.", "plain_english": "A delay ring is a row of delayed speakers set in an arc across the crowd. Every speaker in the ring is about the same distance from the stage. They all get the same delay, so they line up with the sound from closer speakers. Huge venues use several rings, one behind another.", "purpose_function": "It gives even, aligned coverage to a whole distance band of the audience at once, letting very large venues be covered in zones by adding rings as distance grows.", "practical_application": "A system engineer defines delay rings at set distances and aligns each ring's delay to the sound arriving from the ring in front of it.", "category": "Loudspeaker Deployment", "related_terms": ["Delay loudspeaker", "Delay speaker", "Time alignment", "Main array", "Haas effect", "Fill loudspeaker"], "common_mistakes": ["Aligning a ring to the stage instead of to the loudspeakers just in front of it, which mis-times the handoff between zones.", "Spacing the loudspeakers in a ring too far apart, leaving coverage gaps between them.", "Forgetting that each ring farther back needs more delay than the ring in front of it."], "scenario_contexts": ["Covering a large flat festival field with two or three delay rings behind the main PA.", "Designing delay rings down a long convention hall so speech stays intelligible at the back."]}, "aab37f0b-91ff-45a7-b70a-491caecd8202": {"definition": "A common shorthand for a delay loudspeaker: a supplementary loudspeaker located farther from the stage than the mains and driven through a signal delay so its output arrives in time with the main system's wavefront at the listener, extending clear coverage without disturbing stage localization.", "plain_english": "A delay speaker is just another name for a delay loudspeaker. It is an extra speaker set deeper in the audience. Its sound is held back a moment so it matches the main speakers. That keeps far seats clear while the sound still seems to come from the stage.", "purpose_function": "It reinforces level and clarity where the mains fall short, while a matched delay preserves timing so listeners still hear the stage as the sound source.", "practical_application": "On the job a tech places a delay speaker partway down the room, measures its distance, and dials in a delay time so it aligns with the mains.", "category": "Loudspeaker Deployment", "related_terms": ["Delay loudspeaker", "Delay ring", "Fill loudspeaker", "Time alignment", "Haas effect", "Main array"], "common_mistakes": ["Assuming a delay speaker needs no delay time set, so it fires early and draws the image off the stage.", "Confusing a delay speaker, placed for distance coverage, with a fill speaker, placed to fill a coverage gap near the mains.", "Setting its level higher than needed, which causes noticeable echo and pulls localization to the speaker."], "scenario_contexts": ["Adding a delay speaker halfway back in a long club so the rear hears vocals clearly.", "Using delay speakers on poles down a banquet hall for a corporate presentation."]}, "3fac9ce8-0399-4054-89bd-dea63e9092ce": {"definition": "A small time delay applied to one driver or passband of a multi-way loudspeaker so that the acoustic outputs of its low-, mid-, and high-frequency drivers arrive together at the crossover region, compensating for the differing acoustic-centre depth and filter group delay of each driver. Correct alignment lets the drivers sum properly for a smooth frequency and phase response through crossover.", "plain_english": "A speaker box often has separate drivers for low, mid, and high sounds. These drivers sit at slightly different depths, so their sound can reach you at slightly different times. Driver alignment delay holds the closer driver back a tiny bit. Then all the drivers line up and blend smoothly where their ranges overlap.", "purpose_function": "It time-aligns the drivers of a multi-way loudspeaker at crossover so their outputs sum correctly, giving a smooth response and coherent phase instead of dips or lobing.", "practical_application": "In loudspeaker processor or crossover setup, a tech sets a per-output alignment delay, often in microseconds or samples, on the earlier-arriving driver to match the deeper one.", "category": "Time Alignment", "related_terms": ["Crossover", "Acoustic center", "Time alignment", "Group delay", "Phase alignment", "Loudspeaker processor"], "common_mistakes": ["Confusing driver alignment delay, which aligns drivers inside one box, with delay used to time-align separate loudspeakers across a room.", "Delaying the wrong driver, which increases the timing error instead of removing it.", "Ignoring the crossover's filter group delay, so the drivers still do not align at the crossover frequency."], "scenario_contexts": ["Setting per-driver delays when building a preset for a bi-amped two-way loudspeaker.", "Tuning a self-powered loudspeaker's internal DSP so its horn and woofer align at crossover."]}, "caad2a96-fcb8-4ec2-a9ca-6c3db00ae696": {"definition": "A graphic equalizer providing 31 fixed frequency bands centred on the ISO standard one-third-octave centre frequencies from 20 Hz to 20 kHz, each band adjusted by its own slider to boost or cut level (commonly up to about plus or minus 12 dB). The slider positions form a visual, or graphic, picture of the applied response curve.", "plain_english": "A 31-band graphic EQ is a row of 31 sliders. Each slider controls one narrow band of sound, from deep bass up to high treble. Sliding one up boosts that band; sliding it down cuts it. The shape the sliders make shows how the sound is being changed.", "purpose_function": "It lets an operator shape a system's overall frequency response across the full audio range using fixed, evenly spaced bands, commonly to tune a room or reduce feedback.", "practical_application": "A tech patches a 31-band graphic EQ across a system or monitor output and pulls down the specific bands that ring or sound harsh.", "category": "Equalization", "related_terms": ["Parametric EQ", "Graphic equalizer", "One-third-octave", "Feedback", "System equalization", "Constant-Q"], "common_mistakes": ["Assuming each slider affects only its labelled frequency, when neighbouring bands overlap and interact.", "Boosting many bands at once, which raises overall level and eats headroom instead of shaping tone.", "Using broad graphic-EQ bands to notch narrow feedback, when a parametric filter would be more precise."], "scenario_contexts": ["Ringing out a stage monitor by pulling down the graphic-EQ bands that feed back.", "Setting a house tuning curve on the mains during system alignment."]}, "756cf358-4ab8-46e1-a147-54d996c6bf79": {"definition": "A delay located in the input (pre-crossover) section of a loudspeaker management processor, or at the input of a console or DSP channel, applied to the incoming signal before it is routed to the individual outputs so it affects every output fed from that input equally. It is used to time-align the whole processor or channel with other sources, unlike output delay, which is set separately per driver or zone.", "plain_english": "Many sound processors split one incoming signal to several outputs. Input delay sits before that split. So it delays every output at once by the same amount. Engineers use it to line up a whole device with other speakers or sources.", "purpose_function": "It offsets an entire input signal in time so a processor or channel aligns with other systems or sources, applying one common delay ahead of any per-output delays.", "practical_application": "A tech enters an input delay on a loudspeaker processor to align a subsystem with the mains, then fine-tunes each output's own delay afterward.", "category": "Time Alignment", "related_terms": ["Output delay", "Driver Alignment Delay", "Time alignment", "Loudspeaker processor", "Signal delay", "Input EQ"], "common_mistakes": ["Confusing input delay, which affects all outputs together, with output delay, which is set per driver or zone.", "Adding input delay to align one subsystem while forgetting it also shifts every output of that processor.", "Overlooking a device's own fixed processing latency when calculating the delay time needed."], "scenario_contexts": ["Aligning a delay-tower processor to the main PA using its input delay.", "Offsetting a subwoofer processor's input to align the low end with the tops."]}, "27978f29-490b-495c-8bb1-08a163010bfd": {"definition": "Equalization in the input (pre-crossover) section of a loudspeaker management processor, or at the input stage of a console or DSP channel, applied to the whole incoming signal before it is split to the individual outputs so it shapes the tone of every output equally. It is distinguished from output EQ, which is applied separately to each driver or zone.", "plain_english": "Input EQ changes the tone of a signal as it enters a device. It sits before the signal is split to several outputs. So one setting affects all of those outputs at once. It is used for broad, overall tone shaping.", "purpose_function": "It provides common tonal shaping, or system equalization, for an entire input before per-output processing, so one adjustment sets the overall voicing of everything fed from that input.", "practical_application": "A tech uses input EQ on a loudspeaker processor to set the overall house curve, leaving output EQ for driver-specific correction.", "category": "Equalization", "related_terms": ["Output EQ", "Input Parametric EQ", "System equalization", "Graphic EQ (31-band)", "Loudspeaker processor", "Voicing"], "common_mistakes": ["Using input EQ to fix a single driver's response, when that belongs in output EQ.", "Confusing input EQ, which shapes all outputs together, with output EQ, which is per driver or zone.", "Stacking heavy boosts on input EQ, which reduces headroom for every output at once."], "scenario_contexts": ["Dialing an overall system tone curve in the processor's input EQ during tuning.", "Applying a broad low-cut on input EQ to protect all outputs from subsonic energy."]}, "069dda06-6ef3-45e9-bb5b-1b5cb0e79b48": {"definition": "A parametric equalizer located in the input section of a loudspeaker management processor or channel, providing bands with adjustable centre frequency, gain, and bandwidth (Q) that shape the whole incoming signal before it is routed to the outputs. Being pre-crossover it affects all outputs equally, and it offers finer, more surgical control than fixed-band graphic input EQ.", "plain_english": "A parametric EQ lets you pick the exact frequency to change, how much, and how wide. Input means it works on the signal before it splits to several outputs. So one filter shapes all outputs together. It is used for precise fixes, like removing a single problem tone.", "purpose_function": "It gives precise, fully adjustable tonal correction to an entire input signal before per-output processing, useful for notching problem frequencies or setting an overall response with exact filters.", "practical_application": "A tech places a narrow parametric filter in the processor's input EQ to notch a room resonance affecting the whole system.", "category": "Equalization", "related_terms": ["Parametric EQ", "Input EQ", "Output EQ", "Q (bandwidth)", "System equalization", "Loudspeaker processor"], "common_mistakes": ["Setting an extremely narrow, high-gain filter to fix a broad tonal issue, which sounds unnatural.", "Confusing input parametric EQ, which affects all outputs, with per-driver output parametric EQ.", "Boosting instead of cutting to solve a resonance, which wastes headroom and can worsen ringing."], "scenario_contexts": ["Notching a persistent room mode with a narrow input parametric filter during system tuning.", "Using input parametric EQ to gently correct the overall system response after measurement."]}, "d3721121-166b-4812-adb1-6ae770b5f789": {"definition": "In a loudspeaker-management processor or system DSP, output delay is a fixed time delay applied to one output channel, set in milliseconds or an equivalent distance. It is used to time-align that output with others, correcting the arrival-time offset between drivers in a multi-way loudspeaker, between subwoofers and main loudspeakers, or between a distant delay loudspeaker and the main system.", "plain_english": "Output delay holds back the sound on one speaker output by a tiny amount of time. Sound from separate speakers can reach a listener at slightly different moments. A small delay lines them up so they arrive together. This makes the whole system sound tighter and clearer.", "purpose_function": "It makes signals from separate drivers or loudspeakers arrive at the listener at the same time, so they combine correctly instead of smearing or partly cancelling. Proper time alignment restores clarity and a solid, coherent response through crossover regions.", "practical_application": "A technician measures the arrival-time offset between two sources with a dual-channel analyzer such as Smaart, then sets the output delay so both arrive together, for example delaying a rear delay loudspeaker to match sound coming from the main array.", "category": "Time Alignment", "related_terms": ["Time Alignment", "Crossover", "Subwoofer Alignment", "Delay Tower", "Phase", "Latency"], "common_mistakes": ["Confusing output delay (system time alignment) with device latency, which is the fixed processing delay through the unit itself", "Adding delay to the wrong output, so the two sources move further apart in time instead of together", "Setting delay from a distance value alone without accounting for how air temperature changes the speed of sound", "Trying to fix a polarity or phase error with delay when a driver or crossover is actually wired in reverse"], "scenario_contexts": ["Aligning subwoofers with the main loudspeakers around the crossover frequency during system tuning", "Delaying a rear delay loudspeaker so its sound arrives in step with the main system", "Time-aligning the low, mid, and high drivers inside a multi-way loudspeaker"]}, "cac514e1-6cc4-4167-af29-b0af890307a4": {"definition": "Output parametric EQ is a bank of parametric equalizer filters applied to a single output channel of a loudspeaker-management processor or console, each filter adjustable in center frequency, gain, and bandwidth (Q). Placed after the crossover, it corrects the frequency response of the specific driver or loudspeaker fed by that output, tuning the loudspeaker itself before room effects are addressed.", "plain_english": "A parametric EQ lets you boost or cut chosen bands of sound. You set the exact frequency, how much to change it, and how wide the change is. Output parametric EQ does this on one speaker output. Techs use it to smooth the tone of that speaker before dealing with the room.", "purpose_function": "It flattens and voices the response of each loudspeaker output on its own, correcting driver and cabinet colorations so every part of the system shares one consistent, intended tonal balance.", "practical_application": "A technician measures a single output with a dual-channel analyzer, then sets parametric filters on that output to tame resonances and match it to a target response, keeping speaker EQ and room EQ on separate stages.", "category": "Equalization", "related_terms": ["System equalization", "Parametric Equalizer", "Crossover", "Graphic EQ", "Output Delay", "Target Curve"], "common_mistakes": ["Using output EQ to fix a room problem instead of the loudspeaker's own response, combining two different tuning jobs on one stage", "Applying large boosts to force a flat curve, which wastes amplifier headroom and stresses the drivers", "Setting a very narrow, high-gain filter that only corrects one measurement position rather than the whole coverage area", "Confusing output (per-loudspeaker) EQ with the input or master EQ that affects the entire mix"], "scenario_contexts": ["Voicing each driver output of a multi-way system to a target response during tuning", "Notching a resonant peak measured on one specific loudspeaker output", "Matching the tonal balance of main and fill loudspeakers that run on different output channels"]}, "95c7cab2-6b17-4ac0-a8fc-acd457fb1b5c": {"definition": "System equalization is the process of adjusting the frequency response of a complete sound reinforcement system with equalizers so its output matches a chosen target response over the listening area. It corrects for the combined tonal effects of the loudspeakers, their interaction, and the room, and is usually the final tuning stage after levels, crossover, and time alignment are set.", "plain_english": "Every room and speaker system colors the sound in its own way. Some notes come out too loud and others too quiet. System equalization uses EQ to even out that tone. The goal is a balanced sound that matches a chosen target across the whole audience.", "purpose_function": "It delivers a consistent, natural tonal balance to the audience despite the coloration added by the loudspeakers and the room, giving mix engineers a neutral, predictable starting point.", "practical_application": "A technician measures the system with a calibrated microphone and analyzer, compares the response to a target curve, and applies mostly broad EQ to correct the overall tone across the coverage area rather than at one seat.", "category": "Equalization", "related_terms": ["Output Parametric EQ", "Graphic EQ", "Target Curve", "Time Alignment", "Room Acoustics", "Pink Noise"], "common_mistakes": ["Trying to equalize away a feedback ring or a room reflection that placement or time alignment should fix instead", "Equalizing to flat at a single microphone position rather than optimizing across the whole audience area", "Using large boosts to fill dips caused by cancellation, which EQ cannot fix and which only wastes headroom", "Confusing system-wide equalization with EQ applied to individual mixer input channels"], "scenario_contexts": ["Tuning a concert PA to a house target curve before doors open", "Correcting an installed system's tonal balance for speech intelligibility in a house of worship", "Comparing the measured response to a pink-noise reference and smoothing the largest peaks with EQ"]}, "0bbe1b85-cae3-47f6-8b36-1d73dc2a7a46": {"definition": "A party-line intercom circuit that carries two-way (duplex) audio and the DC power for its stations on a single unbalanced pair (with common shield), so every station shares one common talk-and-listen bus. In the classic Clear-Com pinout, pin 2 carries the DC power, pin 3 the duplex audio, and pin 1 the shield/ground.", "plain_english": "2-wire is an intercom wiring style. One cable pair carries both the talking and the listening audio. The same pair also sends power to the beltpacks. Everyone shares one line, like a group phone call.", "purpose_function": "It lets many intercom stations share one simple cable run for talk, listen, and power, keeping crew communication cheap and easy to wire.", "practical_application": "A stage crew daisy-chains beltpacks along a single mic cable back to a 2-wire party-line base station for hands-free show communication.", "category": "Intercom Systems", "related_terms": ["4-wire", "Party-line intercom", "Beltpack", "Intercom base station", "Duplex audio"], "common_mistakes": ["Thinking 2-wire literally means two physical wires, when the shielded pair usually runs in a three-pin XLR cable", "Connecting a 2-wire port straight to a 4-wire port without a 2-wire/4-wire interface to translate between them", "Confusing a 2-wire intercom line with an ordinary unbalanced two-conductor audio cable"], "scenario_contexts": ["Wiring a party-line communication loop for a theatre stage crew", "Adding beltpacks to a Clear-Com or RTS base station", "Interfacing a 2-wire party-line to a digital matrix through a 2-wire/4-wire converter"]}, "978c517f-15d2-44f9-b6bf-483c6f22945c": {"definition": "An intercom or audio circuit that uses one conductor pair for the send (transmit) signal and a separate pair for the receive signal, keeping the two directions fully independent.", "plain_english": "4-wire is an intercom wiring style. It uses one pair of wires to send audio and a second pair to receive it. Talking and listening travel on separate lines. This keeps the two directions from mixing.", "purpose_function": "It separates send and receive audio so each direction stays clean over long runs and connects easily to matrices, digital systems, and telecom links.", "practical_application": "A technician patches a 4-wire port from a digital intercom matrix to a codec or fiber link, wiring transmit and receive as two independent audio pairs.", "category": "Intercom Systems", "related_terms": ["2-wire", "Intercom matrix", "Party-line intercom", "Duplex audio", "2-wire/4-wire interface"], "common_mistakes": ["Confusing the two audio pairs of a 4-wire circuit with the four physical conductors inside some 2-wire cables", "Wiring the transmit and receive pairs reversed, so no audio passes in one or both directions", "Connecting a 4-wire port straight to a 2-wire party-line without a converter between them"], "scenario_contexts": ["Linking an intercom matrix to a remote broadcast site over a codec", "Interfacing a digital communication system to a telephone hybrid", "Trunking two separate intercom systems together with a 4-wire link"]}, "828df40e-4968-42cd-a85a-2f39a97037d3": {"definition": "A powered RF device that splits the signal from one antenna, or an A/B antenna pair, to feed multiple wireless receivers, using built-in amplification to offset the insertion loss the split would otherwise cause.", "plain_english": "An active antenna splitter shares one antenna's signal among several wireless receivers. It has a built-in amplifier. That amp makes up for the signal lost when the feed is split. So many receivers can run from just one pair of antennas.", "purpose_function": "It lets several receivers share a single antenna pair without the level loss a plain split would cause, cutting antenna clutter in multi-channel wireless setups.", "practical_application": "A technician feeds one pair of remote paddle antennas into a rack's active splitter to serve many wireless microphone receivers from a single antenna position.", "category": "Antenna Systems", "related_terms": ["Antenna distribution system", "Passive splitter", "Antenna bias voltage", "Antenna cascade", "Active antenna", "Wireless receiver"], "common_mistakes": ["Assuming more amplification always helps, when excess gain can overload receiver front ends and raise the noise floor", "Overlooking that the splitter must cover the RF band of every receiver connected to it", "Forgetting that an active splitter needs power, unlike a passive splitter"], "scenario_contexts": ["Racking a multi-channel wireless microphone system off one antenna pair", "Replacing several standalone whip antennas with one remote antenna feed", "Distributing a shared antenna signal across a full receiver rack"]}, "7cd9a255-0ca3-4fbb-97d8-553beb864288": {"definition": "A wireless microphone or monitor system that transmits audio as an analog frequency-modulated (FM) RF carrier, typically using companding to fit the audio's dynamic range into the available RF bandwidth.", "plain_english": "An analog wireless system sends sound through the air as an FM radio signal, like an FM station. It squeezes the audio to fit the radio channel, then expands it again at the receiver. This trick is called companding.", "purpose_function": "It carries microphone or monitor audio without a cable, using proven FM radio technology to give very low latency and simple, reliable transmission.", "practical_application": "A technician deploys an analog UHF wireless microphone for a presenter, setting transmitter and receiver to the same frequency and gain-staging so the companding stays clean.", "category": "Wireless Systems", "related_terms": ["Digital wireless system", "Companding", "Frequency modulation", "Squelch", "Wireless receiver", "UHF band"], "common_mistakes": ["Assuming analog wireless does no processing, when companding shapes the audio and can breathe if levels are set wrong", "Expecting the same crowded-spectrum efficiency from analog systems as from digital ones", "Confusing low latency with higher audio fidelity"], "scenario_contexts": ["Choosing analog wireless for the lowest latency in a live in-ear monitor mix", "Coordinating analog UHF microphone frequencies at an event", "Troubleshooting companding artifacts on an older wireless microphone"]}, "820acba8-1250-4442-b042-f00e9cc9c617": {"definition": "A DC voltage, commonly 12 V, applied to an antenna coaxial line by a receiver or antenna distribution unit to remotely power active antennas or in-line RF amplifiers over the same cable that carries the RF signal.", "plain_english": "Antenna bias voltage is DC power sent up the antenna cable. It travels on the same coax that carries the radio signal. This power runs active antennas or signal boosters at the far end. It saves running a separate power wire.", "purpose_function": "It powers remote active antennas and in-line amplifiers through the existing coax, so no separate power run is needed to antennas mounted far from the rack.", "practical_application": "Before a show, a technician confirms the receiver or distribution unit's antenna bias, often 12 V DC, is switched on so the active antennas at the far end power up.", "category": "Antenna Systems", "related_terms": ["Active antenna", "In-line amplifier", "Antenna distribution system", "Active antenna splitter", "Coaxial cable", "Bias tee"], "common_mistakes": ["Feeding bias voltage into a passive antenna or a DC-shorting device, which can trip protection or damage the port", "Forgetting to enable bias power, so the active antennas stay dead and the signal drops out", "Assuming every antenna port supplies bias, when many ports are passive and provide none"], "scenario_contexts": ["Powering active antennas from a receiver's DC-enabled antenna port", "Feeding an in-line amplifier over a long coaxial run", "Diagnosing a dead active antenna caused by disabled bias voltage"]}, "59a6b177-f412-4b29-a0c3-95a98198a7e2": {"definition": "A daisy-chain arrangement in which the RF output of one antenna distribution unit feeds the input of another, letting several distributors share a single antenna pair to serve a larger number of receivers.", "plain_english": "Antenna cascade means linking antenna distributors in a chain. The signal passes out of one unit and into the next. This lets you feed more receivers from just one pair of antennas. Each link is like adding another box to the chain.", "purpose_function": "It expands a wireless system beyond one distributor's outputs, so many receivers can still run from a single set of antennas.", "practical_application": "A technician connects the cascade port of one antenna distribution unit to a second unit, expanding a four-channel rack to eight channels off one antenna pair.", "category": "Antenna Systems", "related_terms": ["Antenna distribution system", "Active antenna splitter", "Antenna bias voltage", "Wireless receiver", "Coaxial cable"], "common_mistakes": ["Cascading too many stages, so accumulated loss and noise degrade the RF signal", "Powering cascaded units from one supply and overloading it instead of using separate supplies", "Confusing the cascade loop-through port with a standard receiver output"], "scenario_contexts": ["Expanding a wireless rack past four or eight channels off one antenna pair", "Linking a second antenna distribution unit for a large multi-channel show", "Planning antenna infrastructure for a broadcast or theatre wireless system"]}, "a2fa25bc-7ca8-4538-affb-3603e3c60755": {"definition": "A device that takes the signal from an A/B diversity antenna pair and splits it into multiple buffered outputs so several wireless receivers can share the same antennas, usually also distributing DC power to those receivers.", "plain_english": "An antenna distribution system shares one pair of antennas among many wireless receivers. It splits the signal into several outputs. It often sends power to the receivers too. This means you need far fewer antennas.", "purpose_function": "It reduces antenna clutter and RF problems by letting a whole receiver rack work from one well-placed antenna pair instead of dozens of small antennas.", "practical_application": "A technician mounts one pair of antennas near the stage, then feeds a rack of wireless microphone receivers through an antenna distribution system in the equipment room.", "category": "Antenna Systems", "related_terms": ["Active antenna splitter", "Antenna cascade", "Antenna diversity", "Antenna bias voltage", "Wireless receiver", "Passive splitter"], "common_mistakes": ["Mixing receivers of different RF bands on one distributor that cannot cover all of them", "Ignoring that each passive split adds insertion loss unless the unit is active", "Placing antennas poorly and expecting the distributor to fix a weak signal"], "scenario_contexts": ["Racking a multi-channel wireless microphone system for a conference", "Cleaning up antenna clutter behind a receiver rack", "Feeding remote paddle antennas to a bank of receivers"]}, "0032fbdd-b67a-43e5-ac2d-6e84bca2bbdb": {"definition": "A reception technique that uses two or more antennas separated in space or polarization, so that when one antenna sits in a multipath signal null the other still receives a usable signal, greatly reducing dropouts.", "plain_english": "Antenna diversity uses two antennas instead of one. Radio signals can bounce and cancel out at certain spots. If one antenna lands in a dead spot, the other usually does not. The receiver uses whichever antenna is stronger.", "purpose_function": "It fights multipath dropouts by giving the receiver more than one antenna, so a signal null at one antenna rarely kills reception.", "practical_application": "A technician spaces a receiver's two antennas apart, or angles them differently, to keep a moving performer's microphone from dropping out.", "category": "Antenna Systems", "related_terms": ["Antenna diversity combiner", "Multipath", "Dropout", "Diversity reception", "Antenna distribution system", "Wireless receiver"], "common_mistakes": ["Placing the two antennas too close together, which removes the diversity benefit", "Assuming diversity mainly adds range, when it chiefly cures multipath dropouts", "Blocking one antenna behind metal or bodies, which defeats spatial diversity"], "scenario_contexts": ["Setting up a true-diversity wireless microphone receiver for a stage show", "Curing intermittent dropouts as a performer moves around", "Positioning two receive antennas for best coverage in a reflective room"]}, "47a37641-ec11-43da-a6a6-2c976d39151c": {"definition": "The circuit or device in a diversity receiver that continuously evaluates the signals from two or more receiver chains, each with its own antenna and tuner, and either selects the best one or combines them, for example by maximal-ratio combining, into a single output for demodulation.", "plain_english": "A diversity combiner is the part that manages a receiver's two antennas. It checks both signals all the time. It picks the stronger one, or blends them together. The goal is one steady, clean signal with no dropouts.", "purpose_function": "It turns the outputs of multiple antenna paths into one reliable signal, so the listener never hears the receiver switching between antennas.", "practical_application": "Inside a true-diversity receiver, the combiner cross-fades or sums the two antenna feeds so the audio stays seamless even as RF conditions shift.", "category": "Antenna Systems", "related_terms": ["Antenna diversity", "Maximal-ratio combining", "Diversity reception", "Multipath", "Wireless receiver", "Squelch"], "common_mistakes": ["Thinking every diversity receiver truly combines, when some only switch antennas and can click", "Assuming the combiner can rescue two equally poor antenna signals", "Confusing signal combining with simply joining two antenna cables together"], "scenario_contexts": ["Comparing switching-diversity with true-diversity or ratio-combining receivers", "Explaining why a quality diversity receiver has no audible antenna switching", "Specifying receivers for a demanding multipath-heavy venue"]}}$ape$::jsonb)) d WHERE g.id=d.id;
UPDATE glossary g SET definition = CASE WHEN d.p ? 'definition' THEN d.p->>'definition' ELSE g.definition END, plain_english = CASE WHEN d.p ? 'plain_english' THEN d.p->>'plain_english' ELSE g.plain_english END, purpose_function = CASE WHEN d.p ? 'purpose_function' THEN d.p->>'purpose_function' ELSE g.purpose_function END, practical_application = CASE WHEN d.p ? 'practical_application' THEN d.p->>'practical_application' ELSE g.practical_application END, category = CASE WHEN d.p ? 'category' THEN d.p->>'category' ELSE g.category END, related_terms = CASE WHEN d.p ? 'related_terms' THEN ARRAY(SELECT jsonb_array_elements_text(d.p->'related_terms')) ELSE g.related_terms END, common_mistakes = CASE WHEN d.p ? 'common_mistakes' THEN ARRAY(SELECT jsonb_array_elements_text(d.p->'common_mistakes')) ELSE g.common_mistakes END, scenario_contexts = CASE WHEN d.p ? 'scenario_contexts' THEN ARRAY(SELECT jsonb_array_elements_text(d.p->'scenario_contexts')) ELSE g.scenario_contexts END FROM (SELECT key::uuid AS id, value AS p FROM jsonb_each($ape${"f352a1c9-3b26-4703-9c60-6f5c0259493a": {"definition": "The orientation of the electric-field component of the radio wave that an antenna transmits or receives, described as vertical, horizontal, or circular. Maximum energy transfer occurs when the transmitting and receiving antennas share the same polarization, while a cross-polarized mismatch causes significant signal loss.", "plain_english": "Polarization is the direction a radio wave points as it travels. Antennas work best when the sending and receiving antennas point the same way. If one is upright and the other is sideways, the signal gets much weaker.", "purpose_function": "It defines how transmit and receive antennas should be oriented relative to each other so the maximum amount of RF energy is captured, and it explains dropouts that come from antenna misalignment.", "practical_application": "A technician keeps receiver and bodypack antennas in similar orientation, and expects some mismatch loss as performers move, which is one reason diversity receivers are used.", "category": "Antenna Systems", "related_terms": ["Antenna diversity", "Antenna gain", "Omnidirectional antenna", "Dropout", "Line of sight", "RF signal strength"], "common_mistakes": ["Assuming antenna orientation does not matter as long as the antennas are close together", "Confusing polarization with the antenna's radiation pattern (directionality), which is a separate property", "Mounting all antennas horizontally when handheld and bodypack transmitters usually radiate closer to vertical, increasing dropouts"], "scenario_contexts": ["A presenter's bodypack antenna bends horizontal under clothing, causing polarization-mismatch dropouts", "Angling receiver antennas to catch signals from performers who move and turn on stage", "Troubleshooting signal loss that changes as a performer rotates"]}, "52085c9e-50d7-4752-af45-d4f27bce3efe": {"definition": "Low-voltage DC power (typically about 12 V DC) sent up the coaxial feedline from a receiver, antenna distribution system, or bias tee to operate an active (amplified) antenna or an in-line RF amplifier. It is carried on the same coax as the RF signal so no separate power cable is needed at the antenna.", "plain_english": "Some antennas have a built-in amplifier that needs electricity to run. That power travels up the same coax cable that carries the radio signal. This saves you from running a separate power wire out to the antenna.", "purpose_function": "It powers active antennas and in-line boosters over the signal coax so their amplifiers can offset cable loss, without needing a separate power feed at the antenna location.", "practical_application": "A technician enables antenna DC power (bias) on the receiver or distribution unit only when using active antennas, and disables it for passive antennas to avoid faults.", "category": "Antenna Systems", "related_terms": ["Active antenna", "Antenna distribution system", "Coaxial cable", "In-line amplifier", "Cable loss", "Antenna bias voltage"], "common_mistakes": ["Feeding DC bias to a passive antenna or a shorted cable, which can trip the port's protection or cause a fault", "Forgetting to turn on antenna power, so an active antenna delivers weak or no signal", "Assuming every antenna needs bias power when passive antennas do not"], "scenario_contexts": ["Powering a remote active directional antenna at the rear of a hall through its coax run", "Enabling bias voltage on an antenna distribution unit for amplified paddle antennas", "Diagnosing a dead active antenna caused by disabled DC power on the distro"]}, "56c7e0cb-e892-4fb1-b584-da16d9d827df": {"definition": "The process of choosing the appropriate antenna type, gain, radiation pattern, and polarization, such as omnidirectional versus directional, for a given wireless deployment based on coverage area, distance, and the local RF environment.", "plain_english": "Antenna selection means picking the right antenna for the job. A wide-coverage antenna suits close, all-around use. A focused antenna reaches farther in one direction. The best choice depends on distance, coverage, and interference.", "purpose_function": "Choosing the correct antenna type and placement maximizes usable range and signal quality while rejecting noise and interference arriving from unwanted directions.", "practical_application": "A technician selects omnidirectional antennas for nearby all-around coverage and directional antennas to aim gain toward a distant stage or to reject off-axis interference.", "category": "Antenna Systems", "related_terms": ["Omnidirectional antenna", "Directional antenna", "Antenna gain", "Antenna diversity", "Antenna placement", "RF coverage"], "common_mistakes": ["Using a high-gain directional antenna where wide coverage is needed, which creates dead spots", "Adding antenna gain to fix a range problem that is really caused by obstruction or interference", "Ignoring polarization and pattern when selecting antennas"], "scenario_contexts": ["Choosing directional antennas to reach a stage far from the receiver rack", "Selecting omnidirectional antennas for in-the-round theatre coverage", "Switching to directional antennas to reject interference from a nearby transmitter"]}, "dfe2c385-15b6-4924-a723-963d1492d91c": {"definition": "A function that silences the audio output of a wireless system, either automatically when the receiver loses RF or the signal falls below the squelch threshold, or manually via a transmitter or receiver mute control, preventing noise or unwanted sound from reaching the output.", "plain_english": "Audio mute turns off the sound coming out of a wireless receiver. It can happen on its own when the radio signal is lost. That way you do not hear a burst of static. A performer can also mute a transmitter by hand.", "purpose_function": "It protects the sound system and audience from noise bursts when RF is lost, and lets performers or operators cut a channel's audio without powering the unit off.", "practical_application": "A technician relies on automatic mute (squelch) to keep dropouts quiet and uses a transmitter's mute switch so a presenter can go silent between segments.", "category": "Receiver Functions", "related_terms": ["Squelch", "Dropout", "RF signal strength", "Transmitter", "Receiver", "Signal-to-noise ratio"], "common_mistakes": ["Confusing audio mute with switching the transmitter off, which drops the RF link and can leave the frequency open to interference", "Setting squelch so it mutes too late, letting noise through during dropouts", "Forgetting a transmitter is muted and troubleshooting the wrong part of the signal chain"], "scenario_contexts": ["A bodypack mutes automatically when the performer walks out of range", "A presenter uses the mute switch during a question-and-answer break", "Squelch mutes the receiver to stop static when a transmitter battery dies"]}, "9d1b795a-26ec-47f3-b35f-e0d22de19b69": {"definition": "An automated software or system process that calculates a set of mutually compatible operating frequencies for multiple wireless channels, avoiding intermodulation products and known local interference so all channels can operate at the same time without interfering with one another.", "plain_english": "When you use many wireless mics at once, their signals can clash. Automatic frequency coordination is software that picks a clean channel for each one. It does the tricky math so the channels do not interfere.", "purpose_function": "It replaces manual calculation by computing intermodulation-free, interference-free frequency plans, letting large multi-channel systems operate reliably in a crowded RF environment.", "practical_application": "A technician runs coordination software or an on-device tool to generate a compatible frequency plan and deploy it across all receivers before a show.", "category": "Frequency Coordination", "related_terms": ["Intermodulation", "Automatic frequency scan", "Backup frequencies", "Frequency plan", "RF spectrum", "TV white space"], "common_mistakes": ["Assuming one coordination lasts forever, when the local RF environment changes by venue and by day", "Ignoring nearby TV broadcast channels and other spectrum users during coordination", "Mixing gear from different bands or regions without re-coordinating"], "scenario_contexts": ["Coordinating dozens of channels for a theatre production before opening night", "Using networked software to push a frequency plan to every receiver at once", "Re-coordinating on tour because each city has different occupied TV channels"]}, "7f23a14c-471a-483e-805f-a78ba5ac7e0f": {"definition": "A receiver or system function that automatically sweeps a frequency band to measure RF activity and identify clear, unoccupied channels, which can then be assigned to a wireless link to avoid interference.", "plain_english": "Automatic frequency scan lets a wireless receiver listen across its band. It finds which channels are busy and which are open. Then you can pick an empty channel instead of guessing.", "purpose_function": "It surveys the local RF spectrum so operators can quickly choose clear frequencies without external test equipment, reducing the chance of interference.", "practical_application": "A technician runs a scan on arrival at a venue to see which frequencies are occupied, assigns clear channels, and often syncs the chosen frequency to the transmitter by infrared.", "category": "Frequency Coordination", "related_terms": ["Automatic frequency coordination", "RF spectrum", "Interference", "Squelch", "Frequency plan", "Spectrum analyzer"], "common_mistakes": ["Scanning with your own nearby transmitters switched on, which hides truly open channels behind your own signals", "Scanning once and never rescanning when the RF environment changes", "Treating a scan as full coordination when it does not calculate intermodulation among your own channels"], "scenario_contexts": ["Scanning the band during load-in at an unfamiliar venue", "Finding an open channel after a nearby broadcast starts causing interference", "Running the receiver's scan, then infrared-syncing the clear frequency to the bodypack"]}, "82960362-f226-4a47-888e-8bd29b43b3a9": {"definition": "A system capability in which a wireless link automatically moves to a pre-coordinated backup frequency when interference or a fault is detected on the active channel, keeping the link running without manual intervention.", "plain_english": "This feature watches the channel a wireless mic is using. If interference hits, it moves the mic to a clean backup channel by itself. It happens fast, so the audience should not hear a problem. You do not have to change anything by hand.", "purpose_function": "It preserves an uninterrupted audio link during live use by detecting interference and shifting both ends of the link to a known-good backup frequency automatically.", "practical_application": "A technician pre-loads coordinated backup frequencies and enables the feature so a critical channel self-heals if interference appears during a show.", "category": "Frequency Coordination", "related_terms": ["Backup frequencies", "Automatic frequency coordination", "Interference", "Frequency diversity", "Dropout", "Transmitter"], "common_mistakes": ["Enabling auto-switching without loading valid, coordinated backup frequencies for it to use", "Assuming the transmitter can follow instantly with no control link between receiver and transmitter", "Believing it replaces good initial coordination rather than backing it up"], "scenario_contexts": ["A key vocal channel jumps to a backup frequency when a two-way radio causes interference", "A broadcast system self-heals during a live shot when a new signal appears", "Using interference-avoidance switching on a high-stakes microphone that cannot drop out"]}, "d68989c0-add4-48eb-bcd5-dd9e3a446c10": {"definition": "Pre-coordinated spare operating frequencies held in reserve for a wireless system, ready to be used if the primary frequency suffers interference or a dropout during operation.", "plain_english": "Backup frequencies are spare radio channels you set aside ahead of time. If your main channel gets interference, you switch to a spare. It is like having a second lane ready when your lane gets blocked.", "purpose_function": "They provide a tested, interference-free fallback so a channel can be recovered quickly instead of going dead when its primary frequency is compromised.", "practical_application": "A technician coordinates and stores backup frequencies for critical channels, then switches to one manually or automatically if interference appears.", "category": "Frequency Coordination", "related_terms": ["Backup frequency assignment", "Automatic frequency switching", "Automatic frequency coordination", "Interference", "Frequency plan", "Automatic frequency scan"], "common_mistakes": ["Choosing backups that were not coordinated, so they conflict with other active channels", "Keeping only one backup for many channels instead of enough spares", "Never testing the backups, so they fail when actually needed"], "scenario_contexts": ["Switching a lapel mic to a backup channel when interference appears mid-speech", "Storing spare frequencies for the lead vocal before a festival set", "Reaching for a coordinated backup when a nearby broadcaster starts transmitting"]}, "56965780-3f3b-417c-abee-6f51bcf125a2": {"definition": "The process of allocating and storing specific pre-coordinated backup frequencies to individual wireless channels or devices, so each has a verified, conflict-free alternate to switch to if its primary frequency fails.", "plain_english": "This is the step of giving each wireless mic its own set of spare channels. You pick spares that do not clash with anything else and save them to the device. That way each mic has a safe channel to jump to.", "purpose_function": "It ensures every channel has dedicated, intermodulation-free fallbacks loaded in advance, so switching to a backup does not create new interference.", "practical_application": "During coordination a technician assigns and loads backup frequencies into each receiver, and the paired transmitter, often through networked software, ready for manual or automatic switching.", "category": "Frequency Coordination", "related_terms": ["Backup frequencies", "Automatic frequency coordination", "Automatic frequency switching", "Frequency plan", "Intermodulation", "Automatic frequency scan"], "common_mistakes": ["Assigning the same backup to several channels, which causes a clash if more than one switches to it", "Assigning backups without checking them against active channels for intermodulation", "Loading backups on the receiver but not enabling the path for the transmitter to follow"], "scenario_contexts": ["Assigning several coordinated spares to each of many channels in coordination software", "Loading backup frequencies into receivers during pre-production for a broadcast", "Setting per-channel backups so automatic switching has valid targets to move to"]}, "f338a274-c2f8-4cfd-8ba4-07a6e09427cd": {"definition": "A spare wireless bodypack (or handheld) transmitter kept configured and ready to replace a primary transmitter that fails during a performance. It is typically preset to the same frequency, gain, and channel-name settings as the unit it protects so it can be swapped in with minimal disruption.", "plain_english": "A backup pack is a spare wireless transmitter kept ready during a show. If a performer's main pack breaks or dies, the crew swaps in the spare. It is set up the same way, so the sound keeps working.", "purpose_function": "It provides redundancy for critical wireless channels so that a single transmitter failure, dead battery, or physical damage does not take a performer off air.", "practical_application": "A theatre or broadcast tech pre-programs backup packs, keeps them charged offstage, and hands one to a performer or dresser for a quick swap during a costume change or break.", "category": "Wireless Systems", "related_terms": ["Bodypack transmitter", "Handheld transmitter", "Backup frequencies", "Wireless microphone system", "RF dropout"], "common_mistakes": ["Assuming a backup pack will work instantly without first pre-programming it to the correct frequency and settings", "Leaving backup packs uncharged or with depleted batteries so they fail when actually needed", "Storing the backup on an active frequency that clashes with another live channel, causing interference when switched on"], "scenario_contexts": ["A lead actor's transmitter fails mid-scene and the crew swaps in a preset backup pack during a blackout", "Broadcast crews keeping duplicate packs on key presenters for live news", "Handing a charged backup to a performer during a costume change when the main pack battery is low"]}, "6f43c3ae-73ec-4756-861e-7ac11bc6fe94": {"definition": "A radio-frequency filter built from one or more resonant metal cavities that passes (or rejects) a narrow band of frequencies with high selectivity (high Q) and low insertion loss. In wireless audio it protects receivers from strong out-of-band signals, such as TV, LTE, or nearby transmitters, that could cause front-end overload or intermodulation.", "plain_english": "A cavity filter is a metal box tuned to let only certain radio channels pass through. It blocks strong unwanted signals nearby, like a TV or phone tower. This keeps a wireless mic receiver from getting overloaded.", "purpose_function": "It sharpens the receiver front-end's selectivity, rejecting powerful nearby signals so they cannot desensitize the receiver or generate intermodulation interference.", "practical_application": "An RF tech installs a tunable cavity or bandpass filter between the antenna and the receiver or distribution unit in crowded RF environments, such as near broadcast towers or in large multichannel systems.", "category": "Antenna Systems", "related_terms": ["Bandpass filter", "Intermodulation", "Front-end overload", "Antenna distribution system", "Filter Q"], "common_mistakes": ["Confusing a cavity filter with an antenna, when it is a tuned filter placed in the signal path", "Leaving the filter mistuned so it attenuates the wanted band along with the interference", "Assuming a filter can remove intermodulation already generated downstream, rather than preventing overload at the front end"], "scenario_contexts": ["Adding a cavity filter near a TV broadcast tower to stop receiver overload", "Filtering out a strong LTE signal that is desensitizing wireless mic receivers", "Protecting a large multichannel wireless rig at a stadium from strong out-of-band transmitters"]}, "0dbcf71a-fa70-4a85-b98f-c42b3fd6d2cb": {"definition": "A wave polarization in which the electric-field vector rotates at a constant magnitude, tracing a circle perpendicular to the direction of propagation as the wave travels; the rotation sense may be right-hand or left-hand. A circularly polarized antenna (e.g., a helical) can receive a linearly polarized transmitter at any orientation with an approximately 3 dB fixed loss, reducing polarization-mismatch dropouts.", "plain_english": "Normally a radio wave points one steady direction. In circular polarization the wave spins as it travels. An antenna like this can pick up a moving transmitter no matter how it is tilted. That helps stop dropouts when performers turn.", "purpose_function": "It lets a receive antenna capture a transmitter's signal regardless of the transmitter's orientation, trading a small fixed loss for steadier reception from moving or rotating performers.", "practical_application": "A tech deploys a circularly polarized (helical) antenna to reduce polarization-related dropouts when performers move and rotate on stage.", "category": "Antenna Systems", "related_terms": ["Antenna polarization", "Linear polarization", "Helical antenna", "Antenna diversity", "RF dropout"], "common_mistakes": ["Thinking circular polarization eliminates all dropouts, when it only removes polarization-mismatch loss", "Ignoring the roughly 3 dB loss when a circularly polarized antenna receives a linearly polarized signal", "Mismatching right-hand and left-hand circular antennas between transmit and receive, which causes large loss"], "scenario_contexts": ["Using a helical circularly polarized antenna for a dance or acrobatic act where performers rotate", "Reducing dropouts from handheld mics that performers wave and tilt", "Covering a stage where bodypack antenna orientation changes constantly"]}, "513f7a4d-b4cf-44da-99bf-4f7747ca18cf": {"definition": "A wireless intercom beltpack worn by a crew member that connects to a communications (intercom) system, providing headset talk and listen so the user can hear and speak on one or more intercom channels. It is the wireless equivalent of a wired party-line beltpack.", "plain_english": "A com pack is a small radio box a crew member wears on a belt. It links to a headset so they can talk and listen to the rest of the team. It works like a walkie-talkie built into the show's intercom.", "purpose_function": "It gives mobile crew hands-free, real-time two-way communication on the production intercom without a cable tether.", "practical_application": "A stage manager or camera operator wears a com pack with a headset to stay on cues and coordinate with the director during a live event.", "category": "Intercom Systems", "related_terms": ["Comms", "Wireless intercom", "Beltpack", "Party-line intercom", "Headset"], "common_mistakes": ["Confusing a com pack (crew intercom) with a wireless mic bodypack, which carries program audio, not crew talk", "Leaving the pack on the wrong intercom channel and missing cues", "Forgetting to charge or replace batteries before a long show"], "scenario_contexts": ["A stage manager calling cues to crew over a wireless com pack", "Camera operators on a live broadcast coordinating shots on comms", "Spotlight operators taking cues on a headset com pack during a concert"]}, "699d413a-536b-43ce-9715-b3f0be565f96": {"definition": "Short for communications; the intercom/talkback system that production crew use to coordinate before and during a live event or broadcast. It may be wired (party-line or matrix) or wireless, and links stations such as director, stage manager, camera, audio, and lighting through headsets and beltpacks.", "plain_english": "Comms is short for communications. It is the private intercom crew use to talk to each other during a show. People wear headsets so the director, camera, and stage crew can stay in sync.", "purpose_function": "It provides a dedicated, low-latency channel for crew coordination and cueing that is kept separate from the program audio the audience hears.", "practical_application": "A technician patches and tests comms stations and headsets before a show so every department can hear cues clearly during the performance.", "category": "Intercom Systems", "related_terms": ["Com pack", "Wireless intercom", "Party-line intercom", "Talkback", "Matrix intercom"], "common_mistakes": ["Confusing comms (crew talkback) with the program or PA audio the audience hears", "Feeding comms audio into the main mix by patching the wrong channel", "Assuming all comms stations share one channel when systems can split into several"], "scenario_contexts": ["A director calling camera shots to crew over comms during a live broadcast", "Stage manager and deck crew coordinating a scene change on comms", "Audio and lighting teams cueing each other on separate comms channels"]}, "11b36e35-fac4-4fdb-96f5-0fa90d3e09c4": {"definition": "A set of operating frequencies chosen so that multiple wireless systems can run at the same time without interfering with one another. The frequencies are spaced and selected so that neither the carriers nor their intermodulation products fall on any channel in active use.", "plain_english": "Compatible frequencies are radio channels that can all run together without clashing. They are picked so their signals stay out of each other's way. This keeps every wireless mic clear.", "purpose_function": "They allow many wireless microphones, in-ear systems, and intercoms to operate simultaneously by avoiding direct-frequency clashes and intermodulation interference.", "practical_application": "A tech uses coordination software or a manufacturer's frequency chart to assign a compatible set before a multichannel show, then loads those frequencies into each system.", "category": "Frequency Coordination", "related_terms": ["Frequency coordination", "Intermodulation", "Backup frequencies", "Automatic frequency scan", "Coordination mode"], "common_mistakes": ["Spreading channels evenly instead of calculating an intermodulation-free set", "Reusing a manufacturer's preset group in an RF environment it was not designed for", "Adding one more system to a coordinated set without re-checking compatibility"], "scenario_contexts": ["Assigning a compatible set for 24 wireless channels at a corporate event", "Loading a coordinated frequency group into mics and in-ear systems before a concert", "Re-coordinating when a venue's local TV channels differ from the last city"]}, "7588b152-f3da-424c-b193-2e7cef43865d": {"definition": "An operating state in wireless receivers or coordination software used to scan the RF environment and calculate or assign a set of compatible, intermodulation-free frequencies for the systems in use. In this state the equipment gathers spectrum data and derives clear channels rather than passing program audio.", "plain_english": "Coordination mode is a setup state on wireless gear or its software. In it, the system looks at which radio channels are busy. Then it works out clear channels that will not clash. It is used before a show, not during it.", "purpose_function": "It automates or guides frequency coordination, letting a tech find and assign non-interfering channels quickly instead of choosing them by hand.", "practical_application": "Before doors, a tech puts the receiver or software into coordination mode to scan the band and generate a compatible frequency plan to deploy to all systems.", "category": "Frequency Coordination", "related_terms": ["Frequency coordination", "Compatible frequencies", "Automatic frequency scan", "Intermodulation", "Backup frequencies"], "common_mistakes": ["Running coordination mode with nearby transmitters left on, which hides channels that are actually free", "Coordinating at a different location or time than the show, missing changes in the local RF", "Assuming coordination mode also deploys the frequencies, when each unit still must be set"], "scenario_contexts": ["Putting a receiver into coordination mode to scan a new venue's spectrum", "Using software coordination mode to build a frequency plan for a festival", "Re-running coordination mode when interference appears during setup"]}, "c96f7122-62f8-45f3-82d2-40b33e5d19fe": {"definition": "A reception technique that uses two or more antennas (and often two receiver sections) at different positions or orientations so that when one path suffers a fade or dropout, another still provides a usable signal. The receiver selects or combines the strongest available signal to maintain steady reception.", "plain_english": "Diversity means using more than one antenna to catch a wireless signal. Radio signals can fade or drop in some spots. If one antenna gets a weak signal, another usually gets a good one. The receiver picks the better one.", "purpose_function": "It reduces dropouts caused by multipath fading and antenna-position nulls by giving the receiver more than one chance to receive a clean signal.", "practical_application": "A tech uses a diversity receiver with two spaced antennas so a performer moving around the stage does not cause audio dropouts.", "category": "Antenna Systems", "related_terms": ["Antenna diversity", "Diversity mode", "Multipath", "RF dropout", "True diversity"], "common_mistakes": ["Placing the two diversity antennas too close together, which reduces the benefit", "Thinking diversity mainly increases range, when its core job is to fight dropouts", "Assuming any receiver with two antenna jacks combines them properly without confirming it is true diversity"], "scenario_contexts": ["A singer walking the stage while a diversity receiver prevents dropouts", "Spacing two antennas apart to cover a reflective, multipath-heavy room", "Choosing a diversity receiver for a moving presenter over a non-diversity unit"]}, "5d37d1fe-c860-41dc-879c-bca3edad2f5b": {"definition": "The specific method a diversity receiver uses to handle its multiple antenna signals, such as antenna (switching) diversity using a single receiver and an RF switch, true diversity using two dedicated receiver sections that select or combine, ratio/maximal-ratio combining, or phase diversity. It is often a selectable receiver setting that determines how the two RF paths are compared or combined to produce the output.", "plain_english": "Diversity mode is the setting that tells a receiver how to use its two antennas. Some just switch to whichever antenna is stronger. Others blend both signals together. The goal each way is fewer dropouts.", "purpose_function": "It defines how a receiver exploits its multiple antennas, letting the design or user pick the switching or combining scheme best suited to the reception environment.", "practical_application": "A tech confirms a receiver is set to its true-diversity or combining mode, rather than a single-antenna mode, when reliable coverage is needed.", "category": "Receiver Functions", "related_terms": ["Diversity", "Antenna diversity", "True diversity", "Maximal-ratio combining", "Receiver"], "common_mistakes": ["Leaving a receiver in a non-diversity or single-antenna mode when two antennas are connected", "Confusing simple antenna switching with signal-combining diversity", "Assuming all diversity modes perform identically in every room"], "scenario_contexts": ["Selecting true-diversity mode on a receiver for a moving performer", "Comparing switching versus combining diversity in a reflective venue", "Diagnosing dropouts caused by a receiver left in a non-diversity mode"]}, "3282dd09-4be9-45e2-abe7-66b2bc7e283c": {"definition": "A colloquial term for a personal in-ear monitoring (IEM) rig: the wireless setup a performer wears to hear a personal monitor mix, comprising a bodypack receiver, in-ear earphones, and a paired IEM transmitter that sends the mix over an RF link.", "plain_english": "An ear rig is a wireless earpiece system for performers. It sends their monitor mix to small earphones they wear. This lets them hear themselves clearly without loud stage speakers.", "purpose_function": "It delivers a private, consistent monitor mix to a performer over a wireless link, reducing stage volume and the feedback and hearing risks that come with loud floor wedges.", "practical_application": "A technician tunes the IEM transmitter and the bodypack receiver to the same frequency, coordinates that frequency with the microphone channels, and sets a safe listening level for the performer.", "category": "Stage Monitoring", "related_terms": ["In-ear monitor", "Bodypack", "Transmitter", "Frequency sync", "Frequency coordination", "Diversity"], "common_mistakes": ["UNSAFE: Running in-ear monitor levels very high, which can cause permanent hearing damage; set conservative limits and use limiting", "Forgetting to coordinate the IEM transmit frequency with the microphone frequencies, causing intermodulation interference", "Assuming the IEM bodypack is a receiver only, then tuning it like a microphone transmitter"], "scenario_contexts": ["A singer wears an ear rig so they can hear their vocal over a loud band without stage wedges", "A worship drummer uses an ear rig fed a click track and personal mix", "Coordinating several performers' ear rigs alongside the wireless microphones for one show"]}, "e5ccbfe8-65ef-434a-aff5-a042fa2f1060": {"definition": "A specific operating frequency, or narrow band around it, on which a single wireless link transmits and receives, selectable as one of many discrete channels within a device's tuning range.", "plain_english": "A frequency channel is one radio frequency a wireless mic uses. Each wireless system needs its own clear channel. Think of it like a lane on a road that only one signal should use at a time.", "purpose_function": "It defines the exact frequency a transmitter and receiver share so their audio link stays separate from other wireless systems and interference.", "practical_application": "A technician assigns each wireless system its own frequency channel, checks it is clear, and matches the transmitter to the receiver on that channel.", "category": "Frequency Coordination", "related_terms": ["Frequency group", "Frequency selection", "Frequency coordination", "Intermodulation", "RF spectrum", "Frequency sync"], "common_mistakes": ["Putting two active systems on the same frequency channel, which causes dropouts and noise", "Confusing a device's channel number preset with the actual frequency in megahertz", "Choosing channels without coordinating them, so their intermodulation products interfere"], "scenario_contexts": ["Assigning a separate frequency channel to each handheld before a panel discussion", "Reading which frequency channel a receiver is tuned to during troubleshooting", "Moving a system to a different frequency channel to escape interference"]}, "06b55a20-5007-4eb6-bc71-40b674bc6a39": {"definition": "A preset set of factory- or software-coordinated frequencies stored in a wireless device, chosen so that any channels selected from the same group are mutually compatible and free of intermodulation interference with each other.", "plain_english": "A frequency group is a ready-made set of channels that all work together. If you pick channels from the same group, they will not clash. It saves you from doing the tricky interference math by hand.", "purpose_function": "It lets an operator deploy several compatible wireless systems quickly by selecting channels from one coordinated group, avoiding manual intermodulation calculation.", "practical_application": "A technician sets all receivers to the same frequency group, then gives each system a different channel within that group so they run together cleanly.", "category": "Frequency Coordination", "related_terms": ["Frequency channel", "Frequency coordination", "Intermodulation", "Frequency selection", "Frequency plan", "Frequency scan"], "common_mistakes": ["Mixing channels from different groups, which can break the guaranteed compatibility and cause interference", "Assuming a factory group accounts for local TV and other outside signals, which it does not", "Using the largest group when a smaller one offers more spacing for a small channel count"], "scenario_contexts": ["Selecting one frequency group and spreading eight microphones across its channels", "Choosing a different group after a scan shows the first group's frequencies are occupied locally", "Standardizing every receiver to the same group for a touring rig"]}, "dc5d6483-6e34-45d9-9e44-9ec4df28f193": {"definition": "A small deliberate shift of a carrier frequency away from its nominal value, used to fine-tune a channel off an interfering signal or to space channels more evenly; it also describes the difference between a transmitter's actual carrier and its intended frequency.", "plain_english": "Frequency offset means nudging a channel slightly off its set frequency. You do it to dodge a nearby interfering signal. It is like scooting your chair a little to avoid someone's elbow.", "purpose_function": "It gives fine control to move a channel just enough to escape interference or improve spacing without jumping to a whole new channel.", "practical_application": "A technician applies a small frequency offset to a troubled channel to step it off an interfering carrier while keeping it within the coordinated plan.", "category": "Frequency Coordination", "related_terms": ["Frequency channel", "Frequency selection", "Interference", "Frequency coordination", "Intermodulation", "Carrier frequency"], "common_mistakes": ["Offsetting one channel into another coordinated channel's spacing, creating new interference", "Confusing frequency offset with the audio fine-tuning or gain controls", "Applying large offsets that push a channel outside its coordinated group's compatibility"], "scenario_contexts": ["Nudging a channel a few kilohertz to step off a persistent interfering signal", "Fine-tuning channel spacing when packing many systems into a narrow band", "Correcting a channel that sits slightly off its intended frequency"]}, "98ec268b-87ce-4cfe-a403-25f4225a0bcb": {"definition": "The process of choosing the operating frequency for a wireless system, either manually from available channels or automatically via a scan or coordination tool, so the link operates on a clear, compatible frequency.", "plain_english": "Frequency selection is picking which radio frequency a wireless system will use. You want a clear one that does not clash with other gear. The receiver can help by scanning for open channels.", "purpose_function": "It ensures each wireless link runs on an unoccupied, coordinated frequency, which is the first step in avoiding dropouts and interference.", "practical_application": "A technician scans the band, picks clear frequencies for each system, and syncs the chosen frequency to each transmitter before a show.", "category": "Frequency Coordination", "related_terms": ["Frequency channel", "Frequency group", "Frequency scan", "Frequency coordination", "Frequency sync", "RF spectrum"], "common_mistakes": ["Selecting frequencies without scanning, so the choice collides with local signals", "Picking frequencies channel by channel without checking intermodulation between your own systems", "Reusing last venue's frequencies when the local spectrum has changed"], "scenario_contexts": ["Selecting clear frequencies for a set of microphones during load-in", "Using a receiver scan to guide frequency selection at an unfamiliar venue", "Re-selecting frequencies on tour because each city occupies different TV channels"]}, "abb4b4c3-e805-4428-82a3-e5cb02ee4a27": {"definition": "The process of transferring a receiver's chosen operating frequency to its paired transmitter so both ends of the wireless link operate on the same frequency, commonly performed over a short-range infrared (IR) link.", "plain_english": "Frequency sync copies the receiver's chosen frequency over to its transmitter. Both ends must be on the same frequency to work. Many systems do this by holding the transmitter up to an infrared window on the receiver.", "purpose_function": "It quickly and reliably matches the transmitter to the receiver's frequency, avoiding manual entry errors and speeding up setup for many channels.", "practical_application": "After choosing a clear frequency, a technician holds the transmitter's IR window to the receiver and syncs, confirming both show the same frequency.", "category": "Frequency Coordination", "related_terms": ["Frequency selection", "Frequency channel", "Frequency scan", "Transmitter", "Receiver", "Frequency coordination"], "common_mistakes": ["Choosing a frequency on the receiver but forgetting to sync it to the transmitter, so the link stays dead", "Holding the transmitter too far from the infrared window, so the sync fails silently", "Assuming sync also transfers settings it does not, such as gain, on every model"], "scenario_contexts": ["Infrared-syncing a bodypack to its receiver after a scan finds an open channel", "Re-syncing transmitters after re-coordinating frequencies at a new venue", "Quickly syncing many channels during a fast changeover between acts"]}, "484a04ff-6cdc-4a9a-9c49-f2974d2c9646": {"definition": "A wireless system whose operating frequency can be tuned across a range of selectable channels, typically using phase-locked-loop (PLL) frequency synthesis, as opposed to a fixed, crystal-controlled single-frequency system.", "plain_english": "Frequency-agile wireless can be tuned to many different frequencies. Older systems were stuck on just one. Being able to change frequency lets you find a clear channel and avoid interference.", "purpose_function": "It lets an operator move the system to a clear frequency in a crowded or changing RF environment, which fixed-frequency systems cannot do.", "practical_application": "A technician tunes frequency-agile receivers to coordinated open channels at each venue instead of being locked to one factory frequency.", "category": "Wireless Systems", "related_terms": ["Frequency selection", "Frequency channel", "Frequency coordination", "Frequency scan", "Phase-locked loop", "RF spectrum"], "common_mistakes": ["Assuming agility removes the need for coordination, when you still must pick compatible frequencies", "Confusing frequency-agile tuning with automatic interference switching, which is a separate feature", "Tuning outside the licensed or legal band just because the hardware allows it"], "scenario_contexts": ["Retuning agile systems to open channels in each city on a tour", "Selecting clear frequencies on agile receivers after a spectrum scan", "Replacing legacy fixed-frequency units with agile systems for flexible deployment"]}, "d0273aa2-0958-48bd-a1d6-6b4e4f50b244": {"definition": "A wireless microphone transmitter built into a handheld microphone body, combining the capsule, transmitter electronics, antenna, and battery in one unit that a presenter or vocalist holds or places in a mic stand clip.", "plain_english": "A handheld is a wireless microphone with the radio transmitter built inside its body. There is no cable and no separate belt pack. You just hold it and talk or sing.", "purpose_function": "It provides a self-contained wireless vocal or speech microphone, freeing the user from a cable while keeping the capsule and transmitter in a single familiar mic form.", "practical_application": "A technician fits the handheld with a fresh battery, tunes it to a coordinated frequency, checks the capsule and gain, and hands it to a vocalist or presenter.", "category": "Wireless Systems", "related_terms": ["Bodypack", "Transmitter", "Receiver", "Microphone capsule", "Frequency sync", "Antenna"], "common_mistakes": ["Cupping the head of the handheld, which can detune the built-in antenna and change the sound", "Assuming any capsule fits any handheld body, when capsule mounts and models vary", "Forgetting the handheld's own battery and mute state when troubleshooting no audio"], "scenario_contexts": ["Handing a wireless handheld to a presenter for a conference Q and A", "Swapping capsules on a modular handheld to match a vocalist's preference", "Managing a set of handhelds on a mic stand for a panel discussion"]}, "08640008-7d03-444f-85e7-9bf2433817c9": {"definition": "Describes a helical antenna, whose radiating element is a conductor wound in a helix (spiral) to produce circular polarization and directional gain, used in some wireless setups to reduce polarization-mismatch dropouts from moving transmitters.", "plain_english": "A helical antenna has its wire wound in a spiral shape. This makes the radio wave spin as it travels, called circular polarization. It helps keep a steady signal even when a performer's transmitter keeps changing angle.", "purpose_function": "Its circular polarization captures signal well regardless of transmitter orientation, reducing dropouts caused by polarization mismatch as performers move and turn.", "practical_application": "A technician may use a directional helical antenna aimed at the stage to hold a steadier link with moving bodypacks whose antenna angle constantly changes.", "category": "Antenna Systems", "related_terms": ["Antenna polarization", "Directional antenna", "Antenna gain", "Antenna diversity", "Dropout", "Circular polarization"], "common_mistakes": ["Confusing a helical antenna with a helical resonator filter, which are different components", "Expecting circular polarization to fix problems that are really caused by distance or interference", "Ignoring that a helical antenna is directional and must be aimed at the coverage area"], "scenario_contexts": ["Aiming a helical antenna at a stage where performers move and rotate a lot", "Reducing polarization-mismatch dropouts on a theatrical production with active blocking", "Choosing a circularly polarized antenna where transmitter orientation cannot be controlled"]}, "4b4cf90a-4910-4b83-bf02-a801a9ae82f5": {"definition": "An RF combiner for in-ear monitor (IEM) systems that merges the outputs of several IEM transmitters onto a single shared transmitting antenna, providing filtering and isolation between transmitters so their signals do not interfere with or feed back into one another.", "plain_english": "An IEM combiner lets several wireless in-ear transmitters share one antenna. It keeps their signals apart so they do not clash. This means fewer antennas on the transmitter side.", "purpose_function": "It reduces the number of transmit antennas needed for a multichannel IEM rig and isolates transmitter outputs, limiting intermodulation and protecting transmitter output stages.", "practical_application": "A technician patches each IEM transmitter into a combiner input and runs a single coax to one paddle antenna, tidying the rack and improving transmitter-to-transmitter isolation.", "category": "Antenna Systems", "related_terms": ["IEMs", "Antenna distribution system", "Intermodulation product", "Coaxial cable", "Antenna combiner", "In-line RF amplifier"], "common_mistakes": ["Connecting IEM transmitters directly together or to one antenna without a combiner, causing intermodulation and possible damage to output stages", "Exceeding the combiner's input count or power rating by adding more transmitters than it supports", "Assuming a combiner boosts signal, when its job is to merge and isolate, not to add net gain"], "scenario_contexts": ["Combining four IEM transmitters onto one antenna for a band's personal monitor mixes", "Cleaning up a monitor rack by replacing multiple whip antennas with a single combined feed", "Reducing transmitter interaction when several IEM channels share a small stage area"]}, "d19fb8a4-cc4b-4b5d-a73a-e9e8ad64fe3d": {"definition": "In-ear monitors: small sealed earphones worn by a performer to hear a personal monitor mix; in a wireless system a stationary transmitter sends the mix over RF to a bodypack receiver that drives the earpieces, replacing or supplementing floor wedge monitors.", "plain_english": "IEMs are earphones that let a performer hear their own mix on stage. A small pack picks up the sound by radio and plays it in their ears. They can replace the big speakers on the floor.", "purpose_function": "They deliver a clear, personal monitor mix directly to each performer and lower stage volume, which reduces feedback and limits hearing exposure compared with loud floor wedges.", "practical_application": "An engineer builds each performer's monitor mix, feeds it to the IEM transmitter, and the performer sets pack volume for a comfortable, safe level in their earpieces.", "category": "Personal Monitoring", "related_terms": ["IEM combiner", "Bodypack", "Monitor mix", "Floor wedge", "Diversity receiver", "Squelch"], "common_mistakes": ["UNSAFE: Running IEM levels too high, which can cause permanent noise-induced hearing loss over time", "Removing one earpiece to hear the room, which tempts the performer to raise the level in the other ear", "Confusing the earphones themselves with the whole wireless IEM system (transmitter plus bodypack receiver)"], "scenario_contexts": ["A lead singer using wireless IEMs instead of floor wedges to keep stage volume low", "Building individual monitor mixes for each band member on the monitor console", "Troubleshooting dropouts in a performer's earpieces during a moving stage performance"]}, "832227eb-cbc1-4d0e-832d-abb0b5577bd4": {"definition": "In a superheterodyne receiver, an RF bandpass or preselector filter placed ahead of the mixer that attenuates the image frequency, the unwanted frequency spaced from the desired signal by twice the intermediate frequency, so it is not down-converted into the IF passband along with the wanted signal.", "plain_english": "A radio receiver can pick up a second, unwanted frequency called the image. This filter blocks that unwanted frequency before it gets mixed in. That keeps the real signal clean.", "purpose_function": "It stops an image frequency from being converted into the IF and imitating the wanted signal, improving a superheterodyne receiver's selectivity and rejection of out-of-band interference.", "practical_application": "A technician relies on this front-end filtering as part of receiver design, and benefits from it when strong nearby transmitters do not create phantom interference on a channel.", "category": "Receiver Design", "related_terms": ["Superheterodyne receiver", "Intermediate frequency", "Bandpass filter", "RF front end", "Selectivity", "Image frequency"], "common_mistakes": ["Confusing the image frequency with a harmonic or an intermodulation product; the image is set by twice the IF, not by multiples of the carrier", "Assuming any interference near the channel is an image problem, when most receiver interference has other causes", "Believing a wide antenna filter alone rejects images without adequate front-end preselection"], "scenario_contexts": ["Evaluating a wireless receiver's ability to reject strong signals two IF steps away from the tuned channel", "Comparing receiver front-end designs for performance in a dense RF environment", "Explaining why a distant transmitter appears to interfere despite being on a different frequency"]}, "14df33a5-a5b2-4192-832a-ee533f281cd4": {"definition": "An amplifier inserted into a coaxial antenna feedline that boosts the received RF signal to compensate for cable attenuation over long runs; it is typically powered by DC bias voltage carried up the same coax from the receiver or distribution system.", "plain_english": "A long antenna cable makes the radio signal weaker. An in-line RF amplifier sits in the cable and boosts the signal back up. It usually gets its power through the same cable.", "purpose_function": "It offsets coaxial cable loss on long antenna runs so enough signal reaches the receiver, preserving usable range and reducing dropouts caused by cable attenuation.", "practical_application": "On a long feed from a remote antenna, a technician adds an in-line amplifier with gain set to roughly match the cable loss, avoiding overload of the receiver front end.", "category": "Antenna Systems", "related_terms": ["Cable loss", "Antenna power", "Coaxial cable", "Active antenna", "Antenna distribution system", "Antenna gain"], "common_mistakes": ["Adding more amplifier gain than the cable loses, which raises the noise floor and can overload the receiver front end", "Forgetting to supply the DC bias power the amplifier needs, so it passes little or no signal", "Believing an in-line amplifier improves signal-to-noise ratio, when it mainly restores level lost in the cable"], "scenario_contexts": ["Feeding a receiver from an antenna at the far end of a long coax run in a large venue", "Matching amplifier gain to measured cable loss during a wireless system installation", "Diagnosing weak RF caused by cable length and deciding whether an in-line amplifier is warranted"]}, "944e840f-40be-4b28-bd55-2794bc209f66": {"definition": "The process, or a receiver/software feature, of identifying unwanted RF energy on or near a channel, such as other transmitters, digital TV signals, noise, or intermodulation, typically using a spectrum scan or RF level metering that reveals energy on otherwise unused frequencies.", "plain_english": "Interference detection means finding unwanted radio signals that could ruin your channel. Your gear scans the airwaves and shows where other signals are. You then pick clear frequencies to stay away from them.", "purpose_function": "It reveals occupied or noisy frequencies before and during a show so a coordinator can avoid them, preventing dropouts and audio artifacts caused by competing RF energy.", "practical_application": "A technician runs a spectrum scan on the receiver or coordination software, notes busy frequencies, and assigns channels into the clear gaps.", "category": "Frequency Coordination", "related_terms": ["Frequency scan", "Frequency coordination", "Intermodulation product", "RF signal strength", "Squelch", "Dropout"], "common_mistakes": ["Scanning only once at load-in and assuming the RF environment stays the same all day", "Scanning with transmitters powered on, so the system's own signals mask the picture of outside interference", "Treating every RF spike as external interference without checking for intermodulation from the local rig"], "scenario_contexts": ["Running a pre-show spectrum scan to find clear frequencies at a new venue", "Investigating a channel that drops out only when a nearby broadcast or Wi-Fi source is active", "Confirming which TV channels are occupied before coordinating wireless mics"]}, "9ba5703c-6b26-4025-be26-d036080bd4f9": {"definition": "A setting or algorithm in wireless coordination software or a receiver's automatic setup that restricts frequency selection to channels calculated to be free of significant intermodulation products, so the chosen frequencies remain mutually compatible when many transmitters operate together.", "plain_english": "When many wireless systems run at once, their signals can mix and make new, unwanted signals. This mode only picks frequencies that dodge those bad mixes. It helps many channels work together.", "purpose_function": "It automates intermodulation-safe frequency selection so a large multichannel system stays clean without the operator hand-calculating every possible mixing product.", "practical_application": "A technician enables the mode in coordination software or a receiver's auto-setup and lets it assign a set of compatible, intermodulation-free frequencies.", "category": "Frequency Coordination", "related_terms": ["Intermodulation product", "Intermodulation coordination", "Frequency coordination", "Frequency scan", "Group and channel", "Interference detection"], "common_mistakes": ["Assuming the mode accounts for outside transmitters it cannot see without first scanning the local RF environment", "Adding extra frequencies by hand after the mode runs, which can reintroduce intermodulation problems", "Expecting it to fix interference from sources other than intermodulation, such as a busy TV channel"], "scenario_contexts": ["Letting coordination software auto-assign intermodulation-safe channels for a large multichannel event", "Using a receiver's automatic group-and-channel setup to place mics without manual intermod math", "Rebuilding a frequency plan on site after a scan reveals new occupied channels"]}, "fca54efa-eb39-408b-852f-b2de99b7885a": {"definition": "The practice, within RF frequency coordination, of selecting and assigning operating frequencies for multiple transmitters so that their intermodulation products, especially third-order products, do not fall on any active channel, ensuring compatible simultaneous operation.", "plain_english": "Radios running together can mix and make extra signals. Good planning picks frequencies so those extra signals miss every channel in use. That lets many mics run at once.", "purpose_function": "It lets many wireless channels coexist by placing them where their mixing products avoid all in-use frequencies, preventing interference in dense multichannel RF setups.", "practical_application": "A coordinator uses software, or calculation, to build an intermodulation-compatible frequency plan for every mic and IEM at an event, then documents it for the crew.", "category": "Frequency Coordination", "related_terms": ["Intermodulation product", "Intermodulation avoidance mode", "Frequency coordination", "Frequency scan", "Interference detection", "Group and channel"], "common_mistakes": ["Ignoring third-order products, which fall closest to the original frequencies and are the most likely to interfere", "Coordinating only the local rig while ignoring nearby TV, broadcast, or other wireless users on the same band", "Reusing an old frequency plan at a new location without rescanning and recoordinating"], "scenario_contexts": ["Planning dozens of compatible wireless channels for a festival or broadcast with many operators", "Coordinating mics and IEMs together so no intermodulation product lands on an active channel", "Recalculating a frequency plan after adding more wireless systems to a show"]}, "64332f66-e17b-4a9c-81c6-a81cfc6478e9": {"definition": "An unwanted signal created when two or more RF signals mix in a non-linear device such as an amplifier or receiver front end, appearing at mathematical sums and differences of the original frequencies and their harmonics; third-order products (2f1 minus f2, and 2f2 minus f1) are the most troublesome because they fall close to the original frequencies.", "plain_english": "When two radio signals mix in electronics, they can create brand-new signals at other frequencies. These extra signals are called intermodulation products. They can land on a channel you are using and cause trouble.", "purpose_function": "The concept explains why closely spaced transmitters interfere, which guides frequency coordination to keep these products off every channel in use.", "practical_application": "A technician coordinates frequencies so third-order products fall on empty channels, and suspects intermodulation when interference appears only once several systems are powered on together.", "category": "Frequency Coordination", "related_terms": ["Intermodulation coordination", "Intermodulation avoidance mode", "Frequency coordination", "Harmonics", "RF front end", "Interference detection"], "common_mistakes": ["Thinking intermodulation products come from a single transmitter, when they need two or more signals mixing in a non-linear stage", "Focusing only on the transmitted frequencies and ignoring the products that fall between them", "Assuming more spacing always helps, without checking where the third-order products actually land"], "scenario_contexts": ["Interference that appears on a channel only when several nearby transmitters are switched on", "Planning frequencies so no third-order product coincides with an active mic or IEM channel", "Diagnosing noise created when strong signals overload a receiver or amplifier front end"]}, "bd756b9b-dc20-492f-86d9-a4b1d263b1b9": {"definition": "A setup method in which a wireless receiver sends channel parameters, such as frequency and often name, gain, and other settings, to a transmitter over a short-range infrared (IR) link, matching the two devices automatically without manual menu entry.", "plain_english": "IR sync uses an infrared beam, like a TV remote, to copy settings from the receiver to the transmitter. You hold the transmitter up to the receiver's window. This sets the frequency for you, with no menu typing.", "purpose_function": "It quickly and reliably matches a transmitter to its receiver's assigned frequency and settings, cutting setup time and avoiding manual entry errors across many channels.", "practical_application": "A technician scans for a clean frequency on the receiver, then holds the bodypack or handheld to the IR window to sync it before soundcheck.", "category": "System Setup", "related_terms": ["Frequency scan", "Frequency coordination", "Transmitter", "Receiver", "Group and channel", "Bodypack"], "common_mistakes": ["Holding the transmitter too far from or misaligned with the IR window, so the sync fails or only partly transfers", "Assuming IR sync also updates the transmitter over distance during a show; the infrared link is short-range and line-of-sight", "Syncing before finishing frequency coordination, so the transmitter is set to a frequency that later changes"], "scenario_contexts": ["Syncing a rack of receivers to their bodypacks before a show after coordinating frequencies", "Quickly re-syncing a swapped transmitter to a receiver during a fast changeover", "Setting up many channels at load-in without typing each frequency by hand"]}, "3af158ac-7cd0-47ff-828f-52637c876965": {"definition": "Lav is the common shorthand for a lavalier microphone: a small clip-on mic, usually an omnidirectional condenser, worn on the body near the chest and typically connected to a wireless bodypack transmitter for hands-free voice pickup.", "plain_english": "A lav is a tiny microphone you clip to your shirt. It leaves your hands free to move. It usually plugs into a small wireless pack, so no cable trails behind you.", "purpose_function": "It captures a talker's voice hands-free and nearly out of sight, feeding a bodypack transmitter so the person can move freely on stage or camera.", "practical_application": "A technician clips a lav on a presenter's chest, dresses and hides the cable, and plugs it into a bodypack for wireless voice.", "category": "Microphones", "related_terms": ["Bodypack transmitter", "Omnidirectional microphone", "Condenser microphone", "Headset microphone", "Windscreen", "Packs"], "common_mistakes": ["Placing the lav too far from the mouth, which makes the voice weak and hard to hear", "Letting the lav rub against clothing or jewelry, which adds rustle and thumps", "Assuming a lav is directional when most are omnidirectional and pick up sound from all around"], "scenario_contexts": ["Miking a presenter for a keynote so their hands stay free", "Fitting an actor with a hidden lav under a costume for theatre", "Clipping a lav on an interviewee for a broadcast segment"]}, "af0e2044-472f-46dd-a0a0-b17cfff967a7": {"definition": "A form of electromagnetic wave polarization in which the electric field oscillates in a single fixed plane, described as vertical or horizontal depending on that plane's orientation; most wireless microphone antennas, such as dipoles and whips, are linearly polarized.", "plain_english": "Linear polarization means a radio wave's field stays lined up in one flat direction as it travels. It can be upright or sideways. Two antennas work best when their lines match.", "purpose_function": "It describes the fixed field orientation of an antenna, which sets how well two antennas couple; matched linear polarization gives the best transfer, while a crossed orientation causes loss.", "practical_application": "A technician keeps transmit and receive antennas in the same orientation and expects mismatch loss when a performer tilts a bodypack antenna.", "category": "Antenna Systems", "related_terms": ["Antenna polarization", "Circular polarization", "Cross-polarization", "Antenna diversity", "Dipole antenna", "Paddle"], "common_mistakes": ["Confusing linear polarization with circular polarization, which rotates as the wave travels", "Assuming polarization does not matter, when a 90-degree mismatch causes large signal loss", "Mounting receive antennas horizontally while body-worn transmitters radiate closer to vertical"], "scenario_contexts": ["Orienting a whip antenna vertically to match a vertically held handheld transmitter", "Explaining dropouts when a performer lies down and tilts a bodypack antenna", "Choosing circular-polarized antennas to reduce mismatch with moving performers"]}, "d10a17f1-2530-4e66-ad00-3ad187c4be30": {"definition": "In a party-line (PL) intercom system, the main station (also called the master station or power supply) is the central unit that supplies DC power to the intercom line, sets the master audio level, and provides the primary control point for one or more channels to which beltpacks and other stations connect.", "plain_english": "A main station is the central box that runs an intercom system. It powers the line and sets the volume for everyone. Crew beltpacks all connect back to it so the team can talk.", "purpose_function": "It powers the party-line, combines everyone's audio, and gives master control so a crew can talk together over one or more shared channels.", "practical_application": "A technician places the main station at a control point, powers the intercom line from it, and connects beltpacks and headsets along the run.", "category": "Intercom Systems", "related_terms": ["Party-line", "Beltpack", "Intercom", "Headset", "Wireless intercom", "Packs"], "common_mistakes": ["Confusing the main station with a plain beltpack, when only the main station powers the line", "Connecting too many beltpacks for the main station's power supply, which weakens the audio", "Forgetting that the main station sets the master level for the whole channel"], "scenario_contexts": ["Setting up a main station to run crew intercom for a live show", "Powering a party-line channel from the main station during load-in", "Adding beltpacks to a channel fed by the main station"]}, "a6e95a5e-9e10-4c38-90db-e4ff1e439cf6": {"definition": "A wireless microphone receiver whose RF front end and IF filtering accept only a narrow slice of spectrum around the operating frequency, rejecting signals outside that band to improve selectivity and interference immunity, as opposed to a wideband receiver that passes a larger frequency range at once.", "plain_english": "A narrowband receiver only listens to a thin slice of radio around its channel. It ignores signals outside that slice. That tight focus helps block interference from nearby transmitters.", "purpose_function": "By filtering tightly around the wanted frequency, it improves selectivity and rejects out-of-band interference, at the cost of a smaller instantaneous tuning range.", "practical_application": "A technician relies on narrowband filtering in crowded RF to reject strong nearby signals, accepting that the receiver tunes over a smaller range at one time.", "category": "Receivers", "related_terms": ["Wideband receiver", "Selectivity", "Intermediate frequency", "Noise squelch", "Diversity receiver", "Intermodulation"], "common_mistakes": ["Assuming narrowband means longer range, when it mainly improves selectivity, not distance", "Confusing the narrowband tuning range with the audio bandwidth of the system", "Expecting a narrowband receiver to tune across a whole band the way wideband gear does"], "scenario_contexts": ["Selecting narrowband gear for a crowded urban RF environment", "Rejecting a strong nearby transmitter using tight receiver filtering", "Comparing narrowband and wideband receivers when planning frequency ranges"]}}$ape$::jsonb)) d WHERE g.id=d.id;
UPDATE glossary g SET definition = CASE WHEN d.p ? 'definition' THEN d.p->>'definition' ELSE g.definition END, plain_english = CASE WHEN d.p ? 'plain_english' THEN d.p->>'plain_english' ELSE g.plain_english END, purpose_function = CASE WHEN d.p ? 'purpose_function' THEN d.p->>'purpose_function' ELSE g.purpose_function END, practical_application = CASE WHEN d.p ? 'practical_application' THEN d.p->>'practical_application' ELSE g.practical_application END, category = CASE WHEN d.p ? 'category' THEN d.p->>'category' ELSE g.category END, related_terms = CASE WHEN d.p ? 'related_terms' THEN ARRAY(SELECT jsonb_array_elements_text(d.p->'related_terms')) ELSE g.related_terms END, common_mistakes = CASE WHEN d.p ? 'common_mistakes' THEN ARRAY(SELECT jsonb_array_elements_text(d.p->'common_mistakes')) ELSE g.common_mistakes END, scenario_contexts = CASE WHEN d.p ? 'scenario_contexts' THEN ARRAY(SELECT jsonb_array_elements_text(d.p->'scenario_contexts')) ELSE g.scenario_contexts END FROM (SELECT key::uuid AS id, value AS p FROM jsonb_each($ape${"894b4b3c-cff7-47ec-baf9-0927c846d9bd": {"definition": "A squelch method that mutes a wireless receiver's audio by comparing the high-frequency noise energy in the demodulated signal to a reference set by the squelch control; when noise rises above the threshold, indicating a weak or lost RF carrier, the audio is muted to prevent bursts of static. It contrasts with tone-key (pilot-tone) squelch.", "plain_english": "Noise squelch listens for static in a wireless signal. Too much hiss means the radio link is failing. So it mutes the sound to stop a burst of noise from reaching the speakers.", "purpose_function": "It prevents loud noise bursts when RF drops out by muting whenever demodulated noise exceeds a set threshold, protecting the sound system and the audience.", "practical_application": "A technician sets the noise-squelch threshold high enough to mute dropouts but low enough not to cut a usable, slightly noisy signal.", "category": "Receiver Functions", "related_terms": ["Squelch", "Tone squelch", "Pilot tone", "Audio mute", "Dropout", "Signal-to-noise ratio"], "common_mistakes": ["Setting the squelch threshold too low, which lets static through during dropouts", "Setting it too high, which mutes a usable signal and cuts range", "Confusing noise squelch with pilot-tone squelch, which keys on a coded tone instead of noise"], "scenario_contexts": ["Adjusting squelch so a receiver mutes cleanly when a transmitter is switched off", "Stopping a static burst when a performer walks out of range", "Tuning the threshold at a venue with a high RF noise floor"]}, "494103f6-f9b1-4b2d-85c9-62c7ffd6a810": {"definition": "Packs is the common shorthand for bodypack transmitters: small battery-powered units worn on the body that accept a lavalier, headset, or instrument input and transmit its audio to a receiver. The term can also refer to bodypack in-ear monitor (IEM) receivers worn the same way.", "plain_english": "Packs is crew slang for bodypacks. These are little battery boxes worn on the body. A lav or headset mic plugs into one, and it sends the sound to a receiver by radio.", "purpose_function": "They let a performer carry a lavalier, headset, or instrument input wirelessly, sending audio to a receiver without a trailing cable.", "practical_application": "A technician fits packs on performers, checks batteries and inputs, and assigns each pack a coordinated frequency before a show.", "category": "Transmitters", "related_terms": ["Bodypack transmitter", "Lav", "Headset microphone", "In-ear monitor", "Handheld transmitter", "Antenna diversity"], "common_mistakes": ["Using packs with worn or partly charged batteries, which causes dropouts mid-show", "Confusing a bodypack transmitter with a bodypack IEM receiver, which do opposite jobs", "Not securing the pack, so it tugs on the mic cable and adds noise"], "scenario_contexts": ["Handing out packs to a cast during a costume fitting", "Swapping batteries in packs between acts", "Assigning frequencies to each pack during coordination"]}, "9e053fd3-e920-4aa6-b8d1-0ff92824bd3a": {"definition": "Paddle is the common name for a flat, directional wireless antenna, typically a log-periodic dipole array (LPDA) shaped like a paddle, that provides gain and a directional pickup pattern over a wide UHF range for receiving wireless microphone or transmitting in-ear monitor signals.", "plain_english": "A paddle is a flat, directional antenna shaped a bit like a ping-pong paddle. It points at the stage to grab signals from one direction. Aiming it boosts range and cuts interference from behind.", "purpose_function": "It adds directional gain so a receiver can reach farther toward a stage and reject interference arriving from other directions.", "practical_application": "A technician mounts paddle antennas on stands aimed at the performance area and feeds them into an antenna distribution system.", "category": "Antenna Systems", "related_terms": ["Directional antenna", "Log-periodic antenna", "Antenna gain", "Antenna distribution system", "Omnidirectional antenna", "Passive antenna splitter"], "common_mistakes": ["Aiming the paddle away from the stage, losing the directional gain it is meant to provide", "Assuming a paddle covers all directions the way an omnidirectional antenna does", "Placing paddles too close to metal or to each other, which distorts the pattern"], "scenario_contexts": ["Aiming paddle antennas at a stage from the receiver rack", "Using directional paddles to reject interference arriving from behind the antenna", "Mounting paddles on stands at front of house for wide UHF coverage"]}, "26082f63-762f-4f83-ab8e-d94a8b8172df": {"definition": "A party-line (PL) intercom is an analog, two-wire communication system in which all connected beltpacks and stations share a common audio bus, so every user on a channel can talk to and hear all others at the same time, powered from a central main or power-supply station.", "plain_english": "A party-line is a shared intercom line for a crew. Everyone on the line hears everyone else at once, like an old shared phone line. Each person uses a beltpack and headset to join in.", "purpose_function": "It gives a production crew a simple shared channel to coordinate, letting all members hear and speak to one another over one common line.", "practical_application": "A technician wires beltpacks along a party-line channel from a main station so stage, lighting, and video crew can talk together during a show.", "category": "Intercom Systems", "related_terms": ["Main station", "Beltpack", "Intercom", "Headset", "Wireless intercom", "Matrix intercom"], "common_mistakes": ["Confusing a party-line with a matrix intercom, where users are routed to each other individually", "Adding too many beltpacks for the line's power, which causes weak or noisy audio", "Forgetting that everyone on the channel hears everything said on it"], "scenario_contexts": ["Running a party-line so stage and lighting crew share one channel", "Adding beltpacks along a PL line during setup", "Choosing a party-line for a small crew instead of a matrix system"]}, "18377b1f-b58c-43a0-8edf-e425b7b47bfa": {"definition": "A passive antenna splitter (or combiner) divides the RF from one antenna among multiple wireless receivers, or combines several IEM transmitters onto one antenna, using unpowered components with no amplification. The split adds insertion loss, roughly 3 to 4 dB for a two-way split and more as outputs increase, because the incoming signal energy is shared.", "plain_english": "A passive antenna splitter shares one antenna's signal with several receivers. It uses no power and no amplifier. Because the signal is split, each receiver gets a weaker share, so it suits short cable runs.", "purpose_function": "It lets several receivers share one pair of antennas without active electronics, at the cost of split loss, suiting short runs where amplification is not needed.", "practical_application": "A technician uses a passive splitter for a couple of nearby receivers on short coax, but switches to an active distribution system for longer runs or many channels.", "category": "Antenna Systems", "related_terms": ["Active antenna splitter", "Antenna distribution system", "Insertion loss", "Coaxial cable", "Antenna power", "Antenna diversity"], "common_mistakes": ["Using a passive splitter with long coax, where split loss plus cable loss kills the signal", "Expecting DC antenna bias to pass through a passive splitter that does not carry it", "Splitting to too many receivers, so insertion loss drops each one's signal too far"], "scenario_contexts": ["Sharing two antennas between two receivers on a short run", "Choosing a passive splitter for a small rack to save power and cost", "Diagnosing weak signal caused by too many passive splits"]}, "c8ac29c9-f64f-4842-98e7-394ab73fd2a2": {"definition": "A sub-audible continuous tone, typically below about 300 Hz, transmitted along with the RF carrier that a receiver must detect before it opens its squelch and passes audio; PL (Private Line) is Motorola's trademarked name for CTCSS (Continuous Tone-Coded Squelch System). It lets several user groups share one frequency while each hears only transmissions carrying its assigned tone.", "plain_english": "PL is a quiet tone sent under a two-way radio signal. Your radio stays silent unless it hears the right tone. This lets many groups share one channel. You only hear people set to your own tone. It works like a password for your group.", "purpose_function": "It provides selective squelch so a receiver ignores signals that lack the correct tone, letting multiple user groups share a single RF channel without constantly hearing each other.", "practical_application": "A technician programs matching PL/CTCSS tones on paired radios or intercom beltpacks so a crew hears only its own group, even when others use the same frequency nearby.", "category": "Squelch and Muting", "related_terms": ["Squelch", "RF carrier", "Interference", "Two-way radio", "Audio mute", "Frequency plan"], "common_mistakes": ["Believing a PL tone encrypts or secures the audio; it only controls squelch, and anyone can still monitor the channel by turning tone squelch off", "Assuming a PL tone gives you a private frequency, when the channel is still shared and can be blocked by others transmitting on it", "Setting mismatched tones on the transmitter and receiver, so the receiver never opens and stays silent", "Confusing PL/Private Line (a CTCSS tone-squelch feature on a two-way radio) with a party-line (PL) intercom bus; they share only the abbreviation and are otherwise unrelated"], "scenario_contexts": ["Assigning different PL tones to stage crew and lighting crew who share one radio frequency", "Troubleshooting a radio that stays silent because its receive tone does not match the sender", "Using CTCSS tones to keep a busy event's radio channel quiet between messages"]}, "1d95d0cd-cfab-44d7-9bcb-80950586103d": {"definition": "A diversity technique in which a wireless receiver evaluates or combines the signal from up to four independent antenna paths or receiver sections and selects or blends the strongest, cleanest one to minimise dropouts caused by multipath and fading. It extends the common two-antenna 'true diversity' approach to four inputs for greater reliability.", "plain_english": "Radio signals can fade or bounce and cause dropouts. Quad diversity uses four antennas instead of two. The receiver picks or blends whichever antennas have the best signal. More antennas mean fewer dropouts. It is like having four listeners and trusting whoever hears best.", "purpose_function": "By drawing on four antenna paths, it reduces the chance that all inputs fade at the same moment, improving link reliability over standard two-antenna diversity in difficult RF environments.", "practical_application": "A technician deploys quad-diversity receivers, or combines multiple spaced antennas, on demanding shows such as large stages and film sets where movement and obstructions cause frequent multipath dropouts.", "category": "Diversity Reception", "related_terms": ["Antenna diversity", "True diversity", "Dropout", "Multipath", "Receiver front end", "Diversity combining"], "common_mistakes": ["Assuming more antennas always mean more range, when diversity fights dropouts and fading rather than raw distance", "Placing all four antennas close together, which defeats diversity because they tend to fade at the same time", "Confusing quad diversity with simply operating four separate independent receivers"], "scenario_contexts": ["Using quad-diversity receivers for a performer who moves across a large, multipath-heavy stage", "Deploying multiple spaced antennas on a film set to cut dropouts as actors move", "Choosing quad diversity for a high-stakes channel that cannot tolerate dropouts"]}, "8354f0ce-e8e1-48f1-a391-2637f3a53e83": {"definition": "The first RF stages of a receiver between the antenna input and the first frequency-conversion (mixer) stage, typically comprising input filtering (preselection), a low-noise amplifier, and the first mixer. Its design sets the receiver's sensitivity, selectivity, and resistance to overload and intermodulation.", "plain_english": "The front end is the first part of a receiver, right after the antenna. It filters and boosts the tiny incoming radio signal before the rest of the circuit works on it. A good front end can hear weak signals without getting swamped by strong nearby ones.", "purpose_function": "It captures, filters, and amplifies the weak antenna signal while rejecting out-of-band signals, protecting later stages and determining how well the receiver detects wanted signals amid interference.", "practical_application": "A technician protects the front end from overload by managing strong nearby transmitters, using RF attenuation, filters, or antenna placement to avoid desensitisation and intermodulation.", "category": "Receiver Design", "related_terms": ["Receiver sensitivity setting", "RF attenuation", "Intermodulation", "Selectivity", "RF carrier", "Diversity combining"], "common_mistakes": ["Assuming a more sensitive front end is always better, when too much gain lets strong signals cause overload and intermodulation", "Ignoring strong local transmitters that can desensitise or overload the front end", "Confusing front-end selectivity with squelch, which is a separate audio-muting function"], "scenario_contexts": ["Adding front-end RF attenuation when a transmitter is used very close to the receiver antenna", "Diagnosing intermodulation traced to front-end overload at a crowded RF site", "Selecting receivers with strong front-end filtering for use near TV broadcast towers"]}, "b2886ccb-2a20-487f-bb79-2ab0cf70393d": {"definition": "A receiver control that sets the threshold RF signal level (squelch) required before the receiver opens and passes audio. A higher setting demands a stronger, cleaner signal and rejects weak interference and noise, while a lower setting extends usable range but risks letting noise or interference through.", "plain_english": "This setting decides how strong a radio signal must be before the receiver plays sound. Set it high and weak junk signals get blocked, but range shrinks. Set it low and you get more range, with more chance of static. You tune it to fit the room.", "purpose_function": "It lets the operator balance interference rejection against range by choosing how strong the incoming RF must be before audio is passed, preventing noise bursts during dropouts.", "practical_application": "A technician raises the squelch/sensitivity threshold in RF-noisy venues to block interference, and lowers it when maximum range is needed and the spectrum is clean.", "category": "Receiver Functions", "related_terms": ["Squelch", "Receiver front end", "RF signal strength", "Dropout", "Interference", "Audio mute"], "common_mistakes": ["Setting the threshold too low, so the receiver passes noise and interference instead of muting during dropouts", "Setting it too high, which cuts range and causes dropouts even with a healthy transmitter", "Confusing this RF/squelch threshold with the transmitter's audio input gain"], "scenario_contexts": ["Raising squelch to stop static bursts from a nearby interfering signal", "Lowering squelch to keep a distant transmitter connected in a clean RF environment", "Adjusting the threshold during soundcheck to balance range against noise rejection"]}, "5f9aa6ee-5a22-46f5-a364-40ba9e992539": {"definition": "An arrangement in which the receiving (or transmitting) antennas are located away from the receiver rack and connected by coaxial feedline, often with an antenna distribution system and in-line or active amplification, to place antennas closer to the performers and maintain line of sight.", "plain_english": "Sometimes the receiver rack sits far from the stage or behind walls. A remote antenna system moves the antennas out near the performers. Cables carry the signal back to the rack. This keeps a clear path and cuts dropouts.", "purpose_function": "It improves reception by positioning antennas for clear line of sight and shorter distance to the transmitters, while the receivers stay in a convenient, protected rack location.", "practical_application": "A technician mounts antennas near the performance area and runs coax back to a rack-mounted antenna distribution unit, adding active antennas or amplifiers to offset cable loss on long runs.", "category": "Antenna Systems", "related_terms": ["Antenna distribution system", "Active antenna", "Coaxial cable", "Cable loss", "Line of sight", "Antenna placement"], "common_mistakes": ["Running long coax without accounting for cable loss, which weakens the signal reaching the receiver", "Placing remote antennas behind metal, walls, or bodies, losing the line-of-sight benefit", "Feeding DC bias to passive antennas, or forgetting to enable bias power for active ones", "UNSAFE: running antenna coax across walkways without securing and marking it, creating a trip and fall hazard"], "scenario_contexts": ["Mounting paddle antennas at the front of a stage with coax back to the receiver rack backstage", "Extending antennas into an arena bowl to keep line of sight to roaming performers", "Adding an antenna distribution system so remote antennas feed many receivers at once"]}, "fb2060ff-333b-480b-b78b-3cf3bbcfea4f": {"definition": "A user station, such as a beltpack, handheld, or panel, located away from the central base or master station in a communications or intercom system, linked to it by cable or wirelessly, allowing an operator to talk and listen from a remote position.", "plain_english": "A remote station is a talk-and-listen unit placed away from the main base. It connects back by cable or radio. Crew use one to communicate from wherever they are working. Think of it as a handset far from the switchboard.", "purpose_function": "It extends a communications system to people working away from the central control point, so they can send and receive messages without being at the base station.", "practical_application": "A technician issues wireless beltpacks or remote panels to crew around a venue so they stay in contact with the central intercom base throughout a show.", "category": "Intercom Systems", "related_terms": ["Base station", "Beltpack", "Intercom", "Two-way radio", "Wireless intercom", "PL (private line)"], "common_mistakes": ["Assuming a remote station works everywhere without checking coverage, range, or the need for repeaters", "Forgetting to charge or power wireless remote stations before a show", "Confusing a remote station with the base or master station that controls the system"], "scenario_contexts": ["Handing wireless beltpacks to stagehands as remote stations on a theatre intercom", "Placing a remote intercom panel at a follow-spot position far from the control room", "Using remote radio stations for crew spread across an outdoor event"]}, "c4a11abb-946f-4cfc-bb6a-6b1f013f6e11": {"definition": "The reduction in the power or amplitude of a radio-frequency signal, expressed in decibels, whether deliberate (using an attenuator pad or reducing RF gain to prevent overload) or unintended (loss from cables, connectors, distance, and obstacles).", "plain_english": "RF attenuation means making a radio signal weaker. Sometimes you do it on purpose to stop a strong signal from overloading a receiver. Sometimes it just happens in cables, or over distance and through walls. It is measured in decibels.", "purpose_function": "Deliberate attenuation protects sensitive receiver inputs from overload and balances signal levels, while understanding unintended attenuation helps predict range and coverage limits.", "practical_application": "A technician inserts an attenuator or engages input attenuation when a transmitter is close to the receiver, and budgets for cable and distance loss when planning antenna runs.", "category": "Signal Management", "related_terms": ["Receiver front end", "Cable loss", "Attenuator", "RF signal strength", "Intermodulation", "Decibel"], "common_mistakes": ["Boosting RF gain when the real problem is overload and attenuation is what is actually needed", "Ignoring cable and connector loss when planning long antenna runs", "Adding attenuation on a weak, distant link and causing dropouts"], "scenario_contexts": ["Adding an in-line attenuator when a bodypack is used within a few feet of the receiver antenna", "Calculating cable loss to size a coax run and decide whether active antennas are needed", "Reducing front-end overload at a crowded RF site with input attenuation"]}, "25fd9006-5750-4c01-a4de-1f52309f0fea": {"definition": "Choosing the width of the frequency range over which a tunable wireless transmitter or receiver operates (its switching or tuning bandwidth), and in some equipment the receiver filter bandwidth. A wider bandwidth allows more channels and tuning flexibility, while a narrower one can improve selectivity and interference rejection.", "plain_english": "Wireless gear can tune across a range of radio frequencies. Bandwidth selection sets how wide that range is. A wide range gives you more channels to choose from. A narrower filter can block more interference. You pick what the situation needs.", "purpose_function": "It matches the device's frequency coverage and filtering to the job, giving enough tuning range to find clear channels while keeping enough selectivity to reject unwanted signals.", "practical_application": "A technician chooses equipment with a switching bandwidth wide enough to cover the spectrum available at a venue, so every needed channel can be coordinated within one system.", "category": "Frequency Coordination", "related_terms": ["Switching bandwidth", "Frequency plan", "Selectivity", "Receiver front end", "RF spectrum", "Automatic frequency coordination"], "common_mistakes": ["Assuming a wider tuning bandwidth improves audio quality, when it mainly affects tuning range and channel count", "Buying gear whose bandwidth does not cover the frequencies available at your venues or region", "Confusing tuning or switching bandwidth with the audio bandwidth of the system"], "scenario_contexts": ["Selecting wide-tuning receivers so one system can be re-coordinated across many cities on tour", "Choosing a frequency band and bandwidth that fit the local spectrum before coordination", "Picking narrower filtering to reject a strong nearby signal"]}, "b7b1ec79-eebd-40ec-9920-b09f337bb96e": {"definition": "The steady radio-frequency sine wave generated by a transmitter that carries information by being modulated (in amplitude, frequency, or phase) with the audio or data signal; the receiver tunes to the carrier's frequency to recover that information. In wireless audio the carrier frequency defines the channel the system operates on.", "plain_english": "A carrier is a steady radio wave a transmitter sends out. The audio is added onto this wave to ride along, like a message written on a moving train. The receiver tunes to that wave's frequency to get the audio back.", "purpose_function": "It provides the radio-frequency vehicle that carries audio through the air, and its frequency defines the channel on which a wireless system transmits and receives.", "practical_application": "A technician selects and coordinates each system's carrier frequency to a clear channel, and matches the transmitter and receiver to the same carrier so the link works.", "category": "RF Fundamentals", "related_terms": ["Modulation", "Carrier frequency", "RF spectrum", "Frequency plan", "Companding", "Squelch"], "common_mistakes": ["Confusing the carrier frequency with the audio frequency it carries", "Leaving two systems on the same carrier frequency, which causes interference", "Assuming the carrier alone contains sound, when without modulation it carries no audio"], "scenario_contexts": ["Tuning the transmitter and receiver to the same carrier frequency during setup", "Coordinating carrier frequencies so multiple systems do not share a channel", "Identifying an unused carrier on a scan before assigning it to a microphone"]}, "192df68f-8e11-4a0d-a246-2987584b26f3": {"definition": "A bandpass or band-limiting filter placed at the input of a wireless receiver's RF section, ahead of or around the first amplifier and mixer, that passes the intended operating band while attenuating out-of-band signals. It prevents strong off-frequency signals from overloading the front end and generating intermodulation or receiver desensitization.", "plain_english": "This is a filter at the very front of a wireless receiver. It lets in the radio band you want and blocks other strong signals. That keeps nearby transmitters from swamping the receiver and causing noise.", "purpose_function": "It protects the receiver's sensitive input stages from overload and blocks out-of-band interference so mainly wanted signals reach the tuner.", "practical_application": "A technician relies on front-end filtering, and may add an external bandpass filter, when working near strong TV or cellular transmitters that could overload receivers.", "category": "Receiver Design", "related_terms": ["RF preselector", "Intermodulation", "Front-end overload", "Bandpass filter", "Desensitization", "Receiver"], "common_mistakes": ["Confusing a broad front-end filter with a narrow preselector tuned to a single channel", "Assuming a front-end filter removes interference that falls inside the operating band", "Ignoring strong out-of-band transmitters that can still overload the front end despite filtering"], "scenario_contexts": ["Adding an external bandpass filter ahead of receivers near a high-power TV tower", "Diagnosing receiver overload caused by a nearby cellular base station", "Selecting band-specific gear so the front-end filter matches the operating range"]}, "1f7b0e34-25c0-408e-bbef-aa85a4b6a1ac": {"definition": "The continuous monitoring and display of a wireless system's radio-link status metrics, such as RF signal level, link quality or signal-to-noise, antenna and diversity status, and interference or dropout events, typically across all channels via networked management software or the receiver front panel.", "plain_english": "This means keeping an eye on how well your wireless links are working. Software or the receiver shows signal strength, noise, and warnings. It lets you spot a weak or failing channel before it drops out during a show.", "purpose_function": "It gives operators real-time visibility of link quality across many channels so they can catch interference, weak signals, or antenna faults before they cause an audible failure.", "practical_application": "A technician watches health metrics in monitoring software during a show and reacts to falling RF or rising noise on a channel before it drops out.", "category": "System Monitoring", "related_terms": ["RF signal strength", "Squelch", "Dropout", "Antenna diversity", "Signal-to-noise ratio", "RF scan"], "common_mistakes": ["Only checking levels at soundcheck instead of monitoring continuously during the show", "Treating a strong RF bar as proof of good audio when noise or interference can still be high", "Ignoring diversity or antenna warnings that predict an imminent dropout"], "scenario_contexts": ["Watching per-channel RF and audio meters in management software during a live broadcast", "Spotting a bodypack with a dying battery from falling RF and battery telemetry", "Catching rising interference on a channel and switching it to a backup frequency"]}, "a6c117fa-ea50-4778-a1ad-2d7ae3b58b16": {"definition": "A transmitter or system function that turns off the RF carrier output while the unit stays powered, so the device stops radiating and its frequency becomes free. This differs from an audio mute, which silences only the audio while the carrier keeps transmitting.", "plain_english": "RF mute switches off the radio signal a transmitter sends out, without turning the unit off. Unlike an audio mute, it stops the transmitter using its channel. That frees the frequency for other gear.", "purpose_function": "It lets an operator take a transmitter off the air without powering it down, freeing its frequency and preventing it from interfering while it is not needed.", "practical_application": "A technician uses RF mute to clear an unused channel during a spectrum scan or between acts, so it does not hide open channels or interfere with active links.", "category": "Transmitter Functions", "related_terms": ["Audio mute", "RF output power", "Transmitter", "RF scan", "Squelch", "Frequency coordination"], "common_mistakes": ["Confusing RF mute with audio mute, which leaves the carrier on and the frequency occupied", "Scanning the band with transmitters only audio-muted, so their carriers still hide open channels", "Forgetting a transmitter is RF-muted and troubleshooting the receiver for a lost link"], "scenario_contexts": ["RF-muting spare transmitters before a frequency scan so their carriers do not appear", "Taking a channel off the air between scenes without powering the pack down", "Clearing a frequency for another user while keeping the transmitter configured and ready"]}, "f2bf92b6-ab1f-4c02-bc57-aa4c501a4c16": {"definition": "A representation of measured RF spectrum activity across a frequency range, showing which frequencies or channels are occupied and which are clear, usually derived from a spectrum scan and used to plan interference-free wireless deployments.", "plain_english": "An RF occupancy map shows which radio channels are busy and which are empty. It comes from scanning the airwaves at a location. You use it to pick clear channels for your wireless gear.", "purpose_function": "It visualizes the local spectrum so coordinators can identify open frequencies and avoid occupied ones when building a frequency plan.", "practical_application": "A technician generates an occupancy map from a venue scan and uses it, often imported into coordination software, to choose clear operating frequencies.", "category": "Frequency Coordination", "related_terms": ["RF scan", "RF scan database", "Spectrum analyzer", "Frequency coordination", "TV white space", "Interference"], "common_mistakes": ["Treating one occupancy map as permanent when spectrum use changes by day and by venue", "Mapping occupancy with your own transmitters on, which marks clear channels as busy", "Assuming an empty-looking channel is safe without checking intermodulation among your own channels"], "scenario_contexts": ["Building an occupancy map from a load-in scan to guide frequency selection", "Comparing occupancy across days of a multi-day festival to find stable open channels", "Importing scan data into coordination software to visualize occupied spectrum"]}, "0e76a035-e441-4445-80de-372845392711": {"definition": "The RF carrier power a wireless transmitter radiates, typically expressed in milliwatts (for example 10, 30, or 50 mW on many professional units) and bounded by regulations such as FCC and ETSI rules. Higher power can extend range but increases battery drain and the potential to interfere with or desensitize nearby receivers.", "plain_english": "RF output power is how strong a radio signal a transmitter sends out. It is measured in milliwatts. More power can reach farther, but it drains the battery faster. It can also interfere with other wireless gear nearby.", "purpose_function": "It sets the strength of the transmitted signal, trading range and link margin against battery life, regulatory limits, and interference with other systems.", "practical_application": "A technician picks a transmitter power setting suited to the distance and RF environment, using lower power in dense multi-channel setups and staying within legal limits.", "category": "Transmitter Functions", "related_terms": ["Transmitter", "RF signal strength", "Front-end overload", "Battery life", "Intermodulation", "RF mute"], "common_mistakes": ["Turning power to maximum by default, which drains batteries and can overload nearby receivers", "Assuming more transmit power always improves range when antennas and obstructions often matter more", "Exceeding the power limit permitted for the band or region"], "scenario_contexts": ["Lowering transmitter power in a dense rack of many channels to reduce intermodulation", "Raising power for a long throw from a bodypack to a distant receiver", "Setting power within legal limits for the operating band and country"]}, "23cb6c21-5de5-4b4a-8125-03deed4f750c": {"definition": "A tunable or fixed bandpass filter stage at the receiver input that narrowly restricts the range of frequencies reaching the first mixer, selecting the wanted channel or sub-band and rejecting adjacent and out-of-band signals before amplification. In wideband receivers it often tracks the tuned frequency to keep the passband centered on the active channel.", "plain_english": "A preselector is a tuning filter at the receiver's input. It narrows down what gets through to just the channel you want. This stops strong nearby signals from mixing together and creating interference.", "purpose_function": "It improves selectivity and blocks strong off-channel signals from reaching the mixer, reducing intermodulation and overload in crowded RF conditions.", "practical_application": "A technician benefits from receivers with tracking preselectors in dense RF, understanding they trade some scan speed for better interference rejection.", "category": "Receiver Design", "related_terms": ["RF front-end filter", "Front-end overload", "Intermodulation", "Selectivity", "Bandpass filter", "Receiver"], "common_mistakes": ["Confusing a preselector with squelch, which acts on the recovered signal rather than the RF input", "Assuming a preselector can reject interference on the same frequency as the wanted signal", "Expecting a fixed filter to track when only tunable preselectors follow the tuned channel"], "scenario_contexts": ["Choosing receivers with tracking front-end filters for a crowded urban RF site", "Reducing intermodulation from nearby transmitters in a multi-channel rack", "Understanding why a wideband receiver rejects a strong out-of-band signal"]}, "82a2db68-c7a6-4c6c-96c1-79f972c6c7b3": {"definition": "A function in which a receiver or spectrum tool sweeps a frequency band and measures RF activity to identify occupied and clear frequencies, used to choose interference-free operating channels for a wireless system.", "plain_english": "An RF scan means the receiver listens across its whole band. It finds which channels are busy and which are open. Then you pick an empty channel for your wireless mic.", "purpose_function": "It surveys the local spectrum so operators can choose clear frequencies without separate test gear, lowering the chance of interference.", "practical_application": "A technician runs an RF scan on arrival at a venue, then assigns clear channels and often syncs them to transmitters by infrared.", "category": "Frequency Coordination", "related_terms": ["RF scan database", "RF occupancy map", "Automatic frequency scan", "Spectrum analyzer", "Frequency coordination", "Squelch"], "common_mistakes": ["Scanning with your own transmitters on, which hides truly open channels", "Scanning once and never rescanning when the RF environment changes", "Treating a scan as full coordination when it does not calculate intermodulation"], "scenario_contexts": ["Scanning the band during load-in at an unfamiliar venue", "Finding an open channel after a nearby broadcast starts causing interference", "Running the receiver scan, then infrared-syncing a clear frequency to the bodypack"]}, "e5bab98c-90ac-43ea-8e52-16cdb2b57ee8": {"definition": "A stored collection of RF spectrum scan data, such as measured signal levels across frequencies and identified occupied or clear channels, saved for later use in frequency coordination or imported into coordination software to build a frequency plan.", "plain_english": "An RF scan database is saved scan results kept for later. It records which channels were busy at a place and time. Coordination software can load it to help pick clear frequencies.", "purpose_function": "It preserves scan measurements so coordinators can reuse, compare, or import spectrum data into planning software instead of relying on a live scan alone.", "practical_application": "A technician saves venue scans to a database and imports them into coordination software to generate or refine a frequency plan.", "category": "Frequency Coordination", "related_terms": ["RF scan", "RF occupancy map", "Frequency coordination", "Spectrum analyzer", "TV white space", "Frequency plan"], "common_mistakes": ["Reusing old saved scans when the spectrum has since changed", "Storing scans taken with your own transmitters on, which record false occupancy", "Assuming stored scan data replaces intermodulation coordination"], "scenario_contexts": ["Importing a saved scan into coordination software to build a frequency plan", "Comparing stored daily scans across a festival to find stable channels", "Archiving venue scans for reuse on a returning tour date"]}, "f99958ef-d937-4ac2-aa45-82428d9bf09f": {"definition": "The RF signal level, or link-quality level, below which a receiver mutes its audio output, set to silence noise when the wanted signal is too weak or absent. Signals above the threshold pass to the output, while those below it trigger muting.", "plain_english": "The squelch threshold is the signal level where the receiver decides to mute. If the radio signal drops below it, the audio cuts to avoid loud static. Set it too high and you lose good signal; too low and you let noise through.", "purpose_function": "It defines the cutoff point for muting so the receiver stays quiet during dropouts and weak signals but still passes usable audio, balancing noise rejection against range.", "practical_application": "A technician sets the squelch threshold just above the noise floor, high enough to block static at dropout but low enough not to cut the wanted signal early.", "category": "Receiver Functions", "related_terms": ["Squelch", "Audio mute", "RF signal strength", "Dropout", "Signal-to-noise ratio", "Noise floor"], "common_mistakes": ["Setting the threshold too low, letting bursts of noise through during dropouts", "Setting it too high, which mutes the audio early and shortens usable range", "Confusing the squelch threshold with transmitter RF power or receiver gain"], "scenario_contexts": ["Adjusting squelch so a receiver mutes cleanly when a transmitter is switched off", "Raising the threshold to stop static in a high-interference venue", "Lowering the threshold to keep a weak but usable signal from muting at the edge of range"]}, "7e1d5947-ff02-4755-b96b-2c33f9e1cc5b": {"definition": "A coverage test in which a technician moves through the performance and audience area carrying or wearing a transmitter while monitoring the receiver's RF level and audio, in order to find dropouts, dead spots, and weak-coverage areas before the system is used.", "plain_english": "An RF walk is a coverage check. You carry a wireless mic and walk the whole stage and room. Someone watches the receiver for signal drops. It finds dead spots before the show, not during it.", "purpose_function": "It verifies that antennas and receivers give solid, dropout-free coverage everywhere a performer will move, so weak spots get found and fixed during setup rather than during the show.", "practical_application": "Before doors, a tech walks every part of the stage and audience path with a transmitter while a colleague watches the receiver's RF meter for fades.", "category": "Frequency Coordination", "related_terms": ["Dropout", "Space diversity", "Antenna placement", "RF zones", "Squelch"], "common_mistakes": ["Walking the stage only and skipping the audience and backstage areas the talent will actually enter", "Doing the walk with different antenna positions than the show will use, so the results do not match", "Watching only the audio and ignoring the receiver's RF level meter, which warns of a fade before it is heard"], "scenario_contexts": ["Checking wireless coverage across a theatre stage and wings before a performance", "Testing a presenter's lavalier as they walk into the audience during a corporate event", "Confirming coverage after moving antennas to fix a reported dropout"]}, "a9e3c1b7-9f74-400b-b7e0-c0ec43617973": {"definition": "Separate coverage areas into which a large or obstructed venue is divided, each served by its own dedicated receive antenna or antennas, so wireless microphones stay reliably covered where a single antenna set could not reach the whole space.", "plain_english": "RF zones split a big venue into smaller coverage areas. Each zone gets its own antenna. This helps when one antenna cannot cover the whole place. It is a bit like several Wi-Fi points serving a large building.", "purpose_function": "Zones give reliable wireless coverage in venues too large or too blocked by walls for one antenna position to serve, by placing antennas close to each area of use.", "practical_application": "In a large church, a tech assigns one antenna to the altar zone and another to the far congregation zone, then combines the zones into the receiver rack.", "category": "Antenna Systems", "related_terms": ["Antenna placement", "Antenna distribution", "Active antenna splitter", "Space diversity", "RF-over-fiber transport"], "common_mistakes": ["Trying to cover a huge or L-shaped venue from one antenna position instead of splitting it into zones", "Forgetting to make up cable loss with an in-line amplifier on long runs to a distant zone", "Overlapping zones so heavily that the same signal arrives twice and causes interference"], "scenario_contexts": ["Covering a 2,000-seat cathedral with several antenna zones", "Serving separate stage and greenroom areas from one wireless rack", "Adding a new coverage zone when a production expands into a lobby"]}, "3167e13f-1214-49dd-8c3c-6dd38b64b73a": {"definition": "A method of carrying wireless-microphone RF signals by converting them to modulated light for transmission over fiber-optic cable and converting them back to RF at the far end, allowing antennas to be placed very far from the receivers with almost no signal loss over the run.", "plain_english": "RF-over-fiber sends antenna signals as light through a fiber cable. A box turns the radio signal into light. Another box turns it back at the far end. Fiber loses almost no signal, so antennas can sit very far from the rack.", "purpose_function": "It connects remote antennas to receivers over very long distances without the heavy signal loss that long coaxial cable causes, keeping wireless reliable across large sites.", "practical_application": "A tech runs fiber from stage-edge antennas to a receiver rack hundreds of feet away in a broadcast truck, avoiding the loss a coax run that long would add.", "category": "Antenna Systems", "related_terms": ["Antenna distribution", "Coaxial cable", "Active antenna splitter", "RF zones", "Insertion loss"], "common_mistakes": ["Assuming the fiber link also powers the remote antenna unit, which usually needs its own local power", "Reaching for fiber on short runs where good coaxial cable is simpler and cheaper", "Ignoring the gain settings on the conversion units, causing overload or a weak signal"], "scenario_contexts": ["Linking stadium-roof antennas to a control room far below", "Connecting antennas in a broadcast compound to receivers in a truck", "Covering a long stadium concourse where coaxial cable loss would be too high"]}, "82e75d76-32ab-4818-82cc-078efb2ff26d": {"definition": "A measurement in which a receiver, spectrum manager, or coordination software sweeps across a frequency band and records the RF energy present, producing a picture of which frequencies are occupied and which are open for wireless use.", "plain_english": "A scan checks the airwaves across a band of frequencies. The gear measures how busy each frequency is. It shows which channels are free and which are in use. You scan first, then pick clear frequencies.", "purpose_function": "It reveals the local RF environment, including TV stations and other transmitters, so a technician can choose clear, compatible frequencies and avoid interference.", "practical_application": "On arrival at a venue, a tech runs a scan with a receiver or spectrum manager, then imports the data into coordination software to assign frequencies.", "category": "Frequency Coordination", "related_terms": ["Scan sensitivity", "Spectrum analyzer mode", "Frequency coordination", "Squelch", "Intermodulation"], "common_mistakes": ["Scanning from one spot only, missing interference that appears elsewhere in the venue", "Scanning with your own nearby transmitters left on, so your gear hides truly open frequencies", "Trusting an old scan instead of re-scanning, since the RF environment changes daily"], "scenario_contexts": ["Finding open frequencies on load-in at a new venue", "Re-scanning between soundcheck and doors to catch new interference", "Feeding scan data into Wireless Workbench for coordination"]}, "343700d4-dd22-48ca-a74a-77690179543d": {"definition": "An adjustable threshold that sets how strong an RF signal must be during a scan to be counted as an occupied frequency; a more sensitive setting flags weaker signals as used, while a less sensitive setting ignores them.", "plain_english": "Scan sensitivity sets how faint a signal counts as busy during a scan. A high setting marks even weak signals as used. A low setting ignores them. It is like adjusting how picky the search is.", "purpose_function": "It lets the technician tune how cautious a scan is, balancing between flagging too many frequencies as occupied and missing weak interference that could still cause dropouts.", "practical_application": "A tech lowers scan sensitivity in a noisy urban venue so faint distant signals do not wrongly rule out usable frequencies.", "category": "Frequency Coordination", "related_terms": ["Scan", "Squelch", "Spectrum analyzer mode", "Noise floor", "Frequency coordination"], "common_mistakes": ["Setting sensitivity so high that nearly every frequency looks occupied and few remain usable", "Setting it so low that real interference is missed and dropouts happen during the show", "Confusing scan sensitivity with the receiver's squelch, which mutes audio rather than marking frequencies"], "scenario_contexts": ["Adjusting the exclusion or scan threshold in coordination software before a scan", "Tuning scan sensitivity for a busy downtown RF environment", "Comparing scans at different thresholds to judge how crowded a band is"]}, "c403bcd0-10d3-437e-9e03-cd486dabfb9c": {"definition": "Industry nickname for a directional log-periodic dipole array (LPDA) antenna, named for its triangular fin-like shape, used to receive wireless-microphone signals from a chosen direction across a wide frequency range.", "plain_english": "A shark fin is a directional antenna shaped like a fin. It listens best in the direction it points. It also works across many frequencies at once. Techs aim it at the stage to grab the mic signals and reject noise from behind.", "purpose_function": "Its directional pattern boosts the wanted signal from the stage while rejecting interference from other directions, and its wide bandwidth covers many channels at once.", "practical_application": "A tech mounts a pair of shark-fin antennas on stands aimed at the performers, feeding a diversity receiver rack for cleaner reception.", "category": "Antenna Systems", "related_terms": ["Log-periodic dipole array", "Directional antenna", "Space diversity", "Antenna gain", "Paddle antenna"], "common_mistakes": ["Aiming the shark fin away from the performers, losing the directional gain it is meant to provide", "Assuming it is omnidirectional and mounting it without care for where it points", "Placing the diversity pair too close together, which reduces the diversity benefit"], "scenario_contexts": ["Aiming a directional antenna pair at a stage in a busy RF environment", "Rejecting interference from an LED wall behind the receive position", "Covering a wide UHF range with one broadband directional antenna"]}, "4712c3eb-dd7a-4109-b8f2-a6b3c9fda8b8": {"definition": "A diversity technique that uses two receiving antennas placed a distance apart so that each picks up a different multipath signal path; the receiver then combines or selects the stronger one, reducing dropouts caused by fading and reflections.", "plain_english": "Space diversity uses two antennas set apart from each other. Each one hears the signal a little differently. The receiver picks whichever is stronger moment to moment. This keeps the sound going when one antenna hits a weak spot.", "purpose_function": "It fights dropouts from multipath fading by giving the receiver two spatially separated signal paths, so a fade at one antenna rarely happens at the other at the same instant.", "practical_application": "A tech spaces a true-diversity receiver's two antennas apart by at least a quarter wavelength so reflections that null one antenna do not null the other.", "category": "Antenna Systems", "related_terms": ["True diversity", "Dropout", "Multipath", "Antenna placement", "Shark fin"], "common_mistakes": ["Mounting the two antennas touching or very close, which cancels the spatial difference diversity relies on", "Assuming any two-antenna receiver gives diversity, when some only use the second antenna as a spare", "Crossing or mismatching the A and B antenna feeds so the receiver cannot compare them properly"], "scenario_contexts": ["Setting up a true-diversity receiver rack for a live band", "Reducing dropouts as a performer moves behind stage scenery", "Spacing antennas correctly in a reflective, metal-walled room"]}, "fe9e3c01-5828-45d5-b847-33348c10840d": {"definition": "Informal term for a spare handheld wireless microphone transmitter kept charged, tuned, and ready so it can instantly replace a handheld unit that fails, runs low on battery, or is dropped during a show.", "plain_english": "A spare stick is a backup handheld wireless mic, ready to go. 'Stick' is slang for a handheld mic. If the main one dies or breaks, someone hands over the spare. It keeps the show running with no gap.", "purpose_function": "It gives an immediate replacement for a live handheld mic, avoiding dead air or a stopped show if the primary transmitter fails or its battery dies.", "practical_application": "A stage tech keeps a spare stick on the same frequency plan, powered and muted at the side, ready to swap in if a singer's handheld drops out.", "category": "Wireless Systems", "related_terms": ["Handheld transmitter", "Frequency coordination", "Battery management", "Dropout", "RF walk"], "common_mistakes": ["Leaving the spare on a frequency that clashes with an active channel, causing interference when it is powered on", "Storing the spare with a flat battery, so it is not truly ready when needed", "Forgetting to mute the spare, so switching it on adds noise or feedback"], "scenario_contexts": ["Keeping a backup handheld ready at front-of-house during a concert", "Swapping in a spare when a presenter's handheld battery runs low", "Having a pre-tuned handheld ready for a guest speaker at a conference"]}, "7030cc67-13fc-4a6d-8a8a-633a16e4962e": {"definition": "A built-in mode on a wireless receiver or spectrum manager that displays measured RF energy across a frequency band, much like a dedicated spectrum analyzer, so the operator can see occupied and open frequencies without separate test equipment.", "plain_english": "Spectrum analyzer mode turns a receiver into a signal viewer. It shows how busy each frequency is across a band. Free channels and used ones appear on a graph. It helps you find clear frequencies without extra test gear.", "purpose_function": "It gives technicians an on-board view of the RF environment for finding clear frequencies and spotting interference, without needing a standalone spectrum analyzer.", "practical_application": "A tech switches a receiver into spectrum analyzer mode to watch a band in real time and confirm a chosen frequency is clear before going live.", "category": "Frequency Coordination", "related_terms": ["Scan", "Scan sensitivity", "Frequency coordination", "Spectrum manager", "Noise floor"], "common_mistakes": ["Reading the display from one location only, missing interference elsewhere in the room", "Confusing the live spectrum view with a saved scan used for coordination", "Ignoring the noise floor level, which shows how much RF junk is present"], "scenario_contexts": ["Watching a UHF band live before assigning a frequency", "Spotting a new interfering transmitter that appeared during a show", "Checking a band on-site without carrying a separate spectrum analyzer"]}, "8313965c-d351-4f4d-949c-a3437d76858d": {"definition": "The systematic process of assigning operating frequencies to multiple wireless systems so that no unit interferes with another, with local broadcast services, or with other spectrum users. It accounts for intermodulation products, occupied TV channels, guard bands, and each unit's tuning range to produce a compatible frequency plan.", "plain_english": "Spectrum coordination means picking radio channels for many wireless units so none of them clash. It is like giving cars separate lanes so they do not collide. Software checks each choice against nearby TV stations and other gear.", "purpose_function": "It exists so many wireless microphones, in-ear monitors, and intercoms can run at the same time without dropouts or interference, especially where the airwaves are crowded.", "practical_application": "A technician uses coordination software to scan the RF environment and generate a set of compatible frequencies before load-in, then loads those frequencies into every unit.", "category": "Frequency Coordination", "related_terms": ["Intermodulation", "Third-order intermod", "Frequency scan", "TV-channel coordination", "Guard band", "Frequency agile"], "common_mistakes": ["Choosing frequencies by spacing them evenly without calculating intermodulation products", "Coordinating only your own systems while ignoring nearby broadcasters and other production wireless", "Assuming a coordination done in one city will work unchanged in another location", "Leaving IEM and intercom transmitters out of the same coordination as the microphones"], "scenario_contexts": ["Building a frequency plan for a multi-channel festival with dozens of wireless systems", "Re-coordinating after arriving in a new city where the local TV channels differ", "Adding extra microphones to a show and checking they stay compatible with the existing plan"]}, "63d1c81e-8c23-4b86-baf3-600bb06d9ec8": {"definition": "A dedicated output and talk function on an intercom main station that routes a user's voice to a separate loudspeaker system, letting crew address performers and personnel on and around the stage. It is triggered by a switch that interrupts or supplements the normal intercom talk path.", "plain_english": "Stage announce lets someone on a headset talk out loud to people on stage. It sends the voice to loudspeakers instead of only to other headsets. Crew use it to page performers or backstage staff.", "purpose_function": "It provides a built-in paging path so an operator can make announcements to the stage area without a separate PA microphone, keeping backstage communication fast and centralized.", "practical_application": "A stage manager presses the stage-announce key on the intercom base station to call performers to places over the backstage loudspeakers.", "category": "Intercom Systems", "related_terms": ["2-wire", "4-wire", "Party-line intercom", "Intercom base station", "Beltpack", "Talkback"], "common_mistakes": ["Confusing stage announce with normal intercom talk, which only reaches other headsets", "Leaving the stage-announce key latched on, so private conversation is broadcast over the loudspeakers", "Assuming every beltpack can trigger stage announce when it is usually a main-station function"], "scenario_contexts": ["A stage manager paging performers to the stage before a cue", "Making a backstage call for a scenic crew to reset props between acts", "Announcing a hold or safety message to everyone in the stage area"]}, "545b3591-d06b-4ed6-8620-dd327da581a8": {"definition": "A third-order intermodulation product is an unwanted signal created when two RF carriers mix in a non-linear device, appearing at frequencies equal to twice one carrier minus the other. These products are the most troublesome in wireless systems because they fall close to the original carriers and often land inside a receiver's passband.", "plain_english": "When two radio signals mix inside gear, they create extra fake signals. The third-order ones land very close to the real channels. That makes them a main cause of interference between wireless mics.", "purpose_function": "Understanding third-order products lets coordinators space frequencies so these strong, close-in interference signals do not fall on any channel in use.", "practical_application": "A technician relies on coordination software to calculate third-order products and avoids assigning any wireless channel that lands on one.", "category": "Frequency Coordination", "related_terms": ["Intermodulation", "Spectrum coordination", "Frequency scan", "Nonlinearity", "Guard band", "TV-channel coordination"], "common_mistakes": ["Spacing frequencies evenly and assuming that alone avoids intermodulation", "Thinking intermodulation only matters at high transmit power", "Ignoring third-order products created between microphones and nearby IEM transmitters", "Believing more expensive receivers are immune to intermodulation interference"], "scenario_contexts": ["Diagnosing dropouts that appear only when two specific transmitters are switched on together", "Coordinating a dense channel count where third-order products limit how many systems fit", "Checking a manual frequency choice against a calculated intermodulation chart"]}, "020627d8-01ad-49eb-bd8d-7c165ff6533e": {"definition": "A diversity technique that transmits or reconstructs the same information at more than one point in time so a brief fade or burst of interference does not destroy the message. In digital wireless it is implemented with methods such as interleaving, error-correction coding, or retransmission across separate time intervals.", "plain_english": "Time diversity sends the same data more than once at slightly different moments. If one copy is hit by interference, a later clean copy fills the gap. It is like repeating an important word so it is not missed.", "purpose_function": "It improves reliability against short, time-varying fades and noise bursts, and it complements antenna (space) diversity, which instead fights fades that vary by location.", "practical_application": "A technician usually meets time diversity indirectly, as the error resilience built into a digital wireless link, rather than as a switch to set.", "category": "Diversity Techniques", "related_terms": ["Antenna diversity", "Frequency diversity", "Space diversity", "Dropout", "Error correction", "Fading"], "common_mistakes": ["Confusing time diversity with antenna (true) diversity, which uses two antennas instead of two time slots", "Assuming diversity of any kind removes all dropouts rather than reducing them", "Thinking time diversity is a user control when it is built into the system design"], "scenario_contexts": ["Comparing why a digital wireless link rides through brief interference that would drop an analog one", "Explaining the difference between space, frequency, and time diversity during training", "Evaluating digital wireless systems for robustness in an RF-hostile venue"]}, "d2300087-7f4b-4a86-b0eb-8966a7a7aea7": {"definition": "A transmitter operating mode that lowers RF output power or places the transmitter into a reduced-activity state to extend battery life when full range is not required. It trades transmission range and link margin for longer runtime.", "plain_english": "This mode lowers the transmitter's radio power to save battery. It works when the receiver is close, so full range is not needed. You get longer runtime but shorter reach.", "purpose_function": "It exists to stretch battery life for long events and rehearsals, and to cut RF energy in the room when maximum range is unnecessary.", "practical_application": "A technician enables a power-save or low-power setting on bodypacks during long rehearsals where the receiver antennas are nearby.", "category": "Transmitters", "related_terms": ["Transmitter power adjustment", "RF output power", "Bodypack transmitter", "Battery life", "Link budget", "Standby mode"], "common_mistakes": ["Leaving power-save on for a show and then losing range as a performer moves far from the antennas", "Assuming power-save mode saves large amounts of battery when RF output is only part of the total drain", "Confusing power-save mode with a full standby or sleep mode that mutes the transmitter"], "scenario_contexts": ["Running long technical rehearsals where performers stay near the receivers", "Extending bodypack runtime on a show with no time for a battery change", "Reducing RF congestion in a small room with many transmitters close to the antennas"]}, "137ff5af-bf2f-4c0d-ae94-691dafb26a06": {"definition": "A limiter stage in a wireless transmitter's audio path that caps peak audio levels before modulation, preventing the modulator from being overdriven. It stops overmodulation, which would otherwise cause distortion, excessive RF deviation, and splatter into adjacent channels.", "plain_english": "This is a safety brake on the sound going into a wireless transmitter. It stops loud peaks from overloading the radio signal. That keeps the audio clean and stops it from spilling onto other channels.", "purpose_function": "It protects the radio link from overmodulation caused by sudden loud sounds, keeping distortion low and keeping the signal inside its assigned channel.", "practical_application": "A technician still sets transmitter gain correctly and treats the limiter as protection for occasional peaks, not as a substitute for proper gain staging.", "category": "Transmitters", "related_terms": ["Transmitter power adjustment", "Gain staging", "Modulation", "Companding", "Overmodulation", "Bodypack transmitter"], "common_mistakes": ["Relying on the limiter instead of setting input gain correctly, causing constant limiting and dull sound", "Setting transmitter gain so low that the limiter never helps and the signal-to-noise ratio suffers", "Assuming the limiter can undo distortion that happens before it in the microphone or preamp"], "scenario_contexts": ["Setting bodypack gain for a singer who suddenly belts loud notes", "Preventing overmodulation on a lavalier during unexpected shouts", "Troubleshooting distortion and checking whether the transmitter is clipping before the limiter"]}, "8239163a-fed6-40ac-b6c5-40b0fe3b2234": {"definition": "A control that sets a wireless transmitter's RF output power, typically among fixed steps such as low, medium, and high (for example, 10, 50, or 100 milliwatts). The chosen setting balances operating range and link margin against battery life, intermodulation, and regulatory power limits.", "plain_english": "This control sets how strong the transmitter's radio signal is. Higher power reaches farther but drains the battery faster. Lower power saves battery and can reduce interference when the receiver is close.", "purpose_function": "It lets an operator match transmit power to the distance and RF environment, saving battery and reducing interference while staying within legal power limits.", "practical_application": "A technician raises power for long throws or difficult sightlines and lowers it in small, crowded RF spaces to save battery and limit intermodulation.", "category": "Transmitters", "related_terms": ["Transmit power save mode", "RF output power", "Link budget", "Intermodulation", "Bodypack transmitter", "Battery life"], "common_mistakes": ["Setting output power above the legal limit for the frequency band and license, which causes interference and breaks the rules", "Running maximum power everywhere, which needlessly drains batteries and worsens intermodulation", "Assuming more power always cures dropouts when the real cause is antenna placement or multipath"], "scenario_contexts": ["Increasing bodypack power for a performer who works the far end of a large stage", "Lowering transmitter power in a small studio to save battery and reduce intermodulation", "Setting power to comply with the RF output limits for the operating band and license"]}, "79b05e73-f42e-46af-ac82-935c55f9fd1c": {"definition": "The practice of assigning wireless microphone frequencies to locally unused television broadcast channels (white spaces) within the UHF band so they do not interfere with active DTV stations. It requires knowing which TV channels are occupied at the specific location and keeping wireless systems out of those channels.", "plain_english": "Wireless mics often share the same airwaves as TV stations. TV-channel coordination means using only the TV channels that are empty in that area. This keeps the mics from clashing with local broadcasts.", "purpose_function": "It keeps wireless microphones from interfering with, and being interfered by, licensed television broadcasts, which have priority in the UHF band.", "practical_application": "A technician checks which TV channels are active at the venue's location, then tunes all wireless gear into the vacant channels before coordinating individual frequencies.", "category": "Frequency Coordination", "related_terms": ["Spectrum coordination", "White space", "UHF band", "Frequency scan", "Third-order intermod", "DTV interference"], "common_mistakes": ["Reusing a frequency plan from another city, where a different set of TV channels is occupied", "Forgetting that TV-channel occupancy changes by location, so each venue must be rechecked", "Placing wireless systems in a TV channel that is actually active or legally protected locally"], "scenario_contexts": ["Setting up wireless at a touring venue and identifying the local open TV channels first", "Avoiding a TV channel that carries a strong local station near the venue", "Rescanning and retuning after moving a production to a new broadcast market"]}}$ape$::jsonb)) d WHERE g.id=d.id;
UPDATE glossary g SET definition = CASE WHEN d.p ? 'definition' THEN d.p->>'definition' ELSE g.definition END, plain_english = CASE WHEN d.p ? 'plain_english' THEN d.p->>'plain_english' ELSE g.plain_english END, purpose_function = CASE WHEN d.p ? 'purpose_function' THEN d.p->>'purpose_function' ELSE g.purpose_function END, practical_application = CASE WHEN d.p ? 'practical_application' THEN d.p->>'practical_application' ELSE g.practical_application END, category = CASE WHEN d.p ? 'category' THEN d.p->>'category' ELSE g.category END, related_terms = CASE WHEN d.p ? 'related_terms' THEN ARRAY(SELECT jsonb_array_elements_text(d.p->'related_terms')) ELSE g.related_terms END, common_mistakes = CASE WHEN d.p ? 'common_mistakes' THEN ARRAY(SELECT jsonb_array_elements_text(d.p->'common_mistakes')) ELSE g.common_mistakes END, scenario_contexts = CASE WHEN d.p ? 'scenario_contexts' THEN ARRAY(SELECT jsonb_array_elements_text(d.p->'scenario_contexts')) ELSE g.scenario_contexts END FROM (SELECT key::uuid AS id, value AS p FROM jsonb_each($ape${"77ae979a-1f38-4f31-8a16-2d7e09c1028e": {"definition": "A wireless microphone receiver whose RF front end and tuning cover a wide, continuous span of spectrum, often an entire UHF band of several hundred megahertz, rather than a narrow fixed sub-band. This lets one unit be tuned to a large range of frequencies for greater coordination flexibility.", "plain_english": "A wideband receiver can tune across a big chunk of the radio band. Narrow ones only cover a small slice. The wide range makes it easier to find a clear channel. One model can also work in more places.", "purpose_function": "It gives operators a large tuning range in a single device so they can avoid interference and coordinate many channels without buying separate band-specific units.", "practical_application": "A technician chooses a wideband receiver to cover the full range a show needs, then scans and tunes it to clear frequencies as venues and local TV usage change.", "category": "Receiver Systems", "related_terms": ["Wireless microphone system", "Automatic frequency scan", "Antenna diversity", "Frequency coordination", "RF spectrum", "UHF band"], "common_mistakes": ["Assuming a wider tuning range automatically means better sensitivity or longer range, which are separate specifications", "Believing a wideband unit may legally transmit or operate on any frequency it can tune to, ignoring local spectrum rules", "Confusing the receiver's overall tuning bandwidth with the narrow bandwidth a single link actually occupies"], "scenario_contexts": ["A touring rig uses one receiver model across cities that each have different open channels", "Choosing wideband receivers to simplify inventory and spares across many venues", "Rescanning and retuning a wideband receiver when local interference changes"]}, "c0ed5bf4-a5cd-4af3-91f5-0d2c9ad766b2": {"definition": "A hardwired production communication system that links crew members through cabled beltpacks and headsets over a shared party-line or matrix, allowing hands-free talk and listen during a production. Common formats include analog two-wire party-line and four-wire or digital matrix systems.", "plain_english": "A wired intercom lets a crew talk to each other over cables. Each person wears a headset and a small beltpack. Everyone on the line can hear and speak. It works like a shared phone line for the show crew.", "purpose_function": "It provides reliable, low-latency, hands-free communication among crew so cues and coordination stay clear during rehearsals and live shows.", "practical_application": "A technician runs cable to beltpacks at each position, sets each headset's mic and listen level, and uses the intercom to pass cues with the director and crew.", "category": "Intercom Systems", "related_terms": ["Wireless intercom", "Party-line intercom", "Beltpack", "Matrix intercom", "Headset microphone", "Program audio"], "common_mistakes": ["Confusing two-wire party-line gear with four-wire or matrix systems, which are not directly compatible without an interface", "Failing to null or set sidetone, so users hear their own voice too loudly in the headset", "Overloading a long party-line so beltpacks at the far end are weak, noisy, or under-powered"], "scenario_contexts": ["A stage manager cues lighting and sound over a headset during a live show", "A broadcast camera crew coordinates shots through cabled beltpacks", "Running intercom cable to front-of-house, monitors, and backstage positions"]}, "ad109af2-547c-4e54-83d9-30d2a54c4cf3": {"definition": "The discipline of designing, coordinating, deploying, and maintaining radio-frequency audio systems such as wireless microphones, in-ear monitors, and wireless intercom. It covers spectrum management, antenna and RF distribution, frequency coordination, and regulatory compliance.", "plain_english": "This is the work of running audio gear that sends sound over radio. It covers wireless mics, in-ear monitors, and intercoms. The engineer finds clear channels. They set up antennas and follow the radio rules.", "purpose_function": "It exists to deliver reliable, interference-free wireless audio by managing limited radio spectrum, antenna systems, and coordination across many channels and users.", "practical_application": "A technician in this field scans the spectrum, coordinates frequencies, deploys antennas, and monitors RF during a production to keep every wireless link stable.", "category": "RF Fundamentals", "related_terms": ["Wireless microphone system", "Frequency coordination", "RF spectrum", "Antenna distribution system", "In-ear monitor system", "Intermodulation"], "common_mistakes": ["Treating wireless setup as plug-and-play rather than planned spectrum coordination", "Ignoring local spectrum regulations and licensed users of the same frequencies", "Assuming more transmitter power always fixes range or dropout problems"], "scenario_contexts": ["Planning RF for a multi-channel theatre or festival production", "Coordinating frequencies and antennas for a live broadcast", "Managing spectrum on tour where each city has different occupied channels"]}, "bd756d03-b1ab-4fd0-a1da-e2e4d328907c": {"definition": "A crew communication system that uses radio-frequency or DECT wireless beltpacks and headsets instead of cabled connections, letting mobile users talk and listen hands-free while moving around a production. It may run standalone or bridge into a wired intercom system.", "plain_english": "A wireless intercom lets crew talk without being tied to a cable. Each person wears a headset and a small radio beltpack. They can walk around and still hear cues. It often links into the wired intercom too.", "purpose_function": "It gives mobile crew hands-free communication on the same party-line as wired positions, freeing them from cable while keeping everyone coordinated.", "practical_application": "A technician assigns wireless beltpacks to roaming crew, places the base-station antennas and channels, and bridges the wireless system into the wired intercom for one network.", "category": "Intercom Systems", "related_terms": ["Wired intercom", "Beltpack", "Party-line intercom", "Base station", "Antenna", "Frequency coordination"], "common_mistakes": ["Assuming unlimited beltpacks per base station, when each system has a fixed channel or user limit", "Forgetting that wireless intercom shares crowded spectrum with mics and monitors and needs coordination", "Placing the base-station antenna poorly, causing dropouts as users roam"], "scenario_contexts": ["A roaming stage manager stays on comms while walking the set", "Camera operators on a live sports broadcast use wireless beltpacks", "Bridging wireless beltpacks into the wired party-line for a touring show"]}, "f8c53228-33bf-4883-a570-d1d8a0119f00": {"definition": "A complete radio link for audio consisting of a transmitter (handheld, bodypack, or plug-on) that converts a microphone's audio into an RF signal, and a receiver that recovers the audio and feeds it to a mixer or sound system, both operating on a coordinated frequency in a licensed or license-exempt band.", "plain_english": "A wireless microphone system sends a mic's sound over radio instead of a cable. A transmitter turns the sound into a radio signal. A receiver catches it and passes the audio to the mixer. This lets performers move freely on stage.", "purpose_function": "It frees performers and presenters from mic cables while still delivering their audio to the sound system, using matched transmitter and receiver tuned to the same clear frequency.", "practical_application": "A technician pairs a transmitter and receiver on a coordinated frequency, sets gain and squelch, checks battery and RF levels, and monitors the link throughout a performance.", "category": "Wireless Systems", "related_terms": ["Transmitter", "Receiver", "Antenna diversity", "Squelch", "Frequency coordination", "Companding"], "common_mistakes": ["Setting transmitter input gain too high, causing clipping and distortion that no receiver setting can undo", "Ignoring frequency coordination so multiple systems interfere with one another", "Mixing transmitters and receivers from different bands or regions without checking legality and compatibility"], "scenario_contexts": ["A vocalist using a handheld transmitter during a concert", "A presenter wearing a bodypack with a lavalier at a conference", "Coordinating multiple wireless mic systems for a full theatre cast"]}, "e34304f5-f2d8-40e8-b078-6ebca1fb55e5": {"definition": "The process of confirming that a deployed wireless system meets required operating standards before and during use, by measuring RF signal strength, diversity behavior, audio level and quality, squelch performance, and coverage across the performance area, and documenting the results.", "plain_english": "This is the step of proving a wireless system really works before the show. You check that the radio signal is strong everywhere performers go. You listen for clean audio and no dropouts. Then you write down the results.", "purpose_function": "It exists to catch weak coverage, interference, or setup errors before they cause failures on stage or on air, giving objective proof the system is ready.", "practical_application": "A technician walks the stage with a transmitter while watching the receiver's RF and audio meters, marking any dropout zones and fixing antenna placement or frequencies before doors open.", "category": "System Deployment", "related_terms": ["Wireless system commissioning", "Antenna diversity", "RF signal strength", "Dropout", "Walk test", "Squelch"], "common_mistakes": ["Verifying only from the mix position instead of walking the whole performance area", "Testing with other transmitters switched off, which hides interference that appears during the show", "Skipping documentation, so recurring problems cannot be traced or compared later"], "scenario_contexts": ["Walk-testing every wireless channel across the stage before a live broadcast", "Checking mic and in-ear coverage in balcony and backstage areas", "Confirming diversity and RF levels during rehearsal to find dead spots"]}, "3db0471e-5a4a-4e60-be85-eb5a64b30f9a": {"definition": "The structured process of bringing a wireless audio system into service, including spectrum scanning, frequency coordination, antenna and distribution setup, transmitter and receiver configuration, gain and squelch calibration, coverage or walk testing, and documentation, so the system is verified and ready for reliable operation.", "plain_english": "Commissioning is the full setup that gets a wireless system ready to use. You scan for clear channels, coordinate frequencies, and place antennas. Then you set levels, test coverage, and write it all down. After that the system is trusted for the show.", "purpose_function": "It ensures a wireless system is correctly configured, coordinated, and proven before hand-off or first use, reducing failures and giving a documented baseline for later troubleshooting.", "practical_application": "A technician commissions a new install or show rig by scanning and coordinating frequencies, mounting antennas, configuring receivers, verifying coverage, and recording the final settings.", "category": "System Deployment", "related_terms": ["Wireless performance verification", "Frequency coordination", "Antenna distribution system", "Automatic frequency scan", "Squelch", "RF coverage"], "common_mistakes": ["Skipping a documented frequency plan, so the system cannot be reproduced or troubleshot later", "Commissioning without a full coverage walk test across the performance area", "Leaving default gain and squelch settings instead of calibrating them for the specific venue"], "scenario_contexts": ["Commissioning a permanent wireless install in a house of worship or conference center", "Setting up and proving a touring wireless rig on arrival at each venue", "Handing a verified, documented wireless system over to a venue's staff"]}, "d7e8881c-b880-4cd3-b789-811c336a4fc7": {"definition": "The most basic scratch technique, in which the DJ moves the record forward and backward under the stylus with the crossfader left fully open, so every motion is heard. It produces a rhythmic back-and-forth sound and forms the foundation for more advanced, fader-based scratches.", "plain_english": "The simplest scratch. You push and pull the record back and forth by hand while the sound stays on. It makes that classic wikki-wikki noise and is the first scratch every DJ learns.", "purpose_function": "It develops basic record control and hand rhythm, and serves as the building block from which fader scratches like the chirp and transformer are learned.", "practical_application": "A scratch DJ uses the baby scratch to add rhythmic texture over a beat and to warm up hand coordination before performing more complex patterns.", "category": "Scratch technique", "related_terms": ["Forward scratch", "Chirp scratch", "Transformer scratch", "Crossfader", "Combo", "Backspin"], "common_mistakes": ["Moving the crossfader during the motion, which turns it into a different scratch rather than a baby scratch", "Spinning the whole platter instead of nudging just the record with the fingertips", "Gripping too hard and losing the steady back-and-forth timing"], "scenario_contexts": ["A beginner practising record control before learning fader cuts", "Adding a simple rhythmic scratch over an instrumental break", "Warming up hand-eye coordination at the start of a practice session"]}, "8d48bd40-11aa-4df4-a502-cc70bfbdce1f": {"definition": "A turntable technique in which the DJ manually spins the record backward, faster than its normal reverse speed, to quickly return to an earlier point or to repeat a short musical phrase or break. It is a core building block of breakbeat DJing and beat juggling.", "plain_english": "You spin the record backwards fast with your hand to jump back to an earlier part. DJs use it to repeat a drum break or a favourite bit again and again.", "purpose_function": "It lets a DJ re-cue or loop a section by hand in real time, extending breaks and creating repetition without stopping the music.", "practical_application": "A DJ backspins one deck to relaunch a break while the other record plays, or uses repeated backspins to juggle and rearrange beats.", "category": "Turntable technique", "related_terms": ["Beat juggling", "Break", "Cueing", "Doubles", "Crossfader"], "common_mistakes": ["Spinning so hard the stylus skips out of the groove and loses the cue", "Confusing a backspin with a scratch, though a scratch stays in one spot while a backspin travels back through the groove", "Failing to catch the record at the right point, so the phrase restarts off-beat"], "scenario_contexts": ["Repeating a drum break to extend it for dancers or a rapper", "Beat juggling two copies of the same record", "Quickly re-cueing a record back to its start point"]}, "0bf1cc00-a344-4e72-8078-ce55937d5e33": {"definition": "A DJ mix or routine performed in the competitive, skills-focused style of a DJ battle, prioritising technical turntablism such as scratching, beat juggling, tricks and precise cutting over the smooth, dancefloor-oriented blending of a club mix.", "plain_english": "A mix made to show off DJ skills in a contest, not to keep a dancefloor moving. It is packed with scratching, tricks and clever cuts to beat the other DJ.", "purpose_function": "It exists to demonstrate a DJ's technical command of the turntables and mixer in a competitive setting, where judges reward skill, difficulty and creativity.", "practical_application": "A DJ prepares a battle mix for competitions such as DMC or ITF events, rehearsing tightly timed scratch and juggle sequences.", "category": "Battle performance", "related_terms": ["Battle record", "Beat juggling", "Scratching", "Turntablism", "Crossfader", "Combo"], "common_mistakes": ["Treating a battle mix like a club set, where smooth blending matters more than technical tricks", "Overloading the routine with tricks that are not clean or in time", "Ignoring how the routine will be judged, such as originality and difficulty"], "scenario_contexts": ["Competing in a DMC or ITF turntablist battle", "Recording a routine to enter a scratch competition", "Showcasing turntable skills in a demo rather than a dancefloor set"]}, "0f37ad96-4fe8-4906-893e-ef4b9ff193b4": {"definition": "A record produced specifically for DJ battling and scratch practice, containing curated material such as scratch phrases (sentences), vocal and instrumental samples, drum breaks and short, skip-resistant loops arranged for easy cueing and manipulation.", "plain_english": "A record made just for scratching and battling. Instead of songs, it holds handy sounds, drum beats and short loops that DJs cut and scratch.", "purpose_function": "It gives turntablists ready-made, easy-to-find sounds and beats designed for scratching and juggling, so they do not have to dig through ordinary songs.", "practical_application": "A battle DJ loads a battle record such as DJ QBert's Battle Breaks to source scratch samples and skipless loops during practice and competition.", "category": "Battle media", "related_terms": ["Battle vinyl", "Battle mix", "Scratching", "Beat juggling", "Break", "Skipless loop"], "common_mistakes": ["Assuming a battle record is meant for normal listening rather than manipulation", "Confusing a battle record with a DVS timecode control record, which carries no musical audio", "Expecting every battle record to share the same layout of sounds"], "scenario_contexts": ["Sourcing scratch samples for a competition routine", "Practising beat juggling with matched breaks", "Building a scratch sentence from curated phrases"]}, "a79f9b91-d98f-4e56-bd2b-3d00a3769144": {"definition": "Vinyl records pressed specifically for DJ battling and scratching, carrying scratch samples, drum breaks and short, skip-resistant loops rather than conventional songs. The term stresses the physical vinyl medium a turntablist manipulates during battles and practice.", "plain_english": "Vinyl made for scratching and battling instead of listening. It holds short sounds, beats and loops that a DJ cuts up on the turntable.", "purpose_function": "It provides a turntablist with ready-to-cue sounds and beats on vinyl, laid out for the repeated hands-on handling that scratching and juggling require.", "practical_application": "A turntablist keeps battle vinyl on the decks for scratch routines, choosing pressings with clearly spaced sounds for quick cueing.", "category": "Battle media", "related_terms": ["Battle record", "Battle mix", "Scratching", "Turntable", "Stylus", "Skipless loop"], "common_mistakes": ["Assuming battle vinyl and DVS timecode control vinyl are the same thing", "Using a rare or valuable pressing for heavy scratching and wearing it out", "Thinking battle vinyl is for normal playback rather than manipulation"], "scenario_contexts": ["Setting up the decks with battle vinyl before a routine", "Practising scratches on a working pressing", "Choosing well-spaced sounds for fast cueing in a battle"]}, "23942d43-e871-4782-bb4a-682743d1e36b": {"definition": "A turntablism technique using two copies of the same record on two turntables, where the DJ cues, backspins and crossfades between the decks to rearrange, extend and recombine beats into new rhythmic patterns in real time.", "plain_english": "Using two copies of the same record on two decks to build a new beat by hand. The DJ jumps between the records to rearrange and repeat the drums live.", "purpose_function": "It lets a DJ compose fresh rhythms and extend breaks on the fly, turning existing records into a new live arrangement.", "practical_application": "A turntablist beat juggles two copies of a break to create an original drum pattern during a battle routine or performance.", "category": "Turntable technique", "related_terms": ["Backspin", "Doubles", "Break", "Crossfader", "Cueing", "Battle mix"], "common_mistakes": ["Using two different records instead of two matched copies (doubles)", "Losing the beat because the two records drift out of time", "Relying only on the fader and neglecting accurate hand cueing"], "scenario_contexts": ["Rearranging a drum break live in a battle routine", "Extending a short break for a dancer or MC", "Creating an original rhythm from two copies of one record"]}, "9ce01477-db31-4d54-9947-a8287024c6bb": {"definition": "A scratch technique in which the DJ cuts the sound with the crossfader at both the start and end of each forward and backward record motion, producing two short, clipped bursts that resemble a bird's chirp. It is widely credited to DJ Jazzy Jeff.", "plain_english": "A scratch that sounds like a bird chirping. You push and pull the record while quickly cutting the sound on and off with the fader at each end.", "purpose_function": "It adds sharp, staccato accents to a scratch pattern and trains the coordination between the record hand and the fader hand.", "practical_application": "A DJ uses chirps to punctuate a scratch routine and often chains them with other scratches in combos.", "category": "Scratch technique", "related_terms": ["Baby scratch", "Transformer scratch", "Crossfader", "Combo", "Flare scratch", "Forward scratch"], "common_mistakes": ["Leaving the fader open, which turns the chirp into a baby scratch", "Mistiming the fader cut so the two bursts sound uneven", "Moving the record too far, blurring the short clipped sound"], "scenario_contexts": ["Adding staccato accents in a scratch solo", "Building a combo that links chirps with flares", "Practising fader-and-record hand coordination"]}, "03322a7b-44d1-440e-a79f-ff2b99d95ba3": {"definition": "In turntablism, short for combination: two or more different scratch techniques executed back-to-back as a single continuous phrase or sequence, rather than repeating one scratch.", "plain_english": "A combo is when a DJ links different scratches together into one smooth run. It is like stringing separate dance moves into a routine.", "purpose_function": "It lets a DJ build longer, more musical and expressive scratch phrases by joining individual techniques into a flowing sequence.", "practical_application": "A scratch DJ chains moves such as chirp, flare and tear into a combo when composing a routine.", "category": "Scratch technique", "related_terms": ["Baby scratch", "Chirp scratch", "Flare scratch", "Transformer scratch", "Tear scratch", "Scribble scratch"], "common_mistakes": ["Attempting combos before the individual scratches are clean and in time", "Rushing transitions so the scratches blur together", "Repeating the same scratch, which is not a combo"], "scenario_contexts": ["Composing a scratch solo for a routine", "Progressing from single scratches to linked sequences in practice", "Judging technical difficulty in a battle"]}, "64098b56-abb5-4327-a447-140c2edf4117": {"definition": "A DJ set, or the closing segment of a set, deliberately programmed at lower tempo, intensity, and energy in order to bring the dance floor and audience down gradually after a peak or toward the end of an event.", "plain_english": "A cool-down set is the calmer music a DJ plays near the end. It slowly lowers the energy after the busy part of the night. This helps the crowd wind down before they leave.", "purpose_function": "It eases the crowd down from peak energy and gives a night a natural, comfortable close rather than an abrupt stop.", "practical_application": "A closing DJ drops the tempo and chooses softer, slower tracks in the final part of the night to send dancers home smoothly.", "category": "Set Programming", "related_terms": ["Warm-up set", "Peak time", "Energy level", "Crowd energy", "Set programming"], "common_mistakes": ["Dropping the energy too fast, which empties the floor abruptly instead of easing it", "Confusing a cool-down set with a warm-up set, since both use lower-energy tracks for different reasons", "Treating the closing segment as unimportant and putting no thought into track selection"], "scenario_contexts": ["The final thirty minutes of a club night as the DJ winds the room down before closing", "An after-party or chill-out room where lower-energy music is played throughout", "Following a peak-time headliner, easing the crowd before the venue's lights come up"]}, "ebe17cac-88fc-4e16-a6c2-baf666843e84": {"definition": "An advanced turntablism crossfader technique, credited to DJ Q-Bert, in which the fader is tapped open by bouncing three or four fingers in rapid sequence against the resistance of the thumb, producing a burst of very fast, distinct clicks from a single sound.", "plain_english": "A crab scratch is a fast fader trick invented by DJ Q-Bert. The DJ flicks the crossfader with several fingers against the thumb. This makes a quick string of clicking sounds from one short sample.", "purpose_function": "It lets a turntablist fire off many crossfader clicks faster than one finger can, adding speed and rhythmic complexity to a scratch pattern.", "practical_application": "A battle or performance DJ uses the crab to produce rapid four-click bursts over a drum or vocal sample during a scratch routine.", "category": "Scratch Technique", "related_terms": ["Crossfader", "Transformer scratch", "Flare scratch", "Twiddle scratch", "Turntablism", "Scratching"], "common_mistakes": ["Attempting the crab before mastering basic clicks and flares, so the timing comes out uneven", "Forgetting that the thumb provides the spring and resistance, and pushing the fader with the fingers alone", "Assuming the record hand can stay still, when it must move the sound under each click"], "scenario_contexts": ["A DMC-style battle routine where a DJ layers rapid crab clicks over a beat", "Practising crossfader control and finger independence during scratch training", "A turntablist performance building complex rhythmic patterns from a single sample"]}, "2ce15015-f0e2-42dc-9c06-5b26ba773ef3": {"definition": "In DJ performance, the skill of directing and managing an audience's mood, movement, and energy through deliberate track selection, mixing, and pacing so that the crowd responds and stays engaged as the DJ intends.", "plain_english": "Crowd control is a DJ's power to steer the room with music. By picking the right tracks at the right time, the DJ guides how people feel and move. Good DJs keep the floor full and happy.", "purpose_function": "It lets the DJ shape the experience of an event, keeping people dancing, building excitement, and steering the room away from dips in energy.", "practical_application": "A DJ reads the floor and swaps a planned track for a proven crowd-pleaser when energy dips, regaining the room's attention.", "category": "Crowd Reading", "related_terms": ["Reading the crowd", "Crowd energy", "Crowd response", "Dance floor management", "Energy level", "Set programming"], "common_mistakes": ["Playing only what the DJ likes instead of what the specific crowd responds to", "Staring at the gear and ignoring the floor, missing cues that energy is dropping", "Assuming one big track will fix a dead floor rather than rebuilding energy step by step"], "scenario_contexts": ["A wedding DJ shifting genres to keep several age groups on the dance floor", "A club DJ rebuilding momentum after a track empties the floor", "A festival set where the DJ paces energy so the crowd peaks at the right moment"]}, "54421202-c1a5-4368-8f18-d201457dfbe9": {"definition": "The collective level of excitement, movement, and enthusiasm expressed by an audience at a given moment, which a DJ continuously reads and influences through music selection and mixing.", "plain_english": "Crowd energy is how excited and lively the audience feels right now. You can see it in how much people dance, cheer, and move. DJs watch it closely to decide what to play next.", "purpose_function": "It is the key feedback signal a DJ uses to judge whether to build, hold, or ease the intensity of a set.", "practical_application": "A DJ senses rising crowd energy and responds by dropping a bigger track to push the floor toward a peak.", "category": "Crowd Reading", "related_terms": ["Crowd response", "Energy level", "Crowd control", "Peak time", "Reading the crowd"], "common_mistakes": ["Confusing a loud but static crowd with a crowd that is actually dancing hard", "Pushing energy too high too early and leaving nowhere left to build", "Ignoring falling energy until the floor has already emptied"], "scenario_contexts": ["Reading rising energy before deciding when to drop the night's biggest track", "Noticing an energy dip and mixing in a familiar track to re-engage dancers", "A back-to-back set where two DJs trade tracks to keep energy climbing"]}, "5deddb88-2c7d-4069-a97f-a44ea1ae3154": {"definition": "The observable reaction of an audience to what a DJ plays - such as cheering, dancing, singing along, or leaving the floor - that provides real-time feedback on the effectiveness of track selection and mixing.", "plain_english": "Crowd response is how the audience reacts to each track. They might cheer, sing, dance harder, or walk off. DJs use these reactions to learn what is working.", "purpose_function": "It gives the DJ immediate feedback to confirm good choices and correct poor ones during a live set.", "practical_application": "A DJ watches the crowd response to a new track and, if dancers thin out, quickly mixes into something more familiar.", "category": "Crowd Reading", "related_terms": ["Crowd energy", "Reading the crowd", "Crowd control", "Energy level", "Dance floor management"], "common_mistakes": ["Reading only the front row and missing that the wider floor has disengaged", "Mistaking polite clapping for genuine dance-floor engagement", "Reacting to one person's request instead of the whole room's response"], "scenario_contexts": ["Testing an unfamiliar or brand-new track and judging the floor's reaction", "A mobile DJ changing genre after a weak response at a private party", "A radio-style set where visible response is limited and must be inferred"]}, "b3765d4f-3862-4ff3-9af0-7a8c3ef08610": {"definition": "The DJ practice of keeping a full, active dance floor across a set by pacing energy, sequencing tracks, and timing transitions so that dancers are drawn in, kept engaged, and not driven away by poor programming.", "plain_english": "Dance floor management is keeping people dancing all night. The DJ plans the order and timing of tracks so the floor never empties. It is about steady flow, not just single great songs.", "purpose_function": "It ensures a consistently populated, energetic floor, which for most events is the main measure of a successful DJ set.", "practical_application": "A DJ spaces out the biggest tracks and avoids jarring genre or tempo jumps so the floor stays full through the whole set.", "category": "Crowd Reading", "related_terms": ["Reading the crowd", "Set programming", "Crowd control", "Energy level", "Peak time", "Crowd energy"], "common_mistakes": ["Playing every big track early and having nothing left to hold the floor later", "Making abrupt tempo or genre jumps that clear the dance floor", "Prioritising technical mixing over whether people are actually dancing"], "scenario_contexts": ["A long club set paced so the floor stays busy from open to close", "A wedding where the DJ keeps a mixed-age crowd dancing between formalities", "A festival slot where the DJ must fill the floor quickly in a short set"]}, "f2d53a1f-707b-495c-b7df-e8ac29dd3d2b": {"definition": "A qualifying stage in a DJ competition or battle in which competitors perform and are judged, with lower-scoring entrants removed so that only the higher-placed DJs advance to the next round or the final.", "plain_english": "An elimination round is an early stage of a DJ contest. DJs perform and judges score them. The lowest scorers are knocked out, and the rest move on.", "purpose_function": "It narrows a large field of entrants down to the strongest performers before the final, keeping the competition fair and manageable.", "practical_application": "A DJ entering a DMC battle must first win a regional elimination round before qualifying for the national or world final.", "category": "DJ Competition", "related_terms": ["DMC World DJ Championship", "Battle", "Exhibition", "Routine", "Qualifier"], "common_mistakes": ["Saving the best routine for later rounds and getting eliminated early", "Ignoring the round's specific time limit and being penalised", "Assuming an exhibition slot counts toward the elimination scoring"], "scenario_contexts": ["A regional DMC heat that selects who advances to the national final", "An online battle where submitted videos are scored to cut the field", "A club DJ contest where judges eliminate competitors round by round"]}, "a64b0dc6-55aa-43d7-a226-25696bbf91a6": {"definition": "A measure of how intense, driving, or exciting a track or a moment in a set feels; DJs use it to sequence music so that intensity rises and falls in a deliberate arc, and preparation software commonly stores it as a numeric track tag or rating.", "plain_english": "Energy level is how intense or exciting a track feels. DJs rate tracks by energy to plan the order they play them. Low-energy songs warm up the room; high-energy ones push the peak.", "purpose_function": "It gives the DJ a consistent way to compare tracks and arrange them so a set builds and releases intensity smoothly.", "practical_application": "A DJ rates or tags each track by energy in library software, then sequences the set so intensity climbs from warm-up to peak.", "category": "Set Programming", "related_terms": ["Crowd energy", "Set programming", "Peak time", "Warm-up set", "Cool-down set", "BPM"], "common_mistakes": ["Judging energy by tempo alone, ignoring that a slow track can still feel intense", "Jumping between extreme energy levels and jarring the dance floor", "Rating almost every favourite track as high energy, which makes the tags useless for sequencing"], "scenario_contexts": ["Tagging a library by energy in preparation software to plan a set's arc", "Choosing a next track that matches the floor's current energy", "Building a warm-up to peak-time progression using rising energy ratings"]}, "2f211749-17a7-4e65-b0c9-b0937d4a1323": {"definition": "A non-competitive performance at a DJ or turntablism event - such as a showcase routine by a guest, champion, or judge - presented for demonstration and entertainment rather than being scored as a competition entry.", "plain_english": "An exhibition is a show-off performance, not a scored contest entry. A guest or champion DJ plays to entertain and demonstrate skills. Judges do not rank it against other competitors.", "purpose_function": "It lets skilled DJs demonstrate technique and entertain the audience outside the pressure and scoring of the competitive bracket.", "practical_application": "Between elimination rounds, a former champion may perform an exhibition routine while judges tally the competitors' scores.", "category": "DJ Competition", "related_terms": ["Elimination round", "Routine", "Battle", "DMC World DJ Championship", "Showcase"], "common_mistakes": ["Thinking an exhibition set is scored toward the competition result", "Confusing an exhibition with a battle round between ranked competitors", "Assuming exhibition performers must follow the same strict time and rule limits as competitors"], "scenario_contexts": ["A champion's showcase routine performed while judges score the finalists", "A brand or gear demonstration where a DJ exhibits a product's features", "A skills showcase segment at a turntablism event, separate from the battle bracket"]}, "48bc5ec4-c76c-4374-925a-63815d725eb1": {"definition": "A scratch technique, credited to DJ Flare, in which the record is moved forward or backward while the crossfader is momentarily 'clicked' closed one or more times during the stroke, cutting the sound into rhythmic segments. Because the fader rests open and is briefly closed (the opposite of a transform), a 'one-click' flare interrupts each stroke once and a 'two-click' flare twice, allowing fast, syncopated patterns from a single record motion.", "plain_english": "A flare is a scratch move. You slide the record and quickly tap the crossfader shut once or twice mid-slide. Each tap chops the sound into pieces. This lets you make fast, bouncy rhythms with one push of the record.", "purpose_function": "It lets a turntablist create rapid, evenly spaced gaps in a sound using brief crossfader closes rather than opening the fader for every note, so complex rhythmic scratch patterns become physically achievable at speed.", "practical_application": "A battle or performance DJ uses one-click and two-click flares to build fast scratch phrases, often chaining them with record tricks like the orbit and chirp.", "category": "Scratch Techniques", "related_terms": ["Orbit scratch", "Transform scratch", "Chirp scratch", "Crossfader", "Baby scratch", "Beat juggling"], "common_mistakes": ["Confusing the flare with the transform: a transform starts with the fader closed and opens it, while a flare starts open and clicks closed", "Pushing the fader too far or too slowly, so the clicks smear instead of making clean gaps", "Moving the record unevenly, which makes the flare's rhythm sound sloppy"], "scenario_contexts": ["A DMC battle routine built around fast two-click flare patterns", "Practicing one-click flares over a break to build crossfader control", "Layering flares with baby scratches to create a rhythmic solo"]}, "64eead1e-fbe9-49ec-961a-a53ecccd763c": {"definition": "An improvised DJ or turntablist performance in which techniques such as scratching, beat juggling, mixing, and track selection are executed spontaneously rather than from a rehearsed, pre-planned routine. In battle formats, a freestyle round is judged on how well a DJ improvises and responds in the moment.", "plain_english": "Freestyle means the DJ makes it up as they go. There is no planned routine to follow. They pick tracks and tricks on the spot and react to the moment. It shows how skilled and creative the DJ really is.", "purpose_function": "It showcases a DJ's raw skill, creativity, and adaptability by removing the safety net of a memorized routine, and it lets performers respond to the crowd or an opponent in real time.", "practical_application": "A DJ freestyles during an open set or a battle round, improvising scratches and blends instead of triggering a rehearsed sequence.", "category": "Performance Format", "related_terms": ["Judge's score", "Beat juggling", "Flare scratch", "Read the crowd", "Peak-time set", "Turntablism"], "common_mistakes": ["Thinking freestyle means playing with no skill or preparation, when it actually relies on deep, practiced fundamentals", "Confusing freestyling with having no structure at all; good freestyling still follows musical timing and key", "Freezing up because no routine was memorized, instead of falling back on trusted basics"], "scenario_contexts": ["A DJ plays an unplanned club set, reading the crowd and choosing tracks live", "A battle freestyle round where competitors improvise against each other", "Warming up by freestyling scratches over a random break"]}, "b9549236-ccbc-4bbb-8672-19c3338a7881": {"definition": "In a DJ battle or competition, the points a judge awards to a competitor against defined criteria such as technical skill, originality, track selection, execution, and crowd response. The competitor with the highest combined score from all judges advances or wins.", "plain_english": "In a DJ contest, judges give each DJ points. They rate things like skill, creativity, song choice, and how the crowd reacts. The DJ with the most points from the judges wins. It works much like scoring in a sport.", "purpose_function": "It gives battles a fair, structured way to compare performances, turning subjective skill into comparable numbers so a winner can be chosen consistently across competitors.", "practical_application": "A competitor studies the scoring criteria beforehand and shapes a routine to hit each judged category, while organizers tally judges' scores to rank the field.", "category": "Battle Judging", "related_terms": ["Freestyle", "Beat juggling", "Flare scratch", "Read the crowd", "Turntablism", "Momentum"], "common_mistakes": ["Assuming judging is purely about the fastest or hardest tricks, when originality and musicality also score", "Ignoring the published criteria and losing points in categories the routine never addressed", "Confusing crowd noise with the judges' score; the crowd may influence but does not always decide"], "scenario_contexts": ["Judges scoring competitors at a DMC World DJ Championship qualifier", "A Red Bull 3Style battle where set scores decide who advances", "A competitor reviewing scorecards afterward to see where points were lost"]}, "15b5f696-5316-43d2-9a20-a7a22be6a77f": {"definition": "In a DJ set, the accumulated and sustained sense of energy and forward drive on the dancefloor, built and maintained through deliberate track selection, key and tempo progression, and mixing choices. Losing momentum means the crowd's energy drops, while building momentum keeps them engaged and dancing.", "plain_english": "Momentum is the energy a DJ builds up in the room. Good song choices keep people dancing and wanting more. If the DJ plays the wrong track, the energy can fall. Then it is hard to get the crowd going again.", "purpose_function": "Managing momentum lets a DJ shape the emotional arc of a night, raising and easing energy on purpose so the crowd stays engaged and the set peaks at the right time.", "practical_application": "A DJ watches the floor and sequences tracks to build momentum toward peak time, avoiding an abrupt tempo or energy change that would clear the dancefloor.", "category": "Set Programming", "related_terms": ["Peak-time set", "Read the crowd", "Read the room", "Beatmatching", "Warm-up set", "Freestyle"], "common_mistakes": ["Playing all the biggest tracks too early, leaving nowhere to build and killing momentum", "Making a jarring tempo or genre jump that breaks the flow and empties the floor", "Ignoring the crowd and following a fixed playlist regardless of the room's energy"], "scenario_contexts": ["Building momentum across a warm-up set so the next DJ inherits a full floor", "Recovering lost momentum after a track empties the dancefloor", "Pacing a festival set so energy peaks during the headline slot"]}, "d89f539b-a2db-420d-a30a-a37524fd08bb": {"definition": "The technique of manually placing the stylus (needle) onto a specific point in a record's groove to begin playback exactly at a desired part of the track rather than at the start. It is used for cueing, quickly locating sections, and as a mixing or performance move to jump to a precise passage.", "plain_english": "A needle drop means setting the record needle down on an exact spot. Instead of starting a song from the top, you drop into the part you want. DJs use it to jump straight to a chorus or a beat. It takes a steady hand and practice to hit the right groove.", "purpose_function": "It lets a DJ start or locate a specific section of a vinyl record without playing from the beginning, which speeds up cueing and enables performance tricks that jump between parts of a track.", "practical_application": "A vinyl DJ eyeballs the groove and drops the needle onto an intro, chorus, or breakdown to cue or to mix into that section on the fly.", "category": "Cueing Technique", "related_terms": ["Cueing", "Slip-cueing", "Backspin", "Beatmatching", "Stylus", "Beat juggling"], "common_mistakes": ["Dropping the needle carelessly, which can gouge the record groove or damage the stylus tip", "Dropping too hard, so the needle skips across grooves instead of landing cleanly", "Misjudging the groove position and landing on the wrong section of the track"], "scenario_contexts": ["Cueing a vinyl record by dropping the needle onto the first beat of a phrase", "Jumping straight to a chorus during a live vinyl set", "Beat juggling by needle-dropping between two copies of the same record"]}, "21335148-f4bd-4690-9878-69022a90aa2a": {"definition": "A scratch technique in which a flare is performed continuously in both directions, applying the same crossfader clicks on the forward push and the backward pull so the pattern loops or 'orbits.' It is essentially a two-directional flare that repeats seamlessly to create a rolling rhythmic figure.", "plain_english": "An orbit is a flare scratch done both ways. You do the flare as you push the record and again as you pull it back. Repeating this makes a smooth, looping rhythm. The sound seems to go around and around, like something in orbit.", "purpose_function": "It extends the flare into a repeating, bidirectional loop so a turntablist can sustain a fast rhythmic pattern continuously rather than as a single stroke.", "practical_application": "A turntablist uses orbits to hold a rolling scratch groove in a routine, chaining forward and backward flares without breaking the rhythm.", "category": "Scratch Techniques", "related_terms": ["Flare scratch", "Transform scratch", "Chirp scratch", "Crossfader", "Baby scratch", "Beat juggling"], "common_mistakes": ["Uneven clicks between the forward and backward flare, which makes the orbit sound lopsided", "Confusing an orbit with a single flare; an orbit must repeat the flare in both directions", "Losing the record's rhythm, so the loop drifts off the beat"], "scenario_contexts": ["Holding a rolling orbit pattern as the backbone of a battle routine", "Practicing two-click orbits to build smooth bidirectional fader control", "Combining orbits with beat juggling in a performance"]}, "68404577-e4dc-4ce3-9d85-29d535c0e49d": {"definition": "A DJ set played during the busiest, highest-energy part of an event, when the dancefloor is fullest, typically featuring the most energetic and recognizable tracks to sustain maximum crowd energy. It contrasts with the warm-up (opening) set and the closing set, which are programmed at lower energy.", "plain_english": "A peak-time set is played when the party is at its busiest. The floor is packed and the energy is high. The DJ plays the biggest, most exciting tracks now. The goal is to keep the crowd dancing at full energy.", "purpose_function": "It delivers the emotional high point of a night by concentrating the strongest tracks when the crowd is largest, and it defines a distinct role and skill set from warm-up or closing slots.", "practical_application": "A DJ booked for peak time selects high-energy, crowd-familiar tracks and reads the packed floor to hold the room at its peak.", "category": "Set Programming", "related_terms": ["Momentum", "Warm-up set", "Read the crowd", "Read the room", "Closing set", "Beatmatching"], "common_mistakes": ["Playing a warm-up-style, low-energy set during a peak-time slot and losing the packed floor", "Burning every big track in the first few minutes with no arc to sustain the peak", "Ignoring the venue's timing, so the biggest moment lands too early or too late"], "scenario_contexts": ["Taking the headline midnight slot at a club and playing the biggest tracks", "Following a warm-up DJ and lifting the full floor into peak energy", "Programming a festival main-stage set for the busiest hour"]}, "d0c3ee4f-7b6f-4633-a732-0a067ea368b0": {"definition": "The performance skill of continuously observing an audience's reactions, such as dancing, energy, and engagement, and adjusting track selection, mixing, and pacing in real time to keep the crowd responding. It is a core competency that separates a DJ who merely plays tracks from one who guides a dancefloor.", "plain_english": "Reading the crowd means watching how people react. The DJ sees who is dancing and how the energy feels. Then they pick the next tracks to match. It is like a conversation without words between the DJ and the floor.", "purpose_function": "It lets a DJ respond to what is actually working on the floor rather than following a fixed playlist, so energy and engagement can be built and sustained live.", "practical_application": "A DJ watches the dancefloor's response to each track and adjusts genre, tempo, and energy on the fly, dropping or holding records based on the reaction.", "category": "Crowd Reading", "related_terms": ["Read the room", "Momentum", "Peak-time set", "Warm-up set", "Freestyle", "Beatmatching"], "common_mistakes": ["Staring at the gear or laptop instead of watching the audience's reactions", "Sticking to a pre-planned playlist even when the floor clearly wants something else", "Playing for oneself or a few friends rather than the whole crowd's response"], "scenario_contexts": ["Switching genres mid-set after seeing the dancefloor thin out", "Holding a track longer because the crowd is reacting strongly", "A wedding DJ reading a mixed-age crowd to choose the next song"]}, "1b72a217-b4bb-46e3-832f-1b4b6fadaac1": {"definition": "The broader performance skill of assessing the overall mood, context, and character of a room or event, such as the occasion, demographic, time of night, and atmosphere, and shaping the performance to fit it. It is wider than reading the crowd's moment-to-moment dancing, taking in the whole situation to guide the set.", "plain_english": "Reading the room means sensing the whole vibe of a place. You notice the crowd's age, the mood, and the type of event. Then you play music that fits the situation. A wedding, for example, needs a very different set from a late-night club.", "purpose_function": "It ensures a DJ's choices match the occasion and atmosphere, not just the dancefloor's immediate reaction, so the performance suits the event as a whole.", "practical_application": "A DJ sizes up the event type, audience, and mood on arrival and picks an appropriate style and energy, then keeps adjusting as the night's character changes.", "category": "Crowd Reading", "related_terms": ["Read the crowd", "Momentum", "Peak-time set", "Warm-up set", "Freestyle", "Beatmatching"], "common_mistakes": ["Treating every gig the same regardless of the event, venue, or audience", "Confusing reading the room with only watching dancers; it also includes mood, occasion, and setting", "Playing a personal favourite style that clashes with the event's tone"], "scenario_contexts": ["Adjusting a corporate event set to a formal, older audience", "Sensing a somber or low-key mood and easing off high-energy tracks", "Choosing an opening style that fits an early, half-empty room"]}, "ac7daa2c-0661-4627-a3e8-cd53e7d1e5e2": {"definition": "A pre-planned, rehearsed sequence of scratches, beat juggles, and mixing manoeuvres that a DJ or turntablist performs as a composed set piece, especially in battles and showcases. It is worked out and practised in advance so the timing and moves can be reproduced accurately in performance.", "plain_english": "A routine is an act a DJ plans and practices ahead of time. It strings scratches, tricks, and mixes into one performance. It is like a dance routine, but built from records and turntable moves.", "purpose_function": "It lets a turntablist present complex, tightly timed skills as a repeatable composition, which is how performances are structured and judged in DJ battles and championships.", "practical_application": "A battle DJ builds and rehearses a set-length routine, marking records and memorising cues so every scratch and juggle lands on time.", "category": "Performance", "related_terms": ["Scratching", "Beat juggling", "Showcase", "Battle", "Crossfader", "Turntablism"], "common_mistakes": ["Confusing a routine (a rehearsed set piece) with freestyling, which is improvised on the spot", "Thinking a routine is only scratching, when it can also combine beat juggling, mixing, and body tricks", "Underestimating how much rehearsal and record marking a clean routine actually requires"], "scenario_contexts": ["A competitor performing a rehearsed set-length routine at a DMC championship final", "A turntablist recording a routine as a demo to show technical skill", "Two DJs trading prepared routines during a showcase set"]}, "c7bbb0db-df0d-4420-960d-03d9e1226bc4": {"definition": "A turntablism technique in which a record (or its digital equivalent under a DVS control disc) is moved back and forth by hand under the stylus while the sound is shaped, typically with a mixer's crossfader or upfader, to produce rhythmic, percussive, and tonal effects. Individual scratch types are defined by the pattern of record-hand motion combined with fader cuts.", "plain_english": "Scratching means moving a record back and forth by hand while it plays. The DJ pushes and pulls the record and clicks the mixer fader on and off. Together these make the short, rhythmic sounds heard in hip-hop.", "purpose_function": "It turns the turntable into a musical instrument, letting a DJ play rhythms and phrases from recorded sound rather than just playing tracks back.", "practical_application": "A DJ scratches a sampled sound over a beat, coordinating record-hand motion with crossfader cuts to perform accents, patterns, and solos.", "category": "Scratch Technique", "related_terms": ["Crossfader", "Baby scratch", "Scribble scratch", "Tear scratch", "Slipmat", "Turntablism"], "common_mistakes": ["Believing scratching uses only the record hand, when most named scratches also require crossfader movement", "Pressing down hard on the record, which adds friction and wear instead of improving control", "Confusing scratching with beat juggling, which rearranges beats rather than shaping a sample by hand"], "scenario_contexts": ["A hip-hop DJ scratching a vocal sample during a live set", "A turntablist practising crossfader clicks to learn transformer and flare scratches", "Using a DVS control record to scratch digital audio from a laptop"]}, "235c39d6-0864-460a-b9b3-991862aa1956": {"definition": "A scratch technique produced by rapidly tensing the arm or wrist muscles to move the record back and forth in a fast, spasm-like tremor, without using the crossfader. The result is a dense, buzzing burst of very short forward and backward strokes.", "plain_english": "A scribble scratch is a fast, shaky back-and-forth wiggle of the record. The DJ tenses their arm so it vibrates quickly. It makes a buzzing, stuttering sound, a bit like scribbling with a pen.", "purpose_function": "It adds a fast, textured burst to a scratch pattern, giving a rolling or buzzing sound that steady hand speed alone struggles to produce evenly.", "practical_application": "A turntablist drops a short scribble as a fill or accent between slower scratches, driving it from arm tension rather than fader cuts.", "category": "Scratch Technique", "related_terms": ["Scratching", "Baby scratch", "Tear scratch", "Crossfader", "Turntablism"], "common_mistakes": ["Trying to make the speed with the whole arm instead of quick muscle tension, which sounds slow and uneven", "Adding crossfader cuts, when a true scribble uses record motion only", "Tensing so hard that control and timing are lost"], "scenario_contexts": ["A DJ using a quick scribble as a fill inside a scratch solo", "Practising forearm tension to build scribble speed and evenness", "Layering a scribble over a beat to add a buzzing texture"]}, "b3ae1e09-f393-46b0-9e25-f7195904ce39": {"definition": "A solo performance format in which a DJ or turntablist presents a prepared set of skills and routines to an audience or a panel of judges, rather than competing head-to-head against another DJ. In competitions such as the DMC World DJ Championship, the classic solo showcase is judged on musicality, creativity, and technical skill.", "plain_english": "A showcase is a solo spot where a DJ shows off their skills. They perform a prepared set for a crowd or judges. There is no direct head-to-head battle, just one DJ at a time.", "purpose_function": "It gives a turntablist a stage to demonstrate technical ability and creativity as a complete performance, and gives judges a fair way to score one DJ at a time.", "practical_application": "A competitor prepares a tight set-length showcase of routines, then performs it solo at a championship final.", "category": "Performance Format", "related_terms": ["Routine", "Battle", "Scratching", "Beat juggling", "Turntablism"], "common_mistakes": ["Confusing a showcase (solo demonstration) with a battle, where two DJs compete directly", "Assuming a showcase is unplanned, when strong sets are carefully rehearsed routines", "Focusing only on speed instead of the musicality and creativity that judges also score"], "scenario_contexts": ["A solo showcase set at a DMC championship final", "A DJ performing a skills showcase at a club or product event", "Recording a showcase reel to demonstrate ability to promoters"]}, "45e0de4f-80f7-4699-8855-b1c0952d9df9": {"definition": "A technique for starting a record exactly on cue by holding the record stationary at the desired start point while the platter keeps spinning beneath it on a slipmat, then releasing the record so it plays instantly at full speed. The slipmat lets the platter slip under the held record, so the motor stays up to speed.", "plain_english": "Slip cueing is a way to start a record right on time. The DJ holds the record still at the start point while the turntable keeps spinning underneath. A slippery mat lets it slide, and letting go starts the music instantly.", "purpose_function": "It lets a DJ launch a track precisely on the beat without waiting for the platter to reach speed, which is essential for tight beatmatching and mixing.", "practical_application": "A DJ finds the first beat, holds the record there with the platter spinning, and releases it on the downbeat to bring in the next track.", "category": "Cueing Technique", "related_terms": ["Slipmat", "Beatmatching", "Cue point", "Backspin", "Turntable"], "common_mistakes": ["Confusing slip cueing with a turntable's start or pitch control, when the DJ physically holds and releases the record", "Using a sticky or unsuitable mat, so the platter cannot slip freely under the record", "Releasing early or late, so the track starts off the beat"], "scenario_contexts": ["A club DJ slip-cueing a vinyl track in on the downbeat", "A radio DJ starting a record instantly on air", "Practising slip cues to tighten beatmatched transitions"]}, "49920ab2-38a5-459e-a3cc-a6710cd5efdd": {"definition": "A technique in which the DJ rapidly spins the record backwards by hand, sending it briefly into reverse at high speed to create a fast rewind sound, typically used as a transition or dramatic accent between tracks or sections. Digital DJ systems reproduce the effect on motorised jog wheels or as a reverse/brake function.", "plain_english": "A spinback is when a DJ quickly flings the record backwards by hand. It makes a fast rewind whoosh. DJs use it to jump between tracks or to add a dramatic effect.", "purpose_function": "It provides a quick, attention-grabbing transition or accent, letting a DJ cut out of a track or emphasise a moment with a reverse sweep.", "practical_application": "A DJ throws a spinback at the end of a phrase to slam into the next track or to hype a drop.", "category": "Turntable Technique", "related_terms": ["Backspin", "Slipmat", "Crossfader", "Transition", "Turntable"], "common_mistakes": ["Spinning so hard that the stylus is disturbed or skips out of the groove", "Confusing a spinback (a manual reverse spin) with a turntable brake control", "Overusing it, so the effect loses impact across a set"], "scenario_contexts": ["A DJ spinning back to transition sharply into a new track", "Using a spinback to hype the crowd before a drop", "Reproducing a spinback with a controller's jog wheel or reverse button"]}, "d7838ac2-7e2e-459b-9b60-c0e9e978f8d3": {"definition": "A short, sharp forward push of the record that releases a brief burst of sound, used as a staccato accent to punctuate a beat. It is essentially a shortened forward scratch, often paired with a quick crossfader cut so mainly the initial attack of the sample is heard.", "plain_english": "A stab is a quick, sharp jab of the record forward. It lets out one short burst of sound, like a stab or poke. DJs use it to punch out accents in time with the beat.", "purpose_function": "It provides a punchy rhythmic accent from a sample, letting a DJ hit sharp, staccato notes that land on specific beats.", "practical_application": "A DJ throws a stab on the downbeat to accent a horn or vocal hit while keeping the rest of the sample silent.", "category": "Scratch Technique", "related_terms": ["Scratching", "Baby scratch", "Chirp scratch", "Crossfader", "Turntablism"], "common_mistakes": ["Letting the sample run too long, turning a crisp stab into a full forward scratch", "Forgetting to cut the crossfader, so the accent is not clean", "Confusing a stab with a chirp, which cuts both the start and the end of the sound"], "scenario_contexts": ["A DJ stabbing a horn hit to accent the downbeat", "Using quick stabs to add punctuation over a looped beat", "Combining stabs with chirps in a scratch pattern"]}}$ape$::jsonb)) d WHERE g.id=d.id;
UPDATE glossary g SET definition = CASE WHEN d.p ? 'definition' THEN d.p->>'definition' ELSE g.definition END, plain_english = CASE WHEN d.p ? 'plain_english' THEN d.p->>'plain_english' ELSE g.plain_english END, purpose_function = CASE WHEN d.p ? 'purpose_function' THEN d.p->>'purpose_function' ELSE g.purpose_function END, practical_application = CASE WHEN d.p ? 'practical_application' THEN d.p->>'practical_application' ELSE g.practical_application END, category = CASE WHEN d.p ? 'category' THEN d.p->>'category' ELSE g.category END, related_terms = CASE WHEN d.p ? 'related_terms' THEN ARRAY(SELECT jsonb_array_elements_text(d.p->'related_terms')) ELSE g.related_terms END, common_mistakes = CASE WHEN d.p ? 'common_mistakes' THEN ARRAY(SELECT jsonb_array_elements_text(d.p->'common_mistakes')) ELSE g.common_mistakes END, scenario_contexts = CASE WHEN d.p ? 'scenario_contexts' THEN ARRAY(SELECT jsonb_array_elements_text(d.p->'scenario_contexts')) ELSE g.scenario_contexts END FROM (SELECT key::uuid AS id, value AS p FROM jsonb_each($ape${"8876d006-77b8-4a01-8162-31bc3236fd33": {"definition": "A scratch technique that divides a single stroke, usually the backstroke, into two or more parts by briefly halting the record mid-stroke before completing the movement, producing a stuttered or 'torn' version of a baby scratch. It is executed with the record hand alone, without crossfader cuts.", "plain_english": "A tear scratch breaks one back-and-forth motion into smaller pieces. The DJ pauses the record for a split second in the middle of a stroke. This makes the sound stutter, as if it were torn into parts.", "purpose_function": "It lets a turntablist get more rhythmic notes out of a single push or pull, adding stutter and subdivision without touching the crossfader.", "practical_application": "A DJ tears the backstroke into two parts to double the rhythm of a baby scratch during a pattern.", "category": "Scratch Technique", "related_terms": ["Scratching", "Baby scratch", "Scribble scratch", "Crossfader", "Turntablism"], "common_mistakes": ["Confusing a tear with a transformer scratch, which uses crossfader cuts rather than record halts", "Halting so long that the sound stops instead of stuttering", "Assuming the crossfader makes the tear, when the effect comes from stopping the record"], "scenario_contexts": ["A turntablist tearing the backstroke to add subdivisions in a routine", "Learning tears to build rhythmic variety from a single sample", "Combining tears with baby scratches in a battle set"]}, "37eb5479-d36c-45b6-9dba-da2834e67c0c": {"definition": "A choreographed turntablist performance segment built to demonstrate technical turntable skills such as precise scratching, beat juggling and crossfader control, rehearsed and timed to specific records for a battle or showcase.", "plain_english": "A practised, planned performance where a DJ shows off hard turntable skills like scratching and beat juggling. It is rehearsed in advance, like a dance routine, so every move lands on time.", "purpose_function": "It lets a DJ present their strongest and most difficult techniques in a controlled, repeatable way, so judges or an audience can clearly hear their skill.", "practical_application": "A battle DJ builds and rehearses a technical routine for competitions such as the DMC or ITF, cueing chosen records and drilling each scratch and juggle until it is tight.", "category": "Battle performance", "related_terms": ["Scratching", "Beat juggling", "Crossfader", "Trick mix", "Transformer scratch"], "common_mistakes": ["Confusing a technical routine with an ordinary DJ set; a routine is pre-planned and rehearsed, not improvised.", "Focusing only on raw speed and neglecting timing and musicality, which judges weigh heavily.", "Not rehearsing to the exact records, so cues drift out of time during the performance."], "scenario_contexts": ["A DJ preparing a timed set for a DMC World DJ Championship battle.", "A turntablist performing a rehearsed skills showcase between live acts.", "A student drilling a short routine to demonstrate crossfader control in a lesson."]}, "74cbb66b-c46b-4382-8199-435b83f382ef": {"definition": "A scratch technique in which the record hand moves the sample in a long, relatively slow, continuous stroke while the other hand rapidly opens and closes the crossfader (or line fader), chopping the sustained sound into short, evenly spaced bursts.", "plain_english": "It is a scratch made with both hands. One hand slowly moves the record. The other hand quickly flicks the volume fader on and off. This chops one long sound into short bursts, like a strobe light turning a steady glow into flashes.", "purpose_function": "It turns a single held sound into a rhythmic, stuttering pattern, giving scratch DJs a percussive, robotic texture from one sample.", "practical_application": "A DJ holds a tone or word on the platter and taps the crossfader in time with the beat to produce the classic on/off transformer sound in routines and battles.", "category": "Scratch technique", "related_terms": ["Crossfader", "Scratching", "Baby scratch", "Flare scratch", "Chirp scratch", "Cutting"], "common_mistakes": ["Moving the record too fast, which blurs the separate bursts the fader is meant to create.", "Fading only partway, so muted sound leaks through instead of clean on/off cuts.", "Confusing it with the flare, which clicks the fader closed during a motion rather than tapping it open and closed over a slow stroke."], "scenario_contexts": ["Building a rhythmic scratch phrase in a battle routine.", "Adding a stuttering vocal effect over a beat in a live set.", "Practising crossfader on/off control as a scratch fundamental."]}, "028d6c06-eb98-4c1e-b3b1-418c39c60744": {"definition": "A transition or mix that features overt DJ tricks such as spinbacks, backspins, scratches, cuts, rewinds or echo effects as a deliberate performance element, rather than blending two records smoothly and unnoticeably.", "plain_english": "A mix where the DJ blends songs using flashy moves like scratches, spinbacks and rewinds. Instead of hiding the join between tracks, the DJ makes it a moment the crowd notices.", "purpose_function": "It adds energy and showmanship to a transition, letting a DJ mark a change of track or a drop with a noticeable flourish instead of a seamless blend.", "practical_application": "A DJ ends one record with a spinback and scratches the next one in, using the trick to grab the crowd at a big moment in the set.", "category": "Mixing technique", "related_terms": ["Beatmatching", "Spinback", "Backspin", "Scratching", "Cutting", "Transformer scratch"], "common_mistakes": ["Overusing tricks so every transition becomes a gimmick and the set loses flow.", "Attempting tricks without solid beatmatching first, so the mix falls out of time.", "Thinking a trick mix hides errors; a botched trick is more obvious than a smooth blend."], "scenario_contexts": ["Marking the drop of a crowd favourite with a rewind and scratch.", "A hip-hop DJ cutting between records during a party set.", "A beginner learning spinbacks before attempting them live."]}, "e6310903-7d29-48d5-a268-d6d647b0e61e": {"definition": "The opening DJ set played early in an event, before the headline or peak-time DJ, intended to gradually build the crowd's energy and fill the dancefloor rather than peaking too soon.", "plain_english": "The first DJ set of the night, played before the main act. Its job is to slowly warm up the crowd and fill the floor. The DJ avoids playing the biggest tunes too early.", "purpose_function": "It sets the mood and paces the room so energy rises across the night, handing the headliner a ready, engaged crowd.", "practical_application": "An opening DJ reads the early crowd, keeps tempos and energy lower, and avoids peak-time anthems so the headliner can take the room higher.", "category": "Set structure", "related_terms": ["Peak time", "Reading the crowd", "Track selection", "Beatmatching", "Residency"], "common_mistakes": ["Playing peak-time anthems too early and leaving the headliner nothing to build on.", "Mixing at full energy from the first track instead of pacing the room.", "Ignoring the crowd actually in the room and playing a self-indulgent set."], "scenario_contexts": ["Opening a club night before the headline DJ arrives.", "Playing the early slot at a festival stage.", "A resident DJ warming up the room across the first hour of the night."]}, "2a4f4950-ad52-487f-9970-1d6e1dea493e": {"definition": "A DJ software or hardware function that instantly creates a loop of a preset length (such as 1, 2, 4, 8 or more beats) from the current playback position, using the track's analysed BPM and beatgrid to set precise loop-in and loop-out points automatically. Because the loop is snapped to the detected beats, it stays musically in time even if the button is pressed slightly off the beat.", "plain_english": "Auto loop makes a part of a song repeat by itself. You just pick how many beats to loop, like 4 or 8. The gear finds the right start and end points for you. So the loop stays in time.", "purpose_function": "It lets a DJ set a perfectly beat-aligned loop with a single action, without manually tapping in and out points, so loops can be used quickly and cleanly for transitions, edits and extending a section.", "practical_application": "A DJ presses a 4-beat auto loop on the outgoing track to hold a groove while bringing in the next track, then releases it to let the track play on.", "category": "Looping", "related_terms": ["Manual loop", "Beatgrid", "Loop roll", "Bar", "Beatmatching", "Hot cue"], "common_mistakes": ["Setting an auto loop on a track that has not been analysed, so the calculated loop length is wrong", "Confusing auto loop with manual looping, which needs you to tap the in and out points yourself", "Leaving a loop active by accident and running past the track's structure", "Choosing a loop length that cuts across a phrase, so the loop sounds unmusical"], "scenario_contexts": ["Extending an intro or outro to give more time to mix into the next track", "Holding a breakdown loop to build tension before a drop", "Creating a quick beat-aligned loop for an on-the-fly edit"]}, "0b40ce15-e7d1-42bb-aa5a-c066f4559467": {"definition": "A bar (measure) is a unit of musical time containing a fixed number of beats set by the time signature; in the 4/4 metre of most dance music this is four beats. DJs count tracks in bars and in multi-bar phrases (commonly 4, 8, 16 or 32 bars) to time mixes, loops and transitions to a track's structure.", "plain_english": "A bar is a small, equal chunk of a song's rhythm. In most dance music a bar is four beats. DJs count bars to track where they are in a song. This tells them when to start a mix.", "purpose_function": "It gives DJs a consistent way to count musical time, so loops, cue points and transitions can be lined up with the natural structure of a track.", "practical_application": "A DJ counts in groups of eight or sixteen bars so the next track comes in at the start of a new phrase, keeping the two arrangements aligned.", "category": "Rhythm & Timing", "related_terms": ["Beat", "Phrase", "Phrasing", "Beatgrid", "Downbeat", "Time signature"], "common_mistakes": ["Confusing a beat (a single pulse) with a bar (a group of beats)", "Assuming every genre has four beats per bar regardless of the time signature", "Losing count of bars and starting a mix in the middle of a phrase", "Counting beats but ignoring phrase length, so transitions land awkwardly"], "scenario_contexts": ["Counting bars to bring the next track in on the downbeat of a new phrase", "Setting a loop length in bars to extend a section of a track", "Lining a mix up to a 32-bar phrase so the two arrangements match"]}, "235fde21-931e-4a4d-83f4-7e1f977f4a86": {"definition": "A DJ EQ-mixing move in which the low frequencies of the outgoing track are cut while the low frequencies of the incoming track are simultaneously brought up, transferring the low end from one track to the other. It prevents two basslines or kick drums sounding together, which would clash and produce a muddy or overloaded low end.", "plain_english": "A bass swap hands the deep bass from one song to the next. You turn the bass down on the old song and up on the new one at the same time. This stops two heavy basslines from clashing.", "purpose_function": "It keeps only one track's low end in the mix at a time, so a blend stays clean and punchy instead of muddy, and it manages low-frequency energy that would otherwise pile up.", "practical_application": "Using the channel LOW EQ knobs, a DJ cuts the bass on the playing track and raises it on the incoming track at the same moment, usually on a downbeat, to hand over the low end.", "category": "Mixing Technique", "related_terms": ["EQ mixing", "Bass swap transition", "Crossfader", "Beatmatching", "Isolator", "Frequency mixing"], "common_mistakes": ["Bringing both basslines up at once, which overloads the low end and sounds muddy", "Doing the swap off the beat instead of on a downbeat, so the change sounds clumsy", "Relying on the crossfader alone and forgetting to control the bass with EQ", "Cutting the outgoing bass so slowly that both low ends overlap for too long"], "scenario_contexts": ["Swapping the low end between two house or techno tracks during a long blend", "Bringing in a new track's bassline exactly as the old one's is removed", "Avoiding a muddy low end when two kick-driven tracks overlap"]}, "861e2a5c-dfc6-41c0-baf2-14e5d0488bdc": {"definition": "A track transition built around a bass swap: the DJ beatmatches the two tracks and plays them together with the incoming track's low frequencies cut, then swaps the bass by cutting the outgoing track's low end while raising the incoming track's, usually on a downbeat or phrase boundary. The outgoing track is then faded out, leaving the incoming track carrying the mix.", "plain_english": "A bass swap transition is a way to change from one song to the next. You play both together, but with the new song's bass turned down. Then you swap the deep bass over to the new song. Finally you let the old song go.", "purpose_function": "It provides a clean, energy-preserving way to move between two tracks, keeping a single strong low end throughout so the dancefloor never loses the groove.", "practical_application": "A DJ beatmatches both tracks, holds them together with the incoming bass cut, then on a downbeat swaps the LOW EQ over and fades the old track out.", "category": "Mixing Technique", "related_terms": ["Bass swap", "EQ mixing", "Beatmatching", "Crossfader", "Phrasing", "Blend"], "common_mistakes": ["Swapping the bass without beatmatching first, so the beats clash during the blend", "Making the swap in the middle of a phrase instead of on a phrase boundary", "Leaving both full-range tracks playing too long before the swap, causing a muddy mix", "Forgetting to fade out the outgoing track after the bass has been handed over"], "scenario_contexts": ["Transitioning between two techno tracks while keeping one solid bassline", "Using a bass swap on the downbeat to make the change feel intentional", "Mixing kick-heavy tracks where two low ends together would overload the system"]}, "30f3908e-22d8-4a9e-a030-ad0665efce94": {"definition": "The DJ technique of adjusting the tempo (BPM) of one track to match another and aligning their beats so the two play in time together, allowing a seamless blend or simultaneous playback. It is done by changing a deck's pitch/tempo control and nudging the platter or using pitch-bend until the beats lock and stay in phase.", "plain_english": "Beatmatching means making two songs play at the same speed. You also line up their beats so they hit together. Then you can blend one song into the next with no stumble in the rhythm.", "purpose_function": "It lets a DJ blend two tracks without a clash of tempos or beats, which is the foundation of continuous mixing and of keeping a steady groove on the dancefloor.", "practical_application": "A DJ cues the incoming track in headphones, matches its BPM to the playing track with the tempo fader, and nudges the jog wheel until the beats lock before opening the crossfader.", "category": "Mixing Technique", "related_terms": ["Beatgrid", "Pitch bend", "Bar", "Phrasing", "Sync", "Crossfader"], "common_mistakes": ["Relying on the Sync button and never learning to beatmatch by ear", "Matching the BPM numbers but not aligning the downbeats, so the tracks drift out of phase", "Setting the tempo but failing to make small pitch-bend corrections as tracks slowly drift", "Trying to mix tracks whose tempos or beatgrids are unstable without correcting them"], "scenario_contexts": ["Blending one house track into the next during a continuous club set", "Matching a new record's tempo to the one playing before opening the crossfader", "Practising beatmatching by ear on CDJs with the sync and waveform aids turned off"]}, "b257b381-5994-4cdc-9ffb-886501cb41e4": {"definition": "A momentary tempo change used to shift the timing (phase) of a playing track so its beats realign with another, produced by briefly speeding up or slowing down playback via the jog wheel's outer edge, dedicated tempo/pitch-bend buttons, or nudging the platter, without permanently altering the set tempo. It is also called pitch bend or tempo bend.", "plain_english": "A bend is a quick nudge to a song's speed. You push it a little faster or slower for a moment. This lines the beats back up when they start to drift. It does not change the main speed.", "purpose_function": "It corrects small timing drift between two beatmatched tracks so their beats stay locked, letting a DJ hold a tight mix even when the tempos wander slightly.", "practical_application": "While two tracks are beatmatched, the DJ nudges the jog wheel forward or taps a pitch-bend button to pull a slightly lagging beat back into line.", "category": "Mixing Technique", "related_terms": ["Beatmatching", "Pitch fader", "Jog wheel", "Sync", "Phase", "Nudge"], "common_mistakes": ["Confusing pitch bend (a temporary nudge) with the pitch/tempo fader (a lasting tempo change)", "Bending too hard, so the beats overshoot and drift the other way", "Relying on constant bends instead of first matching the tempos correctly"], "scenario_contexts": ["Nudging a drifting track back into time during a long blend", "Correcting phase after a scratch or beat jump knocks the track off time", "Fine-tuning beat alignment on vinyl or CDJs by touching the platter or jog wheel"]}, "a6cc8bfc-3dc0-47ae-b840-8e464cdf89ed": {"definition": "In DJ and dance-music culture, a bootleg is an unofficial edit, remix, re-edit, or mashup of an existing recording, produced and circulated without the rights holder's licence or authorisation. DJs use bootlegs as exclusive playing tools that rework or combine commercially released tracks for their own sets.", "plain_english": "A bootleg is an unofficial remix or edit of a song. A DJ or fan makes it without permission from the song owners. DJs play them to get versions no one else has.", "purpose_function": "A bootleg lets a DJ play a reworked or combined version of tracks that is not sold officially, giving a set unique, exclusive material. It exists because DJs want fresh edits faster than licensed remixes appear.", "practical_application": "A DJ sources or produces a bootleg edit to drop a mashup of two familiar songs the crowd has not heard blended together before.", "category": "Track type", "related_terms": ["Mashup", "Re-edit", "Remix", "White label", "Acapella"], "common_mistakes": ["Assuming a bootleg is legal to sell or stream, when most bootlegs are unlicensed and cannot be commercially released.", "Confusing a bootleg edit with an official remix that a label commissioned and released.", "Thinking 'bootleg' only means a pirated live recording, when in DJ use it usually means an unofficial edit or mashup."], "scenario_contexts": ["A DJ plays a bootleg mashup blending an acapella over a different instrumental.", "A producer makes a bootleg re-edit that extends a track's intro for easier beatmatching.", "A DJ hunts for exclusive bootlegs so their set stands out from other DJs."]}, "2c95d687-2d49-4733-a903-cd7327225307": {"definition": "BPM matching is the process of adjusting the tempo of one track, measured in beats per minute (BPM), so that it equals the tempo of another track playing at the same time. It is the tempo-alignment part of beatmatching, achieved with a deck's pitch/tempo fader or with software sync.", "plain_english": "BPM stands for beats per minute, which is a song's speed. BPM matching means changing one song's speed to equal another song. This lets two songs run at the same pace so they blend.", "purpose_function": "It exists so two tracks share one tempo, which is the first requirement for a smooth, beat-aligned blend. Without matched BPM the beats drift apart and the mix sounds clumsy.", "practical_application": "A DJ reads each track's BPM on the display, then nudges the tempo fader (or presses Sync) until the incoming track's BPM equals the track already playing.", "category": "Mixing technique", "related_terms": ["Beatmatching", "Tempo", "Pitch fader", "Sync", "Phrasing"], "common_mistakes": ["Thinking matched BPM alone means the tracks are in sync, when the beats must also be phase-aligned (beatmatched).", "Trusting software BPM readings blindly, when analysis can mis-detect tempo, for example reading half or double the true BPM.", "Forgetting that large tempo changes also shift pitch unless key lock / master tempo is enabled."], "scenario_contexts": ["Blending two house tracks by setting both to the same BPM before the transition.", "Speeding up a slower track to match a faster one during a build.", "Checking BPM values in the DJ software before loading a track to the deck."]}, "e54c1295-7e9c-4098-bb32-91d0da737fbb": {"definition": "The brake effect (often labelled 'Vinyl Brake') is a DJ effect that progressively slows the playback speed of the audio down to a stop, imitating the sound of a turntable platter braking when its motor is switched off. On Pioneer DJM mixers the rate of the slow-down is set by the selected beat fraction.", "plain_english": "The brake effect makes a track slow down to a stop. It sounds like a record player switching off with the record still on it. DJs use it to end a track or make a dramatic pause.", "purpose_function": "It exists to create a dramatic slow-to-silence transition or a momentary stop, adding tension or a clean ending before the next track. The beat setting controls how quickly the sound decelerates.", "practical_application": "A DJ triggers the vinyl brake at the end of a phrase so the track winds down like a stopping turntable, then drops the next tune.", "category": "Effect (FX)", "related_terms": ["Beat FX", "Backspin", "Echo (effect)", "Filter", "Cue point"], "common_mistakes": ["Confusing the brake effect with a backspin, when a brake slows forward playback to a stop and a backspin rapidly rewinds the record.", "Setting too long a beat value so the slow-down drags and drains the crowd's energy.", "Assuming it only changes volume, when it lowers playback speed and therefore pitch as it stops."], "scenario_contexts": ["Ending a track with a turntable-style wind-down using the DJM's Vinyl Brake.", "Creating a short dramatic stop before a drop.", "Simulating a power-off record stop without touching the platter."]}, "e30d88ae-a3bf-4ed0-a2b1-1b9c9344eb62": {"definition": "In dance and electronic music, a breakdown is a structural section where the main rhythmic elements, typically the kick drum and much of the percussion, drop out, leaving melodic, harmonic, or atmospheric material to build tension before the full beat and energy return (often at 'the drop'). DJs treat the breakdown as a key mixing and transition zone.", "plain_english": "A breakdown is the part of a dance track where the main beat drops out. You hear melody or mood instead, which builds tension before the beat returns. DJs often start their mix here.", "purpose_function": "The breakdown gives a track dynamic contrast and an emotional build, and it hands the DJ a low-energy window that is easy to mix in or out of. It exists to reset tension so the return of the beat hits harder.", "practical_application": "A DJ starts blending the next track during the current track's breakdown, since the missing drums make the two beats easier to layer cleanly.", "category": "Track structure", "related_terms": ["Drop", "Buildup", "Phrasing", "Intro", "Outro", "Transition"], "common_mistakes": ["Confusing a breakdown with a breakbeat, when a breakdown is a section with the beat removed and a breakbeat is a drum pattern.", "Losing the phrase count so the two tracks clash instead of the breakdowns lining up.", "Assuming every track has a breakdown, when some tracks have little or no breakdown section."], "scenario_contexts": ["Mixing the next track in during a breakdown when the drums are absent.", "Using a long breakdown to introduce an acapella or effect.", "Building crowd anticipation as the breakdown leads into the drop."]}, "328a0ce3-2353-4ac2-80e8-a13766d043e4": {"definition": "The Camelot Wheel is a harmonic-mixing chart, created by Mark Davis (Camelot Sound) and popularised by the Mixed In Key software, that maps the 24 major and minor musical keys onto a clock face of numbers 1 to 12 with a letter (A for minor keys, B for major keys), giving each key a code such as 8A or 8B. Tracks whose codes are the same, share a number with the other letter, or are one number apart are harmonically compatible, so DJs use the wheel to choose tracks that blend without key clashes.", "plain_english": "The Camelot Wheel is a chart shaped like a clock. It turns musical keys into simple codes like 8A or 8B. Keys next to each other on the wheel sound good together. DJs use it to pick songs that blend without clashing.", "purpose_function": "It exists to make harmonic (key) mixing easy without deep music-theory knowledge, by turning key relationships into a simple map of compatible neighbours. This helps DJs avoid dissonant, clashing blends.", "practical_application": "A DJ reads each track's Camelot code in the DJ software, then chooses a next track with the same code, the same number with the other letter, or an adjacent number.", "category": "Harmonic mixing", "related_terms": ["Harmonic mixing", "Key detection", "Circle of fifths", "Key lock", "BPM matching"], "common_mistakes": ["Treating the Camelot code as absolute, when software key detection can be wrong, so DJs should trust their ears too.", "Mixing keys that are far apart on the wheel and expecting them to blend smoothly.", "Forgetting that A means minor and B means major, and confusing the two when picking a compatible track."], "scenario_contexts": ["Choosing the next track by matching or moving one step on the Camelot Wheel.", "Sorting a library by Camelot key to plan a harmonically smooth set.", "Combining harmonic mixing with beatmatching for cleaner long blends."]}, "7a7c4c22-9d37-4b86-a050-19ea33ccce87": {"definition": "A changeover mix is the transition performed when one DJ hands over to the next during an event, blending or bridging the outgoing DJ's final track into the incoming DJ's first track so the music continues without an obvious break. It is the mixing skill used to keep a set handover seamless.", "plain_english": "A changeover mix is how one DJ hands over to the next DJ. The music keeps going smoothly instead of stopping between sets. It keeps the dancefloor moving during the swap.", "purpose_function": "It exists to keep continuous music and energy on the dancefloor while performers swap, avoiding an awkward silence or an abrupt style jump. A smooth changeover protects the atmosphere during a set handover.", "practical_application": "As a slot ends, a DJ beatmatches their last track into the next DJ's opening track, or hands over on a suitable phrase, so the crowd barely notices the switch.", "category": "Mixing technique", "related_terms": ["Changeover playlist", "Transition", "Beatmatching", "Back-to-back (B2B)", "Phrasing"], "common_mistakes": ["Stopping the music dead at the end of a set instead of mixing into the next DJ.", "Not agreeing tempo or key with the incoming DJ, causing a jarring changeover.", "Running past the allotted slot and leaving the next DJ no room for a clean handover."], "scenario_contexts": ["Two club DJs blending sets at the end of one performer's slot.", "A festival stage handover kept seamless with a beatmatched transition.", "Setting up a back-to-back by mixing smoothly between each DJ's tracks."]}, "d3804f9f-9701-4e1f-bf5f-944dfdb98e8e": {"definition": "A changeover playlist is a pre-prepared list of tracks, often set to auto-play or run by a host, used to keep continuous background music during the changeover between DJs or acts, or during breaks when no DJ is actively mixing. It ensures the venue never falls silent while performers swap or reset equipment.", "plain_english": "A changeover playlist is a ready-made list of songs for the gaps between DJs. It plays on its own to keep music going when no one is mixing. This stops the room from going silent during a swap.", "purpose_function": "It exists to guarantee uninterrupted sound and atmosphere during set changes or technical resets, so the room stays alive even when no DJ is performing. It also removes the pressure to mix live during a handover.", "practical_application": "A venue loads a changeover playlist into the media player set to auto-play, covering the minutes while one DJ packs down and the next sets up.", "category": "Set preparation", "related_terms": ["Changeover mix", "Auto play", "Cue", "Playlist", "Transition"], "common_mistakes": ["Filling a changeover playlist with tracks that clash in energy or key with the sets around it.", "Forgetting to enable auto-play, so the music stops when the current track ends.", "Choosing the wrong track lengths so the playlist runs out before the next DJ is ready."], "scenario_contexts": ["Auto-playing background tracks while DJs swap equipment on stage.", "Covering a technical reset without leaving the room silent.", "Keeping steady music during dinner or a warm-up before the headline set."]}, "8064e629-f890-48ec-a5aa-23882faa8d24": {"definition": "The act of repeatedly nudging the platter, jog wheel, or pitch control to keep an incoming track aligned with the track already playing, because the two tempos are not truly matched and their beats keep drifting apart. It is a symptom of an imperfect beatmatch rather than a stable, hands-off sync.", "plain_english": "Chasing the beat means you keep nudging a track to stay in time. The two songs are not at the exact same speed. So their beats slowly drift apart. You push or slow the track again and again to catch up.", "purpose_function": "It describes the constant manual correction a DJ makes when the pitch is set slightly wrong, and it signals that the tempo needs a finer adjustment rather than repeated nudges.", "practical_application": "When a mix keeps drifting, a DJ recognises they are chasing the beat and makes a small pitch-fader change so the decks hold time on their own.", "category": "Beatmatching", "related_terms": ["Beatmatching", "Pitch fader", "Nudge", "Jog wheel", "Drifting", "Train wreck"], "common_mistakes": ["Nudging endlessly instead of correcting the pitch so the tempos actually match", "Over-correcting each nudge and pushing the track past the beat the other way", "Blaming the equipment when the real issue is a slightly mismatched tempo"], "scenario_contexts": ["Beatmatching two vinyl records whose tempos are close but not exact", "Mixing on CDJs with sync off and constantly touching the jog to hold time", "A student's first long blend where the incoming track keeps slipping out of time"]}, "d8f9a016-2238-43ee-b5d9-2f1bded98f9c": {"definition": "A modulation effect that makes a single sound source appear to be several sources playing in unison by mixing the original signal with one or more delayed copies whose delay time is varied by a low-frequency oscillator, producing small pitch (detuning) and timing differences. The blended, slightly detuned copies create a thicker, shimmering, ensemble-like sound.", "plain_english": "Chorus is an effect that makes one sound seem like many. It copies the sound, delays each copy a little, and slowly shifts its pitch. Mixed together, they sound like a group playing as one. It is like one singer turning into a small choir.", "purpose_function": "It exists to thicken and widen a sound, adding movement and a sense of multiple performers, and it is built from a short modulated delay line for exactly that reason.", "practical_application": "A DJ or engineer switches a chorus effect onto a synth, vocal, or full track to fatten it and add width during a breakdown or transition.", "category": "Effects", "related_terms": ["Modulation", "Delay", "Flanger", "Low-frequency oscillator", "Detune", "FX unit"], "common_mistakes": ["Confusing chorus with flanger, which uses much shorter, feedback-heavy modulated delays", "Setting the mix too high so the effect sounds warbly and unnatural", "Assuming chorus changes pitch permanently rather than adding small, moving pitch variations"], "scenario_contexts": ["Adding width to a thin synth line during a track breakdown", "Using a mixer or software chorus FX to thicken a vocal before a drop", "Layering chorus on a guitar or pad to create an ensemble feel"]}, "304e74fb-fa48-47bd-924b-5d5a18f82c77": {"definition": "The stumbling, flamming sound produced when two tracks are mixed together with their beats out of alignment, so the drum hits fall at slightly different moments instead of landing together. It is an audible sign of a failed or drifting beatmatch.", "plain_english": "Clanging is when two tracks' beats do not line up. The drum hits fall at slightly different times. You hear a doubled, stumbling sound instead of one steady beat. It is a common sign of a bad beatmatch.", "purpose_function": "The term names the specific error a DJ listens for while beatmatching, so they can hear when the beats have separated and correct the timing before the crowd notices.", "practical_application": "A DJ hears clanging in the headphones as the beats separate and nudges or adjusts pitch to pull the kicks back on top of each other.", "category": "Beatmatching", "related_terms": ["Beatmatching", "Train wreck", "Chasing the beat", "Nudge", "Phrasing", "Cueing"], "common_mistakes": ["Not monitoring in headphones, so clanging is only noticed once it is already on the speakers", "Mistaking a clang for a deliberate rhythmic effect and leaving it uncorrected", "Correcting with a huge nudge that overshoots and causes a full train wreck"], "scenario_contexts": ["Two kick drums drifting apart during a long blend and doubling up", "A beginner beatmatching by ear and hearing the beats flam out of time", "Mixing records whose tempos slowly separate over a long transition"]}, "dfc7a7da-db65-4c10-bbd7-241572b4b5e5": {"definition": "A track that has endured well beyond its original release and remains widely recognised, respected, and effective on the dancefloor, functioning as a timeless standard a DJ can rely on. The label reflects lasting cultural and dancefloor value rather than a specific age.", "plain_english": "A classic is an old track that people still love and play. It has lasted for years and still fills the floor. DJs keep it ready because crowds always know it. Think of it as a song that never goes out of style.", "purpose_function": "It marks a track as a dependable crowd-pleaser with proven staying power, giving a DJ a trusted option to lift or reconnect with a room.", "practical_application": "A DJ drops a classic when they need a guaranteed reaction, using the crowd's shared recognition to raise energy or rescue a flagging floor.", "category": "Track Terminology", "related_terms": ["Anthem", "Collection", "Peak-time set", "Read the crowd", "Club edit", "Set programming"], "common_mistakes": ["Assuming any old record is a classic, when only enduring, still-effective tracks qualify", "Overusing classics so a set feels dated instead of balanced with current music", "Playing a classic at the wrong moment and killing momentum rather than building it"], "scenario_contexts": ["Dropping a well-known older anthem to reunite a divided dancefloor", "Programming a classics night built around enduring, recognisable tracks", "Reaching for a trusted classic when a newer selection fails to connect"]}, "0d0d730b-24c1-4a13-9663-ea4e085afece": {"definition": "The final track a DJ selects to end a set or night, chosen to leave the crowd with a strong, memorable last impression. It may be a big emotional peak or a calmer wind-down, depending on the moment the set has reached.", "plain_english": "A closer is the track a DJ picks to end the night. It sends people home on a strong feeling. It might be big and emotional, or calm and warm. The right closer is the last thing the crowd remembers.", "purpose_function": "It gives a set a deliberate ending, shaping the final emotional memory of the night rather than letting the music simply stop.", "practical_application": "As a slot ends, a DJ cues a chosen closer that fits the room's energy, sealing the set on a high or a graceful comedown.", "category": "Set Programming", "related_terms": ["Closing DJ", "Set programming", "Peak-time set", "Warm-up set", "Classic", "Read the crowd"], "common_mistakes": ["Not planning a closer and ending on a random or weak track", "Choosing a closer that clashes with the room's actual energy at the end", "Trying to top an already-passed peak instead of ending with intent"], "scenario_contexts": ["Ending a club night with a well-known track that sends the floor home happy", "Closing a warm-up slot cleanly to hand over to the next DJ", "Selecting a calmer final record to wind a late crowd down"]}, "b8749a4a-77b9-4998-90a0-11dcc6f8f8ee": {"definition": "The DJ who plays the final set of an event, taking over after the headline or peak-time slot to play the night out. The role often involves easing the remaining crowd down or delivering a last emotional lift rather than chasing the biggest peak.", "plain_english": "The closing DJ plays the last set of the night. They take over after the main act and the peak. Their job is to play out the final hour. Often they ease the crowd down as the party ends.", "purpose_function": "It defines a distinct programming role with its own skill set, giving the end of the night a considered shape instead of an abrupt stop.", "practical_application": "A closing DJ reads a thinning, late-night floor and selects deeper or calmer tracks to see the last dancers out on the right note.", "category": "Set Programming", "related_terms": ["Closer", "Warm-up set", "Peak-time set", "Set programming", "Read the crowd", "Momentum"], "common_mistakes": ["Trying to out-peak the headliner instead of playing an appropriate closing set", "Ignoring the smaller late crowd and playing as if the floor is still packed", "Ending abruptly with no thought to how the last dancers leave"], "scenario_contexts": ["Playing the final 4-to-6am slot in a club after the peak-time DJ", "Closing a festival stage by winding a tired crowd down gently", "Taking the last slot at an afterparty for the remaining dancers"]}, "5cee32ab-3fea-479d-a5b1-da7e6db96026": {"definition": "A version of a track arranged for club and DJ use, typically featuring extended, beat-driven intro and outro sections and a longer overall length than the radio edit, to give the DJ room to mix it in and out. It prioritises dancefloor function over radio-friendly brevity.", "plain_english": "A club edit is a version of a song made for DJs. It has a long, steady beat at the start and end. Those parts give the DJ room to mix it in and out. It is usually longer than the radio version.", "purpose_function": "It exists to make a track easy to beatmatch and blend, providing plain, rhythmic sections at each end so transitions are smooth on a dancefloor.", "practical_application": "A DJ chooses the club edit over the radio edit so the long intro gives time to beatmatch and mix the track into the set.", "category": "Track Terminology", "related_terms": ["Radio edit", "Extended mix", "Intro", "Outro", "Remix", "Beatmatching"], "common_mistakes": ["Loading the radio edit by mistake and having almost no intro to mix over", "Assuming a club edit and an extended mix are always identical versions", "Ignoring where the club edit's mix-friendly sections start and end"], "scenario_contexts": ["Selecting the club edit of a pop track to get a longer, mixable intro", "Preparing a set and swapping radio edits for club edits for smoother blends", "Using the extended outro of a club edit to mix into the next track"]}, "5889c5b8-d787-4bdf-a458-dec92e5e909e": {"definition": "A DJ set performed in a club setting, usually longer than a festival or radio set and giving the DJ time to build energy gradually and program a journey. The extended format favours smooth mixing and a developing arc over back-to-back big moments.", "plain_english": "A club set is a DJ set played in a club. It is often long, so the DJ can build slowly. There is time to take the crowd on a journey. This is different from a short festival or radio set.", "purpose_function": "It gives a DJ the time and freedom to shape a full arc, so a night in a club can rise, peak, and settle rather than staying at one level.", "practical_application": "Booked for a multi-hour club slot, a DJ paces the selection to warm the room, reach a peak, and then ease it back down.", "category": "Set Programming", "related_terms": ["Set programming", "Peak-time set", "Warm-up set", "Closing DJ", "Momentum", "Read the crowd"], "common_mistakes": ["Playing a short, peak-heavy festival style in a long club slot and exhausting the crowd early", "Failing to pace the set, so there is no build or release across the night", "Burning the biggest tracks too soon with hours still to fill"], "scenario_contexts": ["Playing an extended three-hour residency slot in a club", "Pacing a long set to build gradually toward a peak", "Taking a crowd on a journey across a full night in one room"]}, "ce59de3f-2b83-4093-9cee-0f7942d5183b": {"definition": "The full body of music a DJ owns and draws upon for performance; in DJ software such as rekordbox, the Collection is specifically the master list of all tracks that have been imported and analysed for use. It is the central library from which playlists, crates, and sets are built.", "plain_english": "A collection is all the music a DJ owns and can play. In software like rekordbox, the Collection lists every track you add. The DJ sorts and preps this music before a gig. It is like a personal record shop you carry with you.", "purpose_function": "It centralises every available track in one managed library, so a DJ can search, tag, and organise their music and pull from it quickly during preparation and performance.", "practical_application": "Before a gig, a DJ imports tracks into the Collection, lets them analyse, then organises them into playlists or crates for the night.", "category": "Library Management", "related_terms": ["Playlist", "Crate", "rekordbox", "Track analysis", "Beat grid", "Classic"], "common_mistakes": ["Confusing a single playlist or crate with the whole Collection", "Moving or renaming music files outside the software so the Collection loses track of them", "Never organising the Collection, making tracks hard to find under pressure"], "scenario_contexts": ["Importing and analysing new tracks into the rekordbox Collection before a set", "Building crates and playlists by pulling from the main Collection", "Managing a large digital library so any track can be found quickly mid-set"]}, "33b05dad-c2d5-42db-bc49-313689733dc8": {"definition": "In harmonic mixing, a compatible key is a musical key that blends consonantly with the key of the currently playing track, so the two do not clash melodically when overlapped. Using systems such as the Camelot wheel (a re-labelling of the circle of fifths), compatible keys are typically the same key, its relative major or minor (same number, opposite letter), or a key one step around the wheel (adjacent number, same letter).", "plain_english": "Two songs are in a compatible key when their notes sound good played together. DJ software labels each track's key. Mixing tracks with matching or neighbouring keys stops the blend from sounding out of tune.", "purpose_function": "It lets a DJ overlap or transition between two tracks without musical dissonance, keeping harmonies smooth so mixes sound intentional rather than jarring.", "practical_application": "A DJ reads the detected key shown in rekordbox, Serato or Traktor and picks a next track in the same or an adjacent key to mix in cleanly.", "category": "Harmonic mixing", "related_terms": ["Harmonic mixing", "Camelot wheel", "Key detection", "Key lock", "Beatmatching", "Circle of fifths"], "common_mistakes": ["Assuming only the exact same key is usable, when relative and adjacent keys also blend well", "Trusting software key detection blindly, since analysis can misread a track's key", "Ignoring that pitching a track without key lock shifts its key and breaks compatibility"], "scenario_contexts": ["Planning a smooth harmonic transition between two vocal tracks", "Building a set that moves gradually around the Camelot wheel", "Choosing a next record whose key will not clash with the outgoing one"]}, "dd7463e0-a079-4192-9e6f-70355f3c8557": {"definition": "A crate is a DJ's grouping or container of selected tracks, originally a physical record crate and now, in DJ software such as Serato, a virtual folder used to organise the music library. A single track can belong to several crates at once, letting a DJ file it by genre, mood, energy or event.", "plain_english": "A crate is a box of records, or a folder in DJ software, that holds a chosen group of tracks. DJs use crates to sort music so they can find the right song fast during a set.", "purpose_function": "It organises a large library into manageable, purpose-built groups so a DJ can locate suitable tracks quickly while performing.", "practical_application": "A DJ builds crates by genre, tempo or event and pulls from them during a gig instead of searching the whole collection.", "category": "Library management", "related_terms": ["Crate digging", "Playlist", "Cue preparation", "Smart crate", "Crate exclusive", "BPM"], "common_mistakes": ["Dumping every track into one giant crate, which defeats the point of quick access", "Thinking a track can live in only one crate, when it can sit in many at once", "Confusing a crate with a fixed-order playlist meant to play straight through"], "scenario_contexts": ["Sorting a music library into genre folders before a gig", "Preparing an 'openers' crate of low-energy tracks for early in the night", "Grabbing records from a physical crate at a vinyl set"]}, "f841b949-7303-480d-985a-c0c4f0e07aa4": {"definition": "Crate digging is the practice of searching through large collections of records — in shops, markets, archives or online stores — to find rare, obscure or otherwise useful tracks for DJ sets or sampling. The term comes from physically flipping through crates of vinyl.", "plain_english": "Crate digging means hunting through piles of records to find hidden gems. DJs and producers dig for rare or unusual tracks that other people don't have.", "purpose_function": "It builds a distinctive personal collection, giving a DJ or producer unique material that sets their sets or sampling apart.", "practical_application": "A DJ spends hours in record shops or online stores searching for breaks, edits or rare pressings to add to their crates.", "category": "Music selection", "related_terms": ["Crate", "Sampling", "Break", "Crate exclusive", "Record pool", "Selection"], "common_mistakes": ["Buying records by name or hype instead of actually listening first", "Neglecting to file finds into crates, so gems get lost in the pile", "Assuming digging is only about vinyl, when digital libraries can be dug too"], "scenario_contexts": ["Searching a second-hand record shop for rare funk breaks", "Browsing an online store for obscure edits to sample", "Hunting archives for unique tracks to make a set stand out"]}, "791e62a6-7942-4783-8cc5-8d6a0dc16dac": {"definition": "A crate exclusive is a track or record that a DJ keeps exclusive to their own collection — not shared, revealed or passed to other DJs — so it remains a unique part of their sets. The idea grows out of dubplate and exclusive-record culture, where owning a track no rival has gives a competitive edge.", "plain_english": "A crate exclusive is a track a DJ keeps to themselves. They don't share it with other DJs, so it stays their secret weapon on the dancefloor.", "purpose_function": "It gives a DJ a signature or advantage by ensuring certain tracks appear only in their sets, keeping their selection distinctive.", "practical_application": "A DJ guards a special edit or dubplate as a crate exclusive, refusing to name or share it so rivals cannot play it.", "category": "Music selection", "related_terms": ["Crate", "Crate digging", "Dubplate", "Selection", "Record pool", "Break"], "common_mistakes": ["Thinking every downloaded promo is a true exclusive, when many DJs may hold the same file", "Sharing a supposed exclusive online, which instantly ends its exclusivity", "Confusing a crate exclusive with a commercial release simply labelled 'exclusive' by a store"], "scenario_contexts": ["A DJ keeping a custom edit secret to stay ahead of rivals", "Guarding a dubplate cut specially for one performer", "Refusing to identify a track so it stays a personal weapon"]}, "df459d2b-1cc3-4041-94f3-b02c33ebc0c6": {"definition": "In DJing, a crossfade is the transition of audio from one deck to another by simultaneously lowering the level of the outgoing track and raising the level of the incoming track, controlled by the mixer's crossfader. The crossfader is a horizontal slider that pans between the two (or more) assigned channels.", "plain_english": "A crossfade is a smooth swap from one song to the next. You slide a control across so one track fades out while the other fades in, with no silent gap.", "purpose_function": "It lets a DJ move between tracks seamlessly on a single output, blending or cutting between decks to keep the music continuous.", "practical_application": "A DJ slides the crossfader across to bring in the next beatmatched track, or flicks it quickly to cut and scratch.", "category": "Mixing technique", "related_terms": ["Crossfader", "Beatmatching", "Fader curve", "Channel fader", "Transition", "Blend"], "common_mistakes": ["Crossfading before the two tracks are beatmatched, causing an audible clash", "Leaving the crossfader in the middle by accident, so both tracks play at once", "Setting a sharp fader curve for blends when a gentle curve suits smooth transitions"], "scenario_contexts": ["Blending one beatmatched track into the next during a set", "Cutting quickly between decks while scratching", "Fading out a finished track and bringing in a fresh one"]}, "9cb788e2-4625-4395-83b1-5637ee197bcb": {"definition": "A crowd pleaser is a track a DJ can rely on to draw a strong, positive reaction from a dancefloor — typically a familiar, high-energy or well-loved song that reliably fills the floor. DJs use crowd pleasers strategically to build or rescue the energy of a set.", "plain_english": "A crowd pleaser is a song almost everyone loves. DJs drop it when they want to fill the dancefloor or lift the room's energy fast.", "purpose_function": "It gives a DJ a dependable tool to raise energy, win over a crowd or recover a flagging dancefloor.", "practical_application": "A DJ saves a few crowd pleasers to deploy at peak time or when the floor is emptying, to bring people back.", "category": "Music selection", "related_terms": ["Crowd reading", "Peak time", "Set building", "Selection", "Crate", "Energy level"], "common_mistakes": ["Overplaying crowd pleasers, so the set feels obvious and predictable", "Dropping them too early and leaving nothing to lift the peak", "Assuming one track pleases every crowd, ignoring venue and audience"], "scenario_contexts": ["Filling a thinning dancefloor late in the night", "Building toward peak time with a known anthem", "Winning over an unfamiliar crowd early in a set"]}, "fd061b51-3177-4914-9a69-cf66e1d88ad0": {"definition": "Cue juggling is a performance technique in which a DJ rapidly triggers hot cue points within one or more tracks to rearrange or repeat sections in real time — effectively the digital equivalent of vinyl beat juggling. By jumping between stored cue points, the DJ builds new rhythmic patterns from a track's existing parts.", "plain_english": "Cue juggling means jumping between saved spots in a song to rearrange it live. It's like beat juggling on vinyl, but done with buttons that leap to marked points.", "purpose_function": "It lets a DJ remix, loop or re-pattern a track on the fly using stored cue points, adding live creativity without touching vinyl.", "practical_application": "A DJ sets hot cues on a track's drums and vocals, then taps between them in time to create a new arrangement during a performance.", "category": "Performance technique", "related_terms": ["Cue point (DJ)", "Hot cue", "Beat juggling", "Loop", "Quantize", "Backspin"], "common_mistakes": ["Setting cue points off the beat, so juggled hits land out of time", "Relying on quantize as a crutch and never learning the timing by ear", "Confusing cue juggling with beat juggling, which uses two vinyl copies instead of cue points"], "scenario_contexts": ["Rearranging a track's drum hits live using hot cues", "Repeating a vocal phrase by jumping back to a stored cue", "Performing a controllerist routine built on cue-point triggers"]}, "eaeef31c-cb73-407d-adcd-a10e5fabddad": {"definition": "A cue point is a marker stored at a specific position in a track that lets a DJ jump instantly to that point during playback or cueing. Players and software distinguish a temporary (current) cue from saved memory cues and hot cues, which are recalled at the press of a pad or button.", "plain_english": "A cue point is a bookmark in a song. The DJ marks a spot, like the first beat or a drop. They can then jump straight back to it with one button.", "purpose_function": "It lets a DJ start a track exactly where they want and return to key moments instantly, making cueing and live triggering fast and precise.", "practical_application": "A DJ sets a cue point on the first downbeat so the track launches on time, and adds hot cues at the drop and breakdown for live jumps.", "category": "Cueing", "related_terms": ["Cueing", "Hot cue", "Memory cue", "Cue preparation", "Cue juggling", "Beat grid"], "common_mistakes": ["Placing the cue point slightly off the downbeat, so the track launches out of time", "Confusing a temporary cue with a saved hot cue that stays with the track", "Setting too many hot cues, cluttering the track and slowing decisions"], "scenario_contexts": ["Marking the first beat so a track drops in on time", "Adding hot cues to launch a track from its chorus or drop", "Re-cueing back to the start after testing a mix in headphones"]}, "24147b54-1503-42c0-a6c6-b77f2c20de87": {"definition": "Cue preparation is the advance work of analysing tracks and setting cue points, hot cues, loops, beat grids and other markers before a performance, so they are ready to trigger live. It is part of the wider library preparation DJs do to make tracks reliable and quick to use during a set.", "plain_english": "Cue preparation is the homework a DJ does before a gig. They mark useful spots and set the beat grid in each track, so everything is ready to play live.", "purpose_function": "It removes guesswork during a performance by ensuring every track's launch points and grids are set in advance, so the DJ can focus on mixing.", "practical_application": "Before a gig a DJ loads new tracks, checks the beat grid, and sets cue points and hot cues so each is ready to drop precisely on the night.", "category": "Cueing", "related_terms": ["Cue point (DJ)", "Hot cue", "Beat grid", "Crate", "Cue juggling", "Track analysis"], "common_mistakes": ["Skipping preparation and setting cues live, which risks off-beat launches", "Trusting auto-analysis grids without checking them on tricky or live-recorded tracks", "Preparing cues but forgetting to back up the library, losing all the work"], "scenario_contexts": ["Setting cue points and grids on new tracks the day before a gig", "Fixing a drifting beat grid on a live or older recording", "Marking hot cues so tracks can be juggled or launched cleanly on stage"]}, "d07eec7f-373c-4263-9bb1-d3d54689e554": {"definition": "In DJing, the practice of listening to a track privately through headphones or a monitor via the mixer's cue (pre-fade listen) bus, before it is sent to the main output, in order to locate its start point, set cue points, and beatmatch it to the track currently playing.", "plain_english": "Cueing means the DJ listens to the next song in their headphones before the crowd hears it. This lets them find the right start point and match its beat to the song playing now.", "purpose_function": "It lets a DJ prepare and line up the next track without the audience hearing it, so transitions can be timed and beatmatched accurately.", "practical_application": "A DJ presses the channel's cue button, listens in headphones, finds the first beat, then brings the track into the mix on the beat.", "category": "Cueing Technique", "related_terms": ["Cue point", "Slip cue", "Beatmatching", "Pre-fade listen (PFL)", "Crossfader"], "common_mistakes": ["Confusing cueing (private headphone monitoring) with the main mix the audience hears", "Setting the cue point off the beat, so the track starts out of time", "Forgetting to switch the cue to the incoming channel before mixing"], "scenario_contexts": ["A club DJ cueing the next record in headphones before mixing it in", "Setting cue points on tracks in DJ software before a set", "A radio DJ cueing a song so it starts instantly on air"]}, "44e2790e-e38a-4dd8-a85f-91d21fa4d4c8": {"definition": "The practice of searching through record stores, bins, crates, and other sources, including online catalogs and digital libraries, to find records or tracks, especially rare, obscure, or sample-worthy material, for DJing or music production.", "plain_english": "Digging is when a DJ hunts through stacks of records to find great tracks. They look for rare or unusual songs that other DJs may not have.", "purpose_function": "It builds a DJ's collection and music knowledge, giving them distinctive tracks and samples that set their sets or productions apart from others.", "practical_application": "A DJ spends hours in record shops or online stores, flipping through stock to unearth tracks worth adding to their crates.", "category": "Record Collecting", "related_terms": ["Digging in the crates", "Digital crate", "Record pool", "Sampling", "DJ (Disc Jockey)"], "common_mistakes": ["Thinking digging only means buying popular or charting records, not searching for obscure ones", "Assuming digging is only physical, when DJs also dig through digital libraries and online stores", "Collecting records without cataloguing them, so tracks are hard to find later"], "scenario_contexts": ["A hip-hop DJ digging through funk and soul records to find breaks to sample", "A DJ browsing an online store to dig for new releases before a gig", "Spending an afternoon in a used-record shop digging for rare tracks"]}, "99b34c11-2394-464d-9cea-fcea43e894f5": {"definition": "The practice of methodically searching through crates and bins of records, especially used or obscure vinyl, to find tracks, drum breaks, and samples for DJing and hip-hop production; the phrase originates in hip-hop record-collecting culture.", "plain_english": "This means flipping through boxes of old records to find hidden gems. DJs and producers do it to find rare beats and samples for their music.", "purpose_function": "It is how DJs and producers source rare breaks, samples, and tracks, building a unique library that shapes their individual sound.", "practical_application": "A producer spends hours digging in the crates at a used-record store, pulling out old funk albums to find drum breaks to sample.", "category": "Record Collecting", "related_terms": ["Digging", "Digital crate", "Breakbeat", "Sampling", "DJ (Disc Jockey)"], "common_mistakes": ["Treating it as just shopping, rather than a skilled search for specific breaks and samples", "Assuming it applies only to vinyl, when the idea now extends to digital libraries", "Confusing the practice with the D.I.T.C. crew that took its name from the phrase"], "scenario_contexts": ["A hip-hop producer digging in the crates for a rare drum break to sample", "A DJ searching second-hand bins for obscure records to play out", "Building a sample collection by digging in the crates at flea markets and record fairs"]}, "0f70adab-6003-4b9b-9a0e-70d74d6bf707": {"definition": "A software-based collection or playlist of tracks in DJ software (for example, Serato's 'crates'), functioning as the digital equivalent of a physical record crate; DJs use crates and nested subcrates to group and quickly access tracks during preparation and performance.", "plain_english": "A digital crate is a folder of songs inside DJ software. It works like a box of records, but on a computer. DJs use it to group tracks and find them fast.", "purpose_function": "It lets a DJ organize a large music library into named groups, so the right tracks are easy to find quickly while performing.", "practical_application": "Before a gig, a DJ sorts tracks into digital crates by genre, energy, or set, then pulls from them live on the laptop or controller.", "category": "Music Library", "related_terms": ["Digging", "Digging in the crates", "Cue point", "Record pool", "DJ (Disc Jockey)"], "common_mistakes": ["Confusing a digital crate with the actual audio files, when it only references tracks stored elsewhere", "Assuming a track can live in only one crate, when the same track can sit in many crates", "Not backing up crate data, so the organization is lost if the library file is corrupted"], "scenario_contexts": ["A Serato DJ building digital crates by genre before a wedding set", "Organizing new downloads into digital crates each week", "Nesting subcrates inside a parent crate to sort a large collection"]}}$ape$::jsonb)) d WHERE g.id=d.id;
UPDATE glossary g SET definition = CASE WHEN d.p ? 'definition' THEN d.p->>'definition' ELSE g.definition END, plain_english = CASE WHEN d.p ? 'plain_english' THEN d.p->>'plain_english' ELSE g.plain_english END, purpose_function = CASE WHEN d.p ? 'purpose_function' THEN d.p->>'purpose_function' ELSE g.purpose_function END, practical_application = CASE WHEN d.p ? 'practical_application' THEN d.p->>'practical_application' ELSE g.practical_application END, category = CASE WHEN d.p ? 'category' THEN d.p->>'category' ELSE g.category END, related_terms = CASE WHEN d.p ? 'related_terms' THEN ARRAY(SELECT jsonb_array_elements_text(d.p->'related_terms')) ELSE g.related_terms END, common_mistakes = CASE WHEN d.p ? 'common_mistakes' THEN ARRAY(SELECT jsonb_array_elements_text(d.p->'common_mistakes')) ELSE g.common_mistakes END, scenario_contexts = CASE WHEN d.p ? 'scenario_contexts' THEN ARRAY(SELECT jsonb_array_elements_text(d.p->'scenario_contexts')) ELSE g.scenario_contexts END FROM (SELECT key::uuid AS id, value AS p FROM jsonb_each($ape${"8d561c7d-d7f0-4c12-ab5f-5178fef2394c": {"definition": "A person who selects and plays recorded music for an audience, typically using turntables, media players, or DJ software with a mixer to cue, beatmatch, blend, and manipulate tracks in a continuous program for clubs, radio, events, or broadcast.", "plain_english": "A DJ, short for disc jockey, is someone who picks and plays recorded music for a crowd. They use special gear to blend one song into the next smoothly.", "purpose_function": "A DJ curates and mixes music to shape the mood and energy of an event, keeping a seamless flow of tracks for dancers or listeners.", "practical_application": "A club DJ reads the crowd, selects the next track, cues and beatmatches it in headphones, then blends it in over the current song.", "category": "DJ Role", "related_terms": ["Beatmatching", "Cueing", "Mixing", "Digging", "Crossfader"], "common_mistakes": ["Thinking a DJ only presses play, rather than selecting, cueing, beatmatching, and blending tracks", "Confusing a DJ, who plays and mixes recorded music, with a music producer, who creates tracks in the studio", "Assuming DJing requires vinyl, when DJs also use media players and software"], "scenario_contexts": ["A club DJ playing a continuous mix through the night", "A radio DJ introducing and playing tracks on air", "A mobile DJ providing music for a wedding reception"]}, "56c92371-040d-4dc2-b164-9b7bb7403267": {"definition": "The first beat of a bar (measure) and the strongest metrical accent within it; in conducting it corresponds to the downward stroke of the conductor's hand. In DJ practice the downbeat is the anchor on which phrases begin, so tracks are cued and mixed so their downbeats align.", "plain_english": "The downbeat is the first, strongest beat of each bar of music. It is the beat you most want to tap your foot or nod on. DJs start and line up tracks on the downbeat.", "purpose_function": "It marks where each musical bar begins, giving music its sense of pulse and structure, and DJs use it as the reference point for starting and aligning tracks.", "practical_application": "A DJ finds the downbeat of the incoming track and releases or cues it so its first beat lands on the downbeat of the track already playing.", "category": "Rhythm & Timing", "related_terms": ["Beat", "Bar (measure)", "Phrasing", "Beatmatching", "Cue point", "Upbeat"], "common_mistakes": ["Confusing the downbeat with any strong beat, when it is specifically the first beat of the bar", "Mixing so the incoming track's downbeat lands off the playing track's downbeat, so the phrases clash", "Assuming the loudest sound is always the downbeat, when accents can fall on other beats"], "scenario_contexts": ["Cueing a track so its downbeat drops on the first beat of a new phrase", "Counting bars from the downbeat to plan where a transition will start", "Aligning two tracks' downbeats while beatmatching"]}, "e12ef13f-025d-47f1-a1f7-fbda3ccb0eae": {"definition": "In electronic dance music, the drop is the point where a track releases built-up tension into its main groove, typically after a breakdown and build-up, as the full rhythm section and bass re-enter at peak energy. It is the structural climax around which the arrangement, and often the DJ's transitions and effects, are organised.", "plain_english": "The drop is the big moment in a dance track. After the music builds up and thins out, the full beat and bass slam back in. It is the part the crowd waits for on the dancefloor.", "purpose_function": "It provides the main release of energy in a dance track, giving the arrangement a clear peak that both DJs and dancers anchor to.", "practical_application": "A DJ times a transition or an effect so the incoming track's drop lands on a strong point, maximising the energy hit for the crowd.", "category": "Track Structure", "related_terms": ["Breakdown", "Build-up", "Phrasing", "Downbeat", "Energy mixing", "Transition"], "common_mistakes": ["Confusing the drop with the intro, when the drop is the main release after a build-up", "Mixing out of a track just before its drop, killing the energy the crowd is expecting", "Assuming every track has one obvious drop, when some have several and some have none"], "scenario_contexts": ["Bringing in a new track so its drop lands cleanly after a build-up", "Using an echo or filter sweep to lead into a drop", "Reading the crowd's reaction to a big drop to guide the next track choice"]}, "81404504-0355-4ffc-a5b5-5944a81743d4": {"definition": "A dub version is an alternative mix of a track, rooted in Jamaican dub reggae, in which the vocals are largely removed or used sparingly while the rhythm section (drums and bass) is foregrounded and treated with effects such as echo and reverb. In dance and club music the term also denotes a stripped-down, largely instrumental 'dub mix' made to be more DJ-friendly for mixing.", "plain_english": "A dub version is a remix that strips out most of the singing. It puts the drums and bass up front and adds effects like echo. This idea started in Jamaican reggae and gives DJs a track that is easy to mix.", "purpose_function": "It provides a mostly instrumental, rhythm-focused version of a track that is easier to blend and layer than the full vocal mix.", "practical_application": "A DJ reaches for the dub version when they want long, vocal-free sections to mix over, or a bed to layer another track's vocal on top of.", "category": "Track Version", "related_terms": ["Instrumental", "Remix", "Acapella", "Extended mix", "Version"], "common_mistakes": ["Thinking a dub version is just the plain instrumental, when it is a distinct, effect-treated mix", "Confusing 'dub' the mix style with 'to dub' meaning to copy a recording", "Assuming a dub version has no vocals at all, when it often keeps fragments treated with effects"], "scenario_contexts": ["Playing the dub version to get more instrumental space for a long blend", "Layering an acapella from one track over a dub version of another", "Choosing the dub mix on a 12-inch single for club play"]}, "fa8860be-ef4b-4658-b888-36b844f3da72": {"definition": "A transition and outro technique in which the DJ applies an echo (delay) effect with feedback to the outgoing track and then cuts or fades the source, so the sound tails away as a series of decaying repeats rather than stopping abruptly. It is commonly performed with a mixer's or software's beat-synced echo effect.", "plain_english": "Echoing out means ending a track by switching on an echo effect. The DJ then cuts the track, so the sound keeps repeating and fading. It smooths the exit instead of a sudden stop.", "purpose_function": "It lets a DJ end a track or bridge into the next one smoothly, using the fading repeats to fill the gap and hold energy during the change.", "practical_application": "A DJ engages a beat-synced echo on the last phrase, pulls down the channel fader, and lets the repeats decay while the next track comes in.", "category": "FX Technique", "related_terms": ["Echo", "Delay", "Beat FX", "Transition", "Feedback", "Filter"], "common_mistakes": ["Setting the feedback so high that the repeats build into runaway noise", "Leaving the source track playing, so the echo muddies the mix instead of tailing out", "Confusing echo with reverb, which adds ambience rather than distinct repeats"], "scenario_contexts": ["Echoing out the last bars of a track to bridge into the next one", "Using an echo tail to cover a quick record swap or headphone cue", "Ending a set by echoing the final track out into silence"]}, "4b85b271-94f9-466a-ab3f-942fe86d7f9e": {"definition": "An emergency track is a reliable, crowd-pleasing record a DJ keeps ready to deploy when a set is faltering, for example to rescue a thinning dancefloor or to cover a technical problem or an awkward transition. It is chosen for its dependable floor-filling effect rather than for novelty or personal taste.", "plain_english": "An emergency track is a safe, crowd-pleasing song a DJ keeps ready. They play it if the dancefloor starts to empty or something goes wrong. It is like a backup plan that almost always works.", "purpose_function": "It gives a DJ a dependable fallback to win the crowd back or fill a gap when a set loses momentum or a problem interrupts the flow.", "practical_application": "When the floor thins out or a mix goes wrong, a DJ drops a known emergency track to rebuild energy and buy time to recover.", "category": "Set Programming", "related_terms": ["Set programming", "Reading the crowd", "Floor-filler", "Crate", "Transition"], "common_mistakes": ["Relying on emergency tracks so often that the whole set becomes predictable", "Choosing personal favourites rather than proven floor-fillers as emergency tracks", "Not having emergency tracks cued and ready when they are actually needed"], "scenario_contexts": ["Dropping an emergency track when the dancefloor starts to empty", "Reaching for a safe, familiar track to cover a technical fault mid-set", "Keeping a folder of emergency tracks flagged for quick access"]}, "0be82ab0-9528-4169-81f4-17017639d815": {"definition": "Energy mixing is the practice of selecting and sequencing tracks according to their perceived energy or intensity, so that a set builds, sustains, and releases the dancefloor's momentum in a deliberate arc. Track energy is judged from elements such as tempo, rhythmic density, bass weight, and arrangement, sometimes aided by software energy-level ratings.", "plain_english": "Energy mixing means choosing tracks by how intense they feel. The DJ builds the set up, holds it, then eases it down on purpose. It is about steering the crowd's energy, not just matching beats.", "purpose_function": "It lets a DJ shape the emotional arc of a set, controlling when the crowd is lifted, held, or given a rest, rather than only matching tempo and key.", "practical_application": "A DJ orders tracks so energy rises toward a peak, picking a higher- or lower-energy record next depending on how the floor responds.", "category": "Set Programming", "related_terms": ["Set programming", "Harmonic mixing", "Reading the crowd", "Phrasing", "Drop"], "common_mistakes": ["Treating energy as tempo alone, when arrangement and bass weight also drive it", "Pushing the energy up too fast, leaving nowhere to build to later in the set", "Ignoring the crowd's response and following a fixed plan regardless"], "scenario_contexts": ["Building a set's energy gradually toward a peak-time climax", "Dropping the energy briefly to give dancers a breather before lifting it again", "Using software energy ratings to help order a playlist"]}, "bace1223-2239-44af-ab98-2bf20021aff5": {"definition": "EQ mixing is a transition technique in which the DJ uses the mixer's channel equaliser (typically separate low, mid, and high bands, or full-kill isolators) to blend two playing tracks by adjusting their frequency content, most commonly by cutting the bass on one track while the other's bass is brought in. This keeps only one strong low-frequency source at a time, preventing clashing kick drums and basslines from summing and overloading the mix.", "plain_english": "EQ mixing means blending two tracks using the bass, mid, and treble knobs. The DJ usually turns the bass down on one track while raising it on the other. This stops two heavy basslines from clashing into a muddy mess.", "purpose_function": "It lets a DJ overlap two tracks cleanly by keeping only one dominant bass source at a time, avoiding the muddy, distorted sound of clashing low frequencies.", "practical_application": "During a blend the DJ cuts the low EQ on the incoming track, then swaps the bass over from the outgoing track at the right moment.", "category": "Mixing Technique", "related_terms": ["Equaliser", "Isolator", "Beatmatching", "Transition", "Frequency clash"], "common_mistakes": ["Leaving both tracks' bass up, so the kick drums and basslines clash and distort", "Boosting EQ bands instead of cutting them, which can overload the channel", "Swapping the bass over at the wrong point, breaking the groove of the mix"], "scenario_contexts": ["Cutting the incoming track's bass, then swapping it in during a blend", "Using EQ to remove a clashing element while two tracks overlap", "Isolating a drum or vocal section by cutting the other EQ bands"]}, "c39cd575-6c6c-40a2-9281-030a0a29ebdd": {"definition": "In DJ and record culture, a track that only one DJ (or very few) can play, because it is unreleased, a custom edit, a promo, or a one-off dubplate cut. Playing exclusives gives a DJ a unique sound and a competitive edge that rivals cannot copy.", "plain_english": "An exclusive is a track only you can play. It might be unreleased, a special edit, or a one-off pressing. Because no other DJ has it, your set sounds unique. It gives you an edge over the competition.", "purpose_function": "It lets a DJ stand out by playing music no one else has, building a signature sound and reputation. Historically it drove sound-system and hip-hop rivalries, where a secret record could win a crowd.", "practical_application": "A DJ sources exclusives through promos, personal edits, or dubplates, then guards their identity so rivals cannot find and copy the same track.", "category": "Track Selection", "related_terms": ["Dubplate", "Edit", "Flip", "Floor filler", "Promo", "Track selection"], "common_mistakes": ["Thinking any new or rare track counts as an exclusive; a true exclusive is one others genuinely cannot get", "Revealing an exclusive's identity or source, letting rivals obtain and play the same track", "Relying on exclusives alone instead of skillful mixing and reading the crowd"], "scenario_contexts": ["Cutting a one-off dubplate of an unreleased track to debut at a big event", "Covering the label on a record so other DJs cannot identify an exclusive", "Playing a personal edit no other DJ has to make a set stand out"]}, "01e9b5b3-1da5-4939-bc85-ac750501af8e": {"definition": "A performance move in which a DJ builds tension toward an expected drop, then withholds or replaces it, cutting to silence, a breakdown, or an unexpected section instead of the anticipated impact, before eventually delivering the real drop. It deliberately plays with the crowd's expectations for dramatic effect.", "plain_english": "A fake drop teases the crowd. The DJ builds up like a big drop is coming. Then, at the last moment, they cut it away or change it. The real drop lands later, so it hits even harder.", "purpose_function": "It manipulates crowd anticipation for dramatic effect, heightening the impact of the eventual real drop and keeping dancers surprised and engaged.", "practical_application": "A DJ cues a buildup, then mutes or swaps the beat right where the drop is expected, before triggering the true drop moments later.", "category": "Performance Technique", "related_terms": ["Fake out", "Drop", "Buildup", "Breakdown", "Filter mix", "Read the crowd"], "common_mistakes": ["Overusing fake drops, so the crowd stops trusting the buildups and loses energy", "Mistiming the fake, so it feels like a mistake rather than a deliberate tease", "Never delivering a satisfying real drop after the fake, leaving the floor deflated"], "scenario_contexts": ["Teasing a well-known drop during a peak-time set to heighten anticipation", "Cutting to silence at the expected drop, then dropping the beat a bar later", "Building tension then switching to a breakdown to surprise the crowd"]}, "1429305d-d238-4988-a3c4-afd93057db94": {"definition": "A performance tactic in which a DJ deliberately misleads the crowd's expectations, making them anticipate one thing, such as a drop, a familiar hook, or a mix into a new track, and then withholding or redirecting it for surprise or dramatic effect.", "plain_english": "A fake out tricks the crowd on purpose. You make them expect a certain moment, like a big drop. Then you hold it back or go somewhere else. The surprise keeps people excited and guessing.", "purpose_function": "It builds excitement and surprise by toying with listener expectation, keeping a set unpredictable and the crowd emotionally engaged.", "practical_application": "A DJ teases a recognizable buildup or intro, then pulls it back or switches tracks, using the crowd's reaction to time the real payoff.", "category": "Performance Technique", "related_terms": ["Fake drop", "Read the crowd", "Buildup", "Drop", "Floor filler", "Filter mix"], "common_mistakes": ["Confusing a fake out with a mixing mistake; a fake out is intentional and well-timed", "Faking out too often, so the crowd stops reacting to buildups", "Failing to follow through with a real payoff after the fake"], "scenario_contexts": ["Teasing the intro of a huge track, then pulling it out to build anticipation", "Making the crowd expect a drop, then extending the buildup for tension", "Cutting a familiar hook short to surprise the dancefloor"]}, "b3dbc222-ed50-41bb-8295-b09675711b04": {"definition": "A DJ set performed at a music festival, typically shorter and higher in energy than a club set, programmed with big, recognizable, high-impact tracks to suit a large audience, a large sound system, and a tight time slot. Festival sets are often more prepared and lean on peak-energy moments rather than a long, gradual build.", "plain_english": "A festival set is a DJ's performance at a festival. It is usually short and packed with big, exciting tracks. The crowd is huge, so the DJ aims for constant high energy. There is little time for a slow build.", "purpose_function": "It maximizes impact for a large festival crowd in a limited slot, favoring immediate energy and well-known tracks over the gradual arc of a longer club set.", "practical_application": "A DJ preparing a festival set curates big-room, crowd-familiar tracks and key moments in advance to fit a short, high-energy slot on a large system.", "category": "Set Programming", "related_terms": ["Peak-time set", "Warm-up set", "Floor filler", "Momentum", "Read the crowd", "Set programming"], "common_mistakes": ["Programming a festival set like a long club set, wasting a short slot on a slow build", "Ignoring the large sound system and crowd, playing subtle tracks that do not translate", "Running over the strict time slot and cutting into the next act"], "scenario_contexts": ["Preparing a one-hour main-stage slot packed with high-energy tracks", "Playing to tens of thousands on a festival's large sound system", "Programming big, recognizable tracks to reach a broad festival crowd"]}, "67242bd9-eed0-4d09-8515-e4369a2ac2d5": {"definition": "A mixing and transition technique in which a DJ uses a high-pass or low-pass filter on one or both channels to blend tracks, for example filtering out the bass of an incoming track and gradually opening the filter as the outgoing track is removed. It uses the filter, often a mixer's dedicated FILTER or Sound Color knob, to smooth the transition and avoid clashing frequencies.", "plain_english": "A filter mix blends two songs using a filter knob. You can cut the low end of the new song at first. Then you slowly open the filter as the old song fades out. This makes the change smooth and avoids muddy, clashing bass.", "purpose_function": "It lets a DJ transition between tracks without two basslines clashing, using frequency filtering to remove or introduce parts of a track smoothly rather than relying on volume alone.", "practical_application": "Using a mixer's filter knob, a DJ high-passes an incoming track to hide its bass, then opens the filter while cutting or low-passing the outgoing track to complete the blend.", "category": "Mixing Technique", "related_terms": ["Filter", "High-pass filter", "Low-pass filter", "EQ mixing", "Crossfader", "Beatmatching"], "common_mistakes": ["Leaving both tracks' basslines open, so the low end clashes and sounds muddy", "Sweeping the filter too fast, making the transition sound abrupt or unnatural", "Confusing the filter with the EQ; a filter sweeps a cutoff while EQ boosts or cuts fixed bands"], "scenario_contexts": ["Filtering out the bass of an incoming track to blend it under a playing track", "Sweeping a low-pass filter to create tension before a drop", "Using a mixer's color FILTER knob to transition between two tracks"]}, "7196fb44-218d-4147-9b8b-18cffcb5a7f0": {"definition": "A track known to reliably draw people onto the dancefloor and keep them dancing, valued by DJs as a dependable crowd-pleaser across many audiences. The term describes a song's proven effect on a crowd rather than any specific genre or tempo.", "plain_english": "A floor filler is a track that always fills the dancefloor. As soon as it plays, people rush to dance. DJs trust these songs to get a crowd moving. They are reliable crowd-pleasers.", "purpose_function": "It gives a DJ a dependable tool to build or rescue crowd energy, since a proven floor filler is likely to get people dancing regardless of the specific room.", "practical_application": "A DJ keeps a stock of floor fillers to drop when energy dips or to guarantee a packed floor at a key moment, such as a wedding or a peak-time slot.", "category": "Track Selection", "related_terms": ["Peak-time set", "Read the crowd", "Momentum", "Festival set", "Exclusive", "Set programming"], "common_mistakes": ["Playing every floor filler too early, leaving nothing to lift the crowd later", "Assuming a personal favourite is a floor filler when the crowd does not respond to it", "Relying only on floor fillers, so the set feels obvious and lacks variety"], "scenario_contexts": ["Dropping a guaranteed floor filler to rescue a fading dancefloor", "A wedding DJ keeping classic floor fillers for a mixed-age crowd", "Saving a big floor filler for the peak of a set"]}, "6aa3e4eb-57a1-4ee7-b0c8-d8690afff5aa": {"definition": "A DJ booked to play a one-off or invited set at a venue, event, or radio show, as distinct from the venue's resident DJ who plays there regularly. A guest slot is typically a featured or headline appearance rather than an ongoing residency.", "plain_english": "A guest DJ is invited to play at a club or show just for that night. They are not the regular DJ who works there. It is like a guest star who drops in for one special appearance.", "purpose_function": "Booking a guest DJ brings a fresh name, sound, or draw to an event, letting promoters attract crowds and offer variety beyond the resident roster.", "practical_application": "A promoter books a touring guest DJ to headline a night, while the resident warms up the room and hands over at the guest's start time.", "category": "DJ Roles", "related_terms": ["Resident DJ", "Warm-up set", "Peak-time set", "Read the crowd", "Headline slot"], "common_mistakes": ["Assuming a guest DJ knows the venue's crowd as well as the resident does", "Thinking guest and resident DJs are the same role, when residents play regularly and guests are invited", "Expecting a guest to also handle warm-up duties, which usually fall to the resident"], "scenario_contexts": ["A touring artist booked as the guest headliner for a club night", "A resident warming up before handing over to a guest DJ", "A radio show inviting a guest DJ to record a one-off mix"]}, "ca4707c7-1a99-4e74-8a3c-0fa44d776298": {"definition": "A transition in which the outgoing track is stopped abruptly and the incoming track begins immediately at full level, with no crossfade, blend, or overlap between them. It is the opposite of a smooth blended mix, giving a sharp, instant switch from one track to the next.", "plain_english": "A hard cut switches songs instantly with no fade. One track stops and the next starts at full volume right away. It is like flipping a light switch instead of slowly dimming it.", "purpose_function": "It provides a sudden, deliberate change of track or mood, useful when two songs will not blend or when a DJ wants a sharp, dramatic switch.", "practical_application": "A DJ hard-cuts on the downbeat between two tracks that clash in key or feel, dropping the new track in cold instead of mixing the two together.", "category": "Mixing Technique", "related_terms": ["Crossfade", "Beatmatching", "Blend", "Phrasing", "Transition"], "common_mistakes": ["Cutting off-beat, so the switch sounds jarring instead of intentional", "Assuming every transition needs a blend, when a hard cut is sometimes the better choice", "Confusing a hard cut with a fast crossfade; a hard cut has no overlap at all"], "scenario_contexts": ["Hard-cutting between two tracks in different keys to avoid a clash", "Slamming straight into a big track for dramatic effect", "Cutting sharply between songs in a genre like hip-hop where long blends are less common"]}, "02c0b25b-0a7a-4cf1-bbdf-18bca82146b3": {"definition": "The practice of selecting and mixing tracks whose musical keys are compatible, such as the same key, the relative major or minor, or an adjacent key on the circle of fifths, so their melodic and harmonic content blends without dissonance. DJ software analyses and labels each track's key to help identify compatible combinations.", "plain_english": "Harmonic mixing means blending songs that are in matching musical keys. Tracks in keys that fit together sound smooth when layered. Tracks in clashing keys sound sour, like two singers in different keys. DJ software tags each song's key to help you match them.", "purpose_function": "It helps a DJ avoid the clashing, out-of-tune sound that occurs when two tracks in incompatible keys overlap, so long blends and layered mixes stay musical.", "practical_application": "A DJ reads the key value shown by rekordbox or Serato and chooses a next track in a compatible key before mixing the two together.", "category": "Mixing Technique", "related_terms": ["Key detection", "Beatmatching", "Blend", "Phrasing", "Circle of fifths"], "common_mistakes": ["Trusting software key detection blindly, when analysis can mislabel a track's key", "Thinking only identical keys work, when relative and adjacent keys are also compatible", "Focusing on key while forgetting that tempo still has to match for a clean blend"], "scenario_contexts": ["Choosing the next track by its detected key code during a long blend", "Building a set that moves through related keys to keep it smooth", "Using rekordbox or Serato key analysis to sort a library by key"]}, "dbceb17f-fa86-4c6a-bcb4-bc1e72d72d25": {"definition": "The catchy, memorable musical or lyrical phrase of a song, designed to catch the listener's ear and be easily remembered, often repeated and forming the most recognisable part of the record. Hooks can be melodic, rhythmic, or verbal, and frequently coincide with the chorus.", "plain_english": "A hook is the catchy part of a song you remember and hum later. It grabs your attention and sticks in your head. It is often the chorus or a repeated line. DJs use hooks because crowds know them right away.", "purpose_function": "The hook makes a song memorable and commercially appealing, and it gives a DJ an instantly recognisable moment that crowds respond to.", "practical_application": "A DJ times a mix or drop so the incoming track's hook lands when the crowd is ready to recognise and react to it.", "category": "Song Structure", "related_terms": ["Intro", "Chorus", "Drop", "Phrasing", "Breakdown"], "common_mistakes": ["Assuming the hook is always the chorus, when it can be a riff, beat, or single line", "Confusing the hook with the whole song's melody", "Overplaying a track's hook so it loses its impact"], "scenario_contexts": ["Dropping a new track right as its vocal hook begins", "Choosing tracks with strong hooks to keep a crowd engaged", "Looping a hook to extend a memorable moment"]}, "afe7e945-40ad-4751-9406-75824e059d53": {"definition": "A performer, rooted in hip-hop, who supports the lead rapper, MC, or DJ by energising the audience through call-and-response, ad-libs, echoed phrases, and backing shouts to raise the crowd's excitement. The role is a live-performance support position rather than the lead vocal.", "plain_english": "A hype man is a performer whose job is to fire up the crowd. They shout, echo lines, and lead call-and-response to raise the energy. They back up the main act instead of being the star. Think of a cheerleader with a microphone.", "purpose_function": "The hype man keeps a live crowd's energy high and fills gaps in the lead performer's delivery, strengthening the connection between the act and the audience.", "practical_application": "At a live show, a hype man works the mic beside the main act, echoing key lines and prompting the crowd to shout back.", "category": "DJ Roles", "related_terms": ["MC", "Guest DJ", "Call-and-response", "Read the crowd", "Turntablism"], "common_mistakes": ["Confusing the hype man with the lead MC; the hype man supports rather than leads", "Thinking the role is just shouting, when timing and crowd reading matter", "Assuming a hype man needs no rehearsal, when their cues are practised with the act"], "scenario_contexts": ["A hype man backing a rapper during a live festival set", "Leading crowd call-and-response while the DJ mixes", "Filling energy between verses at a club performance"]}, "a2a906d7-963e-42c6-af04-681f553d9d7e": {"definition": "The opening section of a musical track that precedes the main body, often with reduced or building instrumentation and no lead vocal, used to establish tempo and groove. In DJ practice the intro is a primary point for mixing a track in, and DJ software labels it as a distinct phrase.", "plain_english": "The intro is the beginning part of a song before it fully kicks in. It often has just drums or a simple build, and no singing yet. DJs mix a new track in during its intro so the change sounds smooth.", "purpose_function": "The intro gives a track a lead-in that establishes its beat and mood, and it gives a DJ a beat-driven, vocal-free section over which to blend the previous track out.", "practical_application": "A DJ starts the next track during its intro, beatmatching and blending it under the current track before the vocals or main drop arrive.", "category": "Song Structure", "related_terms": ["Outro", "Hook", "Phrasing", "Beatmatching", "Breakdown"], "common_mistakes": ["Mixing in over the intro too late, so vocals from both tracks clash", "Assuming every track has a long, beatmatching-friendly intro", "Confusing the intro with the first drop or chorus"], "scenario_contexts": ["Blending a new track in during its beat-only intro", "Using rekordbox phrase analysis to find a track's intro", "Cutting a long intro short when the crowd wants the main track quickly"]}, "267cb0a2-cdfe-4e96-8119-9e0136d50e6d": {"definition": "A guiding principle of DJ performance describing the core objective of sustaining the crowd's energy and keeping the dancefloor occupied, achieved through track selection, pacing, and smooth transitions that avoid the dips that would clear the floor. It frames programming decisions around maintaining continuous momentum.", "plain_english": "Keep them dancing sums up a DJ's main goal: do not let the floor empty. The DJ picks songs and mixes them so people never stop moving. One bad track can send dancers to the bar. Good pacing keeps the energy going all night.", "purpose_function": "It reminds a DJ that the job is to serve the dancefloor, guiding selection and mixing choices toward sustained energy rather than personal taste alone.", "practical_application": "A DJ watches the floor and sequences tracks to hold energy, avoiding an abrupt tempo or mood drop that would make dancers stop.", "category": "Set Programming", "related_terms": ["Read the crowd", "Momentum", "Peak-time set", "Warm-up set", "Phrasing"], "common_mistakes": ["Playing personal favourites that clear the floor instead of tracks the crowd wants", "Making a sudden tempo or genre jump that breaks the momentum", "Ignoring the dancefloor and following a fixed playlist regardless of reaction"], "scenario_contexts": ["Choosing the next track to keep a full floor moving", "Recovering energy after a track thins the crowd", "Pacing a set so dancers stay engaged from open to close"]}, "6a44601f-8e1c-42aa-b7cf-16051091e011": {"definition": "The harsh, dissonant sound that results when two tracks played together are in musically incompatible keys, so their melodic and harmonic content conflicts instead of blending. Key clash is the discord that harmonic (key-based) mixing seeks to avoid by pairing tracks whose keys are identical or closely related on the circle of fifths.", "plain_english": "Every song has a musical key. If you blend two songs whose keys do not match, the notes fight each other. This sour, clashing sound is a key clash. DJs pick songs in matching keys to avoid it.", "purpose_function": "The concept warns DJs that beat-matched tracks can still sound wrong if their keys conflict, which is why key detection and harmonic mixing tools exist in modern DJ software.", "practical_application": "A DJ reads each track's detected key tag in software such as rekordbox or Serato and avoids overlapping tracks whose keys would clash during a blend.", "category": "Harmonic Mixing", "related_terms": ["Harmonic mixing", "Key lock", "Key shift", "Key detection", "Camelot wheel", "Beatmatching"], "common_mistakes": ["Assuming two tracks at the same tempo will always mix well, while ignoring their keys", "Trusting automatic key tags blindly without listening, since key detection can misread a track", "Thinking key clash only matters in long blends, when even a brief vocal or melodic overlap can clash"], "scenario_contexts": ["A long blend where two vocal tracks overlap and sound out of tune together", "Building a harmonically mixed set using key tags to avoid clashes", "Diagnosing why a perfectly beat-matched transition still sounds wrong to the crowd"]}, "40ce250a-740a-4204-b9fe-7ccf83b13e40": {"definition": "A playback function, marketed as Master Tempo on Pioneer DJ hardware, that holds a track's musical pitch (key) constant while its tempo is changed with the pitch fader. It relies on time-stretching so that speeding up or slowing down a track does not raise or lower its pitch as it would on a purely varispeed turntable or CD player.", "plain_english": "Speeding a song up also makes it sound higher, like a chipmunk. Slowing it down makes it lower. Key lock stops that. It keeps the pitch the same even when you change the speed. Pioneer calls this Master Tempo.", "purpose_function": "It lets a DJ match two tracks' tempos with the pitch fader without their pitch drifting out of tune, protecting vocals and melodies during large tempo changes.", "practical_application": "A DJ engages Key Lock (or Master Tempo) before making a big tempo adjustment so the track stays in tune while it is beat-matched.", "category": "Tempo & Pitch Control", "related_terms": ["Master Tempo", "Key shift", "Pitch fader", "Time-stretching", "Beatmatching", "Varispeed"], "common_mistakes": ["Believing key lock changes a track's key, when it actually keeps the key fixed while the tempo changes", "Leaving key lock on for extreme tempo changes, where time-stretching artifacts make the audio sound grainy", "Confusing key lock with sync, which matches tempo automatically rather than holding pitch steady"], "scenario_contexts": ["Slowing a track by several BPM to beat-match without the vocal dropping in pitch", "Switching key lock off during scratching so the classic pitch-bend sound returns", "Blending two tracks across a large tempo gap while keeping both in tune"]}, "04fb5b0b-42e3-44f6-93b7-7165fa38c4f0": {"definition": "A function that transposes a track's musical key up or down, usually in semitone steps, independently of its tempo. Unlike key lock, which preserves the original key during tempo changes, key shift deliberately changes the pitch so a track can be moved into a key that matches another track for harmonic mixing.", "plain_english": "Key shift moves a whole song's pitch up or down in steps. It does this without changing the speed. DJs use it to nudge one song into the same key as another. Then the two songs blend without clashing.", "purpose_function": "It gives a DJ a way to correct a key clash on the fly by tuning one track to match another, widening the pool of tracks that can be harmonically mixed together.", "practical_application": "A DJ raises an incoming track by one or two semitones in Serato or Traktor so its key matches the track already playing.", "category": "Tempo & Pitch Control", "related_terms": ["Key lock", "Key clash", "Harmonic mixing", "Key detection", "Semitone", "Pitch fader"], "common_mistakes": ["Confusing key shift, which changes the key, with key lock, which keeps the key", "Shifting by too many semitones, which makes vocals sound obviously processed and unnatural", "Forgetting that key shift does not change tempo, so beatmatching is still required"], "scenario_contexts": ["Nudging an incoming track up a semitone to match the current track's key", "Correcting a track whose key sits one step away from the rest of a harmonic set", "Transposing a familiar track to build tension or freshen it during a set"]}, "b83e9113-0c9a-419b-8c2b-3b44c90d5efb": {"definition": "A DJ mixing move in which a track's low-frequency (bass) band is fully cut using the mixer's low EQ or isolator, reducing the bass to silence or near-silence. It is commonly used during a transition so the bass of only one track plays at a time, avoiding a muddy, overloaded low end.", "plain_english": "Bass is the deep, low sound in a song. To kill the bass you turn the low EQ knob all the way down. This removes the deep boom from that track. DJs do this so two basslines do not clash and turn to mush.", "purpose_function": "It stops two overlapping basslines from stacking and overpowering the mix, giving the DJ clean control over which track owns the low end during a blend.", "practical_application": "During a transition a DJ kills the bass on the outgoing track and brings in the new track's bass, swapping the low end cleanly.", "category": "EQ Mixing", "related_terms": ["Kill the mids", "Kill the highs", "EQ", "Isolator", "Bassline swap", "Frequency mixing"], "common_mistakes": ["Thinking the low EQ only trims a little, when a kill-capable EQ or isolator cuts the band to near silence", "Killing the bass too late, so both basslines overlap and the mix turns muddy", "UNSAFE: cranking channel gains or the master to compensate after cutting bass, which can drive amplifiers and speakers into clipping and damage them"], "scenario_contexts": ["Swapping the bassline from the outgoing to the incoming track during a blend", "Cleaning up a muddy low end when two kick drums overlap", "Creating a breakdown by killing the bass, then dropping it back in on the beat"]}, "e909fbf1-c667-4d80-87d0-85d6f9cc0a6e": {"definition": "A DJ mixing move in which a track's high-frequency (treble) band is fully cut using the mixer's high EQ or isolator. Removing the highs takes out the track's brightness, such as cymbals, hi-hats, and 'air', which can soften a track or let two tracks blend without their top ends clashing.", "plain_english": "The highs are bright, crisp sounds like cymbals and hi-hats. To kill the highs you turn the high EQ knob all the way down. This makes the track sound dull and far away. DJs use it to blend tracks smoothly.", "purpose_function": "It lets a DJ remove clashing top-end detail from one track during a blend, or dull a track on purpose before opening its brightness back up for impact.", "practical_application": "A DJ kills the highs on an incoming track while its bass and mids sit underneath, then opens the highs back up as that track takes over.", "category": "EQ Mixing", "related_terms": ["Kill the bass", "Kill the mids", "EQ", "Isolator", "Filter", "Frequency mixing"], "common_mistakes": ["Confusing killing the highs with a low-pass filter, which sweeps the whole top down rather than cutting one fixed band", "Killing the highs and forgetting to reopen them, leaving the track sounding dull", "Assuming the high EQ only trims slightly, when a kill-capable EQ cuts the band almost completely"], "scenario_contexts": ["Blending two tracks whose hi-hats would otherwise clash", "Dulling a track before a filter sweep or drop for contrast", "Reducing harshness when two bright tracks overlap"]}, "6b10098c-2557-46f9-ad84-4b093da9e82e": {"definition": "A DJ mixing move in which a track's mid-frequency band is fully cut using the mixer's mid EQ or isolator. Because much of a track's vocals, melody, and body sit in the mids, killing them hollows out the sound and is often used to blend or swap vocal and melodic content between two tracks.", "plain_english": "The mids are the middle sounds, where most vocals and melodies live. To kill the mids you turn the mid EQ knob all the way down. This scoops out the voice and melody. DJs use it to swap vocals between two songs.", "purpose_function": "It lets a DJ remove one track's vocals and melodic body so a second track's mids come through cleanly, avoiding two competing vocals playing at once.", "practical_application": "A DJ kills the mids on the outgoing track to drop its vocal, letting the incoming track's vocal lead the blend.", "category": "EQ Mixing", "related_terms": ["Kill the bass", "Kill the highs", "EQ", "Isolator", "Acappella", "Frequency mixing"], "common_mistakes": ["Expecting a mid kill to remove only vocals, when it also thins the drums and instruments in that band", "Cutting the mids too hard for too long, leaving the mix hollow and weak", "Confusing a mid kill with a dedicated vocal isolator or stem control, which target the voice more precisely"], "scenario_contexts": ["Swapping a vocal from one track to another during a blend", "Thinning a track's body so another track's melody can sit on top", "Creating a hollow, scooped sound for a breakdown"]}, "c6da46bb-40d2-4d51-a43f-76af5160f445": {"definition": "DJ vernacular for a track that reliably excites a dancefloor: a dependable crowd-pleaser or floor-filler a DJ can count on to lift the energy of a set. Often shortened to a 'killer', such a track is kept in a DJ's crate as a trusted weapon for peak moments.", "plain_english": "A killer track is a song a DJ knows will get the crowd going. It works almost every time. DJs save these strong tracks for the busiest part of the night. They pull one out when the energy needs a lift.", "purpose_function": "Labelling certain records as 'killers' helps a DJ plan a set around dependable high-impact tracks, holding them back for peak-time when maximum energy is needed.", "practical_application": "A DJ drops a killer track at peak time when the floor needs a lift, trusting it to reignite the crowd.", "category": "Track Selection", "related_terms": ["Peak-time set", "Read the crowd", "Crate digging", "Set programming", "Warm-up set", "Anthem"], "common_mistakes": ["Playing all your killer tracks early, leaving nothing to lift the crowd at peak time", "Assuming a track that killed at one venue will work with every crowd or room", "Relying only on killers instead of building energy through programming and reading the room"], "scenario_contexts": ["Saving a proven crowd-pleaser for the peak of the night", "Rescuing a flagging dancefloor by dropping a dependable killer", "Building a peak-time set around a handful of killer tracks"]}, "154cbe03-b3ef-48b2-9811-bd469aac3ba0": {"definition": "DJ vernacular for giving a track room to develop rather than mixing out of it too quickly, letting it play long enough for the crowd to recognise, react to, and enjoy it before starting the next transition. It also describes resisting the urge to over-layer effects or overlapping tracks so a record's own dynamics can come through.", "plain_english": "To let it breathe means giving a song time to play. You do not rush to the next track. You let the crowd hear and enjoy it first. It also means not piling on too many effects at once.", "purpose_function": "It reminds DJs that constant, rushed mixing can bury great tracks, and that leaving space lets the music's energy and the crowd's response build naturally.", "practical_application": "Instead of mixing out after thirty seconds, a DJ lets a strong track play through its main section so the crowd can lock into it.", "category": "Mixing Technique", "related_terms": ["Set programming", "Read the crowd", "Transition", "Killer track", "Phrasing", "Mixing"], "common_mistakes": ["Mixing out of every track too fast, so no song gets time to connect with the crowd", "Layering too many effects at once instead of leaving space in the mix", "Thinking more frequent mixing always shows more skill, when restraint often reads better"], "scenario_contexts": ["Letting a peak-time anthem play through its chorus before mixing out", "Holding back effects so a track's own build can land with the crowd", "Giving a new release time to register with a crowd that has not heard it"]}, "4b3d4d9d-18dc-48e8-bd02-145d2d309ece": {"definition": "To fix two or more decks to the same tempo so they stay beat-matched, typically by engaging a mixer or software Sync (Beat Sync) function that ties the decks to a shared master tempo and beatgrid. Once locked, changing the master tempo moves all synced decks together, keeping them beat- and phase-aligned.", "plain_english": "Every song has a speed, called tempo, in beats per minute. To lock tempo you tie two songs to the same speed. Then they stay matched on their own. DJ software usually does this with a Sync button.", "purpose_function": "It keeps decks from drifting apart in tempo during a long blend, freeing the DJ to focus on EQ, effects, and track selection instead of constant manual pitch corrections.", "practical_application": "A DJ presses Sync (Beat Sync) to lock the incoming deck's tempo to the master so both stay matched throughout the transition.", "category": "Tempo & Pitch Control", "related_terms": ["Beat Sync", "Beatmatching", "Master Tempo", "Beatgrid", "BPM", "Pitch fader"], "common_mistakes": ["Relying on tempo lock without learning to beatmatch by ear, which leaves you stuck if sync fails or a beatgrid is wrong", "Assuming locked tempo also locks phrasing or key, when it only matches the beat", "Trusting sync on a track with an inaccurate beatgrid, which drifts out of time even when 'locked'"], "scenario_contexts": ["Engaging sync to hold two tracks at one tempo through a long blend", "Locking a whole set to a steady tempo for a seamless continuous mix", "Freeing a hand to work effects while the decks stay tempo-locked"]}, "baa9b633-e44c-4293-8b20-21e2fd51244e": {"definition": "A mixing technique in which two beatmatched tracks are blended together over an extended section, often many bars or several minutes, so the outgoing and incoming records overlap for a long time before the first is faded out. It contrasts with a quick cut or short blend, where the transition between tracks is brief.", "plain_english": "A long mix blends one track into the next slowly. Both songs play together for a long time before the first fades out. It is the opposite of a fast cut between tracks.", "purpose_function": "It creates a smooth, seamless transition and lets a DJ build energy gradually, keeping the dancefloor moving without an obvious break between records.", "practical_application": "A house or techno DJ beatmatches two tracks and rides both faders over many bars, layering the intro of the new track under the outgoing one.", "category": "Mixing Technique", "related_terms": ["Beatmatching", "Crossfader", "Blend", "Quick mix", "Phrasing", "EQ mixing"], "common_mistakes": ["Letting the two tracks drift out of time during the long overlap because the tempos were not properly matched", "Clashing vocals or basslines by overlapping tracks that do not work together for so long", "Thinking a longer mix is always better, when some tracks suit a quick cut instead"], "scenario_contexts": ["A techno DJ blending two tracks over 32 or 64 bars for a seamless transition", "A continuous radio mix show using long blends to keep energy flowing", "Layering the breakdown of one track under the build of another during an extended transition"]}, "10771cfc-e103-4c82-820c-3e40e009b676": {"definition": "A looping function that doubles the length of an active loop, so a loop set to a given number of beats becomes twice as long, for example 4 beats becoming 8 beats. On Pioneer DJ players this is the LOOP 2X control, and each press doubles the loop again.", "plain_english": "Loop doubling makes a playing loop twice as long. A loop of 4 beats becomes 8 beats. Press it again and the loop doubles once more.", "purpose_function": "It lets a DJ quickly change how much of the track repeats without setting new loop points, so the loop can cover a larger musical phrase.", "practical_application": "A DJ tightens a loop to build tension, then doubles it back out to a longer phrase before letting the track play on.", "category": "Looping", "related_terms": ["Loop halving", "Manual loop", "Auto loop", "Loop roll", "Beat loop", "Loop exit"], "common_mistakes": ["Confusing loop doubling (a longer loop) with loop halving (a shorter loop)", "Expecting doubling to change the tempo, when it only changes the loop length", "Doubling a loop that was not beat-accurate, so the longer loop drifts off the beat"], "scenario_contexts": ["Extending a 4-beat loop to 8 beats to loop a whole phrase", "Building a longer loop to buy time while selecting the next track", "Doubling a loop live on a CDJ using the LOOP 2X button"]}, "b1ea4c69-c33f-48d4-b6f7-23bc4acc2b1a": {"definition": "The action of cancelling loop playback so the track continues past the loop out point instead of jumping back to the loop in point. On Pioneer DJ players this is done with the RELOOP/EXIT control, and pressing it again after exiting returns to the stored loop (reloop).", "plain_english": "Loop exit turns off a playing loop. The track then keeps going past the end of the loop instead of repeating. It lets the song carry on normally.", "purpose_function": "It releases the deck from repeating a section so the track can move forward, which is essential for ending a loop cleanly during a mix.", "practical_application": "A DJ loops a track's intro to extend a mix, then hits loop exit on the beat so the track drops into its main section in time.", "category": "Looping", "related_terms": ["Reloop", "Manual loop", "Loop in", "Loop out", "Auto loop", "Loop roll"], "common_mistakes": ["Confusing loop exit (let the track continue) with reloop (jump back into the loop)", "Exiting a loop off-beat, so the track falls out of time with the other deck", "Forgetting the loop is still active and letting the section repeat too long"], "scenario_contexts": ["Exiting an intro loop exactly on the downbeat so the drop lands in time", "Ending a loop that was holding a breakdown before bringing in the next track", "Pressing RELOOP/EXIT on a CDJ to release loop playback"]}, "030a2e99-68b2-4ac9-b1a2-56d95a1c6575": {"definition": "A looping function that cuts the length of an active loop in half, so a loop set to a given number of beats becomes half as long, for example 4 beats becoming 2 beats. On Pioneer DJ players it is the LOOP 1/2X (loop cutter) control, and each press halves the loop again down to very short lengths.", "plain_english": "Loop halving makes a playing loop half as long. A loop of 4 beats becomes 2 beats. Press it again and the loop gets shorter still.", "purpose_function": "It lets a DJ shrink a loop quickly without setting new points, tightening the repeated section to build tension or create stutter effects.", "practical_application": "A DJ repeatedly halves a loop from 4 beats down to a fraction of a beat to build a rising, stuttering effect before a drop.", "category": "Looping", "related_terms": ["Loop doubling", "Manual loop", "Auto loop", "Loop roll", "Beat loop", "Loop exit"], "common_mistakes": ["Confusing loop halving (a shorter loop) with loop doubling (a longer loop)", "Halving so far that the loop becomes an unintended buzzing tone", "Assuming halving changes pitch or tempo, when it only changes loop length"], "scenario_contexts": ["Cutting a 4-beat loop down to build a stutter roll before a drop", "Tightening a loop to a single beat to hold a moment", "Using the LOOP 1/2X (loop cutter) button live on a CDJ"]}, "e9845615-029e-4b83-8f73-d80057446f15": {"definition": "A momentary loop effect in which a short loop plays only while a pad or button is held, and on release playback jumps to where it would have been had the loop not been triggered, as with slip mode. Short roll lengths create stutter effects while the track's underlying timeline keeps running.", "plain_english": "A loop roll repeats a short piece of the track while you hold a pad. When you let go, the track jumps to where it would be if you had not looped. Short rolls make a stutter sound.", "purpose_function": "It lets a DJ add rhythmic stutter and fill effects on the fly without losing the track's place, because playback catches back up to the timeline on release.", "practical_application": "A DJ holds a short loop roll over a snare to create a stutter fill, then releases it so the track continues in time.", "category": "Looping", "related_terms": ["Slip mode", "Beat loop", "Loop halving", "Manual loop", "Censor", "Performance pads"], "common_mistakes": ["Confusing a loop roll (momentary, returns to the timeline) with a normal loop (stays looping until you exit)", "Expecting the track to fall behind after a roll, when slip behaviour keeps it in time", "Rolling off-beat so the stutter clashes with the rhythm"], "scenario_contexts": ["Adding a stutter fill on the last bar before a drop", "Holding a short roll over a vocal to create a chopped effect", "Using Roll pad mode on a Serato or rekordbox controller"]}, "b07e1f20-a1e7-42b8-ad17-c048d61cbbc8": {"definition": "A DJ set of relaxed, downtempo music, such as lounge, chill-out, nu-jazz, or deep and ambient styles, played at lower energy and often lower tempo to suit a laid-back setting rather than a peak-time dancefloor. Mixing tends to favour smooth blends and mood over high-energy transitions.", "plain_english": "A lounge set is a relaxed DJ set of chilled, slower music. It is played to set a calm, laid-back mood. It suits a bar or early evening, not a packed dancefloor.", "purpose_function": "It provides a calm, atmospheric backdrop for a venue such as a lounge, bar, or restaurant, setting a mood rather than driving people to dance.", "practical_application": "A DJ opening a venue early plays a lounge set of downtempo tracks, blending smoothly at low volume before the night builds.", "category": "Set Type", "related_terms": ["Warm-up set", "Downtempo", "Long mix", "Beatmatching", "Programming", "Blend"], "common_mistakes": ["Playing peak-time, high-energy tracks that break the relaxed mood of a lounge set", "Mixing too aggressively when smooth, subtle blends suit the setting better", "Treating a lounge set as unimportant, when reading the room still matters"], "scenario_contexts": ["An early-evening set in a hotel bar or restaurant", "A chill-out room at a festival or club", "Background music for a lounge or private event"]}, "2e2d56f1-f7e5-4472-adab-2da1b0d684a4": {"definition": "The technique of matching the tempo and phase of two tracks by ear without using automatic sync. The DJ adjusts the tempo (pitch) fader until both tracks run at the same BPM, then nudges the jog wheel or platter (pitch bend) to align the beats so they play in time.", "plain_english": "Manual beatmatching means matching two songs by ear. You move the pitch slider until both tracks run at the same speed. Then you nudge the record so the beats line up, without pressing sync.", "purpose_function": "It lets a DJ blend two tracks seamlessly using their own ears and hands, the core skill behind beat-based DJing that works on any gear, even without sync.", "practical_application": "A DJ cues the next track in headphones, adjusts its pitch fader to match the playing track's tempo, and nudges the jog wheel until the kicks line up before bringing it in.", "category": "Beatmatching", "related_terms": ["Beatmatching", "Sync", "Pitch fader", "Pitch bend", "Cueing", "Phrasing"], "common_mistakes": ["Aligning the beats once but not correcting the tempo, so the tracks slowly drift apart", "Relying on the sync button and never learning to match by ear", "Confusing tempo matching (same BPM) with phase matching (beats aligned), when you need both"], "scenario_contexts": ["Beatmatching two tracks by ear on turntables or CDJs without sync", "Mixing on club gear where sync is unavailable or disabled", "A DJ course teaching students to match beats using pitch fader and jog wheel"]}, "51551266-afee-4d94-82fc-832a1b0dc61d": {"definition": "A loop created by manually setting the loop in point and loop out point in real time, rather than using a preset beat-length auto loop. The DJ presses Loop In to mark the start and Loop Out to mark the end, and the section between the two points then repeats; the points can usually be fine-tuned afterward.", "plain_english": "A manual loop is one you set by hand. You press a button to mark the start, then press again to mark the end. The part between the two points repeats over and over.", "purpose_function": "It lets a DJ loop any chosen section of a track, even one that is not an exact number of beats, giving precise control that preset auto loops cannot.", "practical_application": "A DJ presses Loop In at the start of a phrase and Loop Out at its end to repeat an intro, then fine-tunes the out point so the loop stays on the beat.", "category": "Looping", "related_terms": ["Auto loop", "Loop in", "Loop out", "Loop doubling", "Loop halving", "Loop exit"], "common_mistakes": ["Setting the loop out point slightly off-beat, so the loop stutters or drifts", "Confusing a manual loop (set by hand) with an auto loop (a preset beat length)", "Forgetting to exit the loop, leaving the section repeating too long"], "scenario_contexts": ["Looping an intro or breakdown that is not a neat number of beats", "Extending a short outro by setting a manual loop over the last phrase", "Marking loop in and loop out on a CDJ to repeat a section live"]}, "9dc6d127-7c8f-4c99-b808-d4e4aede7d60": {"definition": "A DJ-player feature (also called key lock) that holds a track's musical pitch constant while its tempo is changed with the tempo slider, so speeding a track up or slowing it down does not raise or lower its key. It uses time-stretching so beatmatching by tempo does not alter the perceived pitch.", "plain_english": "Master tempo lets a DJ change a song's speed without changing its pitch. Normally, speeding a track up makes it sound higher, like a chipmunk. This feature keeps the notes sounding the same while the beat gets faster or slower.", "purpose_function": "It exists so a DJ can match two tracks' tempos for beatmatching without detuning them, keeping both in their original key so the mix stays harmonically clean.", "practical_application": "A DJ turns on Master Tempo before making large tempo changes, so pushing a track several percent faster to match a beat does not shift its key or make vocals sound unnatural.", "category": "Tempo Control", "related_terms": ["Beatmatching", "Pitch fader", "Musical key", "Harmonic mixing", "Key lock", "Time-stretching"], "common_mistakes": ["Assuming Master Tempo removes all artifacts, when large tempo shifts still cause audible time-stretching artifacts", "Confusing Master Tempo (pitch stays fixed) with the normal tempo slider, which changes both speed and pitch together", "Leaving Master Tempo off during harmonic mixing, so tempo changes detune the track and clash with the other song"], "scenario_contexts": ["Beatmatching two tracks with different BPMs while keeping each one in its original key", "Harmonically mixing tracks so a tempo adjustment does not shift a track out of key", "Slowing a track for a breakdown without dropping its vocal pitch"]}, "5b370360-f941-44a3-804f-2eb5ced11d10": {"definition": "A performer who speaks or raps over a DJ's music through a microphone to host the event, guide the crowd, and energise the dancefloor; in hip-hop culture the MC (emcee) evolved from the DJ's announcer into the rapper. The role centres on live vocal presentation rather than music selection.", "plain_english": "An MC, or Master of Ceremonies, is the person who talks on the microphone at an event. They hype the crowd, make announcements, and keep the energy up while the DJ plays. In hip-hop, MCs grew into rappers.", "purpose_function": "The MC provides the spoken, crowd-facing side of a performance, freeing the DJ to focus on the music while the MC connects with the audience and drives the event's pace.", "practical_application": "At a party or club night, the MC works alongside the DJ, using the microphone to introduce tracks, take requests, run the room, and keep dancers engaged.", "category": "Performance Roles", "related_terms": ["DJ", "Microphone", "Mobile gig", "Turntablism", "Beatmatching", "Music selection"], "common_mistakes": ["Thinking an MC is the same as the DJ, when the MC handles the mic and the DJ handles the music", "Assuming 'MC' only means a rapper, when it originally meant the event host who works the microphone", "UNSAFE: Holding a live microphone directly in front of a speaker or monitor, causing feedback that can damage hearing and equipment"], "scenario_contexts": ["An MC hosting a wedding reception, introducing the first dance and speeches over the DJ's music", "A hip-hop MC rapping and hyping the crowd while the DJ cuts and scratches", "An MC on the mic at a club night announcing the headline act"]}}$ape$::jsonb)) d WHERE g.id=d.id;
UPDATE glossary g SET definition = CASE WHEN d.p ? 'definition' THEN d.p->>'definition' ELSE g.definition END, plain_english = CASE WHEN d.p ? 'plain_english' THEN d.p->>'plain_english' ELSE g.plain_english END, purpose_function = CASE WHEN d.p ? 'purpose_function' THEN d.p->>'purpose_function' ELSE g.purpose_function END, practical_application = CASE WHEN d.p ? 'practical_application' THEN d.p->>'practical_application' ELSE g.practical_application END, category = CASE WHEN d.p ? 'category' THEN d.p->>'category' ELSE g.category END, related_terms = CASE WHEN d.p ? 'related_terms' THEN ARRAY(SELECT jsonb_array_elements_text(d.p->'related_terms')) ELSE g.related_terms END, common_mistakes = CASE WHEN d.p ? 'common_mistakes' THEN ARRAY(SELECT jsonb_array_elements_text(d.p->'common_mistakes')) ELSE g.common_mistakes END, scenario_contexts = CASE WHEN d.p ? 'scenario_contexts' THEN ARRAY(SELECT jsonb_array_elements_text(d.p->'scenario_contexts')) ELSE g.scenario_contexts END FROM (SELECT key::uuid AS id, value AS p FROM jsonb_each($ape${"c140d4b1-dc12-4859-ba22-0a63c22efcd2": {"definition": "In music, a measure (also called a bar) is a unit of musical time containing a fixed number of beats set by the time signature, marked off by barlines. For DJs, tracks in common dance genres are typically felt in 4/4 measures of four beats, grouped into longer phrases.", "plain_english": "A measure, also called a bar, is a small, equal chunk of a song's beats. In most dance music, one measure holds four beats. DJs count measures to know where a section starts and to line up two songs.", "purpose_function": "The measure gives music a repeating count that organises rhythm; DJs use it to track song structure and to align the downbeats of two tracks when mixing.", "practical_application": "A DJ counts in groups of measures (often eight-measure phrases) to time a transition, so the incoming track's first measure lands on the outgoing track's phrase boundary.", "category": "Music Theory", "related_terms": ["Beat", "Phrase", "Downbeat", "Bar", "Time signature", "Beatmatching"], "common_mistakes": ["Confusing a beat (a single pulse) with a measure (a group of beats)", "Losing count of measures and starting a transition off-phrase, causing a clash", "Assuming every genre uses four beats per measure, when time signatures can differ"], "scenario_contexts": ["Counting measures to find the start of a phrase before dropping the next track", "Setting a loop that is exactly one or two measures long", "Lining up the downbeat of the incoming track's measure with the outgoing track"]}, "fb5c0e8f-6f39-4de1-ab6e-5332301d0b23": {"definition": "A cue point saved to a track's stored analysis data in DJ software or a DJ media player, so the DJ can recall and jump to that exact position on later playback. Unlike a hot cue, a memory cue is normally navigated with call / next-previous controls rather than triggered instantly by a dedicated performance pad.", "plain_english": "A memory cue is a saved spot in a track that a DJ can jump back to later. The DJ marks a point, like the start of a chorus, and the software remembers it. Next time the track loads, that marker is still there.", "purpose_function": "It lets a DJ pre-mark important positions (such as intros, drops, or mix-out points) once and reuse them across sessions, making cueing faster and more reliable during a set.", "practical_application": "Preparing tracks at home, a DJ sets memory cues at each track's first downbeat and drop, then recalls them live with the cue/loop call buttons to cue up quickly.", "category": "Cueing", "related_terms": ["Hot cue", "Cue point", "Beat grid", "Loop", "Beatmatching", "Downbeat"], "common_mistakes": ["Confusing a memory cue (recalled via call controls) with a hot cue (triggered instantly by a pad)", "Forgetting that memory cues save to the track's analysis data, not into the audio file itself", "Setting too many memory cues, making the right one hard to find quickly during a live set"], "scenario_contexts": ["Marking a track's intro and drop at home for fast cueing during a gig", "Recalling a saved memory cue with the CUE/LOOP CALL buttons on a media player", "Storing a mix-out point so the DJ knows exactly where to start the next transition"]}, "a9422d37-d50b-4c10-959c-e390318a422c": {"definition": "A DJ booking performed at a client's chosen venue using the DJ's own transported equipment, typically for private events such as weddings, parties, and corporate functions, rather than a resident club or festival slot. The mobile DJ supplies, sets up, and operates the full sound (and often lighting) system on site.", "plain_english": "A mobile gig is a DJ job where the DJ brings their own gear to an event. Think weddings, birthdays, or office parties. The DJ sets up the speakers and equipment at the venue, plays, then packs it all up afterward.", "purpose_function": "Mobile gigs let a DJ serve private clients who need music at a specific place and time; the DJ provides the complete portable system and adapts the music to the event and crowd.", "practical_application": "For a wedding, a mobile DJ transports controllers, speakers, and cabling, sets up and soundchecks on site, then reads the room and takes requests through the night.", "category": "Gig Types", "related_terms": ["MC (Master of Ceremonies)", "Music selection", "PA system", "Beatmatching", "Music discovery", "Cueing"], "common_mistakes": ["Assuming mobile gigs are only beatmatched sets, when they often mix genres and eras for a mixed-age crowd", "Underestimating the setup, transport, and cabling time needed before a mobile event starts", "UNSAFE: Running power cables across walkways without taping or matting them down, creating a trip hazard for guests"], "scenario_contexts": ["A DJ providing sound and music for a wedding reception", "Setting up a portable rig at a corporate function or private party", "Bringing backup gear to a mobile event in case a controller or cable fails"]}, "22ca1938-46f1-4577-af48-b52a79ee230f": {"definition": "The ongoing process by which DJs and listeners find new or unfamiliar tracks to add to their collections, through channels such as record shops and crate digging, record pools and promos, DJ-focused download stores and streaming, radio, and recommendations. For a DJ it is the continual sourcing of fresh material that keeps sets current.", "plain_english": "Music discovery is how people find new songs they did not know before. DJs do this all the time to keep their music fresh. They dig through record shops, streaming sites, playlists, and tips from other DJs.", "purpose_function": "It keeps a DJ's library current and distinctive, supplying the new and rare tracks that shape a personal sound and keep sets exciting for crowds.", "practical_application": "A DJ regularly browses record pools, new-release charts, and other DJs' sets to discover tracks, then test-plays promising ones before adding them to gig playlists.", "category": "Music Selection", "related_terms": ["Crate digging", "Music selection", "Record pool", "Musical key", "Mobile gig", "Library management"], "common_mistakes": ["Relying only on chart hits, so a set sounds the same as everyone else's", "Adding tracks to the library without listening fully, then getting caught out live", "Not organising or tagging discovered tracks, making them hard to find during a set"], "scenario_contexts": ["Browsing a DJ download store's new releases to find fresh tracks for the weekend", "Crate digging in a record shop for rare or older tracks", "Hearing an unknown track in another DJ's set and tracking it down"]}, "7718c38f-d6ad-4465-8267-0c49551da51e": {"definition": "The key of a piece of music is the tonal centre around which its melody and harmony are organised, named by its tonic note and mode (major or minor), for example A minor or C major. It determines which scale and chords sound resolved, and for DJs it underpins harmonic mixing between tracks.", "plain_english": "A musical key is the group of notes a song is built around. It has a home note and a mood, either major (brighter) or minor (darker). DJs check the key so they can mix songs that sound good together.", "purpose_function": "The key defines a track's harmonic home; knowing it lets a DJ combine tracks whose keys are compatible, avoiding dissonant clashes when two tracks play at once.", "practical_application": "Using key data from analysis software, a DJ selects an incoming track in the same or a related key to the current one, so blended vocals and melodies stay consonant.", "category": "Harmonic Mixing", "related_terms": ["Harmonic mixing", "Open Key notation", "Camelot wheel", "Master tempo", "Measure", "Key lock"], "common_mistakes": ["Confusing key (the tonal centre) with tempo (the speed), which are separate track properties", "Trusting automatic key detection blindly, when analysis software can occasionally mislabel a track", "Assuming only identical keys mix well, ignoring the compatible related keys"], "scenario_contexts": ["Choosing the next track by key for a smooth, in-key blend", "Checking two tracks' keys before overlapping their vocals", "Using Master Tempo so a tempo change does not shift a track out of its key"]}, "20145f4a-fe6b-430f-b010-0bb0c67a4e0b": {"definition": "A momentary, fine adjustment of a playing track's speed to correct its beat alignment (phase) with another track, made by lightly pushing or dragging the platter/record edge, spinning the outer ring of a jog dial, or tapping pitch-bend controls. Unlike a tempo-slider change, a nudge is temporary and returns to the set tempo once released.", "plain_english": "Nudging is a small push a DJ gives a track to line up its beats with another song. If one track drifts slightly ahead, a quick touch on the jog wheel or record slows it back into place. It is a short fix, not a lasting speed change.", "purpose_function": "A nudge fine-tunes phase alignment during beatmatching, letting a DJ keep two tracks' beats locked together without permanently changing either track's tempo.", "practical_application": "When beatmatching by ear, a DJ nudges the jog wheel forward or back in tiny amounts to pull a drifting track's downbeats back into time with the other track.", "category": "Beatmatching", "related_terms": ["Beatmatching", "Pitch bend", "Jog wheel", "Phase", "Tempo control", "Master tempo"], "common_mistakes": ["Nudging too hard, which overshoots and knocks the beats further out of alignment", "Confusing a temporary nudge (pitch bend) with moving the tempo slider (a lasting speed change)", "Fixing phase with nudges while ignoring a real tempo mismatch that keeps drifting"], "scenario_contexts": ["Pulling a track back into phase by hand while beatmatching two records", "Spinning the outer jog-dial ring to nudge a CDJ track into time", "Tapping pitch-bend buttons on a controller to correct a small beat drift"]}, "264d20b2-996f-4a32-b762-e5c24fb4a8a7": {"definition": "A key-notation system offered as a selectable key-display format in DJ software, in which each of the 24 major and minor keys is labelled by a number from 1 to 12 paired with a letter for its mode, arranged around the circle of fifths so that neighbouring numbers are harmonically related. It serves the same harmonic-mixing purpose as Camelot notation, as an alternative naming scheme.", "plain_english": "Open Key notation is a simple way to label a song's key with a number and a letter. DJs turn on this label in their software to find songs that mix well together. Keys with numbers next to each other sound good side by side.", "purpose_function": "It re-labels musical keys into an easy number-and-letter code so DJs can spot compatible keys at a glance for harmonic mixing, without reading traditional key names.", "practical_application": "A DJ sets the software's key display to Open Key notation, then picks an incoming track whose number matches, or is one step from, the current track's for an in-key blend.", "category": "Harmonic Mixing", "related_terms": ["Harmonic mixing", "Camelot wheel", "Musical key", "Key lock", "Master tempo", "Music selection"], "common_mistakes": ["Mixing up Open Key and Camelot numbers, which use different starting points, when reading charts", "Assuming only the exact same number mixes, ignoring the compatible neighbouring keys", "Trusting the software's key label without checking, since automatic detection can be wrong"], "scenario_contexts": ["Switching the DJ software's key display to Open Key notation for harmonic mixing", "Choosing the next track by matching or stepping the Open Key number", "Converting between Open Key and Camelot codes when following a harmonic mixing chart"]}, "624f1409-d27a-4250-8cba-016bb0664a17": {"definition": "A DJ who plays across many musical genres within a single set rather than specialising in one style, selecting and mixing tracks from any format (for example hip-hop, pop, house, R&B, and Latin) to suit the crowd and the moment. The approach prioritises versatility and crowd-reading over adherence to a single genre.", "plain_english": "An open-format DJ plays lots of different music styles in one set. They are not tied to a single genre. They pick whatever fits the crowd, mixing pop, hip-hop, dance, and more.", "purpose_function": "It lets a DJ entertain a mixed audience by drawing on any genre, which is valuable at weddings, clubs, and events where musical tastes vary widely.", "practical_application": "A wedding or club DJ reads the room and jumps between genres, beatmatching or quick-cutting between styles to keep a varied crowd dancing.", "category": "DJ Style", "related_terms": ["Beatmatching", "Phrase mixing", "Peak-time weapon", "Pitch range", "Transition"], "common_mistakes": ["Thinking an open-format DJ lacks a skill focus, when it actually demands broad genre knowledge and fast, clean transitions", "Assuming every genre can be beatmatched the same way, when tempos and song structures vary widely", "Confusing open-format with simply playing requests, rather than curating a flowing multi-genre set"], "scenario_contexts": ["A wedding DJ moving from dinner background music to pop and then to dancefloor tracks as the night builds", "A club DJ blending hip-hop, house, and Latin tracks to hold a mixed crowd", "A mobile DJ taking requests across genres while keeping the energy flowing"]}, "ec19b7b8-7219-4443-9c16-70b55e364954": {"definition": "The closing section of a track, typically a wound-down or reduced arrangement (often a beat-led passage) at the end, which a DJ uses as a mixing-out point. In DJ software such as rekordbox, phrase analysis labels this ending section so it can be located and mixed against another track's intro.", "plain_english": "The outro is the ending part of a song. It often strips back to mostly drums or a simple beat. DJs use it to blend smoothly into the next track.", "purpose_function": "It gives a DJ a stable, less busy section to overlap with the next track's intro, which makes transitions cleaner and easier to beatmatch.", "practical_application": "A DJ starts mixing the next track in over the current track's outro, using the sparse ending to blend without clashing vocals or melodies.", "category": "Track Structure", "related_terms": ["Intro", "Phrase", "Phrase mixing", "Beatmatching", "Transition"], "common_mistakes": ["Confusing the outro (the track's own ending) with a fade the DJ adds by hand", "Waiting until the outro is nearly over to start mixing, leaving no room for a smooth blend", "Assuming every track has a long beat-only outro, when many end abruptly or with vocals"], "scenario_contexts": ["Mixing the next track in over the beat-only outro of the current one", "Using rekordbox phrase analysis to locate a track's outro before a set", "Choosing tracks with clean outros to make beatmatched transitions easier"]}, "6267b1b8-3b73-4726-a707-31a8d9343bfe": {"definition": "An informal term for a track a DJ relies on to deliver maximum impact during peak time, the busiest and highest-energy part of a night, because it reliably excites the crowd. Such tracks are chosen for their strong drops, recognisability, or proven dancefloor effect.", "plain_english": "A peak-time weapon is a track a DJ saves for the busiest part of the night. It reliably gets the crowd going. Think of it as a sure-fire hit for the dance floor.", "purpose_function": "It gives a DJ a dependable tool to lift or hold the crowd's energy at the climax of a set, when the dancefloor is fullest.", "practical_application": "A DJ holds back a few peak-time weapons and drops them when the floor is packed to push the energy to its highest point.", "category": "Track Selection", "related_terms": ["Open-format DJ", "Phrase mixing", "Transition", "Beatmatching", "Outro"], "common_mistakes": ["Playing all the big tracks early, leaving nothing to lift the crowd at peak time", "Assuming a peak-time weapon works at any point, rather than when the floor is full and warmed up", "Judging a track only by personal taste instead of by how the crowd actually reacts"], "scenario_contexts": ["A DJ dropping a well-known anthem when the club is at its fullest", "Saving a track with a huge drop for the climax of a festival set", "Reading the room and holding back weapons until the energy peaks"]}, "e7f8ee40-da6d-45ff-a19b-15e3ddc28143": {"definition": "In DJ mixing, a phrase is a self-contained musical section of a track, typically a group of bars forming a power-of-two block (commonly 8, 16, or 32 beats in 4/4 dance music), that acts as a building block of the arrangement such as an intro, build, or chorus. DJ software such as rekordbox performs phrase analysis to identify and label these sections.", "plain_english": "A phrase is a chunk of a song that hangs together as one section. In dance music it is often 8, 16, or 32 beats long. Songs are built by stacking these chunks in order.", "purpose_function": "Recognising phrases tells a DJ where musical sections start and end, so that mixes, drops, and effects can be lined up with the music's natural structure.", "practical_application": "A DJ counts beats in groups (often 32) to find where a phrase begins, then starts a transition or effect on that boundary.", "category": "Track Structure", "related_terms": ["Phrase matching", "Phrase mixing", "Beatmatching", "Outro", "Intro"], "common_mistakes": ["Confusing a phrase (a multi-bar section) with a single bar or a single beat", "Assuming every track uses tidy 32-beat phrases, when some have odd-length sections", "Ignoring phrases and mixing at random points, which breaks the music's flow"], "scenario_contexts": ["Counting 32 beats to find the start of a new phrase before a transition", "Using rekordbox phrase analysis to see a track's sections at a glance", "Timing a filter sweep to build across a whole phrase"]}, "2ba1141b-7ed6-444b-aacf-0be9f295b653": {"definition": "The practice of aligning the phrase boundaries of two tracks so that their structural sections begin together, for example cueing the incoming track so its phrase starts at the same point as the outgoing track's phrase. It goes beyond beatmatching by synchronising musical structure, not just the beat grid.", "plain_english": "Phrase matching lines up the sections of two songs so they start together. It is not just matching the beat. It makes sure the parts of each track hit at the same time.", "purpose_function": "It keeps a mix musically coherent by making the builds, drops, and choruses of both tracks line up, which avoids clashes between mismatched sections.", "practical_application": "A DJ counts phrases in both tracks and cues the incoming track so its phrase starts on the outgoing track's phrase boundary before blending.", "category": "Mixing Technique", "related_terms": ["Phrase", "Phrase mixing", "Beatmatching", "Cue point", "Outro"], "common_mistakes": ["Beatmatching the tempo but ignoring phrases, so the sections of the two tracks are out of step", "Starting the new track a few beats off the phrase, so the drops or vocals clash", "Confusing phrase matching (aligning sections) with beatmatching (aligning the beat)"], "scenario_contexts": ["Cueing the incoming track so its 32-beat phrase starts with the outgoing track's phrase", "Lining up two tracks' builds so their drops land together", "Using software beat and phrase markers to align sections before a mix"]}, "e00ef62c-e3c6-4f50-b3b2-8d3ad64ea662": {"definition": "A mixing technique in which transitions between tracks are made at phrase boundaries, bringing the new track in and swapping over across whole phrases so that both tracks' structures stay aligned throughout the blend. It applies phrase matching over the course of a transition to keep the mix musically smooth.", "plain_english": "Phrase mixing means changing tracks at the start of a section, not just anywhere. The DJ blends over whole chunks of the music. This keeps the mix sounding smooth and musical.", "purpose_function": "It produces transitions that respect each track's structure, so sections line up and the change between tracks feels natural rather than jarring.", "practical_application": "A DJ brings the next track in at the start of a phrase and completes the swap by the end of that phrase, keeping both tracks' sections in step.", "category": "Mixing Technique", "related_terms": ["Phrase", "Phrase matching", "Beatmatching", "Transition", "Outro"], "common_mistakes": ["Starting or ending a blend in the middle of a phrase, which makes the transition sound abrupt", "Confusing phrase mixing with plain beatmatching, which aligns the beat but not the sections", "Losing count of the phrase during the blend and swapping over at the wrong point"], "scenario_contexts": ["Blending from one track's outro phrase into the next track's intro phrase", "Swapping tracks across a full 32-beat phrase for a seamless change", "Timing a transition so that both tracks' drops land together"]}, "85067e9b-4024-404d-9e71-44d12705b936": {"definition": "The maximum amount by which a turntable, media player, or DJ controller can raise or lower a track's playback speed using its tempo/pitch fader, expressed as a percentage such as +/-8% or +/-16%. Many devices offer selectable ranges; Pioneer CDJ players provide +/-6, +/-10, and +/-16 plus a WIDE (+/-100%) setting, and the Technics SL-1200GR offers +/-8% or +/-16%.", "plain_english": "Pitch range is how far a player can speed up or slow down a track. It is shown as a percent, like plus or minus 8%. A wider range moves the tempo more.", "purpose_function": "It sets how much a DJ can change a track's tempo to beatmatch it against another; a narrow range gives fine control, while a wider range allows bigger tempo changes.", "practical_application": "A DJ picks a narrow range such as +/-8% for precise beatmatching of similar tempos, or switches to a wide range to force very different tempos to match.", "category": "Tempo Control", "related_terms": ["Pitch riding", "Beatmatching", "Master tempo", "Pitch fader", "BPM"], "common_mistakes": ["Confusing pitch range (how far the speed can change) with the current pitch setting itself", "Using too wide a range for close beatmatching, which makes the fader hard to set precisely", "Forgetting that changing speed without Master Tempo also changes the musical key"], "scenario_contexts": ["Selecting +/-6% on a CDJ for fine beatmatching between tracks of similar tempo", "Switching to WIDE range to blend tracks with very different BPMs", "Setting a Technics turntable to +/-16% to match a much faster record"]}, "45d488e0-1b98-4a0d-9d09-3c830370a058": {"definition": "The technique of continuously making small manual adjustments to the pitch/tempo fader (or nudging the platter or jog wheel) during a beatmatched mix to correct tempo drift and keep two tracks locked in time. It compensates for tiny speed differences that would otherwise cause the beats to gradually drift apart.", "plain_english": "Pitch riding means keeping a hand on the speed control during a mix. The DJ makes tiny changes so two tracks stay in time. It fixes small drifts before they become obvious.", "purpose_function": "It keeps beatmatched tracks aligned over a long blend, because even a slight tempo difference will slowly pull the beats out of sync without constant correction.", "practical_application": "While two tracks play together, a DJ nudges the pitch fader up or down to hold the beats locked until the transition is complete.", "category": "Beatmatching Technique", "related_terms": ["Beatmatching", "Pitch range", "Pitch fader", "Phrase mixing", "Transition"], "common_mistakes": ["Making large pitch changes instead of tiny corrections, which causes an audible speed jump", "Relying only on the sync button and never learning to ride the pitch by ear", "Overcorrecting back and forth, so the two tracks never settle in time"], "scenario_contexts": ["Nudging the pitch fader during a long blend to stop two vinyl tracks drifting apart", "Correcting a slight tempo difference between two records by ear", "Holding two tracks locked through a full phrase before completing a transition"]}, "dadee2f5-005c-49ff-ab69-cca339d1cf9d": {"definition": "A monitoring function that lets a DJ hear a channel's signal, tapped from before the channel fader, in their headphones, so the source can be auditioned regardless of the fader position or whether the channel is live to the audience. On DJ mixers this is provided by each channel's headphone CUE button, used to cue and beatmatch the next track privately before mixing it in.", "plain_english": "Pre-fade listen lets a DJ hear a track in their headphones before the crowd hears it. It works even when that channel's volume fader is down. DJs use it to line up the next song.", "purpose_function": "It exists so a DJ can privately cue, beatmatch, and prepare the next track in headphones without sending it to the main speakers.", "practical_application": "A DJ presses a channel's CUE button to hear the next track in the headphones, sets its cue point and matches its beat, then raises the fader to mix it in.", "category": "Monitoring", "related_terms": ["Cue point", "Beatmatching", "Crossfader", "Slip cue", "Phrase mixing"], "common_mistakes": ["Thinking the channel fader must be up to hear a track in the cue, when PFL is taken before the fader", "Confusing pre-fade listen with the booth or master monitor, which carries what the audience hears", "Forgetting to press CUE and beatmatching against the master mix instead"], "scenario_contexts": ["Cueing and beatmatching the next track in headphones before mixing it in", "Checking a track's start point on a DJM mixer using the channel CUE button", "Setting a cue point in headphones while the current track plays to the room"]}, "48143a59-4383-477e-b6e9-773639a256c0": {"definition": "The practice of listening to an incoming track through headphones via the mixer's cue/PFL (pre-fade listen) bus before it is sent to the main output, so the DJ can select, cue up and beatmatch the next record while the current one plays to the audience.", "plain_english": "Previewing means listening to the next song in your headphones first. The crowd only hears the song already playing. This lets you get the next track ready in private.", "purpose_function": "It gives the DJ a private monitor path to select, cue and beatmatch upcoming tracks without the audience hearing, so transitions can be prepared in advance.", "practical_application": "A DJ presses the channel cue (PFL) button and uses headphones to find the first beat and match tempo before opening the fader to the room.", "category": "Cueing & Monitoring", "related_terms": ["Beatmatching", "Cue point", "PFL", "Headphone monitoring", "Crossfader"], "common_mistakes": ["Forgetting to press the channel cue button, so the headphones monitor the wrong deck", "Confusing previewing (headphone cue) with what the audience hears on the main output", "UNSAFE: Monitoring at very high headphone levels for hours, which risks noise-induced hearing loss"], "scenario_contexts": ["Cueing the next track in headphones during a club set before mixing it in", "Checking the start point of a request while the current song plays to the room", "Beatmatching a new record silently before opening its channel fader"]}, "8160df7b-c908-4144-9513-c0cf5cd464b5": {"definition": "A DJ booking for a closed, invitation-only function — such as a wedding, corporate party, birthday or reception — rather than a public club night or ticketed show; the audience is a specific invited group and the DJ typically tailors the music to the host's requests.", "plain_english": "A private event is a booking for a closed guest list, like a wedding or work party. It is not open to the public. The DJ often plays songs the host asks for.", "purpose_function": "It describes a gig where the client and invited guests, not a paying public crowd, set the tone, so the DJ plans music and gear around the host's needs and venue.", "practical_application": "A mobile DJ signs a contract, gathers must-play and do-not-play lists from the client, and brings their own sound and lighting to a venue with no house system.", "category": "Gig Type", "related_terms": ["Mobile DJ", "Resident DJ", "Requests", "Set (DJ)"], "common_mistakes": ["Assuming club-style long mixes suit a private crowd, when guests often expect familiar songs played more fully", "Not obtaining the client's must-play and do-not-play lists in advance", "Arriving without backup gear for a venue that has no house sound system"], "scenario_contexts": ["Playing a wedding reception with first-dance and must-play requests", "A corporate holiday party where the client sets the music policy", "A private birthday booking in a rented hall with no in-house PA"]}, "6aa8c071-6577-437c-b16d-8b9e09b87b3a": {"definition": "Short for 'promotional', a promo is a pre-release or promotional copy of a track supplied to DJs — historically as a promo-stamped vinyl, now typically through digital record pools — so they can play and expose it before or around its commercial release.", "plain_english": "A promo is a free early copy of a song given to DJs. They get it before it goes on sale. The idea is that DJs play it and help make it popular.", "purpose_function": "It lets labels and artists get new music into DJ sets early to build buzz and test crowd reaction before the public release date.", "practical_application": "A DJ downloads promos from a record pool or receives them from a label, then tests them in sets to see which tracks move the floor before they are widely available.", "category": "Music Sourcing", "related_terms": ["Record pool", "Dubplate", "White label", "Resident DJ"], "common_mistakes": ["Thinking a promo is a finished, mastered release when it may be an early or unmastered version", "Sharing or reselling promos, which breaks the terms of most DJ record pools", "Assuming every promo will suit the dance floor without testing it first"], "scenario_contexts": ["Downloading weekly promos from a digital record pool", "Testing a label's pre-release track in a club set before its street date", "A resident DJ breaking a new promo to gauge crowd response"]}, "c3d66f08-f1b7-4450-ad6f-0db00356c012": {"definition": "A DJ-software function that automatically snaps triggered actions — hot cues, loops, loop rolls and effects — to the nearest point on the track's analysed beatgrid, so they land in time even when the button is pressed slightly early or late.", "plain_english": "Quantize makes the software line up your actions with the beat for you. If you hit a cue button a little off, it snaps to the nearest beat. This keeps loops and drops in time.", "purpose_function": "It exists to keep performance actions rhythmically tight, letting a DJ trigger cues, loops and effects on-beat without perfectly precise timing.", "practical_application": "A DJ enables quantize in rekordbox, Serato or Traktor and sets the snap value (for example 1 beat or 1/4 beat) so hot cues and loops always fire on the grid.", "category": "DJ Software Feature", "related_terms": ["Beatgrid", "Hot cue", "Loop (DJ)", "Sync", "Loop roll"], "common_mistakes": ["Blaming quantize for off-beat triggers when the underlying beatgrid is actually misaligned", "Leaving quantize on during manual scratch or cut routines that need free timing", "Assuming quantize fixes a badly analysed track — the grid must be correct first"], "scenario_contexts": ["Enabling quantize so hot cues jump exactly on the beat during a live set", "Setting a small quantize value for tight loop-roll effects", "Turning quantize off to scratch freely without the software snapping cuts"]}, "5e61047f-db05-4752-9e3f-4ceb4864f51a": {"definition": "A hip-hop turntable technique, formalised as Grandmaster Flash's 'quick mix theory', in which the DJ rapidly cuts or blends between short segments — typically the break — of two records, often two copies of the same record, to extend, loop or rearrange those sections in time.", "plain_english": "Quick mix is a fast way of cutting between two records. The DJ jumps back and forth between short drum breaks. This lets them stretch or repeat the best part of a song.", "purpose_function": "It lets a DJ extend or rebuild the most danceable part of a track live by switching quickly between decks, rather than playing records straight through.", "practical_application": "A turntablist marks the start of a break on two copies of a record and cuts between them with the crossfader, re-cueing one deck while the other plays.", "category": "Mixing Technique", "related_terms": ["Backspin", "Crossfader", "Beat juggling", "Cue point", "Beatmatching"], "common_mistakes": ["Confusing a quick mix (a rapid cutting technique) with simply playing a short DJ set", "Not pre-cueing the second copy, so the break is not ready when you cut to it", "Letting the two records drift out of time because their tempos were never matched"], "scenario_contexts": ["Extending a four-bar drum break using two copies of the same record", "A hip-hop set where the DJ loops a breakbeat by cutting between decks", "Rearranging sections of a track live without using software loops"]}, "7b614a41-1f91-4058-92ec-9286d8b194cc": {"definition": "The major or minor key that shares the same key signature (the same set of sharps or flats) as a given key: every major key has a relative minor whose tonic lies a minor third below it, and every minor key has a relative major a minor third above; in harmonic (key-based) DJ mixing, relative major and minor keys are treated as compatible for blending.", "plain_english": "Two keys are 'relative' when they use the same notes. One sounds major (happy) and the other sounds minor (sad). For example, C major and A minor are relatives. DJs treat relative keys as a safe match when mixing.", "purpose_function": "The relationship marks pairs of major and minor keys that share the same notes, which is why DJs use it to pick tracks that will blend without clashing in pitch.", "practical_application": "Using a key-detection tool or the Camelot wheel, a DJ mixes a track in A minor with one in C major — its relative major — for a smooth, in-key transition.", "category": "Harmonic Mixing", "related_terms": ["Harmonic mixing", "Camelot wheel", "Key detection", "Beatmatching"], "common_mistakes": ["Thinking relative keys sound identical — they share notes but have different tonal centres and moods", "Confusing relative keys (same key signature) with parallel keys (same tonic, like C major and C minor)", "Relying only on software key labels without listening, since automatic detection can be wrong"], "scenario_contexts": ["Mixing an A-minor track into its relative C major for a key-matched blend", "Reading the Camelot wheel to find a relative key next to the current track", "Building a harmonically mixed set that moves between relative major and minor keys"]}, "af999594-1ddc-4e5f-98bb-690361d07e75": {"definition": "A DJ who holds a regular, ongoing engagement at a particular venue, club night or event series — playing there on a recurring basis rather than as a one-off guest — and who typically shapes the night's musical identity, warms up the room and supports visiting guest DJs.", "plain_english": "A resident DJ is the regular DJ at a club or night. They play there often, not just once. They help set the style of the night and support visiting guest DJs.", "purpose_function": "The role gives a venue a consistent musical identity and a reliable DJ who knows the crowd, room and sound system, and who can build or bridge sets around guest performers.", "practical_application": "A resident plays weekly at a club, often opening the night to warm up the floor, reading the regular crowd and then handing over to a headlining guest.", "category": "DJ Role", "related_terms": ["Warm-up set", "Guest DJ", "Private event", "Promo"], "common_mistakes": ["Thinking the resident is less skilled than the guest, when residents often do the harder job of warming up", "Playing peak-time bangers during a warm-up slot instead of building the energy gradually", "Not learning the venue's sound system and regular crowd, which is a core part of the role"], "scenario_contexts": ["A weekly club resident opening the night and warming up the floor", "A resident handing the decks over to a touring headliner", "A resident DJ shaping the long-term sound of a club night"]}, "3a4e16c1-76db-42dd-ba1d-69e42f344f25": {"definition": "A playback function on DJ media players, controllers and software that plays the track backwards from the current point; standard reverse runs the audio in the opposite direction, while a related 'slip reverse' mode plays backwards but returns forward playback to where it would have been had reverse not been engaged.", "plain_english": "Reverse plays the track backwards. Instead of moving forward, the sound runs the other way. DJs use it for a quick effect or to build tension before a drop.", "purpose_function": "It provides a rhythmic or dramatic effect, letting the DJ briefly run audio backwards to add tension or a fill before returning to normal playback.", "practical_application": "A DJ presses the reverse button on a CDJ or in Serato for a bar before a drop, often using slip mode so the track resumes in time.", "category": "Playback Function", "related_terms": ["Slip mode", "Backspin", "Censor", "Loop roll"], "common_mistakes": ["Confusing reverse (playing audio backwards electronically) with a backspin (physically spinning the record back)", "Forgetting to enable slip mode, so the track ends up out of time after reversing", "Overusing the effect, which quickly tires the crowd"], "scenario_contexts": ["Running a bar of reverse before a drop to build tension", "Using slip-reverse so the track stays on beat when normal play resumes", "Adding a short reverse fill at the end of a phrase"]}, "df999359-ce2a-41ae-b75b-d979e2218ad1": {"definition": "A DJ performance effect that combines reverse playback with a loop roll, momentarily repeating a short section of the track while it plays backwards for as long as the pad is held. It is provided on many controllers as a dedicated pad mode (for example Pioneer DJ's 'Rev Roll'), and releasing the pad returns playback to its normal forward position.", "plain_english": "A reverse roll plays a small chunk of the song backwards and repeats it while you hold a pad. It sounds like the track is being pulled back before it moves on. DJs use it to build a moment before a drop. Let go and the song plays forward again.", "purpose_function": "It adds tension and a backward 'suck-back' feel to a build-up by looping audio in reverse, then restores normal forward playback when the pad is released.", "practical_application": "A DJ triggers a reverse-roll pad in the bar before a drop or transition, using short beat divisions to create a rising backward stutter.", "category": "Loop Effect", "related_terms": ["Roll", "Reverse", "Slip mode", "Loop", "Beatmatching", "Hot cue"], "common_mistakes": ["Confusing reverse roll with plain reverse; reverse only plays backwards, while reverse roll also loops a short section repeatedly", "Holding the pad too long, so the backward loop pulls the mix noticeably out of time", "Expecting playback to resume from the reversed point; in roll modes playback returns to where the track would naturally be"], "scenario_contexts": ["Adding a reverse roll on the last beat before a drop for a suck-back effect", "Using a reverse roll to smooth an awkward transition between two tracks", "Building tension on a breakdown by reverse-rolling a vocal phrase"]}, "afc65856-b089-40e1-8ad8-d5ef1a19ea8a": {"definition": "The technique of manually moving a channel fader up and down in real time during playback to control a source's level moment to moment, rather than leaving it at a fixed setting. It is used to even out dynamics, lift quiet passages and pull back loud ones so a part sits correctly in the balance.", "plain_english": "Riding the fader means moving a channel volume slider by hand as the music plays. You nudge it up when a part gets too quiet and down when it gets too loud. It keeps everything at the right level, like steering to stay in your lane.", "purpose_function": "It gives live, human control over level so dynamic parts stay audible and balanced, filling the gap between a single fixed fader setting and full automation.", "practical_application": "An engineer rides the vocal fader through a song, lifting soft words and easing loud ones, either on a physical fader or by drawing the moves as automation.", "category": "Level Control", "related_terms": ["Riding the gain", "Fader", "Gain staging", "Automation", "Dynamic range", "Compression"], "common_mistakes": ["Assuming a compressor fully replaces fader riding; hand rides often give more natural results on wide dynamics", "Making large, sudden fader moves that become audible instead of small, smooth corrections", "Riding the fader before gain staging is set, so the channel is already too hot or too quiet"], "scenario_contexts": ["Riding a lead vocal fader across verses and choruses to keep every line clear", "Lifting a quiet guitar solo by hand during a live mix", "Pulling a fader down briefly to tame a loud shouted phrase"]}, "63566003-9552-4a3a-b568-29edd3abf5d4": {"definition": "The technique of manually adjusting a channel's input gain (trim) in real time to control level as the signal changes; an older console-era practice also called 'riding gain'. It is used to keep a fluctuating source at a usable level and to avoid clipping or excessive quietness at the input stage.", "plain_english": "Riding the gain means turning a channel input knob up or down by hand while sound is playing. You lower it when the signal gets too strong and raise it when it drops. This stops the sound from distorting or getting lost. It is a bit like easing off the gas when you go too fast.", "purpose_function": "It keeps a changing signal within a safe, usable range at the input stage, preventing overload and keeping quiet material audible before it reaches later processing.", "practical_application": "During tracking or a broadcast, an operator rides the input gain (trim) on a hot source such as a loud vocalist to avoid clipping the preamp or converter.", "category": "Level Control", "related_terms": ["Riding the fader", "Gain staging", "Trim", "Clipping", "Headroom", "Compression"], "common_mistakes": ["Confusing gain (input trim) with the fader (output level); riding the gain changes the signal feeding all later processing", "Pushing input gain so high to boost a quiet source that the preamp clips and distorts the signal", "Riding gain constantly when a compressor would handle small fluctuations more smoothly"], "scenario_contexts": ["Riding preamp gain on a vocalist who alternates between whispering and belting", "Trimming input gain during a live broadcast to hold speech at a consistent level", "Backing off gain on a loud kick channel to protect headroom before the mix bus"]}, "88acd5e1-d62b-44f5-94d5-7a8d536a422e": {"definition": "In beatmatching, the technique of making continuous small adjustments to a deck's pitch (tempo) control, together with brief pitch-bend nudges, to keep two tracks locked in time as their tempos naturally drift apart. It is the ongoing manual correction a DJ applies to hold a beatmatch without sync.", "plain_english": "When you beatmatch two songs by ear, they slowly drift out of time. Riding the pitch means making tiny changes to the tempo control to keep them locked together. You also give quick nudges to push a track forward or hold it back. It is like steering to stay lined up.", "purpose_function": "It maintains a manual beatmatch over time, correcting the small tempo differences and phase drift that occur when two tracks are not perfectly identical or sync-locked.", "practical_application": "A DJ mixing two records by ear keeps a hand near the pitch fader and the jog or platter, riding the pitch and nudging to hold the beats together through the blend.", "category": "Beatmatching", "related_terms": ["Beatmatching", "Pitch fader", "Pitch bend", "Nudging", "Phrasing", "Sync"], "common_mistakes": ["Relying only on the sync button and never learning to ride the pitch by ear", "Making big pitch-fader jumps instead of tiny corrections, which makes the tempo change audible", "Watching the platters or waveforms instead of listening, so drift is corrected too late"], "scenario_contexts": ["Holding a manual beatmatch on vinyl through a long blend by riding the pitch", "Nudging and trimming pitch when two tracks slowly slip apart mid-mix", "Beatmatching without sync on CDJs by constantly riding the pitch fader"]}, "d276ffa3-88f3-4e30-bbad-2687a75ee950": {"definition": "A DJ performance effect (also called loop roll or beat roll) that momentarily repeats a short section of the playing track for as long as a pad or button is held, then returns playback to the position it would have reached had the loop not occurred. Roll lengths are set in musical divisions (for example 1/32 up to several bars); short lengths create stutter effects while longer ones create rhythmic build-ups.", "plain_english": "Roll makes a tiny slice of the song repeat over and over while you hold a pad. Let go and the track carries on as if nothing happened. Short rolls make a fast stutter. Longer rolls build tension before a drop.", "purpose_function": "It lets a DJ add rhythmic repeats, stutters and build-ups on the fly without editing the track, while keeping the original playback position intact when the effect ends.", "practical_application": "A DJ holds a loop-roll pad on a controller or CDJ during a build-up or transition, choosing beat divisions to stutter a vocal or drum before a drop.", "category": "Loop Effect", "related_terms": ["Loop", "Reverse roll", "Slip mode", "Beatmatching", "Hot cue", "Crossfader"], "common_mistakes": ["Confusing a loop roll with a standard loop; a roll returns playback to where the track would be, while a saved loop keeps repeating from the loop point", "Setting the roll length too long for a fast transition, so the stutter drifts out of time with the beat", "Forgetting to release the pad, so the roll keeps repeating past the intended moment and stalls the mix"], "scenario_contexts": ["Holding a 1/16 loop roll on a vocal just before a drop to build energy", "Using a short roll to cover a rough edit while lining up the next track", "Rolling a drum beat at the end of a phrase to create a stutter fill"]}, "1c816b54-dbaa-4294-820a-b82c4df067c0": {"definition": "An informal term for a track a DJ keeps in reserve that reliably produces a strong crowd reaction, often one that is rare, exclusive, or unexpected, giving the DJ an edge because other DJs are not playing it. Such tracks are held back and deployed at a chosen moment for maximum impact.", "plain_english": "A secret weapon is a special track a DJ saves for the right moment. It nearly always gets a big reaction. It is often rare or unexpected, so the crowd has not heard it played out.", "purpose_function": "It gives a DJ a dependable track to lift the crowd or to stand out from other DJs, held back until the moment it will have the greatest effect.", "practical_application": "A DJ keeps a few secret weapons in the crate and drops one when the moment is right to surprise the crowd or rescue the energy.", "category": "Track Selection", "related_terms": ["Peak-time weapon", "Set list", "Selector", "Open-format DJ", "Transition"], "common_mistakes": ["Playing a secret weapon too early or too often, so it loses its surprise and impact", "Assuming any personal favourite is a secret weapon, rather than a track proven to move a crowd", "Confusing a secret weapon (a reliable, often exclusive track) with a brand-new untested one"], "scenario_contexts": ["Dropping a rare or exclusive track to surprise a crowd at the right moment", "Holding back a signature track that always fills the floor", "Using an unexpected tune to stand out from other DJs on the same lineup"]}, "02301274-2f27-4307-af4a-9f38bb47b1a4": {"definition": "In Jamaican sound-system culture, the selector is the person who chooses and plays the records and dubplates on a sound system, controlling the flow and mood of the music, as distinct from the deejay (MC) who toasts or chats over them. The term is now also used more broadly for a DJ who prioritises track selection and crowd-reading over technical mixing tricks.", "plain_english": "A selector is the person who picks and plays the records at a sound system. In Jamaican music, this job is separate from the MC who talks over the songs. Today it can mean any DJ known for great song choices.", "purpose_function": "The role exists to curate the music and steer the crowd's mood through choice of tunes, which in sound-system culture is valued as highly as any mixing skill.", "practical_application": "A selector builds and orders a crate or playlist of tunes and dubplates, then plays them to read and move the crowd, often working alongside an MC.", "category": "DJ Role", "related_terms": ["Set list", "Secret weapon", "Open-format DJ", "Beatmatching", "Transition"], "common_mistakes": ["Assuming a selector and a deejay (MC) are the same role, when in sound-system culture they are traditionally separate", "Thinking a selector's job is mainly mixing skill, when it is chiefly about track choice and crowd-reading", "Confusing the modern loose use of 'selector' for any DJ with its specific sound-system meaning"], "scenario_contexts": ["A reggae sound system where the selector plays dubplates while the MC toasts over them", "A DJ billed as a 'selector' at a club night focused on rare or carefully chosen tracks", "Building and ordering a crate of tunes to guide a crowd through the night"]}, "a41baff2-c33d-47b1-adc1-58526000ac05": {"definition": "A predetermined, ordered list of the tracks or songs a DJ or performer plans to play during a set, used to plan the programming, pacing, and energy arc of a performance. In DJ practice it may be prepared in advance in software or on paper, although many DJs adapt or depart from it to respond to the crowd.", "plain_english": "A set list is the planned order of songs a DJ or band will play. It maps out how the show builds and flows. Many DJs still change it on the night to match the crowd.", "purpose_function": "It helps a performer plan the pacing and energy of a show in advance, so tracks are ordered to build and hold the crowd rather than chosen at random.", "practical_application": "A DJ drafts a set list of tracks in a logical order before a gig, then follows or adapts it live while reading the crowd.", "category": "Set Preparation", "related_terms": ["Selector", "Secret weapon", "Open-format DJ", "Transition", "Beatmatching"], "common_mistakes": ["Sticking rigidly to a set list and ignoring how the crowd is actually responding", "Confusing a set list (the planned order of tracks) with an unordered playlist folder of tunes", "Planning tracks with no thought to pacing, so the energy rises and falls at the wrong times"], "scenario_contexts": ["Drafting an ordered list of tracks before a wedding or club set", "Adapting a planned set list on the fly when the floor reacts differently than expected", "Programming the energy arc of a festival set from opener to peak"]}, "b73bc5c3-9d4e-44aa-87d9-224cef2d3b1c": {"definition": "A playback mode on DJ media players, controllers, and software in which the track keeps advancing silently in the background while the performer manipulates it (scratching, looping, reversing, or holding a hot cue), so that when the manipulation is released playback resumes from the position it would have reached had the track been left to play. It lets performers add live edits without losing the track's place in the mix or its beat alignment.", "plain_english": "Slip mode keeps a track running in the background while you scratch or loop it. When you let go, the song jumps to where it would have been if you had left it alone. It lets you add tricks without falling out of time.", "purpose_function": "It exists so a DJ can perform scratches, loops, or reverses over a running track and return seamlessly to the beat, preserving timing during a live mix.", "practical_application": "A DJ enables Slip on a CDJ, controller, or in software, performs a scratch or a short loop over a playing track, then releases it so playback snaps back in time with the other deck.", "category": "Playback Mode", "related_terms": ["Slip mode transition", "Hot cue", "Loop", "Beatmatching", "Scratching"], "common_mistakes": ["Thinking slip mode changes the audio you hear during the trick, when it only tracks the hidden playhead in the background", "Forgetting to enable slip before a loop or scratch, so the track loses its place and drifts out of time", "Confusing slip mode with slip-cueing a record by hand on a turntable"], "scenario_contexts": ["Scratching over a running track and releasing back into the beat with slip enabled", "Dropping a short loop for effect, then letting the track resume in time", "Using a hot cue for a stutter, then returning to the correct position via slip mode"]}, "350eb2a4-5b10-43ea-a010-54812f506950": {"definition": "A track transition in which a DJ uses slip mode to apply a loop, scratch, reverse, or roll to one deck during the changeover while the underlying track keeps advancing silently, so that playback returns to the correct beat position when the effect is released and the transition completes in time. It combines a creative effect with slip mode's automatic return to keep both decks beat-aligned.", "plain_english": "A slip mode transition uses slip mode to add a trick, like a loop or scratch, while changing tracks. The track keeps running in the background the whole time. When you let go, it lands back on the beat so the change stays in time.", "purpose_function": "It lets a DJ add a creative flourish during a transition without knocking the mix out of time, because slip mode returns the track to where it should be.", "practical_application": "A DJ turns on slip, drops a loop or scratch on the outgoing track while bringing in the new one, then releases slip so the beats stay aligned as the transition finishes.", "category": "Mixing Technique", "related_terms": ["Slip mode", "Transition", "Loop", "Beatmatching", "Hot cue"], "common_mistakes": ["Attempting the effect without slip enabled, so the track drifts off the beat and the transition falls apart", "Holding the loop or scratch too long, so the hidden playhead passes the point you wanted to return to", "Confusing a slip mode transition with a plain cut, which has no background playback to return to"], "scenario_contexts": ["Rolling a loop on the outgoing track during a changeover, then releasing back on beat", "Adding a scratch over the transition while the track keeps its place via slip", "Using slip to reverse a bar for effect before letting the mix continue in time"]}, "434c963a-85c0-4a84-a24d-22e0ed6ce7dd": {"definition": "A performance technique in which the DJ rapidly rotates the record or jog wheel backwards, producing a fast rewind or falling-pitch 'pull-back' sound, then releases so the track continues or the next track drops. It is used mainly as a dramatic transition or to rewind and re-drop a track, and is closely related to the backspin, which more specifically returns a record to an earlier point.", "plain_english": "A spin back is when a DJ quickly spins the record backwards. This makes a fast rewind sound. DJs use it to end a track or jump into the next one.", "purpose_function": "It gives a DJ a bold, attention-grabbing way to end or switch a track, marking a clear break in energy rather than a smooth blend.", "practical_application": "A DJ spins the platter or jog wheel backwards at the end of a phrase to rewind a big track, then drops the next one on the beat.", "category": "Mixing Technique", "related_terms": ["Backspin", "Transition", "Beatmatching", "Cue point", "Jog wheel"], "common_mistakes": ["Confusing a spin back (a rewind effect) with a backspin used simply to return a record to its cue point", "Spinning back so hard that the next track is dropped off-beat, breaking the mix", "Overusing the spin back, so a bold effect becomes predictable and loses impact"], "scenario_contexts": ["Rewinding a peak-time track with a spin back before dropping the next one", "Using a spin back on a jog wheel as a quick, dramatic transition", "Marking the end of a phrase with a spin back to signal a big change"]}, "205c6239-2a5d-4827-bd38-25c19577a800": {"definition": "A headphone monitoring mode on a DJ mixer in which the cue (pre-fade) signal is sent to one ear and the master (program) output to the other, instead of both being blended together in stereo. On Pioneer DJ mixers this is the MONO SPLIT setting, which feeds the CUE decks to one side of the headphones and the master to the other, letting a DJ beatmatch the cued track against the live mix at the same time.", "plain_english": "Split cue sends the next track to one ear and the live mix to the other. Both play in mono. This lets a DJ line up the beats of both tracks at once.", "purpose_function": "It lets a DJ hear the cued track and the audience's mix side by side, which makes beatmatching easier in loud rooms where the speakers are hard to hear.", "practical_application": "A DJ turns the headphone SPLIT on, hears the master in one ear and the next track in the other, and matches their beats before mixing in.", "category": "Monitoring", "related_terms": ["Pre-fade listen (PFL, DJ)", "Cue point", "Beatmatching", "Crossfader", "Booth monitor"], "common_mistakes": ["Confusing split cue (cue in one ear, master in the other) with a stereo cue blend of the two", "Forgetting that split cue collapses the headphone feed to mono, so stereo detail is lost", "Leaving split cue off and trying to beatmatch against the room in a loud club"], "scenario_contexts": ["Beatmatching in a loud club by putting the master in one ear and the cue in the other", "Using MONO SPLIT on a Pioneer DJM mixer to check the next track against the mix", "Cueing the next track without a booth monitor by relying on split cue"]}, "e17d51a7-ca51-4ad3-8589-785a7cec87c3": {"definition": "A DJ booked to play before the main or headline act, warming up the room and building the crowd's energy toward the headliner rather than peaking too early. Also called a warm-up or opening DJ, the role calls for restraint in track selection and energy so that the headline set has room to climax.", "plain_english": "A support DJ plays before the main act. Their job is to warm up the crowd. They keep the energy building but do not go too big too soon.", "purpose_function": "It exists to prepare the dancefloor and lift the mood gradually, so the crowd is ready and the headliner can take the energy to its peak.", "practical_application": "A support DJ reads an early, filling room and plays slightly lower-energy tracks, resisting the urge to drop peak-time anthems before the headliner arrives.", "category": "DJ Role", "related_terms": ["Open-format DJ", "Peak-time weapon", "Warm-up set", "Track selection", "Headliner"], "common_mistakes": ["Playing peak-time anthems during a warm-up slot, leaving the headliner nowhere to build", "Thinking the support slot is unimportant, when it sets up the whole night's energy", "Ignoring the early crowd and the headliner's style instead of setting them up"], "scenario_contexts": ["Opening a club night with lower-energy tracks before the headliner", "Warming up an early festival crowd for a bigger act to follow", "Building the room's energy gradually as a support DJ"]}, "e9fd1be6-82c4-4bb0-a4d0-afb2d1e4e173": {"definition": "A function in DJ software and hardware that automatically matches the tempo (BPM) and beat position of a track to a designated master deck, using each track's analyzed beatgrid, so the decks stay in time without manual beatmatching. Pressing the SYNC (BEAT SYNC) button aligns the non-master deck's tempo and beat grid to the sync master.", "plain_english": "Sync makes the software match the beats of two tracks for you. You press a button and one deck locks to the other track. It only works on tracks the software has scanned.", "purpose_function": "It exists to lock two tracks in time automatically, freeing the DJ from constant manual pitch adjustment so they can focus on selection, effects, and transitions.", "practical_application": "A DJ loads an analyzed track, presses SYNC so it matches the master deck's tempo and beatgrid, then mixes without riding the pitch fader.", "category": "Tempo Control", "related_terms": ["Beatmatching", "Beatgrid", "Master tempo", "BPM", "Track analysis"], "common_mistakes": ["Relying on sync without checking the beatgrid, so a wrong grid puts the tracks out of time", "Assuming sync works on unanalyzed tracks, when the software needs a beatgrid first", "Never learning manual beatmatching and being stuck when sync drifts or fails"], "scenario_contexts": ["Pressing SYNC in rekordbox or Serato to lock a new track to the master deck", "Using beat sync across CDJs linked over PRO DJ LINK", "Fixing a track that drifts because its beatgrid was set wrong"]}, "751cf046-3fe5-4aae-ab11-7f2f9d167a4a": {"definition": "The process of adjusting two tracks so they play at the same tempo (beats per minute), typically by moving the pitch/tempo fader of one deck until its BPM equals the other's. It is the first stage of beatmatching; matching tempo alone keeps the beats at the same rate, while beatmatching then also aligns their phase.", "plain_english": "Tempo matching means setting two tracks to the same speed. A DJ moves the speed control until both have the same beats per minute. It is the first step before lining up the beats.", "purpose_function": "It makes two tracks run at the same rate, which is required before their beats can be locked together for a smooth blend.", "practical_application": "A DJ reads both tracks' BPM, then nudges the pitch fader on one deck until the numbers match before aligning the downbeats.", "category": "Beatmatching Technique", "related_terms": ["Beatmatching", "BPM", "Pitch fader", "Sync (DJ)", "Pitch range"], "common_mistakes": ["Thinking matched tempo alone means the tracks are beatmatched, when the beats still need aligning in phase", "Matching the BPM numbers but ignoring that the beatgrid or BPM reading is wrong", "Changing tempo so far that the track's key and feel change noticeably"], "scenario_contexts": ["Moving the pitch fader to bring a 126 BPM track up to match a 128 BPM track", "Setting both decks to the same BPM before beatmatching by ear", "Matching tempo as the first step of a manual blend"]}, "e36557a1-acd9-4132-9f35-012a27bebe2e": {"definition": "The process by which DJ software scans an audio file to detect and store performance data such as tempo (BPM), the beatgrid (beat positions), musical key, and waveform overview, so the track can be beatmatched, synced, and browsed. In rekordbox and Serato this analysis is run before tracks are played and can be locked to prevent accidental changes.", "plain_english": "Track analysis is when DJ software studies a song before you play it. It finds the beats, the speed, and the key. This lets tools like sync and the waveform work.", "purpose_function": "It prepares tracks for performance by measuring their tempo, beats, and key in advance, which is what makes sync, beatgrids, and key mixing possible.", "practical_application": "A DJ imports new music and analyzes it in rekordbox or Serato, then checks and fixes any wrong BPM or beatgrid before the gig.", "category": "Track Preparation", "related_terms": ["Beatgrid", "BPM", "Sync (DJ)", "Waveform", "Key detection"], "common_mistakes": ["Playing unanalyzed tracks live, so sync, beatgrids, and quantize do not work", "Trusting the auto-detected BPM or beatgrid without checking it against the music", "Forgetting to re-analyze after editing a track, leaving stale beat data"], "scenario_contexts": ["Analyzing a folder of new tracks in rekordbox before a set", "Fixing a wrongly detected beatgrid after analysis", "Using analyzed key data to plan harmonic mixing"]}}$ape$::jsonb)) d WHERE g.id=d.id;
COMMIT;
